/// Supabase Flutter stores sessions in SharedPreferences by default. Move the
/// existing session once, then keep future access/refresh tokens in Android
/// encrypted storage or the iOS Keychain.
class _SecureSupabaseSessionStorage extends LocalStorage {
  _SecureSupabaseSessionStorage({required this.persistSessionKey});

  final String persistSessionKey;
  final FlutterSecureStorage _secureStorage = const FlutterSecureStorage();
  String? _session;

  @override
  Future<void> initialize() async {
    _session = await _secureStorage.read(key: persistSessionKey);
    final preferences = await SharedPreferences.getInstance();
    if (_session == null) {
      final legacySession = preferences.getString(persistSessionKey);
      if (legacySession != null && legacySession.isNotEmpty) {
        await _secureStorage.write(
          key: persistSessionKey,
          value: legacySession,
        );
        _session = legacySession;
      }
    }
    // Remove any old plaintext copy even if a secure copy already exists.
    await preferences.remove(persistSessionKey);
  }

  @override
  Future<bool> hasAccessToken() async => (await accessToken()) != null;

  @override
  Future<String?> accessToken() async {
    _session ??= await _secureStorage.read(key: persistSessionKey);
    return _session;
  }

  @override
  Future<void> removePersistedSession() async {
    _session = null;
    await _secureStorage.delete(key: persistSessionKey);
  }

  @override
  Future<void> persistSession(String persistSessionString) async {
    await _secureStorage.write(
      key: persistSessionKey,
      value: persistSessionString,
    );
    _session = persistSessionString;
  }
}

String uid(String prefix) =>
    '${prefix}_${math.Random().nextInt(1 << 32).toRadixString(36)}';

String secureTemporaryPassword({int length = 24}) {
  const chars =
      'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#\$%_-';
  final random = math.Random.secure();
  return List<String>.generate(
    length,
    (_) => chars[random.nextInt(chars.length)],
  ).join();
}

Future<void> resetAndShowTemporaryPassword(
  BuildContext context,
  String userId,
  String accountName,
) async {
  try {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: Text(T('Reset password?')),
        content: Text(
          TT(
            'The current password for {0} will stop working. A new temporary password will be shown once.',
            <String>[accountName],
          ),
        ),
        actions: <Widget>[
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: Text(T('Cancel')),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: Text(T('Reset password')),
          ),
        ],
      ),
    );
    if (confirmed != true || !context.mounted) return;
    final credentials = await Store.I.requestAccountPasswordReset(userId);
    if (!context.mounted) return;
    if (credentials['email']!.isEmpty ||
        credentials['temporaryPassword']!.isEmpty) {
      throw StateError('The server did not return temporary login details.');
    }
    final localAccount = Store.I.userById(userId);
    if (localAccount != null) {
      localAccount.remove('password');
      Store.I.save(push: false);
    }
    await showDialog<void>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: Text(TT('Temporary login for {0}', <String>[accountName])),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: <Widget>[
            Text(
              T(
                'Share these details now. They will not be saved or shown again.',
              ),
            ),
            const SizedBox(height: 12),
            SelectableText('Login ID: ${credentials['email']}'),
            const SizedBox(height: 6),
            SelectableText(
              'Temporary password: ${credentials['temporaryPassword']}',
            ),
          ],
        ),
        actions: <Widget>[
          FilledButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: Text(T('Done')),
          ),
        ],
      ),
    );
  } catch (error) {
    if (context.mounted)
      toast(context, error.toString().replaceFirst('Bad state: ', ''));
  }
}

// ---------------------------------- palette ---------------------------------
class Skin {
  Skin({this.dark = true, this.accentKey = 0, this.style = 0});
  final bool dark;
  final Object? accentKey;
  final Object? style;

  int get themeIdx =>
      accentKey is int ? accentKey as int : int.tryParse('$accentKey') ?? 0;

  int get styleIdx => style is int
      ? style as int
      : ('$style' == 'soft' ? 1 : ('$style' == 'crisp' ? 2 : 0));

  // accents (dark-theme values, used everywhere)
  static const gold = Color(0xFFF0B559);
  static const marigold = Color(0xFFF0B559);
  static const marigoldDeep = Color(0xFFF5C77B);
  // check-in / check-out tiles: normal tone as on the phone, one step darker
  // when that is the action waiting for the staff member
  static const checkInBase = Color(0xFF244636);
  static const checkInActive = Color(0xFF0F2A1E);
  static const checkOutBase = Color(0xFF5F2E20);
  static const checkOutActive = Color(0xFF34170D);
  static const green = Color(0xFF6FBB93);
  static const greenBg = Color(0xFF213028);
  static const red = Color(0xFFE08268);
  static const brick = Color(0xFFE08268);
  static const brickBg = Color(0xFF332320);
  static const amber = Color(0xFFE3BE73);
  static const amberBg = Color(0xFF332B1B);
  static const navy = Color(0xFF8FA3D1);
  static const navySoft = Color(0xFFA7B8DC);
  static const navySolid = Color(0xFF1B2A4A);
  static const navySolidHover = Color(0xFF2E4066);
  static const violet = Color(0xFF7C6CF0);
  static const blue = Color(0xFF3B82F6);
  static const pink = Color(0xFFEC4899);
  static const emerald = Color(0xFF10B981);
  static const orange = Color(0xFFF97316);
  static const themeColors = <Color>[violet, blue, pink, emerald, orange];
  static const Map<int, Color> themeColorEntries = <int, Color>{
    0: violet,
    1: blue,
    2: pink,
    3: emerald,
    4: orange,
  };
  static const cream = Color(0xFFF6F4EF);
  static const creamSoft = Color(0xFF4A473F);
  static const creamLine = Color(0xFFC9C3B4);
  static const goldDeep = Color(0xFFC97F1E);
  static const night = Color(0xFF1A1A16);
  static const lineStrongStatic = Color(0xFF4A4A41);
  static const inkSoftStatic = Color(0xFFC5C1B2);
  static const headerGradient = LinearGradient(
    colors: <Color>[Color(0xFF26385F), Color(0xFF1B2A4A)],
    begin: Alignment.topLeft,
    end: Alignment.bottomRight,
  );
  static const themeColorLabels = <int, String>{
    0: 'Violet',
    1: 'Blue',
    2: 'Pink',
    3: 'Green',
    4: 'Orange',
  };
  static const textSizeLabels = <int, String>{
    0: 'Small',
    1: 'Default',
    2: 'Large',
    3: 'Extra large',
  };
  static const uiStyleLabels = <int, String>{
    0: 'Rounded',
    1: 'Soft',
    2: 'Crisp',
  };
  static const serif = 'serif';
  static const mono = 'monospace';
  static bool nightPaper = true;

  bool get isDark => dark;

  Color get bg => dark ? Color(0xFF1A1A16) : Color(0xFFF6F4EF);
  Color get surface => dark ? Color(0xFF232320) : Colors.white;
  Color get surface2 => dark ? Color(0xFF2C2C27) : Color(0xFFEFEBE0);
  Color get ink => dark ? Color(0xFFF2EFE5) : Color(0xFF21201C);
  Color get inkSoft => dark ? Color(0xFFC5C1B2) : Color(0xFF4A473F);
  Color get faint => dark ? Color(0xFF9A9687) : Color(0xFF6B6758);
  Color get line => dark ? Color(0xFF3B3B34) : Color(0xFFC9C3B4);
  Color get lineStrong => dark ? Color(0xFF4A4A41) : Color(0xFFAFA895);
  Color get panelTint => surface;

  double get radius => styleIdx == 2 ? 4 : (styleIdx == 1 ? 14 : 11);

  /// A colour the user mixed themselves, handed over as "#RRGGBB".
  static Color? colorFromHex(Object? raw) {
    if (raw is! String) return null;
    var t = raw.trim().replaceAll('#', '');
    if (t.length == 3) {
      t = '${t[0]}${t[0]}${t[1]}${t[1]}${t[2]}${t[2]}';
    }
    if (t.length != 6) return null;
    final v = int.tryParse(t, radix: 16);
    if (v == null) return null;
    return Color(0xFF000000 | v);
  }

  static String hexOf(Color c) =>
      '#${(c.toARGB32() & 0xFFFFFF).toRadixString(16).padLeft(6, '0').toUpperCase()}';

  Color get accent =>
      colorFromHex(accentKey) ?? themeColors[themeIdx.clamp(0, 4)];

  List<BoxShadow> get shadow => dark
      ? const <BoxShadow>[BoxShadow(color: Color(0x66000000), blurRadius: 1)]
      : const <BoxShadow>[
          BoxShadow(
            color: Color(0x0D211F1C),
            blurRadius: 2,
            offset: Offset(0, 1),
          ),
          BoxShadow(
            color: Color(0x00172B4A),
            blurRadius: 22,
            offset: Offset(0, 6),
          ),
        ];

  ThemeData theme(bool isDark) {
    nightPaper = isDark;
    final k = Skin(dark: isDark);
    final base = isDark ? ThemeData.dark() : ThemeData.light();
    final scheme = ColorScheme.fromSeed(
      seedColor: navySolid,
      brightness: isDark ? Brightness.dark : Brightness.light,
      surface: k.surface,
    ).copyWith(primary: accent);
    return base.copyWith(
      colorScheme: scheme,
      scaffoldBackgroundColor: k.bg,
      canvasColor: k.surface,
      dividerColor: k.line,
      textTheme: base.textTheme.apply(bodyColor: k.ink, displayColor: k.ink),
      inputDecorationTheme: InputDecorationTheme(
        isDense: true,
        filled: true,
        fillColor: k.surface2,
        contentPadding: EdgeInsets.symmetric(horizontal: 12, vertical: 12),
        hintStyle: TextStyle(color: k.faint, fontSize: 13),
        labelStyle: TextStyle(color: k.inkSoft, fontSize: 13),
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(11),
          borderSide: BorderSide(color: k.line),
        ),
        enabledBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(11),
          borderSide: BorderSide(color: k.line),
        ),
        focusedBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(11),
          borderSide: BorderSide(color: marigold, width: 1.4),
        ),
      ),
      filledButtonTheme: FilledButtonThemeData(
        style: FilledButton.styleFrom(
          backgroundColor: navySolid,
          foregroundColor: Colors.white,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(11),
          ),
          padding: EdgeInsets.symmetric(horizontal: 16, vertical: 13),
          textStyle: TextStyle(fontSize: 14, fontWeight: FontWeight.w600),
        ),
      ),
      outlinedButtonTheme: OutlinedButtonThemeData(
        style: OutlinedButton.styleFrom(
          foregroundColor: k.inkSoft,
          side: BorderSide(color: k.lineStrong),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(11),
          ),
          padding: EdgeInsets.symmetric(horizontal: 14, vertical: 11),
          textStyle: TextStyle(fontSize: 13, fontWeight: FontWeight.w600),
        ),
      ),
      textButtonTheme: TextButtonThemeData(
        style: TextButton.styleFrom(foregroundColor: k.inkSoft),
      ),
      snackBarTheme: SnackBarThemeData(
        backgroundColor: isDark ? Color(0xFF31312B) : Color(0xFF21201C),
        contentTextStyle: TextStyle(color: Color(0xFFF2EFE5), fontSize: 13),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }
}

