/// The year-end rollover runs once a year, after the finals on 15 June — the
/// same rule the website uses, so the two stay in step on the shared record.
int currentPromoYear() {
  final d = DateTime.now();
  return (d.month > 6 || (d.month == 6 && d.day >= 15)) ? d.year : d.year - 1;
}

void toast(BuildContext c, String msg) {
  ScaffoldMessenger.of(c)
    ..hideCurrentSnackBar()
    ..showSnackBar(
      SnackBar(
        content: Text(msg),
        behavior: SnackBarBehavior.floating,
        duration: Duration(seconds: 2),
      ),
    );
}

extension SkinColors on BuildContext {
  /// The live skin: carries the accent + UI style the user picked in
  /// Appearance, so every widget follows those settings.
  Skin get k => Skin(
    dark: Theme.of(this).brightness == Brightness.dark,
    accentKey: Store.I.accentKey,
    style: Store.I.uiStyle,
  );
  bool get isDark => Theme.of(this).brightness == Brightness.dark;
  Color get panel => k.surface;
  Color get panel2 => k.surface2;
  Color get ink => k.ink;
  Color get softc => k.inkSoft;
  Color get faint => k.faint;
  Color get line => k.line;
  Color get lineStrong => Skin(dark: dark).lineStrong;
  Color get navy => Skin.navy;
  Color get marigold => Skin.marigold;
  Color get green => Skin.green;
  Color get brick => Skin.brick;
  bool get dark => k.dark;
  Color get soft => k.inkSoft;
}

// ------------------------------- formatting --------------------------------
String two(int n) => n < 10 ? '0$n' : '$n';

String todayStr([DateTime? at]) {
  final d = at ?? DateTime.now();
  return '${d.year}-${two(d.month)}-${two(d.day)}';
}

DateTime parseDay(String s) => DateTime.tryParse(s) ?? DateTime.now();

DateTime dayOnly(DateTime d) => DateTime(d.year, d.month, d.day);

String monthOf(String date) => date.substring(0, 7);

/// the academic session ends on 31 March
String sessionEndDate() {
  final now = DateTime.now();
  final y = now.month >= 4 ? now.year + 1 : now.year;
  return '$y-03-31';
}

/// 31.03.2027 or 31/03/2027 or 2027-03-31 all land as 2027-03-31
String normCardDate(String raw) {
  final t = raw.trim();
  if (t.isEmpty) return '';
  final dmy = RegExp(r'^(\d{1,2})[./-](\d{1,2})[./-](\d{4})$').firstMatch(t);
  if (dmy != null) {
    return '${dmy[3]}-${dmy[2]!.padLeft(2, '0')}-${dmy[1]!.padLeft(2, '0')}';
  }
  return t;
}

/// 2027-03-31 → 31.03.2027 for the printed card
String dmyDate(String iso) {
  final m = RegExp(r'^(\d{4})-(\d{2})-(\d{2})$').firstMatch(iso.trim());
  if (m == null) return iso;
  return '${m[3]}.${m[2]}.${m[1]}';
}

String ymOf(dynamic v) {
  final d = v is DateTime ? v : parseDay(v.toString());
  final y = d.year;
  final m = two(d.month);
  return '$y-$m';
}

String addMonthsStr(String ym, int delta) {
  final p = ym.split('-');
  final d = DateTime(int.parse(p[0]), int.parse(p[1]) + delta, 1);
  return ymOf(d);
}

const List<String> kMonths = <String>[
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December',
];

const List<String> kMonthShort = <String>[
  'Jan',
  'Feb',
  'Mar',
  'Apr',
  'May',
  'Jun',
  'Jul',
  'Aug',
  'Sep',
  'Oct',
  'Nov',
  'Dec',
];

String monthLabel(dynamic v) {
  if (v is String) return monthLabelLong(v);
  if (v is DateTime) return monthLabelLong(ymOf(v));
  if (v is int && v >= 1 && v <= 12) return Store.I.t(kMonths[v - 1]);
  return monthLabelLong(ymOf(todayStr()));
}

String shortTime24(int? ts) {
  if (ts == null) return '—';
  final d = DateTime.fromMillisecondsSinceEpoch(ts);
  return '${two(d.hour)}:${two(d.minute)}';
}

String monthLabelLong(String ym) {
  final p = ym.split('-');
  return '${Store.I.t(kMonths[int.parse(p[1]) - 1])} ${p[0]}';
}

String monthLabelShort(String ym) {
  final p = ym.split('-');
  return '${Store.I.t(kMonthShort[int.parse(p[1]) - 1])} ${p[0]}';
}

String fmtDate(String iso) {
  final d = parseDay(iso);
  return '${two(d.day)} ${kMonthShort[d.month - 1]} ${d.year}';
}

String fmtDateDMon(String iso) {
  final d = parseDay(iso);
  return '${two(d.day)} ${kMonthShort[d.month - 1]}';
}

const List<String> kWeekdayLong = <String>[
  'Monday',
  'Tuesday',
  'Wednesday',
  'Thursday',
  'Friday',
  'Saturday',
  'Sunday',
];

String fmtClock(int ts) {
  final d = DateTime.fromMillisecondsSinceEpoch(ts);
  final h = d.hour % 12 == 0 ? 12 : d.hour % 12;
  return '$h:${two(d.minute)} ${d.hour >= 12 ? 'pm' : 'am'}';
}

String fmtTime(int? ts) => ts == null ? '—' : fmtClock(ts);

String fmtTimeStatic(int? ts) => ts == null ? '—' : fmtClock(ts);

/// 9:37 — the register's own clock, for averages and shift starts.
String minToClock(int? m) {
  if (m == null) return '—';
  return '${m ~/ 60}:${two(m % 60)}';
}

String clockOf(int minutes) {
  final h = (minutes ~/ 60) % 24;
  final m = minutes % 60;
  final hh = h % 12 == 0 ? 12 : h % 12;
  return '$hh:${two(m)} ${h >= 12 ? 'pm' : 'am'}';
}

String nowClock() {
  final d = DateTime.now();
  final h = d.hour % 12 == 0 ? 12 : d.hour % 12;
  return '$h:${two(d.minute)}:${two(d.second)} ${d.hour >= 12 ? 'pm' : 'am'}';
}

String clockSeconds() {
  final d = DateTime.now();
  final h = d.hour % 12 == 0 ? 12 : d.hour % 12;
  return '$h:${two(d.minute)}:${two(d.second)} ${d.hour >= 12 ? 'pm' : 'am'}';
}

String fmtHours(int? minutes) {
  final m = (minutes ?? 0).abs();
  return '${m ~/ 60}h ${two(m % 60)}m';
}

String fmtHoursShort(int minutes) {
  final m = minutes.abs();
  if (m < 60) return '${m}m';
  return '${m ~/ 60}h ${two(m % 60)}m';
}

String fmtSignedHours(int minutes) {
  if (minutes == 0) return T('even');
  final sign = minutes > 0 ? '+' : '−';
  return '$sign${fmtHours(minutes)}';
}

/// 09:04 am style, short. A half-typed shift never throws: "9" reads as 09:00.
String fmtShift(String hhmm) {
  final total = hmToMinutes(hhmm);
  final h = (total ~/ 60) % 24;
  final m = total % 60;
  final hh = h % 12 == 0 ? 12 : h % 12;
  return '$hh:${two(m)} ${h >= 12 ? 'pm' : 'am'}';
}

String addMinutesLabel(String hhmm, int minutes) {
  final total = hmToMinutes(hhmm) + minutes;
  return fmtShift('${two((total ~/ 60) % 24)}:${two(total % 60)}');
}

String minToHHMM(int minutes) =>
    '${two((minutes ~/ 60).clamp(0, 23))}:${two(minutes % 60)}';

/// Minutes past midnight for a `HH:MM` shift. The office types these by hand,
/// so anything unreadable falls back to 00:00 instead of crashing the screen.
int hmToMinutes(String hhmm) {
  final p = hhmm.trim().split(':');
  final h = int.tryParse(p[0].trim()) ?? 0;
  final m = p.length > 1 ? int.tryParse(p[1].trim()) ?? 0 : 0;
  return h * 60 + m;
}

String yesNo(bool v) => v ? 'Yes' : 'No';

String fmtDist(double m) {
  if (m < 1000) return '${m.round()} m';
  return '${(m / 1000).toStringAsFixed(2)} km';
}

double haversineM(double lat1, double lng1, double lat2, double lng2) {
  const r = 6371000.0;
  double rad(double v) => v * math.pi / 180;
  final dLat = rad(lat2 - lat1);
  final dLng = rad(lng2 - lng1);
  final a =
      math.sin(dLat / 2) * math.sin(dLat / 2) +
      math.cos(rad(lat1)) *
          math.cos(rad(lat2)) *
          math.sin(dLng / 2) *
          math.sin(dLng / 2);
  return 2 * r * math.atan2(math.sqrt(a), math.sqrt(1 - a));
}

double bearingDeg(double lat1, double lng1, double lat2, double lng2) {
  double rad(double v) => v * math.pi / 180;
  final dLng = rad(lng2 - lng1);
  final y = math.sin(dLng) * math.cos(rad(lat2));
  final x =
      math.cos(rad(lat1)) * math.sin(rad(lat2)) -
      math.sin(rad(lat1)) * math.cos(rad(lat2)) * math.cos(dLng);
  return (math.atan2(y, x) * 180 / math.pi + 360) % 360;
}

String compassName(num brg) {
  const names = <String>[
    'north',
    'north-east',
    'east',
    'south-east',
    'south',
    'south-west',
    'west',
    'north-west',
  ];
  return names[((brg + 22.5) ~/ 45) % 8];
}

