class JskLogo extends StatelessWidget {
  const JskLogo({super.key, this.size = 62});

  final double size;

  @override
  Widget build(BuildContext context) => Image.memory(
    jskLogoData,
    width: size,
    height: size,
    fit: BoxFit.contain,
    filterQuality: FilterQuality.high,
    gaplessPlayback: true,
    semanticLabel: 'JSK Institute',
    errorBuilder: (context, error, stack) => _JskBadge(size: size),
  );
}

/// Drawn stand-in used only if the embedded bytes ever fail to decode.
class _JskBadge extends StatelessWidget {
  const _JskBadge({required this.size});

  final double size;

  @override
  Widget build(BuildContext context) => SizedBox(
    width: size,
    height: size,
    child: ColoredBox(
      color: Skin.navySolid,
      child: Center(
        child: FittedBox(
          fit: BoxFit.scaleDown,
          child: Padding(
            padding: EdgeInsets.symmetric(horizontal: size * .12),
            child: Text(
              'JSK',
              style: TextStyle(
                color: Colors.white,
                fontWeight: FontWeight.w800,
                fontSize: size * .34,
                letterSpacing: .2,
              ),
            ),
          ),
        ),
      ),
    ),
  );
}

/// Translate a UI string into the app's current language.
String T(String s) => Store.I.t(s);

/// Translate a template containing {0}, {1} … and fill the live values.
String TT(String tpl, List<Object?> args) {
  var out = Store.I.t(tpl);
  for (var i = 0; i < args.length; i++) {
    out = out.replaceAll('{$i}', '${args[i]}');
  }
  return out;
}

// FCM displays notifications while the app is backgrounded. Foreground pushes
// use the local notification channel so they also make the normal alert sound.
@pragma('vm:entry-point')
Future<void> _firebaseMessagingBackgroundHandler(RemoteMessage message) async {
  await Firebase.initializeApp();
}

class FcmPushService {
  static const String _androidChannelId = 'jsk_attendance_alerts_v2';
  static const String _androidChannelName = 'JSK Attendance alerts';
  static const local_notifications.AndroidNotificationChannel _androidChannel =
      local_notifications.AndroidNotificationChannel(
        _androidChannelId,
        _androidChannelName,
        description: 'Attendance, schedule, fee and institute updates.',
        importance: local_notifications.Importance.defaultImportance,
        playSound: true,
        enableVibration: true,
      );
  static final local_notifications.FlutterLocalNotificationsPlugin
  _localNotifications = local_notifications.FlutterLocalNotificationsPlugin();
  static final Set<String> _permissionPromptsInProgress = <String>{};
  static bool _available = false;
  static String? _registeredToken;
  static String? _registeredUserId;
  static StreamSubscription<String>? _tokenRefresh;
  static StreamSubscription<RemoteMessage>? _foregroundMessages;

  static bool pushEnabledForUser(String? userId) =>
      userId != null && Store.I.userById(userId)?['phoneNotifs'] == true;

  static Future<void> initialize() async {
    if (!Platform.isAndroid) return;
    try {
      await Firebase.initializeApp();
      FirebaseMessaging.onBackgroundMessage(
        _firebaseMessagingBackgroundHandler,
      );
    } catch (_) {
      debugPrint('FCM initialization failed.');
      return;
    }

    _available = true;
    try {
      await _localNotifications.initialize(
        const local_notifications.InitializationSettings(
          android: local_notifications.AndroidInitializationSettings(
            '@mipmap/ic_launcher',
          ),
        ),
      );
      await _localNotifications
          .resolvePlatformSpecificImplementation<
            local_notifications.AndroidFlutterLocalNotificationsPlugin
          >()
          ?.createNotificationChannel(_androidChannel);
    } catch (_) {
      debugPrint('Android notification channel setup failed.');
    }
    _foregroundMessages ??= FirebaseMessaging.onMessage.listen(
      _showForegroundMessage,
    );
    _tokenRefresh ??= FirebaseMessaging.instance.onTokenRefresh.listen((token) {
      final store = Store.I;
      final userId = store.userId;
      if (pushEnabledForUser(userId) && store.me?['phoneNotifs'] == true) {
        unawaited(_registerToken(token));
      }
    });
  }

  static Future<void> _showForegroundMessage(RemoteMessage message) async {
    final notification = message.notification;
    final title = notification?.title ?? message.data['title']?.toString();
    final body = notification?.body ?? message.data['body']?.toString();
    if ((title == null || title.isEmpty) && (body == null || body.isEmpty)) {
      return;
    }
    final id =
        message.messageId?.hashCode ?? DateTime.now().millisecondsSinceEpoch;
    await _localNotifications.show(
      id,
      title,
      body,
      const local_notifications.NotificationDetails(
        android: local_notifications.AndroidNotificationDetails(
          _androidChannelId,
          _androidChannelName,
          channelDescription:
              'Attendance, schedule, fee and institute updates.',
          importance: local_notifications.Importance.defaultImportance,
          priority: local_notifications.Priority.defaultPriority,
          playSound: true,
          enableVibration: true,
        ),
      ),
    );
  }

  static Future<bool> requestPermissionAndRegister() async {
    if (!_available || !Platform.isAndroid) return false;
    final store = Store.I;
    if (store.userId == null ||
        store.me == null ||
        store.sb?.auth.currentSession == null) {
      throw StateError('Sign in before enabling push notifications.');
    }
    final messaging = FirebaseMessaging.instance;
    final settings = await messaging.requestPermission(
      alert: true,
      badge: true,
      sound: true,
    );
    if (settings.authorizationStatus != AuthorizationStatus.authorized &&
        settings.authorizationStatus != AuthorizationStatus.provisional) {
      return false;
    }
    final token = await messaging.getToken();
    if (token == null || token.isEmpty) return false;
    await _registerToken(token);
    return true;
  }

  static Future<void> registerIfOptedIn() async {
    if (!_available || !Platform.isAndroid) return;
    final store = Store.I;
    final userId = store.userId;
    if (!pushEnabledForUser(userId) ||
        userId == null ||
        store.me?['phoneNotifs'] != true ||
        store.me == null ||
        store.sb?.auth.currentSession == null) {
      return;
    }
    try {
      final settings = await FirebaseMessaging.instance
          .getNotificationSettings();
      if (settings.authorizationStatus != AuthorizationStatus.authorized &&
          settings.authorizationStatus != AuthorizationStatus.provisional) {
        return;
      }
      final token = await FirebaseMessaging.instance.getToken();
      if (token != null && token.isNotEmpty) await _registerToken(token);
    } catch (_) {
      debugPrint('FCM token refresh failed.');
    }
  }

  /// Ask once after a user's first successful sign-in. Student and guardian
  /// accounts only need notifications; staff, teachers and admins also use
  /// location for check-in or the institute geofence.
  static Future<void> requestAfterAccountRegistration(
    BuildContext context,
  ) async {
    final store = Store.I;
    final userId = store.userId;
    final user = store.me;
    final prefs = store.prefs;
    if (!Platform.isAndroid ||
        userId == null ||
        user == null ||
        prefs == null) {
      return;
    }
    final promptKey = 'jsk_permissions_prompted_v1_$userId';
    if (prefs.getBool(promptKey) == true ||
        !_permissionPromptsInProgress.add(userId)) {
      return;
    }

    try {
      await Future<void>.delayed(const Duration(milliseconds: 700));
      if (store.userId != userId || store.me == null) return;

      final accountAlreadyOptedIn = store.me?['phoneNotifs'] == true;
      if (accountAlreadyOptedIn) {
        try {
          final granted = await requestPermissionAndRegister();
          if (!granted) {
            debugPrint('Push permission is not allowed on this device.');
          }
        } catch (_) {
          debugPrint('Push permission setup failed.');
        }
      } else {
        if (!context.mounted || store.userId != userId) return;
        final allowPush = await showDialog<bool>(
          context: context,
          builder: (dialogContext) => AlertDialog(
            title: const Text('Allow push notifications?'),
            content: const Text(
              'Get attendance, class schedule, fee and institute updates on this phone.',
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.of(dialogContext).pop(false),
                child: const Text("Don't allow"),
              ),
              FilledButton(
                onPressed: () => Navigator.of(dialogContext).pop(true),
                child: const Text('Allow'),
              ),
            ],
          ),
        );
        if (allowPush == true && context.mounted && store.userId == userId) {
          try {
            final granted = await requestPermissionAndRegister();
            if (granted && store.userId == userId) {
              final currentUser = store.me;
              if (currentUser != null) {
                currentUser['phoneNotifs'] = true;
                store.save();
              }
            }
          } catch (_) {
            debugPrint('Push permission setup failed.');
          }
        }
      }

      final role = store.me?['role']?.toString();
      if (role == 'admin' || role == 'teacher' || role == 'staff') {
        try {
          var permission = await Geolocator.checkPermission();
          if (permission == LocationPermission.denied) {
            await Geolocator.requestPermission();
          }
        } catch (_) {
          debugPrint('Location permission setup failed.');
        }
      }
    } finally {
      await prefs.setBool(promptKey, true);
      _permissionPromptsInProgress.remove(userId);
    }
  }

  static Future<void> _registerToken(String token) async {
    final store = Store.I;
    final client = store.sb;
    final userId = store.userId;
    if (client == null ||
        client.auth.currentSession == null ||
        userId == null ||
        store.me == null) {
      return;
    }
    if (_registeredToken == token && _registeredUserId == userId) return;
    final response = await client.functions.invoke(
      'jsk-sync',
      body: <String, dynamic>{
        'action': 'register_push_token',
        'token': token,
        'platform': 'android',
      },
    );
    if (response.data is! Map || response.data['ok'] != true) {
      throw StateError('Push token registration was rejected.');
    }
    _registeredToken = token;
    _registeredUserId = userId;
  }

  static Future<void> unregisterCurrent() async {
    final store = Store.I;
    final client = store.sb;
    final userId = store.userId;
    if (client == null ||
        client.auth.currentSession == null ||
        userId == null) {
      return;
    }
    try {
      final token = _registeredUserId == userId
          ? _registeredToken
          : await FirebaseMessaging.instance.getToken();
      if (token == null || token.isEmpty) return;
      final response = await client.functions.invoke(
        'jsk-sync',
        body: <String, dynamic>{
          'action': 'unregister_push_token',
          'token': token,
        },
      );
      if (response.data is Map && response.data['ok'] == true) {
        if (_registeredUserId == userId && _registeredToken == token) {
          _registeredToken = null;
          _registeredUserId = null;
        }
      }
    } catch (_) {
      debugPrint('Could not unregister the FCM device token.');
    }
  }
}

class Store extends ChangeNotifier {
  Store._();
  static final Store I = Store._();

  static const _prefState = 'jsk_state_v1';
  static const _prefSession = 'jsk_session_v1';
  static const _prefUi = 'jsk_ui_v1';

  final GlobalKey<ScaffoldMessengerState> messenger =
      GlobalKey<ScaffoldMessengerState>();

  Map<String, dynamic> data = <String, dynamic>{};
  SupabaseClient? sb;
  SharedPreferences? prefs;

  bool booted = false;
  bool online = false;
  bool saving = false;
  String? userId;

  // look & feel (device-local, like the web's state.ui)
  bool dark = true;
  int themeColor = 0;

  /// A colour the user mixed in Appearance — "#RRGGBB", empty when unused.
  String customColor = '';

  /// What the skin should paint with: the user's own colour when they set one,
  /// otherwise the recommended swatch they picked.
  Object get accentKey => customColor.isEmpty ? themeColor : customColor;
  int textSize = 1;
  int uiStyle = 0;

  static int appearanceIndex(Object? v, List<String> names, int fallback) {
    if (v is int) return v.clamp(0, names.length - 1);
    final t = (v ?? '').toString().toLowerCase().trim();
    if (t.isEmpty) return fallback;
    final n = int.tryParse(t);
    if (n != null) return n.clamp(0, names.length - 1);
    final i = names.indexOf(t);
    return i >= 0 ? i : fallback;
  }

  String language = 'en';

  // navigation memory
  String page = '';
  String? settingsSub;
  int sessionNonce = 0;
  String? viewStudentId;
  String? viewTeacherId;
  String? viewStaffId;
  String? teacherBatch;
  String? teacherSubject;
  String teacherDate = todayStr();
  String staffView = 'today';
  String? myAttMonth;
  int? inboxShown;
  int? leaveShown;
  String studentAttScope = 'overall';
  int studentLogShown = 10;
  String inboxFilter = 'all';

  /// The login details of the admin created or reset last — the web's
  /// `state.ui.lastAdminInvite`, kept so the office can still read them after
  /// switching tabs or coming back to this screen.
  Map<String, dynamic>? lastAdminInvite;

  Timer? _poll;
  Timer? _saveTimer;
  int _lastPush = 0;
  String? _cachedCloudUserId;

  Skin get skin => Skin(accentKey: accentKey, style: uiStyle);
  double get textScale =>
      const <double>[.88, 1.0, 1.12, 1.24][textSize.clamp(0, 3)];

  String t(String s) {
    final lang = language;
    if (lang == 'en') return s;
    return kI18n[lang]?[s] ?? s;
  }

  // ---------------- raw access ----------------
  List<dynamic> _raw(String k) {
    final v = data[k];
    if (v is List) return v;
    final l = <dynamic>[];
    data[k] = l;
    return l;
  }

  List<dynamic> rawList(String k) => _raw(k);
  List<Map<String, dynamic>> listOf(String k) =>
      _raw(k).whereType<Map>().map((e) => e.cast<String, dynamic>()).toList();

  List<Map<String, dynamic>> get users => listOf('users');
  List<Map<String, dynamic>> get students => listOf('students');
  List<Map<String, dynamic>> get batches => listOf('batches');
  List<Map<String, dynamic>> get subjects => listOf('subjects');
  List<Map<String, dynamic>> get assignments => listOf('assignments');
  List<Map<String, dynamic>> get attendance => listOf('attendance');
  List<Map<String, dynamic>> get staffRecords => listOf('staffRecords');
  List<Map<String, dynamic>> get staffNotifications =>
      listOf('staffNotifications');
  List<Map<String, dynamic>> get leaveRequests => listOf('leaveRequests');
  List<Map<String, dynamic>> get holidays => listOf('holidays');
  List<Map<String, dynamic>> get inbox => listOf('inbox');
  List<Map<String, dynamic>> get announcements => listOf('announcements');
  List<Map<String, dynamic>> get feePayments => listOf('feePayments');
  List<Map<String, dynamic>> get schedules => listOf('schedules');
  List<Map<String, dynamic>> get lateRemarks => listOf('lateRemarks');
  List<Map<String, dynamic>> get notes => listOf('notes');

  /// Every list that can carry a person, used when a photo is set or read.
  List<List<Map<String, dynamic>>> get _people => <List<Map<String, dynamic>>>[
    users,
    students,
    staffRecords,
  ];

  /// The display picture for a person, wherever they are recorded. A screen may
  /// be holding an older copy of the map, so the live record is checked too.
  String photoOf(Map<String, dynamic>? person) {
    if (person == null) return '';
    final own = (person['photo'] ?? '').toString();
    if (own.isNotEmpty) return own;
    final id = (person['id'] ?? '').toString();
    final login = (person['userId'] ?? '').toString();
    if (id.isEmpty && login.isEmpty) return '';
    for (final list in _people) {
      for (final rec in list) {
        final rid = (rec['id'] ?? '').toString();
        final rlogin = (rec['userId'] ?? '').toString();
        final mine =
            rid == id ||
            (rid.isNotEmpty && rlogin == id) ||
            (login.isNotEmpty && (rid == login || rlogin == login));
        if (!mine) continue;
        final photo = (rec['photo'] ?? '').toString();
        if (photo.isNotEmpty) return photo;
      }
    }
    return '';
  }

  /// Saves a display picture on the person and on the login that belongs to
  /// them, so the same face shows in the register, the lists and the ID card.
  void setPersonPhoto(String id, String dataUri) {
    if (id.isEmpty) return;
    final hits = <Map<String, dynamic>>[];
    for (final list in _people) {
      for (final rec in list) {
        if ((rec['id'] ?? '').toString() == id ||
            (rec['userId'] ?? '').toString() == id) {
          hits.add(rec);
        }
      }
    }
    // a student carries its login in userId — take the other side of the link
    for (final rec in hits.toList()) {
      final login = (rec['userId'] ?? '').toString();
      if (login.isEmpty) continue;
      for (final list in _people) {
        for (final other in list) {
          if ((other['id'] ?? '').toString() == login) hits.add(other);
        }
      }
    }
    for (final rec in hits) {
      rec['photo'] = dataUri;
    }
    notifyListeners();
    save();
  }

  /// a student sees what was shared with their batch or their standard, plus
  /// anything sent to the whole institute
  List<Map<String, dynamic>> notesFor(Map<String, dynamic> student) {
    final batch = (student['batchId'] ?? '').toString().trim();
    final std = (student['standard'] ?? '').toString().trim();
    final out = notes.where((n) {
      final b = (n['batchId'] ?? '').toString().trim();
      final st = (n['standard'] ?? '').toString().trim();
      if (b.isEmpty && st.isEmpty) return true;
      if (b.isNotEmpty && b == batch) return true;
      if (st.isNotEmpty && st == std) return true;
      return false;
    }).toList();
    out.sort(
      (a, b) => ((b['ts'] as num?) ?? 0).compareTo((a['ts'] as num?) ?? 0),
    );
    return out;
  }

  List<Map<String, dynamic>> notesBy(String userId) {
    final out = notes
        .where((n) => (n['byId'] ?? '').toString() == userId)
        .toList();
    out.sort(
      (a, b) => ((b['ts'] as num?) ?? 0).compareTo((a['ts'] as num?) ?? 0),
    );
    return out;
  }

  void addNote(Map<String, dynamic> n) {
    _raw('notes').insert(0, n);
    save();
  }

  void removeNote(String id) {
    _raw('notes').removeWhere((e) => e is Map && e['id'].toString() == id);
    save();
  }

  Map<String, dynamic> get geofence =>
      (data['geofence'] as Map?)?.cast<String, dynamic>() ??
      <String, dynamic>{};
  Map<String, dynamic> get settings =>
      (data['settings'] as Map?)?.cast<String, dynamic>() ??
      <String, dynamic>{};

  Map<String, dynamic>? userById(String? id) {
    for (final u in users) {
      if (u['id'] == id) return u;
    }
    return null;
  }

  Map<String, dynamic>? get me => userById(userId);
  String get role => me?['role']?.toString() ?? 'student';

  // ---------------- boot ----------------
  Future<void> boot() async {
    prefs = await SharedPreferences.getInstance();
    if (kSupabaseKey.isNotEmpty) {
      try {
        sb = Supabase.instance.client;
      } catch (_) {
        sb = null;
      }
    }
    final hasAuthSession = sb?.auth.currentSession != null;
    _cachedCloudUserId = hasAuthSession ? prefs!.getString(_prefSession) : null;
    final raw = hasAuthSession ? prefs!.getString(_prefState) : null;
    if (raw != null && raw.isNotEmpty) {
      try {
        data = Map<String, dynamic>.from(jsonDecode(raw) as Map);
      } catch (_) {}
    }
    if (data.isEmpty) data = hasAuthSession ? seedState() : <String, dynamic>{};
    userId = null;
    final uiRaw = prefs!.getString(_prefUi);
    if (uiRaw != null && uiRaw.isNotEmpty) {
      try {
        final ui = Map<String, dynamic>.from(jsonDecode(uiRaw) as Map);
        dark = ui['dark'] as bool? ?? true;
        themeColor = appearanceIndex(ui['themeColor'], [
          'violet',
          'blue',
          'pink',
          'green',
          'orange',
        ], 0);
        textSize = appearanceIndex(ui['textSize'], [
          'small',
          'default',
          'large',
          'xl',
          'extra large',
        ], 1);
        uiStyle = appearanceIndex(ui['uiStyle'], [
          'rounded',
          'soft',
          'crisp',
        ], 0);
        customColor = ui['customColor']?.toString() ?? '';
        if (Skin.colorFromHex(customColor) == null) customColor = '';
        language = ui['language']?.toString() ?? 'en';
        page = ui['page']?.toString() ?? '';
        lastAdminInvite = null;
      } catch (_) {
        themeColor = 0;
        textSize = 1;
        uiStyle = 0;
        dark = true;
      }
    }
    for (final user in _raw('users')) {
      if (user is Map) user.remove('password');
    }
    lastAdminInvite = null;
    await _writeLocal();
    await _writeUi();
    notifyListeners();

    await syncFromCloud();
    if (promoteStudents()) save();
    publishDueAnnouncements();
    ensureMonthlyFeeReminders();
    booted = true;
    notifyListeners();
    _poll = Timer.periodic(Duration(seconds: 30), (_) {
      unawaited(
        syncFromCloud(quiet: true).then((_) {
          if (promoteStudents()) save();
          publishDueAnnouncements();
          ensureMonthlyFeeReminders();
        }),
      );
    });
  }

  @override
  void dispose() {
    _poll?.cancel();
    super.dispose();
  }

  // ---------------- cloud ----------------
  List<dynamic> _tombstones() {
    final v = data['deletedIds'];
    if (v is List) return v;
    final l = <dynamic>[];
    data['deletedIds'] = l;
    return l;
  }

  Set<String> _tombSet() => {
    for (final t in _tombstones())
      if (t is Map && t['id'] != null) t['id'].toString(),
  };

  void tombAdd(String id) {
    _tombstones().add({'id': id, 'ts': DateTime.now().millisecondsSinceEpoch});
  }

  /// Records the ids of rows this device is about to remove. The cloud merge
  /// puts back any record it only finds remotely, so a deletion that is not
  /// recorded here came back on the next 30-second sync.
  void tombRows(Iterable<Map<String, dynamic>> rows) {
    for (final r in rows) {
      final id = (r['id'] ?? '').toString();
      if (id.isNotEmpty) tombAdd(id);
    }
  }

  static const _mergeKeys = [
    'staffRecords',
    'staffNotifications',
    'lateRemarks',
    'inbox',
    'announcements',
  ];

  // The website and this app share one cloud row, but each was written with its
  // own name for the same fact. Every record carries both names, so whoever
  // reads next — the office on the web, a phone in the corridor — sees the same
  // value instead of a blank.
  static const List<(String, String)> _userNames = <(String, String)>[
    ('shift', 'shiftTime'),
    ('target', 'completionTarget'),
    ('blood', 'bloodGroup'),
  ];
  static const List<(String, String)> _studentNames = <(String, String)>[
    ('target', 'targetPct'),
    ('blood', 'bloodGroup'),
    ('joined', 'admissionDate'),
  ];

  static bool _has(Object? v) => v != null && v.toString().trim().isNotEmpty;

  /// Copies a name onto its twin, but only where the twin is missing, so no
  /// value is ever overwritten by an empty one.
  static void _fillNames(Map<String, dynamic> r, List<(String, String)> pairs) {
    for (final (String app, String web) in pairs) {
      if (_has(r[app]) && !_has(r[web])) r[web] = r[app];
      if (_has(r[web]) && !_has(r[app])) r[app] = r[web];
    }
  }

  /// Copies one side onto the other, the way the last save expects it to read.
  static void _copyNames(
    Map<String, dynamic> r,
    List<(String, String)> pairs, {
    required bool fromWeb,
  }) {
    for (final (String app, String web) in pairs) {
      final Object? from = fromWeb ? r[web] : r[app];
      if (!_has(from)) continue;
      if (fromWeb) {
        r[app] = from;
      } else {
        r[web] = from;
      }
    }
  }

  /// The website saved last, so its names are the fresh ones.
  void adoptWebNames() {
    for (final r in rawList('users')) {
      _fillNames(r, _userNames);
      _copyNames(r, _userNames, fromWeb: true);
    }
    for (final r in rawList('students')) {
      _fillNames(r, _studentNames);
      _copyNames(r, _studentNames, fromWeb: true);
    }
  }

  /// This app saved last, so the website gets the value from here.
  void publishWebNames() {
    for (final r in rawList('users')) {
      _fillNames(r, _userNames);
      _copyNames(r, _userNames, fromWeb: false);
    }
    for (final r in rawList('students')) {
      _fillNames(r, _studentNames);
      _copyNames(r, _studentNames, fromWeb: false);
    }
  }

  void _mergeRemote(Map<String, dynamic> remote) {
    if (remote.isEmpty) return;
    final local = data;
    final tomb = _tombSet();
    final merged = <String, dynamic>{...local, ...remote};
    for (final k in _mergeKeys) {
      final incoming = ((remote[k] as List?) ?? [])
          .whereType<Map>()
          .map((e) => Map<String, dynamic>.from(e))
          .toList();
      final mine = ((local[k] as List?) ?? [])
          .whereType<Map>()
          .map((e) => Map<String, dynamic>.from(e))
          .toList();
      final byId = <String, Map<String, dynamic>>{
        for (final r in incoming)
          if (r['id'] != null) r['id'].toString(): r,
      };
      for (final r in incoming) {
        if (r['outTs'] == null) {
          for (final x in mine) {
            if (x['id'] == r['id'] && x['outTs'] != null) {
              r['outTs'] = x['outTs'];
              r['outDist'] = x['outDist'];
            }
          }
        }
      }
      for (final x in mine) {
        final id = x['id']?.toString() ?? '';
        if (id.isEmpty || tomb.contains(id)) continue;
        byId.putIfAbsent(id, () => x);
      }
      merged[k] = byId.values.toList();
    }
    if (local['deletedIds'] is List) {
      merged['deletedIds'] = local['deletedIds'];
    }
    data = merged;
    // the removed-login list only ever merges by union here; a copy from
    // another phone can never quietly re-enable an account the office deleted
    final mineGone = (local['removedLogins'] as List?) ?? const <dynamic>[];
    final theirsGone = (remote['removedLogins'] as List?) ?? const <dynamic>[];
    if (mineGone.isNotEmpty || theirsGone.isNotEmpty) {
      data['removedLogins'] = <String>{
        for (final e in <dynamic>[...mineGone, ...theirsGone]) e.toString(),
      }.toList();
    }
    // a row that was deleted here must not be put back by the merge
    final tombNow = _tombSet();
    if (tombNow.isNotEmpty) {
      for (final key in <String>['students', 'users']) {
        final v = data[key];
        if (v is! List) continue;
        data[key] = <dynamic>[
          for (final r in v)
            if (!(r is Map &&
                r['id'] != null &&
                tombNow.contains(r['id'].toString())))
              r,
        ];
      }
    }
    adoptWebNames();
  }

  Future<bool> syncFromCloud({bool quiet = false}) async {
    final client = sb;
    if (client == null || client.auth.currentSession == null) return false;
    final now = DateTime.now().millisecondsSinceEpoch;
    if (now - _lastPush < 12000) return true;
    try {
      final res = await client.functions.invoke(
        'jsk-sync',
        body: <String, dynamic>{'mode': 'pull'},
      );
      final response = res.data;
      if (response is! Map || response['content'] is! Map) {
        throw StateError('The JSK sync service returned no app data.');
      }
      final profile = response['profile'];
      final profileId = profile is Map ? (profile['id'] ?? '').toString() : '';
      if (profileId.isEmpty)
        throw StateError('The signed-in account is not active.');
      final remote = Map<String, dynamic>.from(response['content'] as Map);
      if (_cachedCloudUserId == profileId && data.isNotEmpty) {
        _mergeRemote(remote);
      } else {
        data = remote;
      }
      final role = profile is Map ? (profile['role'] ?? '').toString() : '';
      if (role != 'admin') {
        for (final user in _raw('users')) {
          if (user is Map) user.remove('password');
        }
      }
      userId = profileId;
      unawaited(FcmPushService.registerIfOptedIn());
      _cachedCloudUserId = profileId;
      await prefs?.setString(_prefSession, profileId);
      online = true;
      await _writeLocal();
      if (!quiet) notifyListeners();
      return true;
    } catch (_) {
      online = false;
      if (!quiet) notifyListeners();
      return false;
    }
  }

  Future<void> pushNow() async {
    publishWebNames();
    await _writeLocal();
    final client = sb;
    if (client == null || client.auth.currentSession == null) return;
    try {
      final res = await client.functions.invoke(
        'jsk-sync',
        body: <String, dynamic>{'mode': 'push', 'content': data},
      );
      final response = res.data;
      if (response is! Map || response['content'] is! Map) {
        throw StateError('The JSK sync service returned no saved data.');
      }
      data = Map<String, dynamic>.from(response['content'] as Map);
      final profile = response['profile'];
      if (profile is Map && profile['id'] != null) {
        userId = profile['id'].toString();
        _cachedCloudUserId = userId;
        if ((profile['role'] ?? '').toString() != 'admin') {
          for (final user in _raw('users')) {
            if (user is Map) user.remove('password');
          }
        }
      }
      await _writeLocal();
      _lastPush = DateTime.now().millisecondsSinceEpoch;
      online = true;
      notifyListeners();
    } catch (_) {
      online = false;
    }
  }

  Future<void> _writeLocal() async {
    try {
      final safe = Map<String, dynamic>.from(
        jsonDecode(jsonEncode(data)) as Map,
      );
      final users = safe['users'];
      if (users is List) {
        for (final user in users) {
          if (user is Map) user.remove('password');
        }
      }
      final ui = safe['ui'];
      if (ui is Map) ui.remove('lastAdminInvite');
      await prefs?.setString(_prefState, jsonEncode(safe));
    } catch (_) {}
  }

  Future<void> _writeUi() async {
    try {
      await prefs?.setString(
        _prefUi,
        jsonEncode({
          'dark': dark,
          'themeColor': themeColor,
          'customColor': customColor,
          'textSize': textSize,
          'uiStyle': uiStyle,
          'language': language,
          'page': page,
        }),
      );
    } catch (_) {}
  }

  void save({bool push = true}) {
    unawaited(_writeLocal());
    notifyListeners();
    if (!push) return;
    _saveTimer?.cancel();
    _saveTimer = Timer(Duration(milliseconds: 700), () async {
      if (saving) {
        save();
        return;
      }
      saving = true;
      await pushNow();
      saving = false;
    });
  }

  void clearSession() {
    userId = null;
    unawaited(prefs?.remove(_prefSession));
    notifyListeners();
  }

  // ---------------- look & feel ----------------
  void setDark(bool v) {
    dark = v;
    unawaited(_writeUi());
    notifyListeners();
  }

  void setThemeColor(int v) {
    // picking a recommended swatch drops any colour the user mixed
    themeColor = v.clamp(0, 4);
    customColor = '';
    unawaited(_writeUi());
    save();
  }

  void setCustomColor(Color c) {
    customColor = Skin.hexOf(c);
    unawaited(_writeUi());
