  /// Remembers the login details handed to a new admin (or a reset password)
  /// so the "Login details to share" card survives a tab switch.
  void setLastAdminInvite(Map<String, dynamic>? invite) {
    lastAdminInvite = invite;
    unawaited(_writeUi());
    notifyListeners();
  }

