  // ---------------- auth ----------------
  /// A login the office removed. It stays out for good, even when a stale copy
  /// of the account is still on another phone or in the cloud row, so the
  /// person only ever sees "Wrong ID and password."
  bool loginBlocked(String email) {
    final e = email.trim().toLowerCase();
    if (e.isEmpty) return false;
    final list = data['removedLogins'];
    if (list is! List) return false;
    for (final x in list) {
      if (x.toString() == e) return true;
    }
    return false;
  }

  void blockLogin(String email) {
    final e = email.trim().toLowerCase();
    if (e.isEmpty || loginBlocked(e)) return;
    final list = data['removedLogins'];
    if (list is List) {
      list.add(e);
    } else {
      data['removedLogins'] = <dynamic>[e];
    }
  }

  /// Called when a login is created again, so a re-added person can sign in.
  void allowLogin(String email) {
    final e = email.trim().toLowerCase();
    final list = data['removedLogins'];
    if (list is List) list.removeWhere((x) => x.toString() == e);
  }

  Future<Map<String, dynamic>> authenticate(
    String email,
    String password,
  ) async {
    final client = sb;
    if (client == null)
      throw StateError('The JSK account service is not configured.');
    final cleanEmail = email.trim().toLowerCase();
    try {
      await client.auth.signInWithPassword(
        email: cleanEmail,
        password: password,
      );
    } catch (firstError) {
      try {
        final migration = await client.functions.invoke(
          'jsk-sync',
          body: <String, dynamic>{
            'action': 'migrate_legacy_user',
            'email': cleanEmail,
            'password': password,
          },
        );
        final result = migration.data;
        if (result is Map && result['ok'] != true) {
          final code = (result['code'] ?? '').toString();
          if (code == 'rate_limited') {
            throw StateError('Too many attempts. Wait an hour and try again.');
          }
          throw StateError('The ID or password is incorrect.');
        }
        await client.auth.signInWithPassword(
          email: cleanEmail,
          password: password,
        );
      } catch (migrationError) {
        await client.auth.signOut();
        final message = migrationError.toString().toLowerCase();
        if (message.contains('rate_limited') ||
            message.contains('too many attempts')) {
          throw StateError('Too many attempts. Wait an hour and try again.');
        }
        throw StateError('The ID or password is incorrect.');
      }
    }
    final loaded = await syncFromCloud();
    final signedIn = me;
    if (!loaded || signedIn == null) {
      await client.auth.signOut();
      userId = null;
      throw StateError(
        'Could not load this account. Check the connection and try again.',
      );
    }
    await signIn(signedIn);
    return signedIn;
  }

  Future<Map<String, String>> requestAccountPasswordReset(
    String appUserId,
  ) async {
    final client = sb;
    if (client == null || client.auth.currentSession == null) {
      throw StateError('Sign in with a live Admin account first.');
    }
    final response = await client.functions.invoke(
      'jsk-sync',
      body: <String, dynamic>{
        'action': 'reset_account_password',
        'userId': appUserId,
      },
    );
    final result = response.data;
    if (result is! Map || result['ok'] != true) {
      final code = result is Map ? (result['code'] ?? '').toString() : '';
      final message = switch (code) {
        'account_not_found' => 'This account is no longer active.',
        'account_needs_secure_login' =>
          'This account needs an Admin to set its first secure password.',
        'account_conflict' =>
          'The login ID does not match its secured account. Ask an Admin to review it.',
        _ =>
          'Could not reset this account password. Try again after the web and app backend are updated.',
      };
      throw StateError(message);
    }
    return <String, String>{
      'email': (result['email'] ?? '').toString(),
      'temporaryPassword': (result['temporaryPassword'] ?? '').toString(),
    };
  }

  Future<void> signIn(Map<String, dynamic> u) async {
    sessionNonce++;
    settingsSub = null;
    viewStudentId = null;
    viewTeacherId = null;
    viewStaffId = null;
    userId = u['id'].toString();
    _cachedCloudUserId = userId;
    unawaited(prefs?.setString(_prefSession, userId!));
    page = u['role'] == 'admin'
        ? 'notices'
        : (u['role'] == 'teacher' || u['role'] == 'staff')
        ? 'attendance'
        : 'home';
    unawaited(_writeUi());
    save(push: false);
    unawaited(FcmPushService.registerIfOptedIn());
  }

  Future<void> logOut() async {
    await FcmPushService.unregisterCurrent();
    final client = sb;
    if (client != null) {
      try {
        await client.auth.signOut();
      } catch (_) {}
    }
    userId = null;
    _cachedCloudUserId = null;
    page = '';
    settingsSub = null;
    viewStudentId = null;
    viewTeacherId = null;
    viewStaffId = null;
    sessionNonce++;
    unawaited(prefs?.remove(_prefSession));
    unawaited(prefs?.remove(_prefState));
    data = <String, dynamic>{};
    unawaited(
      prefs?.setString(
        _prefUi,
        jsonEncode({
          'dark': dark,
          'themeColor': themeColor,
          'customColor': customColor,
          'textSize': textSize,
          'uiStyle': uiStyle,
          'language': language,
          'page': '',
        }),
      ),
    );
    notifyListeners();
    save(push: false);
  }
}

