// ---------------------------------------------------------------------------
//  BUSINESS RULES
// ---------------------------------------------------------------------------
extension JskLogic on Store {
  // ---- people ----
  Map<String, dynamic>? studentById(String? id) {
    for (final s in students) {
      if (s['id'] == id) return s;
    }
    return null;
  }

  // ---- year-end rollover: 11th -> 12th, 12th -> Previous year Student Data ----
  /// Everything a finishing 12th std student carries: profile, guardian,
  /// subject-wise attendance, months paid and their percentage — exactly what
  /// the website files under "Previous year Student Data".
  Map<String, dynamic> archiveEntryOf(Map<String, dynamic> st, String year) {
    final id = (st['id'] ?? '').toString();
    final months = <String>{};
    for (final f in feePayments) {
      if ((f['studentId'] ?? '').toString() == id) {
        final m = (f['month'] ?? '').toString();
        if (m.isNotEmpty) months.add(m);
      }
    }
    final paid = months.toList()..sort();
    final recs = studentRecords(id);
    final stats = statsOf(recs);
    return <String, dynamic>{
      'id': st['id'],
      'userId': st['userId'],
      'name': (st['name'] ?? '').toString(),
      'batchId': st['batchId'],
      'batchName': batchName(st['batchId']),
      'standard': '12th',
      'course': (st['course'] ?? '').toString(),
      'scienceGroup': (st['scienceGroup'] ?? '').toString(),
      'dob': (st['dob'] ?? '').toString(),
      'gender': (st['gender'] ?? '').toString(),
      'bloodGroup': (st['bloodGroup'] ?? '').toString(),
      'phone': (st['phone'] ?? '').toString(),
      'email': (st['email'] ?? '').toString(),
      'address': (st['address'] ?? '').toString(),
      'city': (st['city'] ?? '').toString(),
      'birthplace': (st['birthplace'] ?? '').toString(),
      'admissionDate': (st['admissionDate'] ?? '').toString(),
      'guardianName': (st['guardianName'] ?? '').toString(),
      'guardianRelation': (st['guardianRelation'] ?? '').toString(),
      'guardianContact': (st['guardianContact'] ?? '').toString(),
      'additionalGuardians': st['additionalGuardians'] ?? <dynamic>[],
      'attPct': pctOf(stats) ?? '',
      'attPresent': stats.present,
      'attTotal': stats.total,
      'attendance': <Map<String, String>>[
        for (final r in recs.reversed)
          <String, String>{
            'date': (r['date'] ?? '').toString(),
            'subject': subjectName(r['subjectId']),
            'batch': batchName(r['batchId']),
            'status': (r['status'] ?? '').toString(),
          },
      ],
      'subjects': <String>[
        for (final x in studentSubjects(this, st)) (x['name'] ?? '').toString(),
      ],
      'feesPaid': paid,
      'academicYear': year,
      'savedOn': todayStr(),
    };
  }

  /// The stored archive, year by year. The rollover only ever adds to it.
  Map<String, dynamic> get previousYears {
    final v = data['previousYears'];
    if (v is Map) return v.cast<String, dynamic>();
    final fresh = <String, dynamic>{};
    data['previousYears'] = fresh;
    return fresh;
  }

  /// Files the entries under a year: a student already stored is replaced, and
  /// everything saved for the other years is left exactly as it was.
  int archiveStudents(String year, List<Map<String, dynamic>> entries) {
    final store = previousYears;
    final list = <Map<String, dynamic>>[
      for (final e in (store[year] as List?) ?? const <dynamic>[])
        if (e is Map) e.cast<String, dynamic>(),
    ];
    for (final e in entries) {
      final at = list.indexWhere((x) => x['id'] == e['id']);
      if (at >= 0) {
        list[at] = e;
      } else {
        list.add(e);
      }
    }
    store[year] = list;
    return list.length;
  }

  /// Removes every live trace of the given students — profile, student login,
  /// a guardian login left without any child, attendance, fee marks and the
  /// inbox. The archived copy is never touched by this.
  int purgeStudents(List<Map<String, dynamic>> gone) {
    if (gone.isEmpty) return 0;
    final ids = <String>{};
    final userIds = <String>{};
    final guardianIds = <String>{};
    for (final st in gone) {
      ids.add((st['id'] ?? '').toString());
      final u = (st['userId'] ?? '').toString();
      if (u.isNotEmpty) userIds.add(u);
      final g = (st['guardianUserId'] ?? '').toString();
      if (g.isNotEmpty) guardianIds.add(g);
      final more = st['additionalGuardians'];
      if (more is List) {
        for (final m in more) {
          if (m is Map) {
            final gu = (m['userId'] ?? '').toString();
            if (gu.isNotEmpty) guardianIds.add(gu);
          }
        }
      }
    }
    data['students'] = <Map<String, dynamic>>[
      for (final x in students)
        if (!ids.contains((x['id'] ?? '').toString())) x,
    ];
    final stillGuardianOf = <String>{
      for (final x in students) (x['guardianUserId'] ?? '').toString(),
    };
    final keptUsers = <Map<String, dynamic>>[
      for (final u in users)
        if (!userIds.contains((u['id'] ?? '').toString()) &&
            (!guardianIds.contains((u['id'] ?? '').toString()) ||
                stillGuardianOf.contains((u['id'] ?? '').toString())))
          u,
    ];
    final goneUsers = <Map<String, dynamic>>[
      for (final u in users)
        if (!keptUsers.any((x) => x['id'] == u['id'])) u,
    ];
    tombRows(goneUsers);
    for (final u in goneUsers) {
      blockLogin((u['email'] ?? '').toString());
    }
    data['users'] = keptUsers;
    // attendance and fee marks belong to the student, so they go with them
    for (final key in <String>['attendance', 'feePayments']) {
      final going = <Map<String, dynamic>>[
        for (final r in listOf(key))
          if (ids.contains((r['studentId'] ?? '').toString())) r,
      ];
      tombRows(going);
      data[key] = <Map<String, dynamic>>[
        for (final r in listOf(key))
          if (!ids.contains((r['studentId'] ?? '').toString())) r,
      ];
    }
    final remainingUsers = <String>{
      for (final u in users) (u['id'] ?? '').toString(),
    };
    tombRows(<Map<String, dynamic>>[
      ...gone,
      ...inbox.where(
        (n) =>
            ids.contains((n['studentId'] ?? '').toString()) ||
            userIds.contains((n['recipientUserId'] ?? '').toString()) ||
            (guardianIds.contains((n['recipientUserId'] ?? '').toString()) &&
                !remainingUsers.contains(
                  (n['recipientUserId'] ?? '').toString(),
                )),
      ),
    ]);
    data['inbox'] = <Map<String, dynamic>>[
      for (final n in inbox)
        if (!ids.contains((n['studentId'] ?? '').toString()) &&
            !userIds.contains((n['recipientUserId'] ?? '').toString()) &&
            !(guardianIds.contains((n['recipientUserId'] ?? '').toString()) &&
                !remainingUsers.contains(
                  (n['recipientUserId'] ?? '').toString(),
                )))
          n,
    ];
    return gone.length;
  }

  /// Archive first, then clear. The rollover and the admin's "Complete 12th"
  /// both go through here, so the two paths behave identically.
  int completeStudents(List<Map<String, dynamic>> list, [String? year]) {
    final grads = <Map<String, dynamic>>[
      for (final x in list)
        if (x.isNotEmpty) x,
    ];
    if (grads.isEmpty) return 0;
    final yy = (year ?? '').isEmpty ? academicYearLabelFor('12th') : '$year';
    final entries = <Map<String, dynamic>>[
      for (final st in grads) archiveEntryOf(st, yy),
    ];
    archiveStudents(yy, entries);
    purgeStudents(grads);
    return entries.length;
  }

  /// Once a year, after the finals on 15 June: every 12th std student's full
  /// record is filed in Previous year Student Data and then removed from the
  /// live app, and the 11th std students move up to 12th — so only the current
  /// 11th and 12th std stay visible.
  bool promoteStudents() {
    final y = currentPromoYear();
    final last = data['lastPromotionYear'];
    final lastYear = last is int ? last : int.tryParse('$last') ?? 0;
    if (lastYear >= y) return false;
    final grads = students.where(isTwelfth).toList();
    if (grads.isNotEmpty) completeStudents(grads, academicYearLabelFor('12th'));
    for (final st in students) {
      final std = (st['standard'] ?? '').toString().trim().toLowerCase();
      if (std == '11th' || std == '11' || std == 'xi') st['standard'] = '12th';
    }
    data['lastPromotionYear'] = y;
    return true;
  }

  Map<String, dynamic>? studentOfUser(String? uid) {
    if (uid == null) return null;
    for (final s in students) {
      if (s['userId'] == uid || s['guardianUserId'] == uid) return s;
    }
    return null;
  }

  Map<String, dynamic>? guardianStudent(String uid) {
    for (final s in students) {
      if (s['guardianUserId'] == uid) return s;
    }
    return null;
  }

  String batchName(Object? id) {
    if (id == null || id.toString().isEmpty) return NOT_DECIDED;
    for (final b in batches) {
      if (b['id'] == id) return b['name'].toString();
    }
    return NOT_DECIDED;
  }

  String subjectName(Object? id) {
    for (final s in subjects) {
      if (s['id'] == id) return s['name'].toString();
    }
    return '—';
  }

  List<Map<String, dynamic>> studentsInBatch(Object? batchId) =>
      students.where((s) => s['batchId'] == batchId).toList();

  List<Map<String, dynamic>> teacherAssignments(String teacherId) =>
      assignments.where((a) => a['teacherId'] == teacherId).toList();

  List<Map<String, dynamic>> assignedBatches(String teacherId) {
    final ids = teacherAssignments(teacherId).map((a) => a['batchId']).toSet();
    return batches.where((b) => ids.contains(b['id'])).toList();
  }

  List<Map<String, dynamic>> assignedSubjects(
    String teacherId,
    Object? batchId,
  ) {
    final ids = teacherAssignments(
      teacherId,
    ).where((a) => a['batchId'] == batchId).map((a) => a['subjectId']).toSet();
    return subjects.where((s) => ids.contains(s['id'])).toList();
  }

  // ---- calendar ----
  /// Every day of the month is a working day. The app keeps no holiday rule at
  /// all any more, so no count anywhere ever skips a date.
  Map<String, dynamic>? holidayOn(String date) => null;

  bool isSundayStr(String date) {
    try {
      return parseDay(date).weekday == DateTime.sunday;
    } catch (_) {
      return false;
    }
  }

  List<Map<String, dynamic>> lateDaysOf(Map<String, dynamic> u) {
    final v = u['lateDays'];
    if (v is List) {
      return v.whereType<Map>().map((e) => e.cast<String, dynamic>()).toList();
    }
    return <Map<String, dynamic>>[];
  }

  Map<String, dynamic>? specialDayOf(Map<String, dynamic> u, String date) {
    final day = parseDay(date).weekday;
    const names = [
      'Monday',
      'Tuesday',
      'Wednesday',
      'Thursday',
      'Friday',
      'Saturday',
      'Sunday',
    ];
    for (final d in lateDaysOf(u)) {
      if (d['day'] == names[day - 1]) return d;
    }
    return null;
  }

  String shiftOf(Map<String, dynamic> u) =>
      (u['shift'] ?? '09:00').toString().padLeft(5, '0');

  String shiftEndOf(Map<String, dynamic> u) =>
      (u['shiftEnd'] ?? '17:30').toString();

  double targetOf(Map<String, dynamic> u) {
    final v = u['target'];
    return v is num ? v.toDouble() : 8;
  }

  bool isMonthlyRole(Map<String, dynamic> u) => u['role'] == 'teacher';

  double monthlyTargetOf(Map<String, dynamic> u) {
    final v = u['monthlyTarget'];
    return v is num ? v.toDouble() : 120;
  }

  ({String start, String end}) shiftForDay(
    Map<String, dynamic> u,
    String date,
  ) {
    final sp = specialDayOf(u, date);
    if (sp != null) {
      return (
        start: (sp['start'] ?? '10:00').toString(),
        end: (sp['end'] ?? '14:00').toString(),
      );
    }
    return (start: shiftOf(u), end: shiftEndOf(u));
  }

  String weekKeyOf(String date) {
    final d = parseDay(date);
    final monday = d.subtract(Duration(days: d.weekday - 1));
    return '${monday.year}-${two(monday.month)}-${two(monday.day)}';
  }

  String addDays(String date, int n) {
    final d = parseDay(date).add(Duration(days: n));
    return '${d.year}-${two(d.month)}-${two(d.day)}';
  }

  // ---- staff records ----
  Map<String, dynamic>? staffRecordOn(String uid, String date) {
    for (final r in staffRecords) {
      if (r['userId'] == uid && r['date'] == date) return r;
    }
    return null;
  }

  Map<String, dynamic>? staffToday(String uid) =>
      staffRecordOn(uid, todayStr());

  int workedMs(Map<String, dynamic>? r) {
    if (r == null) return 0;
    final inn = r['inTs'];
    if (inn is! num) return 0;
    final out = r['outTs'];
    final end = out is num
        ? out.toInt()
        : DateTime.now().millisecondsSinceEpoch;
    return math.max(0, end - inn.toInt());
  }

  void evaluateLate(Map<String, dynamic> rec, Map<String, dynamic> u) {
    final inn = rec['inTs'];
    if (inn is! num) return;
    if (isMonthlyRole(u)) {
      rec['late'] = false;
      rec['lateMin'] = 0;
      return;
    }
    final date = rec['date'].toString();
    final sh = shiftForDay(u, date);
    final d = DateTime.fromMillisecondsSinceEpoch(inn.toInt());
    final startMin = hmToMinutes(sh.start);
    final startTs = DateTime(
      d.year,
      d.month,
      d.day,
      (startMin ~/ 60) % 24,
      startMin % 60,
    ).millisecondsSinceEpoch;
    // the minutes shown are the full lateness from the shift start, the grace
    // only decides whether it counts as late at all
    final lateMin = ((inn.toInt() - startTs) / 60000).floor();
    rec['lateMin'] = lateMin > 0 ? lateMin : 0;
    rec['late'] = lateMin > SHIFT_GRACE_MIN;
  }

  bool dayComplete(Map<String, dynamic>? rec, Map<String, dynamic> u) {
    if (rec == null) return false;
    if (isMonthlyRole(u)) return false;
    if (rec['outTs'] == null) return false;
    return workedMs(rec) >= targetOf(u) * 3600000;
  }

  int? recDeltaMin(Map<String, dynamic>? rec, Map<String, dynamic> u) {
    if (rec == null || rec['outTs'] == null) return null;
    if (isMonthlyRole(u)) return null;
    return ((workedMs(rec) - targetOf(u) * 3600000) / 60000).round();
  }

  List<Map<String, dynamic>> monthStaffRecords(String uid, String ym) =>
      staffRecords
          .where((r) => r['userId'] == uid && ymOf(r['date'].toString()) == ym)
          .toList()
        ..sort((a, b) => a['date'].toString().compareTo(b['date'].toString()));

  List<String> missedCheckoutDaysOf(String uid, String ym) {
    final u = userById(uid);
    if (u == null) return [];
    return monthStaffRecords(uid, ym)
        .where((r) => r['outTs'] == null && r['date'] != todayStr())
        .map((r) => r['date'].toString())
        .toList();
  }

  List<String> plDaysOf(String uid, String ym) {
    final u = userById(uid);
    if (u == null) return [];
    final leaves = leaveRequests.where((r) => r['userId'] == uid).toList();
    bool skip(String date) => leaves.any((l) {
      if (l['date'] != date) return false;
      final st = (l['status'] ?? 'pending').toString();
      return st == 'accepted' || st == 'pending' || st == 'approved';
    });
    final out = <String>[];
    final monthStart = parseDay('$ym-01');
    final daysInMonth = DateTime(monthStart.year, monthStart.month + 1, 0).day;
    for (var day = 1; day <= daysInMonth; day++) {
      final dstr = '$ym-${two(day)}';
      final d = parseDay(dstr);
      if (d.isAfter(DateTime.now())) continue;
      if (staffRecordOn(uid, dstr) != null) continue;
      if (skip(dstr)) continue;
      out.add(dstr);
    }
    return out;
  }

  int hoursBalanceOf(String uid, [String? month]) {
    final u = userById(uid);
    if (u == null) return 0;
    final ym = month ?? ymOf(todayStr());
    final mins = <String, int>{};
    final today = todayStr();

    final targetMin = (targetOf(u) * 60).round();
    final monthlyRole = isMonthlyRole(u);
    for (final r in staffRecords.where((r) => r['userId'] == uid)) {
      final date = r['date'].toString();
      if (ymOf(date) != ym) continue;
      final ts = r['inTs'];
      if (ts is! num) continue;
      final outTs = r['outTs'];
      if (monthlyRole) {
        // a teacher is measured on the month, so the bank keeps the plain count
        final ms = outTs is num
            ? (outTs.toInt() - ts.toInt())
            : (date == today
                  ? DateTime.now().millisecondsSinceEpoch - ts.toInt()
                  : 0);
        if (ms > 0) mins[date] = (mins[date] ?? 0) + ms ~/ 60000;
        continue;
      }
      if (outTs is num) {
        // A finished day is scored against the target: the overtime goes into
        // the bank and the hours not completed come straight out of it — so a
        // late arrival who leaves before finishing the hours is minus.
        final worked = (outTs.toInt() - ts.toInt()) ~/ 60000;
        mins[date] = (mins[date] ?? 0) + (worked - targetMin);
      } else if (date == today) {
        // still checked in: only overtime counts, a shortfall waits for the
        // check-out so the day is never punished while it is running
        final soFar =
            (DateTime.now().millisecondsSinceEpoch - ts.toInt()) ~/ 60000;
        if (soFar > targetMin) {
          mins[date] = (mins[date] ?? 0) + (soFar - targetMin);
        }
      }
    }
    // forgetting to check out costs 10 minutes for that day
    for (final d in missedCheckoutDaysOf(uid, ym)) {
      mins[d] = (mins[d] ?? 0) - MISSED_CHECKOUT_MIN;
    }
    // A late check-in only costs 10 minutes when the day's hours were not
    // completed — a late arrival who stays and finishes owes nothing. A day
    // still on the clock is never charged for being late.
    for (final r in monthStaffRecords(uid, ym)) {
      if (r['late'] != true) continue;
      if (r['outTs'] == null) continue;
      if (dayComplete(r, u)) continue;
      final d = r['date'].toString();
      mins[d] = (mins[d] ?? 0) - MISSED_CHECKOUT_MIN;
    }
    // a day off the office did not accept also costs 10 minutes. Accepted,
    // pending and never-requested days stay neutral.
    for (final r in leaveRequests.where((r) => r['userId'] == uid)) {
      if (r['status'] != 'declined') continue;
      final d = r['date'].toString();
      if (ymOf(d) != ym) continue;
      mins[d] = (mins[d] ?? 0) - MISSED_CHECKOUT_MIN;
    }
    for (final a
        in (data['hourAdjustments'] as List? ?? []).whereType<Map>().where(
          (a) => a['userId'] == uid,
        )) {
      final date = a['date'].toString();
      if (ymOf(date) != ym) continue;
      final m = a['minutes'];
      if (m is num) mins[date] = (mins[date] ?? 0) + m.toInt();
    }
    var total = 0;
    for (final m in mins.values) {
      total += m;
    }
    final capped = total.clamp(-MINUS_CAP_MIN, MAX_BANK_MIN);
    return capped.toInt();
  }

  int monthWorkedMin(String uid, String ym) {
    var total = 0;
    for (final r in monthStaffRecords(uid, ym)) {
      total += workedMs(r) ~/ 60000;
    }
    return total;
  }

  /// One person, one month: days present, time on campus, average in and out.
  ({int days, int totalMs, int? inAvg, int? outAvg, int outCount})
  staffMonthStatsOf(String uid, String ym) {
    final counted = monthStaffRecords(uid, ym);
    var inSum = 0;
    var outSum = 0;
    var totalMs = 0;
    var outCount = 0;
    var days = 0;
    for (final r in counted) {
      final inn = r['inTs'];
      if (inn is! num) continue;
      days++;
      final d = DateTime.fromMillisecondsSinceEpoch(inn.toInt());
      inSum += d.hour * 60 + d.minute;
      final out = r['outTs'];
      if (out is num) {
        outCount++;
        totalMs += math.max(0, out.toInt() - inn.toInt());
        final o = DateTime.fromMillisecondsSinceEpoch(out.toInt());
        outSum += o.hour * 60 + o.minute;
      }
    }
    return (
      days: days,
      totalMs: totalMs,
      inAvg: counted.isEmpty ? null : (inSum / counted.length).round(),
      outAvg: outCount == 0 ? null : (outSum / outCount).round(),
      outCount: outCount,
    );
  }

  /// Late remarks only for one role — the teacher page must never show staff.
  List<Map<String, dynamic>> lateRemarksFor(String role) {
    final out = lateRemarks.where((r) {
      final u = userById((r['userId'] ?? '').toString());
      return u != null && u['role'] == role;
    }).toList();
    out.sort(
      (a, b) => ((b['inTs'] as num?) ?? 0).compareTo((a['inTs'] as num?) ?? 0),
    );
    return out;
  }

  int monthDaysCompleted(String uid, String ym) {
    final u = userById(uid);
    if (u == null) return 0;
    return monthStaffRecords(uid, ym).where((r) => dayComplete(r, u)).length;
  }

  int staffMonthCount(String uid) =>
      staffRecords.where((r) => r['userId'] == uid).length;

  int effectiveTargetMinForMonth(Map<String, dynamic> u, String ym) {
    final start = parseDay('$ym-01');
    final workingDays = DateTime(start.year, start.month + 1, 0).day;
    final accepted = acceptedLeaveDaysOf(u['id'].toString(), ym).length;
    if (isMonthlyRole(u)) {
      return ((workingDays - accepted) * 60).clamp(0, 100000);
    }
    return workingDays * (targetOf(u) * 60).round();
  }

  List<String> acceptedLeaveDaysOf(String uid, String ym) => leaveRequests
      .where(
        (r) =>
            r['userId'] == uid &&
            r['status'] == 'accepted' &&
            ymOf(r['date'].toString()) == ym,
      )
      .map((r) => r['date'].toString())
      .toList();

  /// Every day counts, so the working days in a month are simply its days.
  double workingDaysInMonth(String ym) {
    final start = parseDay('$ym-01');
    return DateTime(start.year, start.month + 1, 0).day.toDouble();
  }

  // ---- leave requests ----
  List<Map<String, dynamic>> leaveRequestsOf(String uid) {
    final list = leaveRequests.where((r) => r['userId'] == uid).toList();
    list.sort((a, b) => (b['ts'] as num? ?? 0).compareTo(a['ts'] as num? ?? 0));
    return list;
  }

  List<({String id, List<Map<String, dynamic>> days})> leaveGroupsOf(
    String uid,
  ) {
    final groups = <String, List<Map<String, dynamic>>>{};
    final order = <String>[];
    for (final r in leaveRequestsOf(uid)) {
      final gid = (r['groupId'] ?? r['id']).toString();
      if (!groups.containsKey(gid)) {
        groups[gid] = [];
        order.add(gid);
      }
      groups[gid]!.add(r);
    }
    return [for (final gid in order) (id: gid, days: groups[gid]!)];
  }

  String leaveRangeLabel(List<Map<String, dynamic>> days) {
    final ds = days.map((d) => d['date'].toString()).toList()..sort();
    if (ds.isEmpty) return '—';
    if (ds.length == 1) return fmtDate(ds.first);
    return '${fmtDate(ds.first)} – ${fmtDate(ds.last)} (${ds.length} days)';
  }

  int leaveWeekCount(String uid, String weekKey) => leaveRequests
      .where(
        (r) =>
            r['userId'] == uid &&
            r['status'] != 'declined' &&
            weekKeyOf(r['date'].toString()) == weekKey,
      )
      .length;

  // ---- attendance ----
  Map<String, dynamic>? attendanceFor(
    String studentId,
    String batchId,
    String subjectId,
    String date,
  ) {
    for (final a in attendance) {
      if (a['studentId'] == studentId &&
          a['batchId'] == batchId &&
          a['subjectId'] == subjectId &&
          a['date'] == date) {
        return a;
      }
    }
    return null;
  }

  List<Map<String, dynamic>> studentRecords(String studentId) =>
      attendance.where((a) => a['studentId'] == studentId).toList()
        ..sort((a, b) => b['date'].toString().compareTo(a['date'].toString()));

  ({int present, int absent, int total}) statsOf(
    List<Map<String, dynamic>> recs,
  ) {
    var p = 0;
    var a = 0;
    for (final r in recs) {
      if (r['status'] == 'present') {
        p++;
      } else {
        a++;
      }
    }
    return (present: p, absent: a, total: p + a);
  }

  int? pctOf(({int present, int absent, int total}) st) =>
      st.total == 0 ? null : ((st.present * 100) / st.total).round();

  List<String> monthsOf(String studentId) {
    final set = <String>{};
    for (final r in studentRecords(studentId)) {
      set.add(ymOf(r['date'].toString()));
    }
    final list = set.toList()..sort((a, b) => b.compareTo(a));
    return list;
  }

  int studentTarget(Map<String, dynamic> s) {
    final v = s['target'];
    if (v is! num || v < 1) return 75;
    return v.round().clamp(1, 100);
  }

  ({int present, int absent, int total}) subjectStats(
    Map<String, dynamic> s,
    String subjectId,
    String? scopeYm,
  ) {
    final recs = studentRecords(s['id'].toString()).where(
      (r) =>
          r['subjectId'] == subjectId &&
          (scopeYm == null || ymOf(r['date'].toString()) == scopeYm),
    );
    return statsOf(recs.toList());
  }

  List<({String date, int value})> trendPoints(
    List<Map<String, dynamic>> recs,
    int weeks,
  ) {
    final out = <({String date, int value})>[];
    for (var w = weeks - 1; w >= 0; w--) {
      final end = DateTime.now().subtract(Duration(days: w * 7));
      final start = end.subtract(Duration(days: 6));
      final inWeek = recs.where((r) {
        final d = parseDay(r['date'].toString());
        return !d.isBefore(DateTime(start.year, start.month, start.day)) &&
            !d.isAfter(DateTime(end.year, end.month, end.day));
      }).toList();
      final st = statsOf(inWeek);
      final p = pctOf(st);
      out.add((date: '${start.day}/${start.month}', value: p ?? 0));
    }
    return out;
  }

  int currentStreak(List<Map<String, dynamic>> recs) {
    var n = 0;
    for (final r in recs) {
      if (r['status'] == 'present') {
        n++;
      } else {
        break;
      }
    }
    return n;
  }

  ({int count, bool canMiss}) bufferOf(
    ({int present, int absent, int total}) st,
    int target,
  ) {
    if (st.total == 0) return (count: 0, canMiss: false);
    final pct = (st.present * 100) / st.total;
    if (pct >= target) {
      var n = 0;
      while (n < 200 && (((st.present) * 100) / (st.total + n + 1)) >= target) {
        n++;
      }
      return (count: n, canMiss: true);
    }
    var n = 0;
    while (n < 400 && (((st.present + n) * 100) / (st.total + n)) < target) {
      n++;
    }
    return (count: n, canMiss: false);
  }

  // ---- fees (PAID / NOT PAID only) ----
  List<Map<String, dynamic>> feePaymentsFor(String studentId, String ym) =>
      feePayments
          .where((p) => p['studentId'] == studentId && p['month'] == ym)
          .toList()
        ..sort(
          (a, b) => (a['ts'] as num? ?? 0).compareTo(b['ts'] as num? ?? 0),
        );

  ({bool paid, String status}) feeStatusOf(String studentId, String ym) {
    final paid = feePaymentsFor(studentId, ym).isNotEmpty;
    return (paid: paid, status: paid ? 'PAID' : 'NOT PAID');
  }

  void feeMarkPaid(String studentId, String ym) {
    if (feeStatusOf(studentId, ym).paid) return;
    // rawList, not the feePayments getter: that one hands back a copy and the
    // new record would be thrown away (marking paid never stuck).
    rawList('feePayments').add({
      'id': uid('feepay'),
      'studentId': studentId,
      'month': ym,
      'date': todayStr(),
      'by': me?['name'] ?? 'Office',
      'ts': DateTime.now().millisecondsSinceEpoch,
    });
    ntRemoveByRef('fee_period', '$studentId|$ym');
    save();
  }

  void feeUndo(String studentId, String ym) {
    final keep = feePayments
        .where((p) => !(p['studentId'] == studentId && p['month'] == ym))
        .toList();
    data['feePayments'] = keep;
    // not paid again means the reminder comes back, once, for this month
    final st = studentById(studentId);
    if (st != null) feeRemindOne(st, ym);
    save();
  }

  // ---- fee reminder: the office's line, once a month, until marked paid ----
  /// Word for word what the office asked for. The month is filled in when it
  /// is sent, so one line covers every month.
  String feeReminderMessage(String ym, [String? studentName]) =>
      '${T('Monthly fee reminder: the fees for')} ${monthLabel(ym)} '
      '${T('are NOT PAID yet.')}'
      '${(studentName ?? '').isEmpty ? '' : ' ${T('Student')}: $studentName.'}'
      ' ${T('Month')}: ${monthLabel(ym)}. '
      '${T('Please pay at the institute office.')}';

  /// The student's own login and the guardian login each get one copy.
  int feeRemindOne(Map<String, dynamic> student, String ym) {
    final id = student['id'].toString();
    var sent = 0;
    for (final userId in <String>[
      (student['userId'] ?? '').toString(),
      (student['guardianUserId'] ?? '').toString(),
    ]) {
      if (userId.isEmpty) continue;
      ntPush(
        userId: userId,
        type: 'fee',
        title: 'JSK Institute Fees Reminder',
        message: feeReminderMessage(ym, (student['name'] ?? '').toString()),
        refType: 'fee_period',
        refId: '$id|$ym',
        dedupKey: 'fee_$id|$ym',
      );
      sent++;
    }
    return sent;
  }

  /// Every student still not marked paid for that month, nobody else.
  int sendFeeRemindersForMonth(String ym) {
    var sent = 0;
    for (final st in students) {
      if (feeStatusOf(st['id'].toString(), ym).paid) continue;
      sent += feeRemindOne(st, ym);
    }
    return sent;
  }

  /// Runs on the first open of each month — the 1st, or the first time the app
  /// is opened after it. Once per month, never twice.
  bool ensureMonthlyFeeReminders() {
    final ym = ymOf(todayStr());
    if ((data['feeReminderMonth'] ?? '').toString() == ym) return false;
    final sent = sendFeeRemindersForMonth(ym);
    data['feeReminderMonth'] = ym;
    if (sent > 0) save();
    return sent > 0;
  }

  // ---- notifications / inbox ----
  List<Map<String, dynamic>> inboxOf(String uid) {
    final list = inbox.where((n) => n['userId'] == uid).toList();
    list.sort((a, b) {
      final at = (a['ts'] as num? ?? 0).toInt();
      final bt = (b['ts'] as num? ?? 0).toInt();
      return bt.compareTo(at);
    });
    final seen = <String>{};
    final out = <Map<String, dynamic>>[];
    for (final n in list) {
      final key = '${n['title']}|${n['message']}';
      if (seen.add(key)) out.add(n);
    }
    return out;
  }

  int unreadOf(String uid) =>
      inboxOf(uid).where((n) => n['read'] != true).length;

  void markInboxRead(String uid, String id) {
    for (final n in inbox) {
      if (n['id'] == id) n['read'] = true;
    }
    save();
  }

  void markAllInboxRead(String uid) {
    for (final n in inbox) {
      if (n['userId'] == uid) n['read'] = true;
    }
    save();
  }

  Map<String, dynamic>? ntPush({
    required String userId,
    required String type,
    required String title,
    required String message,
    String? refType,
    String? refId,
    String? dedupKey,
    Map<String, dynamic>? attachment,
  }) {
    if (userId.isEmpty) return null;
    if (dedupKey != null) {
      for (final n in inbox) {
        if (n['userId'] == userId && n['dedupKey'] == dedupKey) {
          n['message'] = message;
          n['title'] = title;
          n['type'] = type;
          if (attachment != null) n['attachment'] = attachment;
          n['ts'] = DateTime.now().millisecondsSinceEpoch;
          n['read'] = false;
          return n;
        }
      }
    }
    final rec = {
      'id': uid('nt'),
      'userId': userId,
      'type': type,
      'title': title,
      'message': message,
      'refType': refType,
      'refId': refId,
      'dedupKey': dedupKey,
      'attachment': ?attachment,
      'ts': DateTime.now().millisecondsSinceEpoch,
      'read': false,
    };
    rawList('inbox').add(rec);
    return rec;
  }

  /// The office answered a leave request: one line to the person who asked,
  /// and the pending copy plus the admins' copies are taken away with it.
  void leaveDecision({
    required String groupId,
    required String userId,
    required String label,
    required bool accept,
  }) {
    ntRemoveByRef('leave', groupId);
    ntPush(
      userId: userId,
      type: 'leave',
      title: accept ? T('Leave accepted') : T('Leave declined'),
      message: accept
          ? TT('Your leave {0} has been accepted.', <String>[label])
          : TT('Your leave {0} was declined.', <String>[label]),
      refType: 'leave',
      refId: groupId,
      dedupKey: 'leave_$groupId',
    );
  }

  void ntRemoveByRef(String refType, String refId) {
    final going = inbox
        .where((n) => n['refType'] == refType && n['refId'] == refId)
        .toList();
    tombRows(going);
    rawList('inbox').removeWhere(
      (n) => n is Map && n['refType'] == refType && n['refId'] == refId,
    );
  }

  // ---------------------------- notices ----------------------------
  /// Who a Send to pick reaches. 'everyone' is the whole institute, 'all' is
  /// students together with their guardians, and the rest name one group. A
  /// batch reaches that batch's students and their guardians. Admins never
  /// receive a notice.
  bool reachesAudience(
    Map<String, dynamic> u,
    String audience,
    String? batchId,
  ) {
    final role = (u['role'] ?? '').toString();
    if (role == 'admin') return false;
    switch (audience) {
      case 'everyone':
        return true;
      case 'all':
        return role == 'student' || role == 'guardian';
      case 'batch':
        //  a batch pick means that batch's students AND their guardians;
        //  studentOfUser also matches a guardian login, so pick the lookup
        //  by role instead of letting a guardian pass as a student
        final st = role == 'guardian'
            ? guardianStudent(u['id'].toString())
            : studentOfUser(u['id'].toString());
        return st != null && st['batchId'] == batchId;
      case 'sgt':
        return role == 'student' || role == 'guardian' || role == 'teacher';
      case 'students':
        return role == 'student';
      case 'guardians':
        return role == 'guardian';
      case 'teachers':
        return role == 'teacher';
      case 'staff':
        return role == 'staff';
      default:
        return role == audience;
    }
  }

  /// Hands a notice to every account it names and returns how many got it.
  /// Kept on the store so a scheduled notice goes out through the same path
  /// the admin's Send button uses.
  int fanOutAnnouncement(Map<String, dynamic> ann) {
    final audience = (ann['audience'] ?? 'all').toString();
    final batchId = ann['batchId']?.toString();
    final attachment = ann['attachment'] is Map
        ? Map<String, dynamic>.from(ann['attachment'] as Map)
        : null;
    final counts = <String, int>{'student': 0, 'guardian': 0, 'staff': 0};
    var sent = 0;
    for (final u in users) {
      if (!reachesAudience(u, audience, batchId)) continue;
      final role = (u['role'] ?? '').toString();
      ntPush(
        userId: (u['id'] ?? '').toString(),
        type: 'notice',
        title: (ann['title'] ?? '').toString(),
        message: (ann['message'] ?? '').toString(),
        refType: 'notice',
        refId: ann['id'].toString(),
        attachment: attachment,
      );
      counts[role == 'teacher' ? 'staff' : role] =
          (counts[role == 'teacher' ? 'staff' : role] ?? 0) + 1;
      sent++;
    }
    ann['fannedOut'] = true;
    ann['recipients'] = counts;
    return sent;
  }

  /// A notice scheduled for later goes out the first time the app runs at or
  /// after that time — the phone does not need to be open when it is due.
  int publishDueAnnouncements() {
    final now = DateTime.now().millisecondsSinceEpoch;
    var sent = 0;
    for (final a in announcements) {
      final at = (a['publishAt'] as num?)?.toInt();
      if (at == null || at <= 0) continue;
      if (a['fannedOut'] == true) continue;
      if (at > now) continue;
      sent += fanOutAnnouncement(a);
    }
    if (sent > 0) save();
    return sent;
  }

  void ntRemoveForAdmins(String refType, String refId) {
    final adminIds = users
        .where((u) => u['role'] == 'admin')
        .map((u) => u['id'])
        .toSet();
    final going = inbox
        .where(
          (n) =>
              adminIds.contains(n['userId']) &&
              n['refType'] == refType &&
              n['refId'] == refId,
        )
        .toList();
    tombRows(going);
    rawList('inbox').removeWhere(
      (n) =>
          n is Map &&
          adminIds.contains(n['userId']) &&
          n['refType'] == refType &&
          n['refId'] == refId,
    );
  }

  void ntStudentAndGuardians(
    Map<String, dynamic> student, {
    required String type,
    required String title,
    required String message,
    String? refType,
    String? refId,
    String? dedupKey,
  }) {
    ntPush(
      userId: student['userId']?.toString() ?? '',
      type: type,
      title: title,
      message: message,
      refType: refType,
      refId: refId,
      dedupKey: dedupKey,
    );
    ntPush(
      userId: student['guardianUserId']?.toString() ?? '',
      type: type,
      title: title,
      message: message,
      refType: refType,
      refId: refId,
      dedupKey: dedupKey,
    );
  }

  /// The person and both admins, which is what a check-in, a check-out and
  /// a leave request each sound like to the office.
  void ntPersonAndAdmins({
    required String userId,
    required String type,
    required String title,
    required String message,
    String? refType,
    String? refId,
    String? dedupKey,
  }) {
    ntPush(
      userId: userId,
      type: type,
      title: title,
      message: message,
      refType: refType,
      refId: refId,
      dedupKey: dedupKey,
    );
    ntAdmins(
      type: type,
      title: title,
      message: message,
      refType: refType,
      refId: refId,
      dedupKey: dedupKey,
    );
  }

  void ntAdmins({
    required String type,
    required String title,
    required String message,
    String? refType,
    String? refId,
    String? dedupKey,
  }) {
    for (final u in users.where((u) => u['role'] == 'admin')) {
      ntPush(
        userId: u['id'].toString(),
        type: type,
        title: title,
        message: message,
        refType: refType,
        refId: refId,
        dedupKey: dedupKey,
      );
    }
  }
}

class Panel extends StatelessWidget {
  const Panel({
    super.key,
    required this.child,
    this.padding = const EdgeInsets.fromLTRB(16, 16, 16, 16),
    this.radius,
    this.color,
    this.borderColor,
    this.border,
    this.glow = true,
    this.margin = const EdgeInsets.only(bottom: 14),
  });
  final Widget child;
  final EdgeInsets padding;
  final double? radius;
  final Color? color;
  final Color? borderColor;
  final Color? border;
  final bool glow;
  final EdgeInsets margin;

  @override
  Widget build(BuildContext context) {
    final k = context.k;
    return Container(
      width: double.infinity,
      margin: margin,
      padding: padding,
      decoration: BoxDecoration(
        color: color ?? k.surface,
        border: Border.all(
          color:
              border ??
              borderColor ??
              (glow ? k.accent.withValues(alpha: .45) : k.line),
          width: 1,
        ),
        borderRadius: BorderRadius.circular(radius ?? k.radius),
        boxShadow: [
          if (glow)
            BoxShadow(
              color: k.accent.withValues(alpha: k.dark ? .26 : .16),
              blurRadius: 20,
              spreadRadius: 1,
              offset: Offset(0, 2),
            ),
          if (glow)
            BoxShadow(
              color: k.accent.withValues(alpha: k.dark ? .10 : .07),
              blurRadius: 44,
              spreadRadius: 6,
            ),
          ...k.shadow,
        ],
      ),
      child: child,
    );
  }
}

/// Card section title — display serif, exactly like the web's `.card h2`.
class SectionTitle extends StatelessWidget {
  const SectionTitle(this.text, {super.key, this.trailing});
  final String text;
  final Widget? trailing;

  @override
  Widget build(BuildContext context) {
    final style = TextStyle(
      fontFamily: Skin.serif,
      fontSize: 17.5,
      fontWeight: FontWeight.w600,
      color: context.k.ink,
      height: 1.2,
    );
    final label = Store.I.t(text);
    if (trailing == null) {
      return Padding(
        padding: EdgeInsets.only(bottom: 10),
        child: Align(
          alignment: Alignment.centerLeft,
          child: Text(label, style: style),
        ),
      );
    }
    return Padding(
      padding: EdgeInsets.only(bottom: 10),
      child: Row(
        children: <Widget>[
          Expanded(child: Text(text, style: style)),
          trailing!,
        ],
      ),
    );
  }
}

class SmallLabel extends StatelessWidget {
