class Avatar extends StatelessWidget {
  const Avatar({
    super.key,
    required this.name,
    this.radius = 18,
    this.color,
    this.fontSize,
  });
  final String name;
  final double radius;
  final Color? color;
  final double? fontSize;

  static String initials(String name) {
    final parts = name.trim().split(RegExp(r'\s+'));
    if (parts.isEmpty || parts.first.isEmpty) return 'JSK';
    if (parts.length == 1) return parts.first.substring(0, 1).toUpperCase();
    return (parts.first.substring(0, 1) + parts[1].substring(0, 1))
        .toUpperCase();
  }

  @override
  Widget build(BuildContext context) {
    final k = context.k;
    return Container(
      width: radius * 2,
      height: radius * 2,
      alignment: Alignment.center,
      decoration: BoxDecoration(
        color: color ?? k.surface2,
        shape: BoxShape.circle,
        border: Border.all(color: k.line, width: 1),
      ),
      child: Text(
        initials(name),
        style: TextStyle(
          color: k.ink,
          fontSize: fontSize ?? radius * 0.62,
          fontWeight: FontWeight.w700,
          letterSpacing: 0.2,
        ),
      ),
    );
  }
}

/// A person's circle: their own display picture when they have one, otherwise
/// their initials. Tapping it opens the picture sheet when [onTap] is given.
class PersonAvatar extends StatelessWidget {
  const PersonAvatar({
    super.key,
    required this.name,
    this.photo = '',
    this.radius = 18,
    this.color,
    this.onTap,
  });

  final String name;
  final String photo;
  final double radius;
  final Color? color;
  final VoidCallback? onTap;

  Widget _face(BuildContext context) {
    final k = context.k;
    final p = photo.trim();
    final initials = Center(
      child: Text(
        Avatar.initials(name),
        style: TextStyle(
          color: k.ink,
          fontSize: radius * 0.62,
          fontWeight: FontWeight.w700,
          letterSpacing: 0.2,
        ),
      ),
    );

    Widget inner = initials;
    final comma = p.indexOf(',');
    if (p.startsWith('data:image') && comma > 0) {
      try {
        inner = Image.memory(
          base64Decode(p.substring(comma + 1)),
          width: radius * 2,
          height: radius * 2,
          fit: BoxFit.cover,
          gaplessPlayback: true,
          errorBuilder: (_, _, _) => initials,
        );
      } catch (_) {
        inner = initials;
      }
    } else if (p.startsWith('http')) {
      inner = Image.network(
        p,
        width: radius * 2,
        height: radius * 2,
        fit: BoxFit.cover,
        errorBuilder: (_, _, _) => initials,
      );
    }

    return Container(
      width: radius * 2,
      height: radius * 2,
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        color: color ?? k.surface2,
        shape: BoxShape.circle,
        border: Border.all(color: k.line, width: 1),
      ),
      child: inner,
    );
  }

  @override
  Widget build(BuildContext context) {
    final face = _face(context);
    if (onTap == null) return face;
    return Pressable(onTap: onTap!, child: face);
  }
}

/// Shrinks a picked picture to the small JPEG that travels inside the person's
/// own record. A phone camera hands over several megabytes; a face needs a
/// fraction of that, and the register stays light enough to sync.
String? displayPictureFrom(Uint8List raw) {
  try {
    var picture = im.decodeImage(raw);
    if (picture == null) return null;
    if (picture.width > 420 || picture.height > 420) {
      picture = im.copyResize(
        picture,
        width: picture.width >= picture.height ? 420 : null,
        height: picture.height > picture.width ? 420 : null,
        interpolation: im.Interpolation.average,
      );
    }
    return 'data:image/jpeg;base64,${base64Encode(im.encodeJpg(picture, quality: 82))}';
  } catch (_) {
    return null;
  }
}

/// The little sheet that decides where a new picture comes from.
Future<String?> askForDisplayPicture(
  BuildContext context, {
  required bool has,
}) {
  final k = context.k;
  Widget choice({
    required IconData icon,
    required String label,
    required String value,
    Color? tone,
  }) {
    return ListTile(
      dense: true,
      leading: Icon(icon, size: 19, color: tone ?? context.soft),
      title: Text(
        label,
        style: TextStyle(
          fontSize: 12.5,
          fontWeight: FontWeight.w600,
          color: tone ?? k.ink,
        ),
      ),
      onTap: () => Navigator.of(context).pop(value),
    );
  }

  return showModalBottomSheet<String>(
    context: context,
    backgroundColor: k.surface,
    shape: RoundedRectangleBorder(
      borderRadius: BorderRadius.circular(k.radius + 8),
    ),
    builder: (c) => SafeArea(
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: <Widget>[
          const SizedBox(height: 10),
          Container(
            width: 38,
            height: 4,
            decoration: BoxDecoration(
              color: c.line,
              borderRadius: BorderRadius.circular(2),
            ),
          ),
          const SizedBox(height: 6),
          choice(
            icon: Icons.photo_camera_outlined,
            label: T('Take a photo'),
            value: 'camera',
          ),
          choice(
            icon: Icons.photo_library_outlined,
            label: T('Choose from gallery'),
            value: 'gallery',
          ),
          if (has)
            choice(
              icon: Icons.delete_outline,
              label: T('Remove photo'),
              value: 'remove',
              tone: Skin.red,
            ),
          const SizedBox(height: 8),
        ],
      ),
    ),
  );
}

/// Opens the sheet, takes the picture and stores it on the person.
Future<void> chooseDisplayPicture(
  BuildContext context,
  Map<String, dynamic> person,
) async {
  final store = Store.I;
  final id = (person['id'] ?? '').toString();
  if (id.isEmpty) return;
  final has = store.photoOf(person).isNotEmpty;

  final choice = await askForDisplayPicture(context, has: has);
  if (choice == null) return;

  if (choice == 'remove') {
    store.setPersonPhoto(id, '');
    if (context.mounted) toast(context, T('Display picture removed'));
    return;
  }

  XFile? picked;
  try {
    picked = await ImagePicker().pickImage(
      source: choice == 'camera' ? ImageSource.camera : ImageSource.gallery,
      maxWidth: 1200,
      maxHeight: 1200,
      imageQuality: 92,
    );
  } catch (_) {
    if (context.mounted) {
      toast(context, T('Could not open the camera or gallery on this phone.'));
    }
    return;
  }
  if (picked == null) return;

  final photo = displayPictureFrom(await picked.readAsBytes());
  if (photo == null) {
    if (context.mounted) toast(context, T('That picture could not be read.'));
    return;
  }
  store.setPersonPhoto(id, photo);
  if (context.mounted) toast(context, T('Display picture saved'));
}

/// The web's `.stat` tile: mono number in navy, tiny muted label, 5px left
/// accent for the navy / green / marigold / theme variants.
class StatTile extends StatelessWidget {
  const StatTile({
    super.key,
    required this.value,
    required this.label,
    this.variant = 'plain',
    this.valueColor,
    this.valueSize,
  });
  final String value;
  final String label;
  final String variant; // plain | navy | green | marigold | theme
  final Color? valueColor;
  final double? valueSize;

  @override
  Widget build(BuildContext context) {
    final k = context.k;
    Color bg = k.surface;
    Color border = k.line;
    Color numColor = valueColor ?? Skin.navy;
    Color lblColor = k.inkSoft;
    double leftWidth = 1;
    Color leftColor = k.line;
    List<BoxShadow> shadow = k.shadow;

    if (variant == 'navy') {
      bg = k.surface2;
      leftWidth = 5;
      leftColor = Skin.navy;
    } else if (variant == 'green') {
      bg = Skin.greenBg;
      leftWidth = 5;
      leftColor = Skin.green;
      numColor = Skin.green;
    } else if (variant == 'marigold') {
      bg = Skin.marigold;
      leftWidth = 5;
      leftColor = Skin.marigoldDeep;
      numColor = Skin.navySolid;
      lblColor = Color(0xFF3D3113);
      shadow = const <BoxShadow>[
        BoxShadow(
          color: Color(0x38C97F1E),
          blurRadius: 18,
          offset: Offset(0, 6),
        ),
      ];
    } else if (variant == 'theme') {
      bg = Skin.navySolid;
      leftWidth = 5;
      leftColor = Skin.navySolidHover;
      numColor = Colors.white;
      lblColor = Color(0xFFB9C6DE);
    }

    return Container(
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        color: bg,
        border: Border.all(color: border),
        borderRadius: BorderRadius.circular(k.radius),
        boxShadow: [
          BoxShadow(
            color: k.accent.withValues(alpha: k.dark ? .20 : .12),
            blurRadius: 16,
            spreadRadius: 1,
            offset: Offset(0, 2),
          ),
          ...shadow,
        ],
      ),
      child: Stack(
        children: <Widget>[
          if (leftWidth > 1)
            Positioned(
              left: 0,
              top: 0,
              bottom: 0,
              width: leftWidth,
              child: ColoredBox(color: leftColor),
            ),
          Padding(
            padding: EdgeInsets.fromLTRB(
              9 + (leftWidth > 1 ? leftWidth - 1 : 0),
              7,
              9,
              8,
            ),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              crossAxisAlignment: CrossAxisAlignment.center,
              children: <Widget>[
                Text(
                  value,
                  maxLines: 2,
                  textAlign: TextAlign.center,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(
                    fontFamily: Skin.mono,
                    fontSize: valueSize ?? 18,
                    fontWeight: FontWeight.w600,
                    color: numColor,
                    height: 1.1,
                  ),
                ),
                SizedBox(height: 2),
                Text(
                  Store.I.t(label),
                  maxLines: 3,
                  textAlign: TextAlign.center,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(
                    fontSize: 10.2,
                    height: 1.22,
                    color: lblColor,
                    fontWeight: variant == 'theme' || variant == 'marigold'
                        ? FontWeight.w600
                        : FontWeight.w400,
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class Field extends StatelessWidget {
