class Pressable extends StatefulWidget {
  const Pressable({super.key, required this.child, this.onTap});
  final Widget child;
  final VoidCallback? onTap;

  @override
  State<Pressable> createState() => _PressableState();
}

class _PressableState extends State<Pressable> {
  bool _down = false;

  @override
  Widget build(BuildContext context) => GestureDetector(
    // a row should answer a tap anywhere on it, not only on its text
    behavior: HitTestBehavior.opaque,
    onTapDown: widget.onTap == null
        ? null
        : (_) => setState(() => _down = true),
    onTapCancel: () => setState(() => _down = false),
    onTapUp: (_) => setState(() => _down = false),
    onTap: widget.onTap,
    child: AnimatedScale(
      scale: _down ? 0.97 : 1,
      duration: Duration(milliseconds: 110),
      child: widget.child,
    ),
  );
}

/// Staggered entrance used for cards, rows and calendar cells.
class Stagger extends StatelessWidget {
  const Stagger({
    super.key,
    required this.child,
    this.index = 0,
    this.base = 240,
    this.step = 45,
  });
  final Widget child;
  final int index;
  final int base;
  final int step;

  @override
  Widget build(BuildContext context) => TweenAnimationBuilder<double>(
    tween: Tween<double>(begin: 0, end: 1),
    duration: Duration(
      milliseconds: base + (index.clamp(0, 14).toInt() * step),
    ),
    curve: Curves.easeOutCubic,
    builder: (context, v, kid) => Opacity(
      opacity: v,
      child: Transform.translate(offset: Offset(0, (1 - v) * 10), child: kid),
    ),
    child: child,
  );
}

class Meter extends StatelessWidget {
  const Meter({super.key, required this.value, this.color, this.height = 8});
  final double value;
  final Color? color;
  final double height;

  @override
  Widget build(BuildContext context) {
    final k = context.k;
    return ClipRRect(
      borderRadius: BorderRadius.circular(999),
      child: Container(
        height: height,
        color: k.dark ? Color(0xFF3B3B34) : Color(0xFFE3DFD3),
        child: TweenAnimationBuilder<double>(
          tween: Tween<double>(begin: 0, end: value),
          duration: Duration(milliseconds: 750),
          curve: Curves.easeOutCubic,
          builder: (context, v, _) => FractionallySizedBox(
            alignment: Alignment.centerLeft,
            widthFactor: v.clamp(0.0, 1.0),
            child: Container(color: color ?? Skin.marigold),
          ),
        ),
      ),
    );
  }
}

/// Pill toggle row (web `.view-toggle` / `.vt-btn`).
class PillToggle extends StatelessWidget {
  const PillToggle({
    super.key,
    required this.options,
    required this.value,
    required this.onChanged,
  });
  final List<MapEntry<String, String>> options;
  final String value;
  final ValueChanged<String> onChanged;

  @override
  Widget build(BuildContext context) {
    final k = context.k;
    return Wrap(
      spacing: 8,
      runSpacing: 8,
      children: <Widget>[
        for (final o in options)
          Pressable(
            onTap: () => onChanged(o.key),
            child: AnimatedContainer(
              duration: Duration(milliseconds: 160),
              padding: EdgeInsets.symmetric(horizontal: 16, vertical: 8),
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(999),
                border: Border.all(
                  color: value == o.key ? Skin.navySolid : k.lineStrong,
                ),
                gradient: value == o.key
                    ? LinearGradient(
                        colors: <Color>[Color(0xFF26385F), Color(0xFF1B2A4A)],
                      )
                    : null,
                color: value == o.key ? null : k.surface,
                boxShadow: value == o.key
                    ? const <BoxShadow>[
                        BoxShadow(color: Color(0x00382B4A), blurRadius: 12),
                      ]
                    : null,
              ),
              child: Text(
                o.value,
                style: TextStyle(
                  fontSize: 12.5,
                  fontWeight: FontWeight.w600,
                  color: value == o.key ? Colors.white : k.inkSoft,
                ),
              ),
            ),
          ),
      ],
    );
  }
}

// ---------------------------------------------------------------------------
//  ENTRY RADAR  (rotating sweep + pulsing zone + live distance)
// ---------------------------------------------------------------------------
/// One past GPS fix, so the radar can show the way you are moving as a fade.
class RadarFix {
  const RadarFix({
    required this.distance,
    required this.bearing,
    required this.ts,
  });

  final double distance;
  final double bearing;
  final int ts;
}

/// The entry radar: the same drawing and the same 4.5 second sweep as the
/// web register — dashed depth rings, a dashed marigold check-in ring, the
/// navy institute pin, a 30 degree sweep wedge and your own dot with the
/// fading trail of the last few fixes.
class Radar extends StatefulWidget {
  const Radar({
    super.key,
    this.distance,
    this.radius = 150,
    this.bearing,
    this.inside = false,
    this.size = 236,
    this.accuracy,
    this.trail = const <RadarFix>[],
  });

  final double? distance;
  final double radius;
  final double? bearing;
  final bool inside;
  final double size;
  final double? accuracy;
  final List<RadarFix> trail;

  @override
  State<Radar> createState() => _RadarState();
}

class _RadarState extends State<Radar> with SingleTickerProviderStateMixin {
  /// exactly one turn every 4.5 s, linear, exactly like the web sweep
  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 4500),
  );

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    // the web stops the sweep when the phone asks for reduced motion
    final reduce = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
    if (reduce) {
      _c.stop();
      _c.value = 0;
    } else if (!_c.isAnimating) {
      _c.repeat();
    }
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final faint = context.faint;
    return SizedBox(
      width: widget.size,
      height:
          widget.size *
          (_RadarPainter.canvasHeight / _RadarPainter.canvasWidth),
      child: AnimatedBuilder(
        animation: _c,
        builder: (context, _) => CustomPaint(
          painter: _RadarPainter(
            t: _c.value,
            distance: widget.distance,
            radius: widget.radius,
            bearing: widget.bearing,
            inside: widget.inside,
            accuracy: widget.accuracy,
            trail: widget.trail,
            nowMs: DateTime.now().millisecondsSinceEpoch,
            dark: context.dark,
            faint: faint,
          ),
        ),
      ),
    );
  }
}

class _RadarPainter extends CustomPainter {
  // Decorative painters must never swallow taps meant for the UI below.
  @override
  bool hitTest(Offset position) => false;

  _RadarPainter({
    required this.t,
    required this.distance,
    required this.radius,
    required this.bearing,
    required this.inside,
    required this.accuracy,
    required this.trail,
    required this.nowMs,
    required this.dark,
    required this.faint,
  });

  /// the web draws everything on a 240 x 236 canvas; the phone just scales it
  static const double canvasWidth = 240;
  static const double canvasHeight = 236;

  final double t;
  final double? distance;
  final double radius;
  final double? bearing;
  final bool inside;
  final double? accuracy;
  final List<RadarFix> trail;
  final int nowMs;
  final bool dark;
  final Color faint;

  Color get _disc => dark ? const Color(0xFF2C2C27) : const Color(0xFFEFEBE0);
  Color get _line => dark ? const Color(0xFF3B3B34) : Skin.creamLine;
  Color get _lineStrong =>
      dark ? Skin.lineStrongStatic : const Color(0xFFAFA895);
  Color get _marigold => dark ? Skin.marigold : const Color(0xFFE8A33D);
  Color get _marigoldDeep => dark ? Skin.marigoldDeep : Skin.goldDeep;
  Color get _inZoneInk => dark ? Skin.green : const Color(0xFF2F7D5E);
  Color get _outZoneInk => dark ? Skin.brick : const Color(0xFFB5482E);

  @override
  void paint(Canvas canvas, Size size) {
    final k = size.width / canvasWidth;
    canvas.save();
    canvas.scale(k);

    const cx = 120.0;
    const cy = 118.0;
    const r = 105.0;
    const center = Offset(cx, cy);
    final pxPerM = r / (radius * 2);
    final zonePx = radius * pxPerM;
    final col = inside ? _inZoneInk : _outZoneInk;

    // ---- the disc
    canvas.drawCircle(center, r, Paint()..color = _disc);
    canvas.drawCircle(
      center,
      r,
      Paint()
        ..color = _line
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1,
    );

    // ---- depth rings so distances read at a glance
    for (final ring in <double>[35, 70]) {
      _dashedCircle(
        canvas,
        center,
        ring,
        Paint()
          ..color = _line
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1,
        2,
        6,
      );
    }

    // ---- a fading trail of the last fixes, under the rings
    for (final f in trail) {
      if (nowMs - f.ts > 600000) continue;
      final td = math.min(f.distance, radius * 2);
      final trr = math.max(7.0, td * pxPerM);
      final tang = ((f.bearing) - 90) * math.pi / 180;
      final age = math.min((nowMs - f.ts) / 600000, 1.0);
      canvas.drawCircle(
        Offset(cx + trr * math.cos(tang), cy + trr * math.sin(tang)),
        3.2,
        Paint()..color = col.withValues(alpha: 0.28 * (1 - age)),
      );
    }

    // ---- the inner guide ring and the check-in ring
    _dashedCircle(
      canvas,
      center,
      zonePx / 2,
      Paint()
        ..color = _lineStrong
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1,
      3,
      4,
    );
    _dashedCircle(
      canvas,
      center,
      zonePx,
      Paint()
        ..color = _marigoldDeep
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.6,
      6,
      5,
    );

    // ---- cross hairs
    final axis = Paint()
      ..color = _line
      ..strokeWidth = 1;
    _dashedLine(
      canvas,
      const Offset(cx, 18),
      const Offset(cx, 218),
      axis,
      2,
      5,
    );
    _dashedLine(
      canvas,
      const Offset(20, cy),
      const Offset(220, cy),
      axis,
      2,
      5,
    );

    // ---- the zone label, sitting just outside the marigold ring
    final label = TextPainter(
      text: TextSpan(
        text: TT('{0}m zone', <String>['${radius.round()}']),
        style: TextStyle(color: faint, fontSize: 9.5, fontFamily: 'monospace'),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    label.paint(canvas, Offset(cx + zonePx + 4, cy + 4 - label.height / 2));

    // ---- the institute itself
    canvas.drawCircle(center, 8, Paint()..color = Skin.navySolid);
    canvas.drawCircle(
      center,
      14,
      Paint()
        ..color = Skin.navySolid.withValues(alpha: .3)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 3,
    );

    // ---- the sweep: a 30 degree wedge with a bright leading edge
    canvas.save();
    canvas.translate(cx, cy);
    canvas.rotate(t * math.pi * 2);
    final wedge = Path()
      ..moveTo(0, 0)
      ..lineTo(r, 0)
      ..lineTo(r * math.cos(-math.pi / 6), r * math.sin(-math.pi / 6))
      ..close();
    canvas.drawPath(wedge, Paint()..color = _marigold.withValues(alpha: .10));
    canvas.drawLine(
      Offset.zero,
      const Offset(r, 0),
      Paint()
        ..color = _marigoldDeep.withValues(alpha: .45)
        ..strokeWidth = 1.5,
    );
    canvas.restore();

    // ---- you
    if (distance != null) {
      final d = math.min(distance!, radius * 2);
      final rr = math.max(7.0, d * pxPerM);
      final ang = ((bearing ?? 0) - 90) * math.pi / 180;
      final dot = Offset(cx + rr * math.cos(ang), cy + rr * math.sin(ang));

      // the GPS accuracy halo, exactly as the web draws it
      final acc = accuracy;
      if (acc != null && acc > 15) {
        final accR = math.min(math.max(acc, 10) * pxPerM, 100.0);
        canvas.drawCircle(
          dot,
          accR,
          Paint()..color = col.withValues(alpha: .08),
        );
        _dashedCircle(
          canvas,
          dot,
          accR,
          Paint()
            ..color = col.withValues(alpha: .25)
            ..style = PaintingStyle.stroke
            ..strokeWidth = 1,
          2,
          3,
        );
      }

      canvas.drawCircle(dot, 7, Paint()..color = col);
      canvas.drawCircle(
        dot,
        12,
        Paint()
          ..color = col.withValues(alpha: .35)
          ..style = PaintingStyle.stroke
          ..strokeWidth = 2,
      );
    }

    canvas.restore();
  }

  /// A dashed circle, drawn the way the web draws its `stroke-dasharray` rings.
  void _dashedCircle(
    Canvas canvas,
    Offset center,
    double radius,
    Paint paint,
    double on,
    double off,
  ) {
    if (radius <= 0) return;
    final path = Path()
      ..addOval(Rect.fromCircle(center: center, radius: radius));
    for (final metric in path.computeMetrics()) {
      var d = 0.0;
      while (d < metric.length) {
        final next = math.min(d + on, metric.length);
        canvas.drawPath(metric.extractPath(d, next), paint);
        d = next + off;
      }
    }
  }

  void _dashedLine(
    Canvas canvas,
    Offset a,
    Offset b,
    Paint paint,
    double on,
    double off,
  ) {
    final total = (b - a).distance;
    if (total == 0) return;
    final dir = (b - a) / total;
    var d = 0.0;
    while (d < total) {
      final next = math.min(d + on, total);
      canvas.drawLine(a + dir * d, a + dir * next, paint);
      d = next + off;
    }
  }

  @override
  bool shouldRepaint(covariant _RadarPainter old) =>
      old.t != t ||
      old.distance != distance ||
      old.bearing != bearing ||
      old.inside != inside ||
      old.accuracy != accuracy ||
      old.trail.length != trail.length ||
      old.dark != dark;
}

// ---------------------------------------------------------------------------
//  FALLING LEAVES — the same slow drift the web register shows on every page
// ---------------------------------------------------------------------------

/// A single drifting petal or leaf. The web spawns at most five and lets each
/// one fall for 18–28 s while it sways left and right and slowly turns.
class _FallingLeaf {
  _FallingLeaf({
    required this.kind,
    required this.size,
    required this.leftFrac,
    required this.sway1,
    required this.sway2,
    required this.duration,
    required this.opacity,
    required this.bornAt,
  });

  /// 0 = blossom, 1 = green leaf, 2 = dry leaf
  final int kind;
  final double size;
  final double leftFrac;
  final double sway1;
  final double sway2;
  final double duration;
  final double opacity;
  final double bornAt;

  /// the six keyframes the web animates through: 0%, 20%, 40%, 60%, 80%, 100%
  static double _six(
    double p,
    double a,
    double b,
    double c,
    double d,
    double e,
    double f,
  ) {
    final q = p.clamp(0.0, 1.0) * 5;
    final seg = q.floor().clamp(0, 4);
    final local = q - seg;
    final v = <double>[a, b, c, d, e, f];
    return v[seg] + (v[seg + 1] - v[seg]) * local;
  }

  /// how far down the screen the leaf has travelled, 0 → 1.12 of the height
  double dropAt(double p) => _six(p, 0, .22, .44, .66, .88, 1.12);

  /// the sideways sway, in pixels either side of its column
  double swayAt(double p) => _six(p, 0, sway1, -sway1, sway2, -sway2, 0);

  /// the slow turn, in radians
  double turnAt(double p) => _six(p, 0, 70, 150, 230, 300, 360) * math.pi / 180;
}

class FallingLeaves extends StatefulWidget {
  const FallingLeaves({super.key, this.maxLeaves = 5});

  final int maxLeaves;

  @override
  State<FallingLeaves> createState() => _FallingLeavesState();
}

class _FallingLeavesState extends State<FallingLeaves>
    with SingleTickerProviderStateMixin {
  final math.Random _rnd = math.Random();
  final List<_FallingLeaf> _leaves = <_FallingLeaf>[];
  final ValueNotifier<double> _clock = ValueNotifier<double>(0);

  Ticker? _ticker;
  Duration _last = Duration.zero;
  double _now = 0;
  double _nextAt = 0;
  int _spawned = 0;

  @override
  void initState() {
    super.initState();
    // start the drift at once — the first leaf arrives within a second
    _nextAt = _range(.4, 1.2);
    _ticker = createTicker(_onTick)..start();
  }

  double _range(double a, double b) => a + _rnd.nextDouble() * (b - a);

  void _onTick(Duration elapsed) {
    final dt = (elapsed - _last).inMicroseconds / 1000000.0;
    _last = elapsed;
    if (dt <= 0) return;
    _now += dt;

    // a leaf is gone once its fall is over
    _leaves.removeWhere((l) => _now - l.bornAt >= l.duration);

    if (_now >= _nextAt && _leaves.length < widget.maxLeaves) {
      _spawn();
      _spawned++;
      // the web sends two leaves in quickly, then one every few seconds
      _nextAt = _now + (_spawned < 2 ? _range(1.8, 3.4) : _range(2.8, 4.8));
    }
    _clock.value = _now;
  }

  void _spawn() {
    _leaves.add(
      _FallingLeaf(
        kind: _rnd.nextInt(3),
        size: _range(14, 22),
        leftFrac: _range(.02, .94),
        sway1: _range(14, 34),
        sway2: _range(14, 34),
        duration: _range(18, 28),
        opacity: _range(.6, .9),
        bornAt: _now,
      ),
    );
  }

  @override
  void dispose() {
    _ticker?.dispose();
    _clock.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    // the web hides the whole layer when the phone asks for reduced motion
    if (MediaQuery.maybeDisableAnimationsOf(context) ?? false) {
      return const SizedBox.shrink();
    }
    return RepaintBoundary(
      child: CustomPaint(
        painter: _LeafPainter(leaves: _leaves, clock: _clock),
        size: Size.infinite,
      ),
    );
  }
}

class _LeafPainter extends CustomPainter {
  _LeafPainter({required this.leaves, required this.clock})
    : super(repaint: clock);

  final List<_FallingLeaf> leaves;
  final ValueNotifier<double> clock;

  /// the blossom and both leaves are drawn in a 24 × 24 box, as on the web
  static const List<List<double>> _petals = <List<double>>[
    <double>[12, 6, 0],
    <double>[18, 10, 72],
    <double>[16, 17, 144],
    <double>[8, 17, 216],
    <double>[6, 10, 288],
  ];

  static final Path _leafBody = Path()
    ..moveTo(12, 2)
    ..cubicTo(6, 6, 3, 12, 6, 18)
    ..cubicTo(8, 21, 12, 22, 15, 20)
    ..cubicTo(19, 17, 20, 11, 17, 6)
    ..cubicTo(15, 4, 13, 2, 12, 2)
    ..close();

  static final Path _leafVein = Path()
    ..moveTo(12, 3)
    ..cubicTo(12, 3, 12, 12, 8, 19);

  @override
  bool hitTest(Offset position) => false;

  @override
  void paint(Canvas canvas, Size size) {
    final now = clock.value;
    for (final leaf in leaves) {
      final p = (now - leaf.bornAt) / leaf.duration;
      if (p < 0 || p > 1) continue;

      final center = Offset(
        leaf.leftFrac * size.width + leaf.swayAt(p),
        -0.08 * size.height + leaf.dropAt(p) * size.height + leaf.size / 2,
      );

      canvas.save();
      canvas.translate(center.dx, center.dy);
      canvas.rotate(leaf.turnAt(p));
      canvas.scale(leaf.size / 24);
      canvas.translate(-12, -12);
      _shape(canvas, leaf.kind, leaf.opacity);
      canvas.restore();
    }
  }

  void _shape(Canvas canvas, int kind, double opacity) {
    switch (kind) {
      case 0:
        // a five petal blossom with a darker heart
        final petal = Paint()
          ..color = const Color(0xFFF4A6C1).withValues(alpha: opacity);
        for (final at in _petals) {
          canvas.save();
          canvas.translate(at[0], at[1]);
          canvas.rotate(at[2] * math.pi / 180);
          canvas.drawOval(
            Rect.fromCenter(center: Offset.zero, width: 8, height: 10),
            petal,
          );
          canvas.restore();
        }
        canvas.drawCircle(
          const Offset(12, 12),
          2.4,
          Paint()..color = const Color(0xFFE8749A).withValues(alpha: opacity),
        );
        break;
      case 1:
        _paintLeaf(
          canvas,
          opacity,
          const Color(0xFF5FAE62),
          const Color(0xFF3C7C42),
        );
        break;
      default:
        _paintLeaf(
          canvas,
          opacity,
          const Color(0xFFC99A5B),
          const Color(0xFF8A6836),
        );
    }
  }

  void _paintLeaf(Canvas canvas, double opacity, Color body, Color vein) {
    canvas.drawPath(
      _leafBody,
      Paint()..color = body.withValues(alpha: opacity),
    );
    canvas.drawPath(
      _leafVein,
      Paint()
        ..color = vein.withValues(alpha: opacity)
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1,
    );
  }

  @override
  bool shouldRepaint(covariant _LeafPainter old) => true;
}

// ---------------------------------------------------------------------------
//  ATTENDANCE TREND CHART (line draws in, target line dashed)
// ---------------------------------------------------------------------------
class TrendChart extends StatefulWidget {
  const TrendChart({
    super.key,
    required this.points,
    required this.target,
    this.height = 128,
    this.divisions = 2,
  });

  final List<({String date, int value})> points;
  final int target;
  final double height;

  /// how many bands the percentage axis is split into (4 → 100/75/50/25/0)
  final int divisions;

  @override
  State<TrendChart> createState() => _TrendChartState();
}

class _TrendChartState extends State<TrendChart>
    with SingleTickerProviderStateMixin {
  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: Duration(milliseconds: 900),
  )..forward();

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => SizedBox(
    height: widget.height,
    width: double.infinity,
    child: AnimatedBuilder(
      animation: _c,
      builder: (context, _) => CustomPaint(
        painter: _TrendPainter(
          points: widget.points,
          target: widget.target,
          progress: Curves.easeOutCubic.transform(_c.value),
          accent: Store.I.skin.accent,
          grid: context.line,
          label: context.faint,
          divisions: widget.divisions,
        ),
      ),
    ),
  );
}

class _TrendPainter extends CustomPainter {
  // Decorative painters must never swallow taps meant for the UI below.
  @override
  bool hitTest(Offset position) => false;

  _TrendPainter({
    required this.points,
    required this.target,
    required this.progress,
    required this.accent,
    required this.grid,
    required this.label,
    this.divisions = 2,
  });

  final List<({String date, int value})> points;
  final int target;
  final double progress;
  final Color accent;
  final Color grid;
  final Color label;
  final int divisions;

  @override
  void paint(Canvas canvas, Size size) {
    if (points.isEmpty) return;
    final left = 26.0;
    final bottom = size.height - 18;
    final top = 8.0;
    final w = size.width - left - 8;

    final gridPaint = Paint()
      ..color = grid.withValues(alpha: .6)
      ..strokeWidth = 1;
    final bands = divisions < 1 ? 1 : divisions;
    for (var i = 0; i <= bands; i++) {
      final y = top + (bottom - top) * i / bands;
      canvas.drawLine(Offset(left, y), Offset(size.width - 8, y), gridPaint);
      final tp = TextPainter(
        text: TextSpan(
          text: TT("{0}%", [100 - i * (100 ~/ bands)]),
          style: TextStyle(color: label, fontSize: 8),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      tp.paint(canvas, Offset(0, y - 5));
    }

    // target line
    final ty = bottom - (bottom - top) * (target / 100);
    final dash = Paint()
      ..color = Skin.gold.withValues(alpha: .8)
      ..strokeWidth = 1.2;
    for (var x = left; x < size.width - 8; x += 8) {
      canvas.drawLine(Offset(x, ty), Offset(x + 4, ty), dash);
    }

    final step = points.length > 1 ? w / (points.length - 1) : w;
    final path = Path();
    final fill = Path();
    var started = false;
    for (var i = 0; i < points.length; i++) {
      final x = left + step * i;
      final y = bottom - (bottom - top) * (points[i].value / 100);
      if (!started) {
        path.moveTo(x, y);
        fill.moveTo(x, bottom);
        fill.lineTo(x, y);
        started = true;
      } else {
        path.lineTo(x, y);
        fill.lineTo(x, y);
      }
    }

    final draw = Path();
    for (final m in path.computeMetrics()) {
      draw.addPath(m.extractPath(0, m.length * progress), Offset.zero);
    }
    final fillDraw = Path();
    for (final m in fill.computeMetrics()) {
      fillDraw.addPath(m.extractPath(0, m.length * progress), Offset.zero);
    }

    canvas.drawPath(
      fillDraw,
      Paint()
        ..shader = ui.Gradient.linear(Offset(left, top), Offset(left, bottom), [
          accent.withValues(alpha: .28),
          accent.withValues(alpha: .02),
        ]),
    );
    canvas.drawPath(
      draw,
      Paint()
        ..color = accent
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.2
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round,
    );

    if (progress > .98) {
      for (var i = 0; i < points.length; i++) {
        final x = left + step * i;
        final y = bottom - (bottom - top) * (points[i].value / 100);
        canvas.drawCircle(Offset(x, y), 2.6, Paint()..color = accent);
        if (points.length <= 8 || i % 2 == 0) {
          final tp = TextPainter(
            text: TextSpan(
              text: points[i].date,
              style: TextStyle(color: label, fontSize: 7.5),
            ),
            textDirection: TextDirection.ltr,
          )..layout();
          tp.paint(canvas, Offset(x - tp.width / 2, bottom + 4));
        }
      }
    }
  }

  @override
  bool shouldRepaint(covariant _TrendPainter old) =>
      old.progress != progress ||
      old.points != points ||
      old.divisions != divisions;
}

// ---------------------------------------------------------------------------
//  LOGIN — jungle night, drawn vines, sleeping lion who roars when touched
// ---------------------------------------------------------------------------
class LoginPage extends StatefulWidget {
  const LoginPage({super.key});

  @override
  State<LoginPage> createState() => _LoginPageState();
}

class _LoginPageState extends State<LoginPage> {
  final _email = TextEditingController();
  final _password = TextEditingController();
  String? _error;
  bool _busy = false;

  @override
  void dispose() {
    _email.dispose();
    _password.dispose();
    super.dispose();
  }

  Future<void> _submit() async {
    if (_busy) return;
    setState(() {
      _busy = true;
      _error = null;
    });
    try {
      await Store.I.authenticate(_email.text, _password.text);
      if (!mounted) return;
      setState(() => _busy = false);
    } catch (e) {
      final message = e.toString().replaceFirst('Bad state: ', '');
      if (mounted) {
        setState(() {
          _busy = false;
          _error =
              message.contains('Admin must sign in') ||
                  message.contains('Too many attempts') ||
                  message.contains('incorrect') ||
                  message.contains('Could not load') ||
                  message.contains('not configured')
              ? message
              : T('Wrong ID and password.');
        });
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    final skin = Store.I.skin;
    return Scaffold(
      body: Stack(
        children: [
          const NightBackdrop(),
          SafeArea(
            child: SingleChildScrollView(
              padding: EdgeInsets.fromLTRB(18, 10, 18, 18),
              child: Column(
                children: [
                  SizedBox(height: 6),
                  _brandRow(),
                  SizedBox(height: 6),
                  SizedBox(
                    width: math.min(
                      MediaQuery.sizeOf(context).width * .86,
                      360,
                    ),
                    height:
                        math.min(MediaQuery.sizeOf(context).width * .86, 360) /
                        kPantherAspect,
                    child: const _PantherHead(),
                  ),
                  SizedBox(height: 14),
                  Container(
                    padding: EdgeInsets.fromLTRB(16, 18, 16, 14),
                    decoration: BoxDecoration(
                      color: Color(0xFF111318).withValues(alpha: .9),
                      borderRadius: BorderRadius.circular(skin.radius),
                      border: Border.all(
                        color: Colors.white.withValues(alpha: .12),
                      ),
                      boxShadow: [
                        BoxShadow(color: Color(0xB3000000), blurRadius: 34),
                      ],
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        if (_error != null)
                          Container(
                            margin: EdgeInsets.only(bottom: 10),
                            padding: EdgeInsets.all(9),
                            decoration: BoxDecoration(
                              color: Skin.red.withValues(alpha: .18),
                              borderRadius: BorderRadius.circular(9),
                              border: Border.all(
                                color: Skin.red.withValues(alpha: .55),
                              ),
                            ),
                            child: Text(
                              _error!,
                              style: TextStyle(
                                color: Color(0xFFF2B9A8),
                                fontSize: 10.5,
                              ),
                            ),
                          ),
                        _loginField('Email', _email, 'you@jsk.edu'),
                        _loginField('Password', _password, '••••••••', true),
                        SizedBox(height: 4),
                        SizedBox(
                          height: 44,
                          child: FilledButton(
                            onPressed: _busy ? null : _submit,
                            style: FilledButton.styleFrom(
                              backgroundColor: Skin.gold,
                              foregroundColor: Color(0xFF201C14),
                              shape: RoundedRectangleBorder(
                                borderRadius: BorderRadius.circular(12),
                              ),
                            ),
                            child: Text(
                              _busy ? 'Signing in…' : 'Sign in',
                              style: TextStyle(
                                fontWeight: FontWeight.w800,
                                fontSize: 13,
                              ),
                            ),
                          ),
                        ),
                        SizedBox(height: 14),
                        Text(
                          T('Accounts are created and shared by a JSK Admin.'),
                          textAlign: TextAlign.center,
                          style: TextStyle(
                            color: Colors.white.withValues(alpha: .58),
                            fontSize: 9,
                          ),
                        ),
                      ],
                    ),
                  ),
                  SizedBox(height: 10),
                  Text(
                    Store.I.online
                        ? 'Connected to the institute register'
