}

// ---------------------------------------------------------------------------
//  NIGHT BACKDROP — the login theme after dark: black sky, canopy light,
//  drifting mist, floating embers and the panther who opens his eyes.
// ---------------------------------------------------------------------------
class NightBackdrop extends StatefulWidget {
  const NightBackdrop({super.key});

  @override
  State<NightBackdrop> createState() => _NightBackdropState();
}

class _NightBackdropState extends State<NightBackdrop>
    with SingleTickerProviderStateMixin {
  late final AnimationController _clock = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 28),
  )..repeat();

  @override
  void dispose() {
    _clock.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final bool still = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
    return DecoratedBox(
      decoration: const BoxDecoration(
        gradient: RadialGradient(
          center: Alignment(0, -.5),
          radius: 1.1,
          colors: <Color>[
            Color(0xFF15181F),
            Color(0xFF08090C),
            Color(0xFF000000),
          ],
          stops: <double>[0, .58, 1],
        ),
      ),
      child: AnimatedBuilder(
        animation: _clock,
        builder: (BuildContext context, Widget? child) => CustomPaint(
          painter: _NightPainter(clock: still ? .35 : _clock.value),
          child: child,
        ),
        child: const SizedBox.expand(),
      ),
    );
  }
}

class _NightPainter extends CustomPainter {
  _NightPainter({required this.clock});

  final double clock;

  static const Color _amber = Color(0xFFF0B559);

  // Decorative painters must never swallow taps meant for the UI above.
  @override
  bool hitTest(Offset position) => false;

  @override
  void paint(Canvas canvas, Size size) {
    final double w = size.width;
    final double h = size.height;
    final double t = clock;

    // Trunks just outside the lamplight.
    final Paint trunk = Paint()..color = Colors.white.withValues(alpha: .022);
    for (final double f in <double>[.05, .19, .87]) {
      canvas.drawRect(Rect.fromLTWH(w * f, 0, w * .07, h), trunk);
    }
    final Paint trunkEdge = Paint()
      ..color = Colors.white.withValues(alpha: .03)
      ..strokeWidth = 1;
    canvas.drawLine(Offset(w * .12, 0), Offset(w * .12, h), trunkEdge);
    canvas.drawLine(Offset(w * .24, 0), Offset(w * .24, h), trunkEdge);

    // Canopy light falling in slow shafts.
    for (int i = 0; i < 3; i++) {
      final double phase = (t + i / 3) % 1;
      final double x = w * (.12 + .5 * phase);
      final Rect band = Rect.fromLTWH(-70, -h * .12, 140, h * .86);
      final Paint shaft = Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: <Color>[
            _amber.withValues(alpha: .045),
            _amber.withValues(alpha: 0),
          ],
        ).createShader(band);
      canvas.save();
      canvas.translate(x, 0);
      canvas.rotate(.13);
      canvas.drawRect(band, shaft);
      canvas.restore();
    }

    // Mist rolling through the dark.
    for (int i = 0; i < 3; i++) {
      final double phase = (t * (1 + i * .22) + i * .37) % 1;
      canvas.drawOval(
        Rect.fromCenter(
          center: Offset(w * (-.25 + 1.5 * phase), h * (.4 + i * .19)),
          width: w * .95,
          height: h * .15,
        ),
        Paint()
          ..color = Colors.white.withValues(alpha: .03)
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 36),
      );
    }

    // Embers drifting up from somewhere warm.
    for (int i = 0; i < 26; i++) {
      final double seed = (i * 37 % 100) / 100;
      final double speed = .45 + (i % 5) * .17;
      final double phase = (t * speed + seed) % 1;
      final double x =
          w * (.08 + .84 * ((i * 61 % 97) / 97)) +
          math.sin((phase + seed) * math.pi * 4) * w * .02;
      final double y = h * (1.02 - phase * 1.1);
      final double fade = math.sin(phase * math.pi).clamp(0.0, 1.0);
      canvas.drawCircle(
        Offset(x, y),
        .8 + (i % 4) * .6,
        Paint()
          ..color = _amber.withValues(alpha: .5 * fade)
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 2),
      );
    }

    // Vignette, so the middle of the screen stays readable.
    canvas.drawRect(
      Rect.fromLTWH(0, 0, w, h),
      Paint()
        ..shader = RadialGradient(
          center: Alignment.center,
          radius: .95,
          colors: <Color>[Colors.transparent, const Color(0xC4000000)],
          stops: const <double>[.42, 1],
        ).createShader(Rect.fromLTWH(0, 0, w, h)),
    );
    // Film grain: one texture across the whole night, photograph included.
    final math.Random grainSeed = math.Random(17);
    final Paint grainLight = Paint()
      ..color = Colors.white.withValues(alpha: .05);
    final Paint grainDark = Paint()
      ..color = Colors.black.withValues(alpha: .07);
    final int grainCount = (w * h / 2600).round().clamp(120, 900);
    for (int i = 0; i < grainCount; i++) {
      canvas.drawCircle(
        Offset(grainSeed.nextDouble() * w, grainSeed.nextDouble() * h),
        grainSeed.nextDouble() < .5 ? .6 : 1.1,
        grainSeed.nextDouble() < .5 ? grainLight : grainDark,
      );
    }
  }

  @override
  bool shouldRepaint(covariant _NightPainter old) => old.clock != clock;
}

/// The panther himself: a rim-lit head in the dark whose eyes open when the
/// screen settles, blink now and then, and flare when he is tapped awake.
class _PantherHead extends StatefulWidget {
  const _PantherHead();

  @override
  State<_PantherHead> createState() => _PantherHeadState();
}

class _PantherHeadState extends State<_PantherHead>
    with TickerProviderStateMixin {
  late final AnimationController _breath = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 4600),
  )..repeat();

  // 0 = lids shut, 1 = he is watching you.
  late final AnimationController _eyes = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1200),
  );

  late final AnimationController _blink = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 300),
  );

  late final AnimationController _flash = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 900),
  );

  Timer? _wakeTimer;
  Timer? _blinkTimer;

  @override
  void initState() {
    super.initState();
    // He wakes on his own five seconds after the door opens.
    _wakeTimer = Timer(const Duration(seconds: 5), () {
      if (!mounted) return;
      _eyes.forward();
      _flash.forward(from: 0);
    });
    _scheduleBlink();
  }

  final math.Random _rng = math.Random();

  /// Blinks land at an irregular beat, and now and then he blinks twice.
  void _scheduleBlink() {
    _blinkTimer?.cancel();
    _blinkTimer = Timer(Duration(milliseconds: 3400 + _rng.nextInt(3000)), () {
      if (!mounted) return;
      if (_eyes.value < .95) {
        _scheduleBlink();
        return;
      }
      _blink.forward(from: 0).whenComplete(() {
        if (!mounted) return;
        if (_rng.nextDouble() < .22) {
          Future<void>.delayed(const Duration(milliseconds: 130), () {
            if (!mounted) return;
            _blink.forward(from: 0).whenComplete(_scheduleBlink);
          });
        } else {
          _scheduleBlink();
        }
      });
    });
  }

  @override
  void dispose() {
    _wakeTimer?.cancel();
    _blinkTimer?.cancel();
    _breath.dispose();
    _eyes.dispose();
    _blink.dispose();
    _flash.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final bool still = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
    // Read the controllers inside the builder: capturing them once in build()
    // would freeze the eyes at whatever value they had on the first frame.
    return AnimatedBuilder(
      animation: Listenable.merge(<Listenable>[_breath, _eyes, _blink, _flash]),
      builder: (BuildContext context, Widget? child) {
        // A lid closes by covering the eye, not by fading it out.
        final double blink = still ? 0 : blinkLidAt(_blink.value);
        final double open = still
            ? 1
            : Curves.easeOutCubic.transform(_eyes.value).clamp(0.0, 1.0);
        final double flash = still ? 0 : _flash.value;
        final double swell =
            1 + .005 * math.sin((still ? .5 : _breath.value) * math.pi * 2);
        return ClipRect(
          child: Transform.scale(
            scale: swell,
            child: Stack(
              fit: StackFit.expand,
              children: <Widget>[
                IgnorePointer(
                  child: DecoratedBox(
                    decoration: BoxDecoration(
                      gradient: RadialGradient(
                        colors: <Color>[Color(0x1AF0B559), Color(0x00F0B559)],
                        stops: <double>[0, 1],
                      ),
                    ),
                  ),
                ),
                Image.memory(
                  _pantherBaseBytes,
                  fit: BoxFit.fill,
                  filterQuality: FilterQuality.high,
                  gaplessPlayback: true,
                ),
                // Only his eyes come alive - the rest of the face never moves.
                _eyePatch(_pantherEyeLBox, _pantherEyeLBytes, open, blink),
                _eyePatch(_pantherEyeRBox, _pantherEyeRBytes, open, blink),
                IgnorePointer(
                  child: CustomPaint(
                    painter: _PantherGlowPainter(
                      open: open * (1 - blink),
                      flash: flash,
                    ),
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  Widget _eyePatch(Rect box, Uint8List bytes, double open, double blink) =>
      Positioned.fill(
        child: LayoutBuilder(
          builder: (BuildContext context, BoxConstraints c) => Stack(
            clipBehavior: Clip.none,
            children: <Widget>[
              Positioned(
                left: box.left * c.maxWidth,
                top: box.top * c.maxHeight,
                width: box.width * c.maxWidth,
                height: box.height * c.maxHeight,
                child: Opacity(
                  opacity: open,
                  // The lid sweeps down over the open eye plate, revealing the
                  // shut-lid photograph underneath instead of fading it.
                  child: ClipRect(
                    clipper: _LidClipper(blink),
                    child: Image.memory(
                      bytes,
                      fit: BoxFit.fill,
                      filterQuality: FilterQuality.high,
                      gaplessPlayback: true,
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
      );
}

/// How far the lid has come down, 0 = wide open, 1 = shut. It drops quickly,
/// rests for an instant, then lifts slowly, which is what a real blink does.
double blinkLidAt(double t) {
  final double v = t.clamp(0.0, 1.0);
  const double closeEnd = .34;
  const double holdEnd = .40;
  if (v < closeEnd) {
    return Curves.easeInCubic.transform(v / closeEnd);
  }
  if (v < holdEnd) return 1;
  return 1 - Curves.easeOutCubic.transform((v - holdEnd) / (1 - holdEnd));
}

/// Swallows the top of an open-eye plate as the lid comes down.
class _LidClipper extends CustomClipper<Rect> {
  const _LidClipper(this.shut);

  final double shut;

  @override
  Rect getClip(Size size) => Rect.fromLTWH(
    0,
    size.height * shut,
    size.width,
    size.height * (1 - shut),
  );

  @override
  bool shouldReclip(covariant _LidClipper old) => old.shut != shut;
}

