/// The warm spill that rolls out of his eyes when they open.
class _PantherGlowPainter extends CustomPainter {
  _PantherGlowPainter({required this.open, required this.flash});

  final double open;
  final double flash;

  @override
  bool hitTest(Offset position) => false;

  @override
  void paint(Canvas canvas, Size size) {
    final double a = (.14 * open + .5 * flash).clamp(0.0, .85);
    if (a < .01) return;
    for (final Rect box in <Rect>[_pantherEyeLBox, _pantherEyeRBox]) {
      final Offset c = Offset(
        box.center.dx * size.width,
        box.center.dy * size.height,
      );
      final double r = size.width * (.06 + .05 * flash);
      canvas.drawCircle(
        c,
        r,
        Paint()
          ..shader = RadialGradient(
            colors: <Color>[
              Color(0xFFF7C368).withValues(alpha: a),
              Color(0x00F0B559),
            ],
          ).createShader(Rect.fromCircle(center: c, radius: r))
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 14),
      );
    }
  }

  @override
  bool shouldRepaint(covariant _PantherGlowPainter old) =>
      old.open != open || old.flash != flash;
}

