/// Loads the three intro typefaces before the first frame, so the opening
/// script never flashes in a fallback face. Kept in code (like the mark) so a
/// single-file drop-in needs no pubspec asset wiring.
Future<void> loadIntroFonts() async {
  Future<void> load(String family, String b64) async {
    final FontLoader loader = FontLoader(family)
      ..addFont(Future<ByteData>.value(base64Decode(b64).buffer.asByteData()));
    await loader.load();
  }

  await Future.wait(<Future<void>>[
    load(_introScript, _kIntroScriptB64),
    load(_introSerifItalic, _kIntroSerifItalicB64),
    load(_introSerifBold, _kIntroSerifBoldB64),
    load(_introSans, _kIntroSansB64),
    load(_introSansSemi, _kIntroSansSemiB64),
  ]);
}

