/// Minimal SVG path reader — enough for the absolute M/C/L/H/V/Z data above,
/// which is what the website uses for every stroke it animates.
Path _introPath(String d) {
  final Path path = Path();
  final RegExp token = RegExp(r'[MmLlCcHhVvZz]|-?\d*\.?\d+(?:[eE][-+]?\d+)?');
  final List<String> t = token
      .allMatches(d)
      .map((Match m) => m.group(0)!)
      .toList(growable: false);
  var i = 0;
  var cmd = '';
  var x = 0.0;
  var y = 0.0;
  double next() => double.parse(t[i++]);
  while (i < t.length) {
    final String s = t[i];
    if (!RegExp(r'\d|\.').hasMatch(s.substring(0, 1))) {
      cmd = s;
      i++;
      if (cmd == 'Z' || cmd == 'z') path.close();
      continue;
    }
    switch (cmd) {
      case 'M':
        x = next();
        y = next();
        path.moveTo(x, y);
        cmd = 'L';
        break;
      case 'm':
        x += next();
        y += next();
        path.moveTo(x, y);
        cmd = 'l';
        break;
      case 'L':
        x = next();
        y = next();
        path.lineTo(x, y);
        break;
      case 'l':
        x += next();
        y += next();
        path.lineTo(x, y);
        break;
      case 'C':
        final double x1 = next(), y1 = next(), x2 = next();
        final double y2 = next();
        x = next();
        y = next();
        path.cubicTo(x1, y1, x2, y2, x, y);
        break;
      case 'c':
        final double x1 = x + next(), y1 = y + next(), x2 = x + next();
        final double y2 = y + next();
        x += next();
        y += next();
        path.cubicTo(x1, y1, x2, y2, x, y);
        break;
      case 'H':
        x = next();
        path.lineTo(x, y);
        break;
      case 'h':
        x += next();
        path.lineTo(x, y);
        break;
      case 'V':
        y = next();
        path.lineTo(x, y);
        break;
      case 'v':
        y += next();
        path.lineTo(x, y);
        break;
      default:
        i++;
        break;
    }
  }
  return path;
}

class _IntroStar {
  _IntroStar(math.Random r)
    : x = r.nextDouble(),
      y = r.nextDouble() * .62,
      scale = .6 + r.nextDouble() * .9,
      delay = r.nextDouble() * 4,
      dur = 3 + r.nextDouble() * 3;
  final double x, y, scale, delay, dur;
}

class _IntroSpore {
  _IntroSpore(math.Random r)
    : x = r.nextDouble(),
      bottom = -.05 + r.nextDouble() * .4,
      delay = r.nextDouble() * 6,
      dur = 6 + r.nextDouble() * 5;
  final double x, bottom, delay, dur;
}

class _IntroLeaf {
  const _IntroLeaf(this.at, this.angle, this.scale, this.appear, this.isBud);
  final Offset at;
  final double angle;
  final double scale;
  final double appear;
  final bool isBud;
}

/// Pre-computes where the leaves and buds sit along each vine, exactly the way
/// the website walks every path at load time.
List<List<_IntroLeaf>> _introLeaves() {
  final math.Random r = math.Random(20261106);
  final List<List<_IntroLeaf>> out = <List<_IntroLeaf>>[];
  for (final _IntroStroke v in _introVines) {
    final List<_IntroLeaf> list = <_IntroLeaf>[];
    for (final ui.PathMetric m in _introPath(v.d).computeMetrics()) {
      var fr = .10;
      var flip = false;
      while (fr < .97) {
        final ui.Tangent? a = m.getTangentForOffset(m.length * fr);
        final ui.Tangent? b = m.getTangentForOffset(
          math.min(m.length, m.length * fr + 2),
        );
        if (a != null && b != null) {
          final double ang =
              math.atan2(
                b.position.dy - a.position.dy,
                b.position.dx - a.position.dx,
              ) *
              180 /
              math.pi;
          final double appear =
              v.delay + fr * v.dur * .9 + r.nextDouble() * .25;
          if (r.nextDouble() < .8) {
            list.add(
              _IntroLeaf(
                a.position,
                ang + (flip ? 90 : -90) + (r.nextDouble() * 36 - 18),
                .65 + r.nextDouble() * .55,
                appear,
                false,
              ),
            );
          } else {
            list.add(
              _IntroLeaf(a.position, 0, 2 + r.nextDouble() * 1.6, appear, true),
            );
          }
        }
        flip = !flip;
        fr += .05 + r.nextDouble() * .04;
      }
    }
    out.add(list);
  }
  return out;
}

