/// Hosts the intro over the app and decides which version plays: the everyday
/// cinema, or the birthday one on the person's own birthday.
class VeilHost extends StatefulWidget {
  const VeilHost({super.key, required this.child, required this.triggerName});

  final Widget child;
  final String? triggerName;

  @override
  State<VeilHost> createState() => _VeilHostState();
}

class _VeilHostState extends State<VeilHost> {
  bool _show = true;

  /// Bumped whenever the answer to "is it his birthday" changes, which forces
  /// the veil to start again in the right mode.
  int _round = 0;
  bool _wasBirthday = false;
  String? _veilFor;

  /// True only when today is the logged-in person's own birthday — never a
  /// batchmate's or a colleague's. Students are matched through their student
  /// record, teachers, staff and admin through their own profile.
  bool get _birthday {
    final Store s = Store.I;
    final Map<String, dynamic>? u = s.me;
    if (u == null) return false;

    // Students keep the date on their student record; the office types the
    // birthday of a teacher, staff member or admin straight onto their login.
    // `bdayToday` reads `dob` and `birthday`, both orders, so every route works.
    if (u['role'] == 'student') {
      final Map<String, dynamic>? rec = s.studentOfUser(u['id'].toString());
      if (bdayToday(rec)) return true;
    }
    return bdayToday(u);
  }

  @override
  void initState() {
    super.initState();
    Store.I.addListener(_onStore);
    // The office may have set a birthday on the website a moment ago, so ask the
    // cloud once as the veil opens. If it lands, the veil replays as a birthday.
    unawaited(Store.I.syncFromCloud(quiet: true));
  }

  @override
  void dispose() {
    Store.I.removeListener(_onStore);
    super.dispose();
  }

  /// The cloud pull can land a moment after the veil has already started, and
  /// an office edit can change the birthday while the app is open. Whenever the
  /// answer changes, the veil replays in the mode that fits.
  void _onStore() {
    if (!mounted || !_show) return;
    final String? id = Store.I.me?['id']?.toString();
    final bool now = _birthday;
    if (id == null) return;
    if (id != _veilFor || now != _wasBirthday) {
      setState(() {
        _veilFor = id;
        _wasBirthday = now;
        _round++;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final Map<String, dynamic>? me = Store.I.me;
    final bool ready = me != null;
    if (ready) {
      _veilFor ??= me['id']?.toString();
      _wasBirthday = _birthday;
    }
    final String name = widget.triggerName ?? me?['name']?.toString() ?? '';
    return Stack(
      children: <Widget>[
        widget.child,
        // Never start the veil before his record is on hand, or it would play
        // the everyday scene and refuse to switch once the birthday arrives.
        if (_show && widget.triggerName != null && ready)
          Positioned.fill(
            child: WelcomeVeil(
              key: ValueKey<String>('veil_${me['id']}_$_round'),
              name: name,
              birthday: _birthday,
              onDone: () {
                if (mounted) setState(() => _show = false);
              },
            ),
          ),
      ],
    );
  }
}

class WelcomeVeil extends StatefulWidget {
  const WelcomeVeil({
    super.key,
    required this.name,
    required this.onDone,
    this.birthday = false,
  });

  final String name;
  final VoidCallback onDone;
  final bool birthday;

  @override
  State<WelcomeVeil> createState() => _WelcomeVeilState();
}

class _WelcomeVeilState extends State<WelcomeVeil>
    with TickerProviderStateMixin {
  /// The website runs the whole signature sequence on an 8.8 s clock.
  static const double _total = 8.8;

  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 8800),
  );
  late final AnimationController _idle = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 4),
  );
  late final AnimationController _amb = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 60),
  );
  late final AnimationController _entry = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1600),
  );
  late final AnimationController _open = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 3),
  );

  bool _ready = false;
  bool _reduce = false;
  bool _leaving = false;
  bool _opened = false;
  Timer? _autoLeave;
  Timer? _autoOpen;
  Timer? _done;

  final List<_IntroStar> _stars = <_IntroStar>[];
  final List<_IntroSpore> _spores = <_IntroSpore>[];
  final List<List<_IntroLeaf>> _leaves = _introLeaves();
  final List<List<ui.PathMetric>> _vineMetrics = <List<ui.PathMetric>>[];
  final List<List<ui.PathMetric>> _signMetrics = <List<ui.PathMetric>>[];
  final List<ui.PathMetric> _flourishMetrics = <ui.PathMetric>[];

  final List<_BdayPiece> _confetti = <_BdayPiece>[];
  final List<_BdayBalloonPiece> _balloons = <_BdayBalloonPiece>[];
  final List<_BdaySparkPiece> _sparks = <_BdaySparkPiece>[];
  final List<_BdayBurstPiece> _burst = <_BdayBurstPiece>[];

  @override
  void initState() {
    super.initState();
    final math.Random r = math.Random(7);
    for (var i = 0; i < 44; i++) {
      _stars.add(_IntroStar(r));
    }
    for (var i = 0; i < 14; i++) {
      _spores.add(_IntroSpore(r));
    }
    for (final _IntroStroke s in _introVines) {
      _vineMetrics.add(_introPath(s.d).computeMetrics().toList());
    }
    for (final _IntroStroke s in _introSign) {
      _signMetrics.add(_introPath(s.d).computeMetrics().toList());
    }
    _flourishMetrics.addAll(_introPath(_introFlourishD).computeMetrics());

    final math.Random c = math.Random(11);
    for (var i = 0; i < 60; i++) {
      _confetti.add(
        _BdayPiece(
          x: c.nextDouble(),
          w: i % 5 == 0 ? 6 : 8,
          h: i % 5 == 0 ? 6 : 14,
          color: _bdayColors[i % _bdayColors.length],
          delay: c.nextDouble() * 4.5,
          dur: 3.4 + c.nextDouble() * 2.8,
          round: i % 3 == 0 || i % 5 == 0,
        ),
      );
    }
    for (var i = 0; i < 9; i++) {
      _balloons.add(
        _BdayBalloonPiece(
          x: .06 + c.nextDouble() * .88,
          color: _bdayColors[(i + 2) % _bdayColors.length],
          delay: c.nextDouble() * 5.5,
          dur: 7 + c.nextDouble() * 4.5,
          size: 34 + c.nextDouble() * 12,
        ),
      );
    }
    for (var i = 0; i < 16; i++) {
      _sparks.add(
        _BdaySparkPiece(
          x: .08 + c.nextDouble() * .84,
          y: .06 + c.nextDouble() * .7,
          color: _bdayColors[(i + 1) % _bdayColors.length],
          delay: c.nextDouble() * 7,
          dur: 1.6 + c.nextDouble() * 1.4,
        ),
      );
    }
    for (var i = 0; i < 44; i++) {
      final double a = math.pi * 2 * i / 44 + c.nextDouble() * .35;
      final double rad = 90 + c.nextDouble() * 230;
      _burst.add(
        _BdayBurstPiece(
          dx: math.cos(a) * rad,
          dy: math.sin(a) * rad * .9 - 50,
          w: 5 + c.nextDouble() * 7,
          h: 6 + c.nextDouble() * 10,
          rot: c.nextDouble() * 720 - 360,
          color: _bdayColors[i % _bdayColors.length],
          dur: .9 + c.nextDouble() * .8,
          round: c.nextBool(),
        ),
      );
    }
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (_ready) return;
    _ready = true;
    _reduce = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
    if (_reduce) {
      _idle.value = .5;
      _amb.value = .5;
      _entry.value = 1;
      _c.value = 1;
    } else {
      _idle.repeat();
      if (widget.birthday) {
        _amb.repeat();
        _entry.forward();
      } else {
        _c.forward();
      }
    }
    if (widget.birthday) {
      _autoOpen = Timer(Duration(milliseconds: _reduce ? 400 : 11000), () {
        if (!_opened) _openGift();
      });
    } else {
      _autoLeave = Timer(Duration(milliseconds: _reduce ? 1800 : 8800), _leave);
    }
  }

  @override
  void dispose() {
    _autoLeave?.cancel();
    _autoOpen?.cancel();
    _done?.cancel();
    _c.dispose();
    _idle.dispose();
    _amb.dispose();
    _entry.dispose();
    _open.dispose();
    super.dispose();
  }

  /// Seconds into the 8.8 s signature sequence.
  double get _el => _c.value * _total;

  /// Seconds since the gift was opened.
  double get _openedFor => _open.value * 3;

  /// Seconds since the birthday stage came up.
  double get _entryFor => _entry.value * 1.6;

  /// Progress of a timeline segment that starts at [start] and lasts [dur].
  double _phase(double start, double dur) =>
      ((_el - start) / dur).clamp(0.0, 1.0).toDouble();

  void _leave() {
    if (_leaving) return;
    setState(() => _leaving = true);
    _autoLeave?.cancel();
    _autoOpen?.cancel();
    _done?.cancel();
    _done = Timer(const Duration(milliseconds: 1100), () {
      if (mounted) widget.onDone();
    });
  }

  void _openGift() {
    if (_opened || _leaving) return;
    HapticFeedback.mediumImpact();
    setState(() => _opened = true);
    _autoOpen?.cancel();
    _open.forward(from: 0);
    _autoLeave?.cancel();
    _autoLeave = Timer(Duration(milliseconds: _reduce ? 2600 : 12000), _leave);
  }

  void _tap() {
    if (!widget.birthday) {
      _leave();
    } else if (_opened) {
      _leave();
    } else {
      _openGift();
    }
  }

  @override
  Widget build(BuildContext context) {
    final String first = widget.name.trim().split(RegExp(r'\s+')).first;
    final String greeting = first.isEmpty
        ? T('Welcome back')
        : TT('Hello, {0}', <Object?>[first]);
    return AnimatedOpacity(
      opacity: _leaving ? 0 : 1,
      duration: const Duration(milliseconds: 1000),
      curve: Curves.easeInOut,
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: _tap,
        child: ColoredBox(
          color: const Color(0xFF030403),
          // Pin the text style: without a Material ancestor Flutter would fall
          // back to its loud red-on-yellow debug style.
          child: DefaultTextStyle(
            style: const TextStyle(
              decoration: TextDecoration.none,
              color: Color(0xFFF0E7CF),
              fontSize: 14,
            ),
            child: AnimatedBuilder(
              animation: Listenable.merge(<Listenable>[
                _c,
                _idle,
                _amb,
                _entry,
                _open,
              ]),
              builder: (BuildContext context, Widget? _) =>
                  widget.birthday ? _birthdayStage() : _cinemaStage(greeting),
            ),
          ),
        ),
      ),
    );
  }

  // -------------------------------------------------------------- everyday --

  Widget _cinemaStage(String greeting) {
    final Size size = MediaQuery.sizeOf(context);
    final double w = size.width;
    final double helloSize = (w * .07).clamp(33.6, 52.8);
    final double welcomeSize = (w * .034).clamp(18.4, 25.6);
    final double toSize = (w * .018).clamp(10.56, 12.8);
    final double subSize = (w * .026).clamp(15.2, 21.6);
    final double signW = math.min(w * .72, 520.0);

    return Stack(
      children: <Widget>[
        Positioned.fill(
          child: CustomPaint(
            painter: _IntroSkyPainter(
              elapsed: _el,
              twinkle: _idle.value,
              halo: _phase(6.1, 2.4),
              stars: _stars,
              spores: _spores,
              animate: !_reduce,
            ),
          ),
        ),
        Positioned.fill(
          child: CustomPaint(
            painter: _IntroVinePainter(
              elapsed: _el,
              vines: _introVines,
              metrics: _vineMetrics,
              leaves: _leaves,
              animate: !_reduce,
            ),
          ),
        ),
        Center(
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 24),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: <Widget>[
                _hello(greeting, helloSize),
                const SizedBox(height: 20),
                _welcomeWord(_phase(2.15, 1.1), welcomeSize),
                const SizedBox(height: 10),
                _smallCaps(_phase(2.95, .9), toSize),
                const SizedBox(height: 2),
                Transform.translate(
                  offset: Offset(0, -20 * (signW / 640)),
                  child: SizedBox(
                    width: signW,
                    height: signW * 300 / 640,
                    child: CustomPaint(
                      painter: _IntroSignPainter(
                        elapsed: _el,
                        strokes: _introSign,
                        metrics: _signMetrics,
                        flourish: _flourishMetrics,
                        animate: !_reduce,
                      ),
                    ),
                  ),
                ),
                _subWord(_phase(6.4, 1.4), subSize),
              ],
            ),
          ),
        ),
        Positioned(
          left: 0,
          right: 0,
          bottom: 26,
          child: Opacity(
            opacity: .85 * _phase(7.2, .9),
            child: Text(
              T('Tap anywhere to continue').toUpperCase(),
              textAlign: TextAlign.center,
              style: const TextStyle(
                fontFamily: _introSans,
                color: Color(0xFF5C6358),
                fontSize: 10.9,
                letterSpacing: 1.96,
              ),
            ),
          ),
        ),
      ],
    );
  }

  /// "Hello, name" written across a script line, with the glowing nib that
  /// travels the full width of the words.
  Widget _hello(String greeting, double size) {
    final double p = _phase(.45, 1.5);
    final double eased = Curves.easeInOutCubic.transform(p);
    final TextStyle style = TextStyle(
      fontFamily: _introScript,
      fontSize: size,
      height: 1.15,
      color: const Color(0xFFF0E7CF),
      shadows: const <Shadow>[Shadow(color: Color(0x40F0E7CF), blurRadius: 12)],
    );
    return LayoutBuilder(
      builder: (BuildContext context, BoxConstraints box) {
        final TextPainter tp = TextPainter(
          text: TextSpan(text: greeting, style: style),
          textDirection: Directionality.of(context),
          maxLines: 1,
        )..layout();
        final double tw = math.min(tp.width, box.maxWidth);
        final double th = tp.height;
        return SizedBox(
          width: box.maxWidth,
          height: th,
          child: Stack(
            clipBehavior: Clip.none,
            children: <Widget>[
              Positioned.fill(
                child: ClipRect(
                  clipper: _LeftReveal(p * 1.05),
                  child: Align(
                    alignment: Alignment.center,
                    child: Text(
                      greeting,
                      textAlign: TextAlign.center,
                      maxLines: 1,
                      style: style,
                    ),
                  ),
                ),
              ),
              if (!_reduce && p > 0 && p < 1)
                Positioned(
                  left: (box.maxWidth - tw) / 2 + tw * eased - 4.5,
                  top: th * .62 - 4.5 + math.sin(eased * math.pi * 2) * 3,
                  child: _GlowNib(
                    size: 9,
                    opacity: p < .05 ? p / .05 : (p > .95 ? (1 - p) / .05 : 1),
                  ),
                ),
            ],
          ),
        );
      },
    );
  }

  Widget _welcomeWord(double p, double size) {
    final double eased = Curves.easeOutCubic.transform(p);
    return Opacity(
      opacity: eased.clamp(0.0, 1.0),
      child: Transform.translate(
        offset: Offset(0, 14 * (1 - eased)),
        child: Text(
          'WELCOME',
          style: TextStyle(
            fontFamily: _introSerifItalic,
            fontSize: size,
            color: const Color(0xFFF4EFDF),
            letterSpacing: size * (0.55 + (0.34 - 0.55) * eased),
            shadows: const <Shadow>[
              Shadow(color: Color(0x2EF4EFDF), blurRadius: 10),
            ],
          ),
        ),
      ),
    );
  }

  Widget _smallCaps(double p, double size) {
    final double eased = Curves.easeOutCubic.transform(p);
    return Opacity(
      opacity: .92 * eased.clamp(0.0, 1.0),
      child: Transform.translate(
        offset: Offset(0, 8 * (1 - eased)),
        child: Text(
          'TO',
          style: TextStyle(
            fontFamily: _introSansSemi,
            color: const Color(0xFFA8A088),
            fontSize: size,
            letterSpacing: size * .62,
          ),
        ),
      ),
    );
  }

  Widget _subWord(double p, double size) {
    final double eased = Curves.easeOutCubic.transform(p);
    return Padding(
      padding: const EdgeInsets.only(top: 4),
      child: Opacity(
        opacity: eased.clamp(0.0, 1.0),
        child: Transform.translate(
          offset: Offset(0, 12 * (1 - eased)),
          child: Text(
            'INSTITUTE',
            style: TextStyle(
              fontFamily: _introSerifBold,
              fontSize: size,
              color: const Color(0xFFF4EFDF),
              letterSpacing: size * (0.7 + (0.42 - 0.7) * eased),
            ),
          ),
        ),
      ),
    );
  }

  // -------------------------------------------------------------- birthday --

  Widget _birthdayStage() {
    final Size size = MediaQuery.sizeOf(context);
    final double w = size.width;
    final double titleSize = (w * .074).clamp(27.2, 49.6);
    final double nameSize = (w * .09).clamp(36.8, 64.0);
    final double subSize = (w * .026).clamp(14.7, 18.4);
    final double since = _openedFor;
    final String first = widget.name.trim().split(RegExp(r'\s+')).first;
    final double subP = ((since - 2.1) / .9).clamp(0.0, 1.0);
    final double nameP = ((since - 1.5) / .8).clamp(0.0, 1.0);
    final double skipP = ((_entryFor - 1.2) / .9).clamp(0.0, 1.0);

    return DecoratedBox(
      decoration: const BoxDecoration(
        gradient: RadialGradient(
          center: Alignment(0, -.64),
          radius: 1.15,
          colors: <Color>[
            Color(0xFF2E2350),
            Color(0xFF17102C),
            Color(0xFF0B081A),
          ],
          stops: <double>[0, .55, 1],
        ),
      ),
      child: ClipRect(
        child: Stack(
          children: <Widget>[
            Positioned.fill(
              child: Opacity(
                opacity: _opened ? 1 : .22,
                child: CustomPaint(
                  painter: _BdaySkyPainter(
                    amb: _amb.value * 60,
                    confetti: _confetti,
                    balloons: _balloons,
                    sparks: _sparks,
                    animate: !_reduce,
                  ),
                ),
              ),
            ),
            if (_opened)
              Positioned.fill(
                child: IgnorePointer(
                  child: CustomPaint(
                    painter: _BdayBurstPainter(
                      progress: (since / 1.7).clamp(0.0, 1.0),
                      pieces: _burst,
                      size: size,
                    ),
                  ),
                ),
              ),
            Center(
              child: Padding(
                padding: const EdgeInsets.symmetric(horizontal: 24),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: <Widget>[
                    _gift(size),
                    if (_opened) ...<Widget>[
                      _bdayTitle(titleSize, since),
                      if (first.isNotEmpty) ...<Widget>[
                        const SizedBox(height: 2),
                        Opacity(
                          opacity: nameP,
                          child: Transform.translate(
                            offset: Offset(0, 10 * (1 - nameP)),
                            child: Text(
                              first,
                              style: TextStyle(
                                fontFamily: _introScript,
                                fontSize: nameSize,
                                height: 1.15,
                                color: const Color(0xFFF0B559),
                                shadows: const <Shadow>[
                                  Shadow(
                                    color: Color(0x8CF0B559),
                                    blurRadius: 26,
                                  ),
                                ],
                              ),
                            ),
                          ),
                        ),
                      ],
                      const SizedBox(height: 18),
                      Opacity(
                        opacity: .95 * subP,
                        child: Text(
                          T(
                            'Wishing you a wonderful day, from everyone at JSK '
                            'Institute.',
                          ),
                          textAlign: TextAlign.center,
                          style: TextStyle(
                            fontFamily: _introSans,
                            color: const Color(0xFFE7DCC6),
                            fontSize: subSize,
                            height: 1.6,
                          ),
                        ),
                      ),
                    ],
                  ],
                ),
              ),
            ),
            Positioned(
              left: 0,
              right: 0,
              bottom: 26,
              child: Opacity(
                opacity: .85 * skipP,
                child: Text(
                  (_opened
                          ? T('Tap anywhere to continue')
                          : T('A gift for you — tap the box to open it'))
                      .toUpperCase(),
                  textAlign: TextAlign.center,
                  style: const TextStyle(
                    fontFamily: _introSans,
                    color: Color(0xFF9089A6),
                    fontSize: 10.9,
                    letterSpacing: 1.96,
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _gift(Size size) {
    final double side = math.min(size.width * .46, 215.0);
    final double t = _openedFor;
    // A photograph cannot fly its lid off, so the box opens as a quick light
    // strike: the lid-off shot fades in under a warm flash.
    final double openP = Curves.easeOut.transform(
      (t / .26).clamp(0.0, 1.0).toDouble(),
    );
    final double flashP = ((t - .04) / .5).clamp(0.0, 1.0).toDouble();
    final double glowP = (t / .9).clamp(0.0, 1.0).toDouble();
    final double collapseP = Curves.easeIn.transform(
      ((t - 1.0) / .55).clamp(0.0, 1.0).toDouble(),
    );
    final double inP = _reduce
        ? 1.0
        : Curves.easeOutBack.transform(
            ((_entryFor - .45) / .85).clamp(0.0, 1.0).toDouble(),
          );
    final double bob = 1 + .03 * math.sin(_idle.value * math.pi * 2);

    if (collapseP >= 1) return const SizedBox.shrink();

    return Opacity(
      opacity: (inP * (1 - collapseP)).clamp(0.0, 1.0),
      child: Transform.rotate(
        angle: -.012 * math.sin(_idle.value * math.pi * 2),
        child: Transform.scale(
          scale: (bob * (1 + .06 * flashP) * inP).clamp(0.0, 2.0),
          child: Transform.translate(
            offset: Offset(0, -size.height * .03 * flashP),
            child: SizedBox(
              width: side,
              height: side,
              child: Stack(
                clipBehavior: Clip.none,
                children: <Widget>[
                  // warm halo behind the box
                  Positioned(
                    left: -side * .34,
                    top: -side * .34,
                    right: -side * .34,
                    bottom: -side * .34,
                    child: Opacity(
                      opacity:
                          (.5 + .5 * math.sin(_idle.value * math.pi * 2)) *
                          (1 - .6 * glowP),
                      child: const DecoratedBox(
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          gradient: RadialGradient(
                            colors: <Color>[
                              Color(0x5CF0B559),
                              Color(0x14F0B559),
                              Color(0x00F0B559),
                            ],
                            stops: <double>[0, .45, .78],
                          ),
                        ),
                      ),
                    ),
                  ),
                  Positioned.fill(
                    child: Opacity(
                      opacity: (1 - openP).clamp(0.0, 1.0),
                      child: Image.memory(
                        _giftClosedBytes,
                        fit: BoxFit.contain,
                        filterQuality: FilterQuality.high,
                        gaplessPlayback: true,
                      ),
                    ),
                  ),
                  Positioned.fill(
                    child: Opacity(
                      opacity: openP,
                      child: Image.memory(
                        _giftOpenBytes,
                        fit: BoxFit.contain,
                        filterQuality: FilterQuality.high,
                        gaplessPlayback: true,
                      ),
                    ),
                  ),
                  // the light that covers the switch
                  Positioned.fill(
                    child: IgnorePointer(
                      child: Opacity(
                        opacity: (.6 * (1 - flashP)).clamp(0.0, 1.0),
                        child: const DecoratedBox(
                          decoration: BoxDecoration(
                            shape: BoxShape.circle,
                            gradient: RadialGradient(
                              colors: <Color>[
                                Color(0xE6FFEBC4),
                                Color(0x00FFEBC4),
                              ],
                              stops: <double>[0, .7],
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }

  /// A gift panel: gradient body, soft inner light, and the gold ribbon band.
  Widget _bdayTitle(double size, double since) {
    final List<Widget> letters = <Widget>[];
    var index = 0;
    for (final String ch in 'HAPPY BIRTHDAY'.split('')) {
      if (ch == ' ') {
        letters.add(SizedBox(width: size * .42));
        continue;
      }
      final int i = index++;
      final double p = ((since - (.55 + i * .05)) / .6).clamp(0.0, 1.0);
      final double e = Curves.easeOutBack.transform(p);
      letters.add(
        Opacity(
          opacity: p,
          child: Transform.translate(
            offset: Offset(0, 36 * (1 - e)),
            child: Transform.rotate(
              angle: -.157 * (1 - e),
              child: Transform.scale(
                scale: .3 + .7 * e,
                child: Text(
                  ch,
                  style: TextStyle(
                    fontFamily: _introSerifBold,
                    fontSize: size,
                    height: 1.25,
                    color: const Color(0xFFFCEFD8),
                    letterSpacing: size * .02,
                  ),
                ),
              ),
            ),
          ),
        ),
      );
    }
    return Wrap(
      alignment: WrapAlignment.center,
      crossAxisAlignment: WrapCrossAlignment.center,
      children: letters,
    );
  }
}

/// The glowing pen nib that trails the handwriting.
class _GlowNib extends StatelessWidget {
  const _GlowNib({required this.size, required this.opacity});

  final double size;
  final double opacity;

  @override
  Widget build(BuildContext context) {
    return Opacity(
      opacity: opacity.clamp(0.0, 1.0),
      child: Container(
        width: size,
        height: size,
        decoration: const BoxDecoration(
          color: Color(0xFFFFE9C2),
          shape: BoxShape.circle,
          boxShadow: <BoxShadow>[
            BoxShadow(color: Color(0xF2FFDE96), blurRadius: 7),
            BoxShadow(color: Color(0x8CE8A33D), blurRadius: 16),
          ],
        ),
      ),
    );
  }
}

/// Reveals a child from the left edge, the way the website's clip-path writes
/// the greeting on.
class _LeftReveal extends CustomClipper<Rect> {
  const _LeftReveal(this.progress);

  final double progress;

  @override
  Rect getClip(Size size) => Rect.fromLTWH(
    0,
    -size.height * .25,
    size.width * progress,
    size.height * 1.5,
  );

  @override
  bool shouldReclip(covariant _LeftReveal old) => old.progress != progress;
}

/// Night sky: the two soft air washes, the late halo, twinkling stars and the
/// golden spores drifting up.
class _IntroSkyPainter extends CustomPainter {
  const _IntroSkyPainter({
    required this.elapsed,
    required this.twinkle,
    required this.halo,
    required this.stars,
    required this.spores,
    required this.animate,
  });

  final double elapsed, twinkle, halo;
  final List<_IntroStar> stars;
  final List<_IntroSpore> spores;
  final bool animate;

  @override
  bool hitTest(Offset position) => false;

  void _wash(
    Canvas canvas,
    Offset center,
    double rx,
    double ry,
    List<Color> colors,
    List<double> stops,
  ) {
    canvas.save();
    canvas.translate(center.dx, center.dy);
    canvas.scale(rx, ry);
    canvas.drawCircle(
      Offset.zero,
      1,
      Paint()..shader = ui.Gradient.radial(Offset.zero, 1, colors, stops),
    );
    canvas.restore();
  }

  @override
  void paint(Canvas canvas, Size size) {
    _wash(
      canvas,
      Offset(size.width * .5, size.height * .4),
      size.width * .7,
      size.height * .45,
      const <Color>[Color(0x262E5B38), Color(0x00000000)],
      const <double>[0, .7],
    );
    _wash(
      canvas,
      Offset(size.width * .5, size.height * 1.08),
      size.width * .6,
      size.height * .3,
      const <Color>[Color(0x1AE8A33D), Color(0x00000000)],
      const <double>[0, .6],
    );

    if (halo > 0) {
      _wash(
        canvas,
        Offset(size.width * .5, size.height * .45),
        math.min(size.width * 1.1, 900) / 2,
        math.min(size.height * .68, 540) / 2,
        <Color>[
          Color.fromRGBO(232, 163, 61, .16 * halo),
          const Color(0x00E8A33D),
        ],
        const <double>[0, .62],
      );
    }

    if (!animate) return;

    for (final _IntroStar s in stars) {
      final double phase = ((twinkle * 4 + s.delay) / s.dur) * math.pi * 2;
      final double o = .12 + .68 * (.5 + .5 * math.sin(phase));
      canvas.drawCircle(
        Offset(s.x * size.width, s.y * size.height),
        s.scale,
        Paint()..color = Color.fromRGBO(245, 235, 210, o),
      );
    }

    for (final _IntroSpore p in spores) {
      final double raw = ((twinkle * 4 - p.delay) % p.dur) / p.dur;
      final double t = raw < 0 ? raw + 1 : raw;
      final double o = t < .12
          ? t / .12 * .7
          : (t < .55 ? .7 - (t - .12) / .43 * .3 : .4 * (1 - (t - .55) / .45));
      if (o <= .01) continue;
      final double r = 2.5 * (.7 + t * .45);
      _wash(
        canvas,
        Offset(
          p.x * size.width,
          size.height * (1 - p.bottom) - t * size.height * .46,
        ),
        r,
        r,
        <Color>[
          Color.fromRGBO(233, 196, 124, o.clamp(0.0, 1.0)),
          const Color(0x00E8A33D),
        ],
        const <double>[0, .7],
      );
    }
  }

  @override
  bool shouldRepaint(covariant _IntroSkyPainter old) =>
      old.elapsed != elapsed || old.twinkle != twinkle || old.halo != halo;
}

/// The border vines plus the leaves and buds that open along them.
class _IntroVinePainter extends CustomPainter {
  const _IntroVinePainter({
    required this.elapsed,
    required this.vines,
    required this.metrics,
    required this.leaves,
    required this.animate,
  });

  final double elapsed;
  final List<_IntroStroke> vines;
  final List<List<ui.PathMetric>> metrics;
  final List<List<_IntroLeaf>> leaves;
  final bool animate;

  static const Size _stage = Size(1440, 900);

  @override
  bool hitTest(Offset position) => false;

  @override
  void paint(Canvas canvas, Size size) {
    final double scale = math.max(
      size.width / _stage.width,
      size.height / _stage.height,
    );
    canvas.save();
    canvas.translate(
      (size.width - _stage.width * scale) / 2,
      (size.height - _stage.height * scale) / 2,
    );
    canvas.scale(scale);

    for (var i = 0; i < vines.length; i++) {
      final _IntroStroke v = vines[i];
      final double p = animate
          ? ((elapsed - v.delay) / v.dur).clamp(0.0, 1.0)
          : 1.0;
      if (p > 0 && i < metrics.length) {
        final Paint paint = Paint()
          ..style = PaintingStyle.stroke
          ..strokeCap = StrokeCap.round
          ..strokeWidth = v.thin ? 1.5 : 3
          ..color = v.thin ? const Color(0xD924402E) : const Color(0xE62C4E38);
        for (final ui.PathMetric m in metrics[i]) {
          canvas.drawPath(m.extractPath(0, m.length * p), paint);
        }
      }

      if (i >= leaves.length) continue;
      for (final _IntroLeaf lf in leaves[i]) {
        final double ap = animate
            ? ((elapsed - lf.appear) / .9).clamp(0.0, 1.0)
            : 1.0;
        if (ap <= 0) continue;
        final double grow = Curves.easeOutBack.transform(ap).clamp(0.0, 1.2);
        canvas.save();
        canvas.translate(lf.at.dx, lf.at.dy);
        canvas.rotate(lf.angle * math.pi / 180);
        if (lf.isBud) {
          canvas.scale(grow);
          canvas.drawCircle(
            Offset.zero,
            lf.scale,
            Paint()..color = Color.fromRGBO(232, 163, 61, .95 * ap),
          );
        } else {
          canvas.scale(grow * lf.scale);
          final Path leaf = Path()
            ..moveTo(0, 0)
            ..cubicTo(6, -7, 16, -9, 24, -2)
            ..cubicTo(16, 5, 6, 6, 0, 0)
            ..close();
          canvas.drawPath(
            leaf,
            Paint()
              ..shader = ui.Gradient.linear(
                Offset.zero,
                const Offset(24, 4),
                <Color>[
                  Color.fromRGBO(60, 138, 99, ap),
                  Color.fromRGBO(127, 176, 105, ap),
                  Color.fromRGBO(232, 163, 61, ap),
                ],
                const <double>[0, .65, 1],
              ),
          );
        }
        canvas.restore();
      }
    }
    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant _IntroVinePainter old) => old.elapsed != elapsed;
}

/// The hand-written JSK signature: three letters and the closing flourish,
/// inked on stroke by stroke with a glowing nib at the tip.
class _IntroSignPainter extends CustomPainter {
  const _IntroSignPainter({
    required this.elapsed,
    required this.strokes,
    required this.metrics,
    required this.flourish,
    required this.animate,
  });

  final double elapsed;
  final List<_IntroStroke> strokes;
  final List<List<ui.PathMetric>> metrics;
  final List<ui.PathMetric> flourish;
  final bool animate;

  static const Size _box = Size(640, 300);

  @override
  bool hitTest(Offset position) => false;

  @override
  void paint(Canvas canvas, Size size) {
    canvas.save();
    canvas.scale(size.width / _box.width);

    final Paint deepGlow = Paint()
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round
      ..strokeWidth = 4.4
      ..color = const Color(0x4DC97F1E)
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 16);
    final Paint glow = Paint()
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round
      ..strokeWidth = 4.4
      ..color = const Color(0x8CE8A33D)
      ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 6);
    final Paint ink = Paint()
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round
      ..strokeWidth = 4.4
      ..shader = ui.Gradient.linear(
        Offset.zero,
        const Offset(640, 0),
        const <Color>[Color(0xFFF2C879), Color(0xFFE8A33D), Color(0xFFC97F1E)],
        const <double>[0, .5, 1],
      );

    Offset? nib;
    for (var i = 0; i < strokes.length && i < metrics.length; i++) {
      final _IntroStroke s = strokes[i];
      final double p = animate
          ? ((elapsed - s.delay) / s.dur).clamp(0.0, 1.0)
          : 1.0;
      if (p <= 0) continue;
      for (final ui.PathMetric m in metrics[i]) {
        final Path part = m.extractPath(0, m.length * p);
        canvas.drawPath(part, deepGlow);
        canvas.drawPath(part, glow);
        canvas.drawPath(part, ink);
        if (animate && p < 1) {
          nib = m.getTangentForOffset(m.length * p)?.position;
        }
      }
    }

    final double fp = animate ? ((elapsed - 6.05) / .65).clamp(0.0, 1.0) : 1.0;
    if (fp > 0) {
      final Paint f = Paint()
        ..style = PaintingStyle.stroke
        ..strokeCap = StrokeCap.round
        ..strokeWidth = 3
        ..color = const Color(0xFFD9A94E);
      for (final ui.PathMetric m in flourish) {
        canvas.drawPath(m.extractPath(0, m.length * fp), f);
      }
    }

    if (nib != null) {
      canvas.drawCircle(
        nib,
        9,
        Paint()
          ..color = const Color(0x8CFFDE96)
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 7),
      );
      canvas.drawCircle(nib, 4.5, Paint()..color = const Color(0xFFFFE9C2));
    }

    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant _IntroSignPainter old) => old.elapsed != elapsed;
}

/// Birthday sky: tumbling confetti, rising balloons and stray sparkles.
class _BdaySkyPainter extends CustomPainter {
  const _BdaySkyPainter({
    required this.amb,
    required this.confetti,
    required this.balloons,
    required this.sparks,
    required this.animate,
  });

  final double amb;
  final List<_BdayPiece> confetti;
  final List<_BdayBalloonPiece> balloons;
  final List<_BdaySparkPiece> sparks;
  final bool animate;

  static final Path _star8 = Path()
    ..moveTo(0, -1)
    ..lineTo(.22, -.22)
    ..lineTo(1, 0)
    ..lineTo(.22, .22)
    ..lineTo(0, 1)
    ..lineTo(-.22, .22)
    ..lineTo(-1, 0)
    ..lineTo(-.22, -.22)
    ..close();

  static const List<double> _fallT = <double>[0, .22, .38, .54, .7, 1];
  static const List<double> _fallX = <double>[0, .03, -.04, .04, -.03, .02];
  static const List<double> _fallY = <double>[-.06, .24, .44, .64, .84, 1.12];
  static const List<double> _fallR = <double>[0, 200, 340, 480, 620, 760];
  static const List<double> _fallS = <double>[1, .35, 1, .35, 1, .6];
  static const List<double> _floatTiltT = <double>[0, .18, .36, .54, .72, 1];
  static const List<double> _floatTilt = <double>[-3, 5, -6, 5, -4, 3];

  @override
  bool hitTest(Offset position) => false;

  double _seg(double t, List<double> times, List<double> values) {
    for (var i = 1; i < times.length; i++) {
      if (t <= times[i]) {
        final double span = times[i] - times[i - 1];
        final double f = span == 0 ? 0 : (t - times[i - 1]) / span;
        return values[i - 1] + (values[i] - values[i - 1]) * f;
      }
    }
    return values.last;
  }

  double _fade(double t, double inAt, double outAt) {
    if (t <= inAt) return (t / inAt).clamp(0.0, 1.0);
    if (t < outAt) return .95;
    return (.95 * (1 - (t - outAt) / (1 - outAt))).clamp(0.0, .95);
  }

  @override
  void paint(Canvas canvas, Size size) {
    if (!animate) return;

    for (final _BdayPiece p in confetti) {
      final double raw = ((amb - p.delay) % p.dur) / p.dur;
      if (raw < 0) continue;
      final double o = _fade(raw, .06, .92);
      if (o <= .01) continue;
      canvas.save();
      canvas.translate(
        size.width * (p.x + _seg(raw, _fallT, _fallX)),
        size.height * _seg(raw, _fallT, _fallY),
      );
      canvas.rotate(_seg(raw, _fallT, _fallR) * math.pi / 180);
      canvas.scale(1, _seg(raw, _fallT, _fallS));
      if (p.round) {
        canvas.drawCircle(
          Offset.zero,
          p.w / 2,
          Paint()..color = p.color.withValues(alpha: o),
        );
      } else {
        canvas.drawRRect(
          RRect.fromRectAndRadius(
            Rect.fromCenter(center: Offset.zero, width: p.w, height: p.h),
            const Radius.circular(2),
          ),
          Paint()..color = p.color.withValues(alpha: o),
        );
      }
      canvas.restore();
    }

    for (final _BdayBalloonPiece b in balloons) {
      final double raw = ((amb - b.delay) % b.dur) / b.dur;
      if (raw < 0) continue;
      final double o = _fade(raw, .06, .94);
      if (o <= .01) continue;
      final double rise =
          _seg(raw, _fallT, _fallY) * -1.05; // mirror of the fall curve
      final double sway = _seg(raw, _fallT, _fallX) * 400;
      final double tilt = _seg(raw, _floatTiltT, _floatTilt) * math.pi / 180;
      canvas.save();
      canvas.translate(size.width * b.x + sway, size.height * (1.24 + rise));
      canvas.rotate(tilt);
      final Rect body = Rect.fromCenter(
        center: Offset(0, -b.size * .7),
        width: b.size,
        height: b.size * 1.27,
      );
      canvas.drawOval(
        body,
        Paint()
          ..shader = ui.Gradient.linear(body.topLeft, body.bottomRight, <Color>[
            b.color.withValues(alpha: o),
            b.color.withValues(alpha: o * .82),
          ]),
      );
      canvas.drawOval(
        Rect.fromCircle(
          center: Offset(-b.size * .18, -b.size * .92),
          radius: b.size * .16,
        ),
        Paint()..color = Color.fromRGBO(255, 255, 255, .55 * o),
      );
      canvas.drawLine(
        Offset(0, -b.size * .05),
        Offset(0, b.size * .55),
        Paint()
          ..color = Color.fromRGBO(255, 255, 255, .32 * o)
          ..strokeWidth = 1,
      );
      canvas.restore();
    }

    for (final _BdaySparkPiece s in sparks) {
      final double raw = ((amb - s.delay) % s.dur) / s.dur;
      if (raw < 0 || raw > .34) continue;
      final double o = raw < .12 ? raw / .12 : (1 - (raw - .12) / .18);
      if (o <= .01) continue;
      final double sc = raw < .12 ? raw / .12 : 1 - (raw - .12) / .18 * .7;
      canvas.save();
      canvas.translate(size.width * s.x, size.height * s.y);
      canvas.rotate(raw * .34 * 70 * math.pi / 180 * 3);
      canvas.scale(sc * 7);
      canvas.drawPath(_star8, Paint()..color = s.color.withValues(alpha: o));
      canvas.restore();
    }
  }

  @override
  bool shouldRepaint(covariant _BdaySkyPainter old) => old.amb != amb;
}

/// Confetti exploding out of the opened box.
class _BdayBurstPainter extends CustomPainter {
  const _BdayBurstPainter({
    required this.progress,
    required this.pieces,
    required this.size,
  });

  final double progress;
  final List<_BdayBurstPiece> pieces;
  final Size size;

  @override
  bool hitTest(Offset position) => false;

  @override
  void paint(Canvas canvas, Size canvasSize) {
    if (progress <= 0 || progress >= 1) return;
    final Offset from = Offset(size.width * .5, size.height * .44);
    for (final _BdayBurstPiece p in pieces) {
      final double t = (progress / p.dur).clamp(0.0, 1.0);
      final double e = Curves.easeOutCubic.transform(t);
      final double o = (1 - t).clamp(0.0, 1.0);
      if (o <= .01) continue;
      canvas.save();
      canvas.translate(from.dx + p.dx * e, from.dy + p.dy * e);
      canvas.rotate(p.rot * e * math.pi / 180);
      canvas.scale(.4 + .6 * e);
      if (p.round) {
        canvas.drawCircle(
          Offset.zero,
          p.w / 2,
          Paint()..color = p.color.withValues(alpha: o),
        );
      } else {
        canvas.drawRRect(
          RRect.fromRectAndRadius(
            Rect.fromCenter(center: Offset.zero, width: p.w, height: p.h),
            const Radius.circular(2),
          ),
          Paint()..color = p.color.withValues(alpha: o),
        );
      }
      canvas.restore();
    }
  }

  @override
  bool shouldRepaint(covariant _BdayBurstPainter old) =>
      old.progress != progress;
}

// ---------------------------------------------------------------------------
//  APP ROOT + SHELL (brand header, role navigation, page transitions)
// ---------------------------------------------------------------------------
Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await FcmPushService.initialize();
  // The welcome intro's typefaces travel inside this file; load them before
  // the first frame so the opening script never flashes a fallback face.
  try {
    await loadIntroFonts();
  } catch (e) {
    debugPrint('intro fonts unavailable: $e');
  }
  if (kSupabaseKey != 'PASTE_YOUR_SUPABASE_ANON_KEY' &&
      kSupabaseKey.isNotEmpty) {
    try {
      final projectId = Uri.parse(kSupabaseUrl).host.split('.').first;
      await Supabase.initialize(
        url: kSupabaseUrl,
        publishableKey: kSupabaseKey,
        authOptions: FlutterAuthClientOptions(
          localStorage: _SecureSupabaseSessionStorage(
            persistSessionKey: 'sb-$projectId-auth-token',
          ),
        ),
      );
    } catch (e) {
      debugPrint('Supabase init failed: $e');
    }
  }
  ErrorWidget.builder = (details) => Directionality(
    textDirection: TextDirection.ltr,
    child: ClipRect(
      child: ColoredBox(
        color: Color(0xFF1A1A16),
        child: Center(
          child: FittedBox(
            fit: BoxFit.scaleDown,
            child: SizedBox(
              width: 280,
              child: Padding(
                padding: EdgeInsets.all(12),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(
                      'JSK Institute',
                      textAlign: TextAlign.center,
                      style: TextStyle(
                        color: Color(0xFFF0B559),
                        fontFamily: 'serif',
                        fontSize: 16,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                    SizedBox(height: 8),
                    Text(
                      details.exceptionAsString(),
                      textAlign: TextAlign.center,
                      maxLines: 4,
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                        color: Color(0xFFF2EFE5),
                        fontSize: 11,
                        height: 1.35,
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        ),
      ),
    ),
  );
  try {
    await Store.I.boot();
  } catch (e) {
    // Never block the app on storage/network: fall back to the seed register.
    debugPrint('boot failed, using seed data: $e');
    Store.I.data = seedState();
    Store.I.booted = true;
  }
  runApp(JskApp());
}

class JskApp extends StatelessWidget {
  const JskApp({super.key});

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: Store.I,
      builder: (context, _) {
        final skin = Store.I.skin;
        final theme = skin.theme(Store.I.dark);
        return MaterialApp(
          title: T('JSK Attendance Register'),
          debugShowCheckedModeBanner: false,
          scaffoldMessengerKey: Store.I.messenger,
          theme: theme,
          builder: (context, child) {
            final mq = MediaQuery.of(context);
            final calm = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
            return MediaQuery(
              data: mq.copyWith(
                textScaler: TextScaler.linear(Store.I.textScale),
              ),
              child: Stack(
                fit: StackFit.expand,
                children: <Widget>[
                  child ?? const SizedBox.shrink(),
                  // the slow drift of petals and leaves over every page
                  if (!calm)
                    const Positioned.fill(
                      child: IgnorePointer(child: FallingLeaves()),
                    ),
                ],
              ),
            );
          },
          home: AnnotatedRegion<SystemUiOverlayStyle>(
            value: SystemUiOverlayStyle(
              statusBarColor: Colors.transparent,
              statusBarIconBrightness: Store.I.dark
                  ? Brightness.light
                  : Brightness.dark,
              systemNavigationBarColor: Store.I.dark ? Skin.night : Skin.cream,
              systemNavigationBarIconBrightness: Store.I.dark
                  ? Brightness.light
                  : Brightness.dark,
            ),
            // Rebuild the whole app when the language changes so every
            // screen picks up the new strings immediately.
            child: _Gate(
              key: ValueKey('gate_${Store.I.sessionNonce}_${Store.I.language}'),
            ),
          ),
        );
      },
    );
  }
}

class _Gate extends StatefulWidget {
  const _Gate({super.key});

  @override
  State<_Gate> createState() => _GateState();
}

class _GateState extends State<_Gate> {
  String? _veilFor;
  bool _updateCheckScheduled = false;
  String? _permissionPromptScheduledFor;

  @override
  Widget build(BuildContext context) {
    final s = Store.I;
    final user = s.me;
    if (!s.booted) {
      return Scaffold(
        body: Center(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: <Widget>[
              JskLogo(size: 96),
              SizedBox(height: 20),
              SizedBox(
                width: 18,
                height: 18,
                child: CircularProgressIndicator(strokeWidth: 2),
              ),
              SizedBox(height: 12),
              Text(
                T('Loading the register…'),
                style: TextStyle(fontSize: 10, color: context.faint),
              ),
            ],
          ),
        ),
      );
    }
    if (Platform.isAndroid && !_updateCheckScheduled) {
      _updateCheckScheduled = true;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) unawaited(checkForAppUpdate(context));
      });
    }
    if (user == null) {
      _veilFor = null;
      return LoginPage();
    }
    final userId = user['id']?.toString();
    if (Platform.isAndroid &&
        userId != null &&
        _permissionPromptScheduledFor != userId) {
      _permissionPromptScheduledFor = userId;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        Future<void>.delayed(const Duration(milliseconds: 700), () {
          if (mounted && context.mounted && Store.I.userId == userId) {
            unawaited(FcmPushService.requestAfterAccountRegistration(context));
          }
        });
      });
    }
    _veilFor ??= user['name']?.toString();
    return VeilHost(
      key: ValueKey('veil_${user['id']}'),
      triggerName: _veilFor,
      child: Shell(user: user),
    );
  }
}

// ---------------------------------------------------------------------------
//  ANDROID SELF-UPDATE — read version.json, fetch the signed APK, open installer
// ---------------------------------------------------------------------------
const String kAppUpdateManifestUrl =
    'https://jsk-attendance.web.app/version.json';
const int _maxUpdateApkBytes = 300 * 1024 * 1024;

class AppUpdateRelease {
  const AppUpdateRelease({
    required this.version,
    required this.currentVersion,
    required this.apkUri,
    required this.notes,
  });

  final String version;
  final String currentVersion;
  final Uri apkUri;
  final String notes;
}

class AppUpdateService {
  static Future<AppUpdateRelease?> checkForUpdate() async {
    final info = await PackageInfo.fromPlatform();
    final response = await http
        .get(
          Uri.parse(kAppUpdateManifestUrl),
          headers: const {
            'Cache-Control': 'no-cache, no-store',
            'Pragma': 'no-cache',
          },
        )
        .timeout(const Duration(seconds: 20));

    if (response.statusCode != 200) {
      throw HttpException(
        'Update server returned HTTP ${response.statusCode}.',
      );
    }

    final decoded = jsonDecode(response.body);
    if (decoded is! Map) {
      throw const FormatException('The update manifest is not a JSON object.');
    }
    final data = Map<String, dynamic>.from(decoded);
    final latestVersion = (data['version'] ?? '').toString().trim();
    if (!_isNumericVersion(latestVersion)) {
      throw const FormatException(
        'The update manifest has an invalid version.',
      );
    }
    final apkUri = Uri.tryParse((data['apkUrl'] ?? '').toString().trim());
    if (apkUri == null ||
        apkUri.scheme != 'https' ||
        apkUri.host.toLowerCase() != 'github.com' ||
        !apkUri.path.contains('/releases/download/') ||
        !apkUri.path.toLowerCase().endsWith('/jsk-attendance.apk')) {
      throw const FormatException(
        'The update manifest does not contain a valid JSK GitHub APK link.',
      );
    }

    if (_compareNumericVersions(latestVersion, info.version) <= 0) return null;

    return AppUpdateRelease(
      version: latestVersion,
      currentVersion: info.version,
      apkUri: apkUri,
      notes: (data['notes'] ?? '').toString().trim(),
    );
  }

  static Future<String> downloadApk(AppUpdateRelease release) async {
    final client = http.Client();
    final tempDirectory = await getTemporaryDirectory();
    final apkFile = File(
      '${tempDirectory.path}${Platform.pathSeparator}'
      'jsk-attendance-${release.version}.apk',
    );
    final partialFile = File('${apkFile.path}.part');
    IOSink? sink;

    try {
      final request = http.Request('GET', release.apkUri);
      final response = await client
          .send(request)
          .timeout(const Duration(seconds: 30));
      if (response.statusCode != 200) {
        throw HttpException(
          'APK download returned HTTP ${response.statusCode}.',
        );
      }
      final expectedLength = response.contentLength;
      if (expectedLength != null && expectedLength > _maxUpdateApkBytes) {
        throw const FormatException('The APK is larger than the 300 MB limit.');
      }

      sink = partialFile.openWrite();
      var received = 0;
      await for (final chunk in response.stream.timeout(
        const Duration(seconds: 60),
      )) {
        received += chunk.length;
        if (received > _maxUpdateApkBytes) {
          throw const FormatException(
            'The APK is larger than the 300 MB limit.',
          );
        }
        sink.add(chunk);
      }
      await sink.flush();
      await sink.close();
      sink = null;
      if (received < 1024) {
        throw const FormatException('The downloaded APK is incomplete.');
      }
      if (await apkFile.exists()) await apkFile.delete();
      await partialFile.rename(apkFile.path);
      return apkFile.path;
    } catch (_) {
      await sink?.close();
      if (await partialFile.exists()) await partialFile.delete();
      rethrow;
    } finally {
      client.close();
    }
  }

  static bool _isNumericVersion(String version) =>
      RegExp(r'^\d+(\.\d+)*$').hasMatch(version);

  static int _compareNumericVersions(String left, String right) {
    if (!_isNumericVersion(left) || !_isNumericVersion(right)) {
      throw const FormatException('App versions must contain numbers only.');
    }
    final a = left.split('.').map(int.parse).toList();
    final b = right.split('.').map(int.parse).toList();
    final length = math.max(a.length, b.length);
    for (var index = 0; index < length; index++) {
      final av = index < a.length ? a[index] : 0;
      final bv = index < b.length ? b[index] : 0;
      if (av != bv) return av.compareTo(bv);
    }
    return 0;
  }
}

Future<void> checkForAppUpdate(
  BuildContext context, {
  bool showLatestVersionMessage = false,
}) async {
  if (!Platform.isAndroid) {
    if (showLatestVersionMessage && context.mounted) {
      toast(context, 'APK updates are available on Android only.');
    }
    return;
  }

  try {
    final release = await AppUpdateService.checkForUpdate();
    if (!context.mounted) return;
    if (release == null) {
      if (showLatestVersionMessage) {
        toast(context, 'You already have the latest version.');
      }
      return;
    }

    final shouldInstall = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: Text('JSK Attendance update available'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('Version ${release.currentVersion} → ${release.version}'),
            if (release.notes.isNotEmpty) ...[
              SizedBox(height: 9),
              Text(release.notes),
            ],
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogContext).pop(false),
            child: Text('Later'),
          ),
          FilledButton.icon(
            onPressed: () => Navigator.of(dialogContext).pop(true),
            icon: Icon(Icons.download_rounded),
            label: Text('Download & install'),
          ),
        ],
      ),
    );
    if (shouldInstall == true && context.mounted) {
      await downloadAndInstallAppUpdate(context, release);
    }
  } catch (error) {
    debugPrint('App update check failed: $error');
    if (showLatestVersionMessage && context.mounted) {
      toast(
        context,
        'Could not check for updates. Check your internet and try again.',
      );
    }
  }
}

Future<void> downloadAndInstallAppUpdate(
  BuildContext context,
  AppUpdateRelease release,
) async {
  var progressDialogOpen = true;
  showDialog<void>(
    context: context,
    barrierDismissible: false,
    builder: (_) => AlertDialog(
      content: Row(
        children: [
          SizedBox(
            width: 22,
            height: 22,
            child: CircularProgressIndicator(strokeWidth: 2.4),
          ),
          SizedBox(width: 14),
          Expanded(child: Text('Downloading update ${release.version}…')),
        ],
      ),
    ),
  );

  try {
    final apkPath = await AppUpdateService.downloadApk(release);
    if (!context.mounted) return;
    Navigator.of(context, rootNavigator: true).pop();
    progressDialogOpen = false;

    final result = await OpenFilex.open(
      apkPath,
      type: 'application/vnd.android.package-archive',
    );
    if (!context.mounted) return;
    if (result.type == ResultType.done) {
      toast(context, 'Downloaded. Confirm Install in the Android installer.');
    } else if (result.type == ResultType.permissionDenied) {
      toast(
        context,
        'Allow JSK Attendance to install apps in Android settings, then try again.',
      );
    } else {
      toast(context, 'Could not open the installer: ${result.message}');
    }
  } catch (error) {
    debugPrint('APK update installation failed: $error');
    if (progressDialogOpen && context.mounted) {
      Navigator.of(context, rootNavigator: true).pop();
    }
    if (context.mounted) {
      toast(context, 'Update download failed. Please try again.');
    }
  }
}

