/// The ID Card tab glyph: a rounded pass card holding a small portrait and two
/// detail lines, drawn rather than picked from a font so it stays crisp.
class _IdCardGlyph extends StatelessWidget {
  const _IdCardGlyph({required this.color, required this.size});

  final Color color;
  final double size;

  @override
  Widget build(BuildContext context) => SizedBox(
    width: size,
    height: size,
    child: CustomPaint(painter: _IdCardGlyphPainter(color)),
  );
}

class _IdCardGlyphPainter extends CustomPainter {
  _IdCardGlyphPainter(this.color);

  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    final s = size.width / 24.0;
    final stroke = Paint()
      ..color = color
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.8 * s
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;
    final fill = Paint()
      ..color = color
      ..style = PaintingStyle.fill;

    // the card
    final card = RRect.fromRectAndRadius(
      Rect.fromLTWH(2.2 * s, 4.6 * s, 19.6 * s, 14.8 * s),
      Radius.circular(3.4 * s),
    );
    canvas.drawRRect(card, stroke);

    // portrait: head and shoulders
    canvas.drawCircle(Offset(8.4 * s, 10.4 * s), 2.05 * s, stroke);
    final shoulders = Path()
      ..moveTo(5.4 * s, 16.4 * s)
      ..quadraticBezierTo(8.4 * s, 12.9 * s, 11.4 * s, 16.4 * s);
    canvas.drawPath(shoulders, stroke);

    // two detail lines
    canvas.drawLine(
      Offset(13.6 * s, 10.2 * s),
      Offset(18.6 * s, 10.2 * s),
      stroke..strokeWidth = 1.6 * s,
    );
    canvas.drawLine(
      Offset(13.6 * s, 13.6 * s),
      Offset(17.4 * s, 13.6 * s),
      stroke..strokeWidth = 1.6 * s,
    );

    // a tiny chip in the corner
    canvas.drawCircle(Offset(19.0 * s, 7.2 * s), 0.0, fill);
  }

  @override
  bool shouldRepaint(_IdCardGlyphPainter old) => old.color != color;
}

class Shell extends StatefulWidget {
  const Shell({super.key, required this.user});

  final Map<String, dynamic> user;

  @override
  State<Shell> createState() => _ShellState();
}

class _ShellState extends State<Shell> {
  late String _page = Store.I.page.isEmpty
      ? (widget.user['role'] == 'admin'
            ? 'notices'
            : widget.user['role'] == 'teacher'
            ? 'myatt'
            : widget.user['role'] == 'staff'
            ? 'attendance'
            : 'home')
      : Store.I.page;

  @override
  void initState() {
    super.initState();
    Store.I.page = _page;
    Store.I.addListener(_followStorePage);
  }

  @override
  void dispose() {
    Store.I.removeListener(_followStorePage);
    super.dispose();
  }

  /// Pages move between tabs by calling Store.I.go(...) (the student home's
  /// "month-by-month attendance" and the guardian one do exactly that). The
  /// tab itself lives in this widget, so adopt the store's page or the tap
  /// would change nothing on screen.
  void _followStorePage() {
    final p = Store.I.page;
    if (!mounted || p.isEmpty || p == _page) return;
    setState(() => _page = p);
  }

  void _nav(String key) {
    setState(() => _page = key);
    Store.I.go(key);
  }

  @override
  Widget build(BuildContext context) {
    final s = Store.I;
    final u = widget.user;
    final role = u['role'].toString();
    final nav = navFor(role);
    final unread = s.unreadOf(u['id'].toString());

    return Scaffold(
      body: SafeArea(
        bottom: false,
        child: Column(
          children: [
            _header(context, u, role),
            Expanded(
              child: AnimatedSwitcher(
                duration: Duration(milliseconds: 260),
                switchInCurve: Curves.easeOutCubic,
                transitionBuilder: (child, anim) => FadeTransition(
                  opacity: anim,
                  child: SlideTransition(
                    position: Tween<Offset>(
                      begin: Offset(0, .02),
                      end: Offset.zero,
                    ).animate(anim),
                    child: child,
                  ),
                ),
                child: KeyedSubtree(
                  key: ValueKey(
                    '$_page-${s.settingsSub}-${s.viewStudentId}-${s.viewTeacherId}',
                  ),
                  child: _body(role),
                ),
              ),
            ),
            _bottomNav(context, nav, unread),
          ],
        ),
      ),
    );
  }

  Widget _header(BuildContext context, Map<String, dynamic> u, String role) {
    final k = context.k;
    final unread = Store.I.unreadOf(u['id'].toString());
    return Container(
      padding: EdgeInsets.fromLTRB(14, 10, 10, 10),
      decoration: BoxDecoration(
        color: k.surface,
        border: Border(bottom: BorderSide(color: k.line)),
      ),
      child: Row(
        children: <Widget>[
          SizedBox(
            width: 34,
            height: 34,
            child: ClipOval(child: JskLogo(size: 34)),
          ),
          SizedBox(width: 10),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: <Widget>[
                Text(
                  T('JSK Institute'),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(
                    fontFamily: Skin.serif,
                    fontSize: 19,
                    height: 1.1,
                    fontWeight: FontWeight.w600,
                    color: k.ink,
                  ),
                ),
                SizedBox(height: 1),
                Text(
                  T('ATTENDANCE REGISTER'),
                  style: TextStyle(
                    fontFamily: Skin.mono,
                    fontSize: 8.2,
                    letterSpacing: 1.5,
                    color: k.faint,
                  ),
                ),
              ],
            ),
          ),
          _headBtn(
            context,
            icon: Icons.settings_outlined,
            active: _page == 'settings',
            onTap: () => _nav('settings'),
          ),
          SizedBox(width: 4),
          Stack(
            clipBehavior: Clip.none,
            children: <Widget>[
              _headBtn(
                context,
                icon: Icons.notifications_none,
                active: _page == 'notifications',
                onTap: () => _nav('notifications'),
              ),
              if (unread > 0)
                Positioned(
                  right: 2,
                  top: 2,
                  child: Container(
                    padding: EdgeInsets.symmetric(horizontal: 4),
                    constraints: BoxConstraints(minWidth: 15),
                    height: 15,
                    alignment: Alignment.center,
                    decoration: BoxDecoration(
                      color: Skin.brick,
                      shape: BoxShape.circle,
                    ),
                    child: Text(
                      TT("{0}", [unread]),
                      style: TextStyle(
                        color: Colors.white,
                        fontSize: 8.5,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ),
                ),
            ],
          ),
          SizedBox(width: 4),
          GestureDetector(
            onTap: () => _nav(
              role == 'admin'
                  ? 'admins'
                  : (role == 'staff' || role == 'teacher'
                        ? 'settings'
                        : 'profile'),
            ),
            child: PersonAvatar(
              name: u['name'].toString(),
              photo: Store.I.photoOf(u),
              radius: 17,
            ),
          ),
        ],
      ),
    );
  }

  Widget _headBtn(
    BuildContext context, {
    required IconData icon,
    required bool active,
    required VoidCallback onTap,
  }) {
    final k = context.k;
    return Pressable(
      onTap: onTap,
      child: Container(
        width: 36,
        height: 36,
        alignment: Alignment.center,
        decoration: BoxDecoration(
          color: active ? k.surface2 : Colors.transparent,
          border: Border.all(color: active ? k.lineStrong : Colors.transparent),
          borderRadius: BorderRadius.circular(999),
        ),
        child: Icon(icon, size: 19, color: active ? Skin.marigold : k.inkSoft),
      ),
    );
  }

  Widget _bottomNav(
    BuildContext context,
    List<Map<String, String>> nav,
    int unread,
  ) {
    final items = nav.where((n) => n['key'] != 'settings').toList();
    final scrollable = items.length > 5;
    final tight = items.length >= 5;
    return Container(
      decoration: BoxDecoration(
        color: context.k.surface,
        border: Border(top: BorderSide(color: context.line)),
      ),
      child: SafeArea(
        top: false,
        child: SizedBox(
          height: 62,
          child: scrollable
              ? SingleChildScrollView(
                  scrollDirection: Axis.horizontal,
                  child: Row(
                    children: [
                      for (final n in items)
                        _navItem(context, n, unread, fixed: true, tight: tight),
                    ],
                  ),
                )
              : Row(
                  children: [
                    // _navItem already returns the Expanded slot
                    for (final n in items)
                      _navItem(context, n, unread, tight: tight),
                  ],
                ),
        ),
      ),
    );
  }

  Widget _navItem(
    BuildContext context,
    Map<String, String> n,
    int unread, {
    bool fixed = false,
    bool tight = false,
  }) {
    final k = context.k;
    final active = _page == n['key'];
    final isBell = n['key'] == 'notifications';
    final body = Padding(
      padding: EdgeInsets.symmetric(horizontal: tight ? 1 : 4),
      child: Pressable(
        onTap: () => _nav(n['key']!),
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: <Widget>[
            Stack(
              clipBehavior: Clip.none,
              children: <Widget>[
                AnimatedContainer(
                  duration: Duration(milliseconds: 200),
                  curve: Curves.easeOutCubic,
                  width: 40,
                  height: 40,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    gradient: active
                        ? LinearGradient(
                            colors: <Color>[
                              Skin.marigold.withValues(alpha: 0.30),
                              Skin.marigold.withValues(alpha: 0.12),
                            ],
                            begin: Alignment.topLeft,
                            end: Alignment.bottomRight,
                          )
                        : null,
                  ),
                  child: n['key'] == 'idcard'
                      ? Center(
                          child: _IdCardGlyph(
                            color: active ? Skin.marigold : k.inkSoft,
                            size: active ? 23 : 22,
                          ),
                        )
                      : Icon(
                          kNavIcons[n['key']] ?? Icons.circle_outlined,
                          size: active ? 23 : 22,
                          color: active ? Skin.marigold : k.inkSoft,
                        ),
                ),
                if (isBell && unread > 0)
                  Positioned(
                    top: -1,
                    right: -2,
                    child: Container(
                      padding: EdgeInsets.symmetric(horizontal: 3),
                      constraints: BoxConstraints(minWidth: 16),
                      height: 16,
                      alignment: Alignment.center,
                      decoration: BoxDecoration(
                        color: Skin.brick,
                        borderRadius: BorderRadius.all(Radius.circular(8)),
                      ),
                      child: Text(
                        unread > 9 ? '9+' : '$unread',
                        style: TextStyle(
                          color: Colors.white,
                          fontSize: 9,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                    ),
                  ),
              ],
            ),
            SizedBox(height: 2),
            Text(
              n['label']!,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: active ? Skin.marigold : k.inkSoft,
                fontSize: tight ? 8.4 : 9.6,
                height: 1.1,
                fontWeight: FontWeight.w600,
              ),
            ),
          ],
        ),
      ),
    );
    return fixed ? SizedBox(width: 82, child: body) : Expanded(child: body);
  }

  Widget _body(String role) {
    final s = Store.I;
    final u = widget.user;
    final page = _page;

    if (page == 'settings') return SettingsPage();

    if (role == 'admin') {
      switch (page) {
        case 'notices':
          return AdminNoticesPage(user: u);
        case 'notifications':
          return NotificationsPage(user: u);
        case 'students':
          return s.viewStudentId != null
              ? AdminStudentDetailPage(user: u)
              : AdminStudentsPage(user: u);
        case 'fees':
          return AdminFeesPage(user: u);
        case 'teachers':
          return s.viewTeacherId != null
              ? AdminTeacherDetailPage(user: u)
              : AdminTeachersPage(user: u);
        case 'staff':
          return s.viewStaffId != null
              ? AdminStaffDetailPage(user: u)
              : AdminStaffPage(user: u);
        case 'admins':
          return AdminAdminsPage(user: u);
        case 'guardians':
          return AdminGuardiansPage(user: u);
        default:
          return AdminNoticesPage(user: u);
      }
    }
    if (role == 'teacher') {
      switch (page) {
        case 'notifications':
          return NotificationsPage(user: u);
        case 'schedule':
          return TeacherSchedulePage(user: u);
        case 'myatt':
          return StaffAttendancePage(user: u);
        case 'idcard':
          return IdCardPage(user: u);
        case 'notes':
          return TeacherNotesPage(user: u);
        default:
          return TeacherAttendancePage(user: u);
      }
    }
    if (role == 'staff') {
      if (page == 'notifications') return NotificationsPage(user: u);
      if (page == 'idcard') return IdCardPage(user: u);
      return StaffAttendancePage(user: u);
    }
    if (role == 'guardian') {
      final student = Store.I.guardianStudent(u['id'].toString());
      if (student == null) {
        return EmptyState(
          title: T('No student record is linked to this guardian login yet.'),
          subtitle: T('Please contact the office.'),
        );
      }
      switch (page) {
        case 'attendance':
          return GuardianAttendancePage(user: u, student: student);
        case 'idcard':
          return IdCardPage(user: u, student: student);
        case 'notifications':
          return NotificationsPage(user: u);
        default:
          return GuardianHomePage(user: u, student: student);
      }
    }
    final student = Store.I.studentOfUser(u['id'].toString());
    if (student == null) {
      return EmptyState(
        title: T('No student record is linked to this login yet.'),
        subtitle: T('Please contact the office.'),
      );
    }
    switch (page) {
      case 'attendance':
        return StudentAttendancePage(user: u, student: student);
      case 'notifications':
        return NotificationsPage(user: u);
      case 'profile':
        return StudentProfilePage(user: u, student: student);
      case 'idcard':
        return IdCardPage(user: u);
      case 'notes':
        return StudentNotesPage(user: u, student: student);
      default:
        return StudentHomePage(user: u, student: student);
    }
  }
}

