// ---------------------------------------------------------------------------
//  STAFF / TEACHER "MY ATTENDANCE" — geofence check-in, hours bank, leave,
//  month register (single-line month bar, calendar, averages)
// ---------------------------------------------------------------------------
class StaffAttendancePage extends StatefulWidget {
  const StaffAttendancePage({super.key, required this.user});

  final Map<String, dynamic> user;

  @override
  State<StaffAttendancePage> createState() => _StaffAttendancePageState();
}

class _StaffAttendancePageState extends State<StaffAttendancePage> {
  late DateTime _now = DateTime.now();
  late String _month = ymOf(todayStr());
  double? _dist;
  double? _acc;
  double? _bearing;
  bool _locating = false;
  String? _locError;
  bool _busy = false;
  Timer? _timer;

  // leave form
  String _leaveMode = 'one';
  String _from = todayStr();
  String _to = todayStr();
  final _reason = TextEditingController();
  bool _leaveForm = false;

  // flat tile like the reference; it turns one shade darker when that action
  // is the one waiting for the staff member
  Widget _checkBtn({
    required String label,
    required bool ready,
    required Color base,
    required Color active,
    required VoidCallback onTap,
  }) {
    return Expanded(
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 180),
        curve: Curves.easeOut,
        decoration: BoxDecoration(
          color: ready ? active : base,
          borderRadius: BorderRadius.circular(11),
        ),
        child: Material(
          color: Colors.transparent,
          child: InkWell(
            borderRadius: BorderRadius.circular(11),
            onTap: _busy ? null : onTap,
            child: Padding(
              padding: const EdgeInsets.symmetric(vertical: 13, horizontal: 6),
              child: Center(
                child: Text(
                  label,
                  textAlign: TextAlign.center,
                  style: const TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w700,
                    color: Colors.white,
                  ),
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  Store get s => Store.I;

  bool get _checkedIn => s.staffToday(_uid)?['inTs'] != null;
  bool get _checkedOut => s.staffToday(_uid)?['outTs'] != null;
  // dark (actionable) only when inside the zone and it is the next step
  bool get _inReady => _inside && !_checkedIn;
  bool get _outReady => _checkedIn && !_checkedOut;
  Map<String, dynamic> get u => widget.user;
  String get _uid => u['id'].toString();

  @override
  void initState() {
    super.initState();
    _timer = Timer.periodic(Duration(seconds: 1), (_) {
      if (mounted) setState(() => _now = DateTime.now());
    });
    WidgetsBinding.instance.addPostFrameCallback((_) => _locate());
  }

  @override
  void dispose() {
    _timer?.cancel();
    _reason.dispose();
    super.dispose();
  }

  /// the last fixes, newest last — the radar fades them into a trail
  final List<RadarFix> _trail = <RadarFix>[];

  double get _tolerance => math.min((_acc ?? 0) * 0.75, 60.0);
  double get _radius => (s.geofence['radius'] as num?)?.toDouble() ?? 150;
  bool get _inside => _dist != null && _dist! <= _radius + _tolerance;
  bool get _logsOut => _dist != null;

  Future<void> _locate() async {
    setState(() {
      _locating = true;
      _locError = null;
    });
    try {
      if (!await Geolocator.isLocationServiceEnabled()) {
        throw 'Turn location on to check in at the institute.';
      }
      var perm = await Geolocator.checkPermission();
      if (perm == LocationPermission.denied) {
        perm = await Geolocator.requestPermission();
      }
      if (perm == LocationPermission.denied ||
          perm == LocationPermission.deniedForever) {
        throw 'Location permission is off. Allow it in phone settings to check in.';
      }
      final pos = await Geolocator.getCurrentPosition(
        locationSettings: const LocationSettings(
          accuracy: LocationAccuracy.high,
          timeLimit: Duration(seconds: 25),
        ),
      );
      final g = s.geofence;
      final dist = haversineM(
        pos.latitude,
        pos.longitude,
        (g['lat'] as num).toDouble(),
        (g['lng'] as num).toDouble(),
      );
      if (!mounted) return;
      final brg = bearingDeg(
        pos.latitude,
        pos.longitude,
        (g['lat'] as num).toDouble(),
        (g['lng'] as num).toDouble(),
      );
      setState(() {
        _dist = dist;
        _acc = pos.accuracy;
        _bearing = brg;
        _trail.add(
          RadarFix(
            distance: dist,
            bearing: brg,
            ts: DateTime.now().millisecondsSinceEpoch,
          ),
        );
        if (_trail.length > 8) _trail.removeRange(0, _trail.length - 8);
        _locating = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _locating = false;
        _locError = e is String
            ? e
            : 'Could not read your location. Step outdoors and try again.';
      });
    }
  }

  void _pushStaffNote(String text) {
    s.rawList('staffNotifications').add({
      'id': uid('snotif'),
      'userId': _uid,
      'staffId': _uid,
      'ts': DateTime.now().millisecondsSinceEpoch,
      'kind': 'in',
      'text': text,
      'read': false,
    });
  }

  Future<void> _check(String kind) async {
    if (_busy) return;
    final rec = s.staffToday(_uid);
    if (kind == 'in' && rec != null) {
      toast(
        context,
        TT("You are already checked in today ({0}).", [
          fmtTime(rec['inTs'] as int?),
        ]),
      );
      return;
    }
    if (kind == 'out') {
      if (rec == null) {
        toast(context, T('Check in first — you have not checked in today.'));
        return;
      }
      if (rec['outTs'] != null) {
        toast(context, T('You are already checked out today.'));
        return;
      }
    }
    setState(() => _busy = true);
    await _locate();
    if (!mounted) return;
    if (!_logsOut) {
      setState(() => _busy = false);
      toast(
        context,
        _locError ?? 'We need a fresh location to verify the zone.',
      );
      return;
    }
    if (!_inside) {
      setState(() => _busy = false);
      toast(
        context,
        TT(
          "You are {0} from the institute. Check-in needs you inside the {1} m zone.",
          [fmtDist(_dist!), _radius.round()],
        ),
      );
      return;
    }

    final today = todayStr();
    final now = DateTime.now().millisecondsSinceEpoch;
    if (kind == 'in') {
      final fresh = <String, dynamic>{
        'id': uid('srec'),
        'userId': _uid,
        'staffId': _uid,
        'name': u['name'],
        'role': u['role'],
        'date': today,
        'inTs': now,
        'inDist': _dist!.round(),
        'outTs': null,
        'outDist': null,
        'late': false,
        'lateMin': 0,
      };
      s.evaluateLate(fresh, u);
      s.rawList('staffRecords').add(fresh);
      final shIn = s.shiftForDay(u, today);
      final late = fresh['late'] == true;
      _pushStaffNote(
        'Checked in at ${fmtTime(now)} · ${_dist!.round()} m from the institute'
        '${late ? ' · LATE by ${fresh['lateMin']} min' : ''}',
      );
      if (late) {
        s.rawList('lateRemarks').add({
          'id': uid('late'),
          'userId': _uid,
          'name': u['name'],
          'role': u['role'],
          'date': today,
          'ts': now,
          'inTs': now,
          'shift': s.shiftForDay(u, today).start,
          'lateMin': fresh['lateMin'],
          'read': false,
        });
      }
      // A late arrival is its own message, and it goes to the staff member and
      // both admins the moment it happens. An on-time arrival stays a plain
      // check-in.
      s.ntPersonAndAdmins(
        userId: _uid,
        type: late ? 'late' : 'in',
        title: late ? T('Late check-in') : T('Check in'),
        message: late
            ? '${u['name']} ${T('checked IN late by')} ${fresh['lateMin']} ${T('min')}. '
                  '${T('Date')}: ${fmtDate(today)}. ${T('Time')}: ${fmtTime(now)}. '
                  '${T('Shift')}: ${shIn.start} — ${shIn.end} '
                  '($SHIFT_GRACE_MIN ${T('min grace')}). '
                  '${T('Late arrivals and unfinished hours are recorded in the hours bank.')}'
            : '${u['name']} ${T('checked IN successfully.')} '
                  '${T('Date')}: ${fmtDate(today)}. ${T('Time')}: ${fmtTime(now)}.',
        refType: late ? 'late' : 'in',
        refId: fresh['id'].toString(),
        dedupKey: late ? 'late_${fresh['id']}' : 'in_${fresh['id']}',
      );
      toast(context, TT("Checked IN at {0}.", [fmtTime(now)]));
    } else {
      final inTs = (rec!['inTs'] as num).toInt();
      rec['outTs'] = now;
      rec['outDist'] = _dist!.round();
      final mins = (now - inTs) ~/ 60000;
      _pushStaffNote(
        'Checked out at ${fmtTime(now)} · ${fmtHours(mins)} worked today.',
      );
      s.ntPersonAndAdmins(
        userId: _uid,
        type: 'out',
        title: T('Check out'),
        message:
            '${u['name']} ${T('checked OUT successfully.')} '
            '${T('Date')}: ${fmtDate(today)}. ${T('Time')}: ${fmtTime(now)}. '
            '${T('Hours worked today')}: ${fmtHours(mins)}.',
        refType: 'out',
        refId: rec['id'].toString(),
        dedupKey: 'out_${rec['id']}',
      );
      toast(context, TT("Checked OUT — {0} worked today.", [fmtHours(mins)]));
    }
    s.save();
    setState(() => _busy = false);
  }

  void _saveBirthday() {
    final c = TextEditingController(
      text: bdayOf(u).isEmpty ? todayStr() : bdayOf(u),
    );
    showDialog<void>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(
          T('One last thing — your birthday'),
          style: TextStyle(fontSize: 15),
        ),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              T(
                'Add your date of birth so fellow staff members can wish you. Only staff can ever see it — students and teachers cannot.',
              ),
              style: TextStyle(fontSize: 11, color: context.soft, height: 1.4),
            ),
            SizedBox(height: 12),
            Field(
              label: T('Your date of birth'),
              controller: c,
              hint: T('YYYY-MM-DD'),
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx),
            child: Text(T('Later')),
          ),
          FilledButton(
            onPressed: () {
              final v = c.text.trim();
              if (!RegExp(r'^\d{4}-\d{2}-\d{2}$').hasMatch(v)) {
                toast(context, T('Use the format YYYY-MM-DD.'));
                return;
              }
              u['dob'] = v;
              u['birthday'] = v;
              s.save();
              Navigator.pop(ctx);
              setState(() {});
              toast(context, T('Birthday saved.'));
            },
            child: Text(T('Save birthday')),
          ),
        ],
      ),
    );
  }

  Future<void> _sendLeave() async {
    final from = _leaveMode == 'one' ? _from : _from;
    final to = _leaveMode == 'one' ? _from : _to;
    if (_leaveMode == 'multiple' && parseDay(to).isBefore(parseDay(from))) {
      toast(context, T('The last day cannot be before the first day.'));
      return;
    }
    if (parseDay(from).isBefore(parseDay(todayStr()))) {
      toast(
        context,
        T(
          "Pick today or a future date — you can't request a leave for a past day.",
        ),
      );
      return;
    }
    final days = <String>[];
    var cursor = from;
    while (!parseDay(cursor).isAfter(parseDay(to))) {
      days.add(cursor);
      cursor = s.addDays(cursor, 1);
      if (days.length > MAX_LEAVE_DAYS) break;
    }
    if (days.length > MAX_LEAVE_DAYS) {
      toast(
        context,
        TT("A leave request can cover up to {0} days.", [MAX_LEAVE_DAYS]),
      );
      return;
    }
    final weeks = days.map(s.weekKeyOf).toSet();
    for (final w in weeks) {
      if (s.leaveWeekCount(_uid, w) >= ONE_LEAVE_PER_WEEK) {
        toast(
          context,
          TT(
            "You already have a leave request in the week of {0} — one leave per week.",
            [fmtDate(w)],
          ),
        );
        return;
      }
    }
    final gid = uid('leavegrp');
    final ts = DateTime.now().millisecondsSinceEpoch;
    for (final d in days) {
      s.rawList('leaveRequests').add({
        'id': uid('leave'),
        'groupId': gid,
        'userId': _uid,
        'name': u['name'],
        'role': u['role'],
        'date': d,
        'reason': _reason.text.trim(),
        'status': 'pending',
        'ts': ts,
      });
    }
    s.ntAdmins(
      type: 'leave',
      title: T('Leave request'),
      message:
          '${u['name']} requested ${s.leaveRangeLabel([
            for (final d in days) {'date': d},
          ])}${_reason.text.trim().isEmpty ? '' : ' — ${_reason.text.trim()}'}',
      refType: 'leave',
      refId: gid,
    );
    s.ntPush(
      userId: _uid,
      type: 'leave',
      title: T('Leave request sent'),
      message:
          '${s.leaveRangeLabel([
            for (final d in days) {'date': d},
          ])} — waiting for the office.',
      refType: 'leave',
      refId: gid,
      dedupKey: 'leave_$gid',
    );
    s.save();
    setState(() {
      _leaveForm = false;
      _reason.clear();
      _leaveMode = 'one';
      _from = todayStr();
      _to = todayStr();
    });
    toast(context, T('Leave request sent to the office.'));
  }

