  Widget _hoursCard(
    BuildContext context, {
    required Map<String, dynamic>? rec,
    required Map<String, dynamic>? holiday,
    required bool monthly,
  }) {
    final worked = s.workedMs(rec);
    final targetMin = (s.targetOf(u) * 60).round();
    final workedMin = worked ~/ 60000;
    final pct = (workedMin / targetMin).clamp(0.0, 1.0).toDouble();
    final ym = ymOf(todayStr());
    final mWorked = s.monthWorkedMin(_uid, ym);
    final mTarget = s.effectiveTargetMinForMonth(u, ym);
    final mPct = mTarget == 0
        ? 0.0
        : (mWorked / mTarget).clamp(0.0, 1.0).toDouble();
    final missed = s.missedCheckoutDaysOf(_uid, ym);

    if (holiday != null) {
      return Panel(
        border: Skin.violet.withValues(alpha: .4),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            SectionTitle(T("Today's hours")),
            SizedBox(height: 8),
            Text(
              '${TT("Institute closed — {0}. ", [holiday['name']])}'
              '${(holiday['reason'] ?? '').toString().trim().isNotEmpty && holiday['reason'] != holiday['name'] ? '· ${holiday['reason']} ' : ''}'
              '${T('Hours are not counted toward your target and no check-in or leave request is needed today.')}',
              style: TextStyle(fontSize: 10, color: context.soft, height: 1.45),
            ),
          ],
        ),
      );
    }

    return Panel(
      border: Skin.gold.withValues(alpha: .45),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Expanded(
                child: SectionTitle(
                  monthly
                      ? TT("This month's hours — target {0}h", [
                          s.monthlyTargetOf(u).toStringAsFixed(0),
                        ])
                      : TT("Today's hours — target {0}h", [
                          s.targetOf(u).toStringAsFixed(0),
                        ]),
                ),
              ),
              Text(
                monthly
                    ? '${fmtHours(mWorked)} · $mPct%'
                    : '${fmtHours(workedMin)} of ${s.targetOf(u).toStringAsFixed(0)}h · ${(pct * 100).round()}%',
                style: TextStyle(fontSize: 9, color: context.soft),
              ),
            ],
          ),
          SizedBox(height: 9),
          Meter(value: monthly ? mPct : pct, color: Skin.gold),
          SizedBox(height: 8),
          Text(
            monthly
                ? (mWorked >= mTarget
                      ? TT("Monthly target complete — {0} extra worked.", [
                          fmtHours(mWorked - mTarget),
                        ])
                      : TT(
                          "Left this month: {0} — complete it by working extra hours any day this month. Today: {1}.",
                          [fmtHours(mTarget - mWorked), fmtHours(workedMin)],
                        ))
                : (workedMin >= targetMin
                      ? TT(
                          "Target complete — {0} extra goes to your overtime bank.",
                          [fmtHours(workedMin - targetMin)],
                        )
                      : '${TT("Left today: {0}", [fmtHours(targetMin - workedMin)])}'
                            '${rec != null && rec['outTs'] != null ? ' — ${T('these hours are pending; complete them by staying extra another day.')}' : (rec != null ? ' — ${TT("you complete your target at about {0}.", [fmtTime((rec['inTs'] as num).toInt() + targetMin * 60000)])}' : '')}'),
            style: TextStyle(fontSize: 9.5, color: context.soft, height: 1.4),
          ),
          SizedBox(height: 7),
          Text(
            monthly
                ? TT(
                    "Every day of the month is a working day. Accepted leave days reduce the month's target. A finished day is scored against the daily target: extra time goes into the bank and any hours you did not complete come off it. Forgetting to check out, or a leave the office did not accept, each cost {0} minutes as well, and so does a late arrival whose hours were left unfinished.",
                    [MISSED_CHECKOUT_MIN],
                  )
                : TT(
                    "Complete your daily target — extra time goes into your hours bank, and the hours you did not complete come off it the same way (the bank stops at {0}). Coming in late costs nothing once you finish the day's hours; leaving them unfinished costs {1} minutes on top. A leave the office did not accept, and a day you forget to check out, cost the same.",
                    [fmtHours(MAX_BANK_MIN), MISSED_CHECKOUT_MIN],
                  ),
            style: TextStyle(fontSize: 9, color: context.faint, height: 1.45),
          ),
          if (missed.isNotEmpty) ...[
            SizedBox(height: 7),
            Text(
              TT(
                "{0} day{1} you never checked out — {2} minutes each has been taken from your hours bank. Always tap Check OUT before you leave.",
                [
                  missed.length,
                  missed.length == 1 ? '' : 's',
                  MISSED_CHECKOUT_MIN,
                ],
              ),
              style: TextStyle(
                color: Color(0xFFE27B61),
                fontSize: 9.5,
                fontWeight: FontWeight.w600,
                height: 1.4,
              ),
            ),
          ],
        ],
      ),
    );
  }

  Widget _leaveCard(BuildContext context) {
    final groups = s.leaveGroupsOf(_uid);
    final shown = s.leaveShown ?? 3;
    final mine = groups.take(shown).toList();
    final more = groups.length - mine.length;
    final monthLeaves = s.leaveWeekCount(_uid, s.weekKeyOf(todayStr()));

    return Panel(
      border: Skin.gold.withValues(alpha: .45),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          SectionTitle(
            T('Request a leave'),
            trailing: Text(
              TT("{0} per week", [ONE_LEAVE_PER_WEEK]),
              style: TextStyle(fontSize: 9, color: context.faint),
            ),
          ),
          SizedBox(height: 8),
          if (!_leaveForm)
            FilledButton(
              onPressed: () => setState(() => _leaveForm = true),
              style: FilledButton.styleFrom(
                backgroundColor: Color(0xFFE09B2E),
                foregroundColor: Color(0xFF201C14),
              ),
              child: Text(
                monthLeaves >= ONE_LEAVE_PER_WEEK
                    ? T('Request another leave')
                    : T('Request a leave'),
                style: TextStyle(fontSize: 12, fontWeight: FontWeight.w700),
              ),
            )
          else
            Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Row(
                  children: [
                    Expanded(child: _modeBtn('one', 'One day')),
                    SizedBox(width: 7),
                    Expanded(child: _modeBtn('multiple', 'Multiple days')),
                  ],
                ),
                SizedBox(height: 9),
                if (_leaveMode == 'one')
                  _dateField(
                    context,
                    'Leave date',
                    _from,
                    (v) => setState(() => _from = v),
                  )
                else ...[
                  _dateField(
                    context,
                    'From',
                    _from,
                    (v) => setState(() => _from = v),
                  ),
                  _dateField(
                    context,
                    'To (max $MAX_LEAVE_DAYS days)',
                    _to,
                    (v) => setState(() => _to = v),
                  ),
                ],
                Field(
                  label: T('Reason (optional)'),
                  controller: _reason,
                  hint: T('Family function, medical, personal…'),
                  maxLines: 2,
                ),
                Row(
                  children: [
                    Expanded(
                      child: FilledButton(
                        onPressed: _sendLeave,
                        style: FilledButton.styleFrom(
                          backgroundColor: Skin.gold,
                          foregroundColor: Color(0xFF201C14),
                        ),
                        child: Text(
                          T('Send request'),
                          style: TextStyle(fontSize: 11.5),
                        ),
                      ),
                    ),
                    SizedBox(width: 7),
                    OutlinedButton(
                      onPressed: () => setState(() => _leaveForm = false),
                      child: Text(T('Cancel'), style: TextStyle(fontSize: 11)),
                    ),
                  ],
                ),
              ],
            ),
          SizedBox(height: 6),
          Text(
            T(
              'Send the request and the office accepts or declines it. Accepted leave is neutral for your bank.',
            ),
            style: TextStyle(fontSize: 9.5, color: context.soft, height: 1.4),
          ),
          if (groups.isNotEmpty) SizedBox(height: 9),
          for (var i = 0; i < mine.length; i++)
            Stagger(index: i, child: _leaveTile(context, mine[i].days)),
          if (more > 0)
            TextButton(
              onPressed: () => setState(() => s.leaveShown = shown + 3),
              child: Text(
                TT("View more — {0} older", [more]),
                style: TextStyle(fontSize: 10.5),
              ),
            ),
        ],
