  Widget _modeBtn(String mode, String label) => OutlinedButton(
    onPressed: () => setState(() => _leaveMode = mode),
    style: OutlinedButton.styleFrom(
      backgroundColor: _leaveMode == mode
          ? Skin.gold.withValues(alpha: .18)
          : null,
      side: BorderSide(color: _leaveMode == mode ? Skin.gold : context.line),
    ),
    child: Text(label, style: TextStyle(fontSize: 10.5)),
  );

  Widget _dateField(
    BuildContext context,
    String label,
    String value,
    ValueChanged<String> onPick,
  ) {
    return Padding(
      padding: EdgeInsets.only(bottom: 10),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          SmallLabel(label),
          InkWell(
            onTap: () async {
              final picked = await showDatePicker(
                context: context,
                initialDate: parseDay(value),
                firstDate: DateTime.now().subtract(Duration(days: 1)),
                lastDate: DateTime.now().add(Duration(days: 120)),
              );
              if (picked != null) {
                onPick(
                  '${picked.year}-${two(picked.month)}-${two(picked.day)}',
                );
              }
            },
            child: Container(
              padding: EdgeInsets.symmetric(horizontal: 12, vertical: 12),
              decoration: BoxDecoration(
                color: context.panel2,
                borderRadius: BorderRadius.circular(10),
                border: Border.all(color: context.line),
              ),
              child: Row(
                children: [
                  Icon(Icons.calendar_today_outlined, size: 13),
                  SizedBox(width: 8),
                  Text(
                    fmtDate(value),
                    style: TextStyle(fontSize: 12, fontWeight: FontWeight.w600),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
