  Widget _leaveTile(BuildContext context, List<Map<String, dynamic>> days) {
    final st = (days.first['status'] ?? 'pending').toString();
    final color = st == 'accepted' || st == 'approved'
        ? Skin.green
        : st == 'declined'
        ? Skin.red
        : Skin.marigold;
    final label = st == 'accepted' || st == 'approved'
        ? 'Accepted'
        : st == 'declined'
        ? 'Declined'
        : 'Pending';
    return Container(
      width: double.infinity,
      margin: EdgeInsets.only(bottom: 6),
      padding: EdgeInsets.all(9),
      decoration: BoxDecoration(
        border: Border.all(color: context.line),
        borderRadius: BorderRadius.circular(10),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            s.leaveRangeLabel(days),
            style: TextStyle(fontSize: 10.5, fontWeight: FontWeight.w700),
          ),
          Text(
            ((days.first['reason'] ?? '').toString().trim().isEmpty
                ? 'Leave request'
                : days.first['reason'].toString()),
            style: TextStyle(fontSize: 8.5, color: context.faint),
          ),
          SizedBox(height: 5),
          Row(
            children: [
              Chip8(label, color: color),
              Spacer(),
              if (st == 'accepted')
                Text(
                  T('neutral for your bank'),
                  style: TextStyle(fontSize: 8, color: context.faint),
                ),
              if (st == 'declined')
                Text(
                  T('day hours deducted'),
                  style: TextStyle(fontSize: 8, color: context.faint),
                ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _monthRegister(BuildContext context, String ym) {
    final recs = s.monthStaffRecords(_uid, ym);
    var totalMs = 0;
    var inCount = 0;
    var inSum = 0;
    var outCount = 0;
    var outSum = 0;
    for (final r in recs) {
      totalMs += s.workedMs(r);
      final inn = r['inTs'];
      if (inn is num) {
        final d = DateTime.fromMillisecondsSinceEpoch(inn.toInt());
        inSum += d.hour * 60 + d.minute;
        inCount++;
      }
      final out = r['outTs'];
      if (out is num) {
        final d = DateTime.fromMillisecondsSinceEpoch(out.toInt());
        outSum += d.hour * 60 + d.minute;
        outCount++;
      }
    }
    final completed = recs.where((r) => s.dayComplete(r, u)).length;
    final pl = s.plDaysOf(_uid, ym);
    final monthly = s.isMonthlyRole(u);
    final prev = _shiftMonth(ym, -1);
    final next = _shiftMonth(ym, 1);
    final canNext = !parseDay('$next-01').isAfter(DateTime.now());
    final current = ym == ymOf(todayStr());

    String clockOf(int mins) => '${two((mins ~/ 60) % 24)}:${two(mins % 60)}';

    final facts = StringBuffer();
    facts.write(
      TT("{0} days · {1} on campus", [
        '${recs.length}',
        fmtHours(totalMs ~/ 60000),
      ]),
    );
    if (monthly) {
      final left =
          s.effectiveTargetMinForMonth(u, ym) - s.monthWorkedMin(_uid, ym);
      facts.write(
        TT(" · month target {0}h", [s.monthlyTargetOf(u).toStringAsFixed(0)]),
      );
      facts.write(
        left >= 0 ? T(' met ✓') : TT(" — {0} left", [fmtHours(-left)]),
      );
      final acc = s.acceptedLeaveDaysOf(_uid, ym);
      if (acc.isNotEmpty) {
        facts.write(TT(" · {0} accepted leave day(s)", ['${acc.length}']));
      }
    } else {
      facts.write(TT(" · target met on {0} day(s)", ['$completed']));
      facts.write(
        TT(" · bank {0}", [fmtSignedHours(s.hoursBalanceOf(_uid, ym))]),
      );
      if (pl.isNotEmpty) {
        facts.write(
          TT(" · {0} absence day(s) — hours deducted", ['${pl.length}']),
        );
      }
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // card 1 — one line: ‹ previous month | month | next month ›
        Panel(
          margin: EdgeInsets.only(bottom: 10),
          padding: EdgeInsets.symmetric(horizontal: 12, vertical: 10),
          child: Row(
            children: [
              Expanded(
                child: _monthChip(
                  context,
                  '‹ ${monthLabelShort(prev)}',
                  () => setState(() => _month = prev),
                ),
              ),
              Padding(
                padding: EdgeInsets.symmetric(horizontal: 8),
                child: GestureDetector(
                  onTap: current
                      ? null
                      : () => setState(() => _month = ymOf(todayStr())),
                  child: Text(
                    monthLabelLong(ym),
                    style: TextStyle(
                      fontSize: 15,
                      fontWeight: FontWeight.w700,
                      color: context.ink,
                    ),
                  ),
                ),
              ),
              Expanded(
                child: _monthChip(
                  context,
                  canNext ? '${monthLabelShort(next)} ›' : '›',
                  canNext ? () => setState(() => _month = next) : null,
                ),
              ),
            ],
          ),
        ),
        // card 2 — month, facts and the day grid
        Panel(
          margin: EdgeInsets.only(bottom: 10),
          padding: EdgeInsets.all(12),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                monthLabelLong(ym),
                style: TextStyle(
                  fontSize: 14,
                  fontWeight: FontWeight.w700,
                  color: context.ink,
                ),
              ),
              SizedBox(height: 4),
              Text(
                facts.toString(),
                style: TextStyle(
                  fontSize: 11.5,
                  color: context.soft,
                  height: 1.6,
                ),
              ),
              Text(
                '${TT("Avg in {0}", [clockOf(inCount == 0 ? 0 : inSum ~/ inCount)])}'
                '${outCount > 0 ? TT(" · avg out {0}", [clockOf(outSum ~/ outCount)]) : ''}',
                style: TextStyle(
                  fontSize: 11.5,
                  color: context.soft,
                  height: 1.6,
                ),
              ),
              SizedBox(height: 8),
              _calendar(context, ym, recs, pl),
            ],
          ),
        ),
      ],
    );
  }

  // ghost chip on both sides of the month bar
  Widget _monthChip(BuildContext context, String label, VoidCallback? onTap) =>
      GestureDetector(
        onTap: onTap,
        child: Container(
          padding: EdgeInsets.symmetric(horizontal: 10, vertical: 9),
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(context.k.radius),
            border: Border.all(color: context.k.lineStrong),
          ),
          child: Text(
            label,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            textAlign: TextAlign.center,
            style: TextStyle(
              fontSize: 12,
              color: onTap == null ? context.faint : context.soft,
            ),
          ),
        ),
      );

  // ghost chip on both sides of the month bar

  Widget _calendar(
    BuildContext context,
    String ym,
    List<Map<String, dynamic>> recs,
    List<String> pl,
  ) {
    final start = parseDay('$ym-01');
    final days = DateTime(start.year, start.month + 1, 0).day;
    final byDate = <String, Map<String, dynamic>>{
      for (final r in recs) r['date'].toString(): r,
    };
    final offDays = s.acceptedLeaveDaysOf(_uid, ym).toSet();
    return GridView.builder(
      shrinkWrap: true,
      padding: EdgeInsets.zero,
      physics: NeverScrollableScrollPhysics(),
      itemCount: days,
      gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
        crossAxisCount: 7,
        crossAxisSpacing: 3,
        mainAxisSpacing: 3,
        mainAxisExtent: 47,
      ),
      itemBuilder: (_, i) => _dayCell(context, ym, i + 1, byDate, pl, offDays),
    );
  }

  Widget _dayCell(
    BuildContext context,
    String ym,
    int day,
    Map<String, Map<String, dynamic>> byDate,
    List<String> pl,
    Set<String> offDays,
  ) {
    final dateStr = '$ym-${two(day)}';
    final rec = byDate[dateStr];
    final absent = pl.contains(dateStr);
    final off = offDays.contains(dateStr);
    final done = s.dayComplete(rec, u);
    final hol = s.holidayOn(dateStr);
    final isToday = dateStr == todayStr();
    final worked = rec != null;
    final k = context.k;

    String sub = '';
    if (worked) {
      final outTs = rec['outTs'];
      sub = outTs != null
          ? '${shortTime24(outTs as int?)}'
                '${hol == null ? (done ? '✓' : '') : ''}'
          : T('in');
    } else if (hol != null) {
      // only the holiday the Admin declared — never an automatic weekly off
      sub = T('HOL');
    } else if (off) {
      // only a leave the office APPROVED
      sub = T('OFF');
    } else if (absent) {
      sub = T('AB');
    } else {
      sub = '—';
    }

    final body = Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Text(
          '$day',
          maxLines: 1,
          style: TextStyle(
            fontFamily: Skin.mono,
            fontSize: 9,
            height: 1.2,
            color: k.faint,
          ),
        ),
        if (worked)
          Text(
            shortTime24(rec['inTs'] as int?),
            maxLines: 1,
            overflow: TextOverflow.clip,
            style: TextStyle(
              fontFamily: Skin.mono,
              fontSize: 10.5,
              height: 1.25,
              fontWeight: FontWeight.w700,
              color: k.ink,
            ),
          ),
        Text(
          sub,
          maxLines: 1,
          overflow: TextOverflow.clip,
          style: TextStyle(
            fontFamily: Skin.mono,
            fontSize: worked ? 9 : 9,
            height: 1.2,
            color: k.inkSoft,
          ),
        ),
      ],
    );

    return Container(
      decoration: BoxDecoration(
        color: worked ? Skin.greenBg : k.surface2,
        borderRadius: BorderRadius.circular(8),
        border: Border.all(
          color: isToday
              ? Skin.gold
              : worked
              ? const Color(0x592F7D5E)
              : k.line,
          width: isToday ? 1.3 : 1,
        ),
      ),
      padding: EdgeInsets.symmetric(horizontal: 1, vertical: 3),
      child: worked ? body : Opacity(opacity: 0.55, child: body),
    );
  }

  String _shiftMonth(String ym, int delta) {
    final p = ym.split('-');
    final d = DateTime(int.parse(p[0]), int.parse(p[1]) + delta, 1);
    return '${d.year}-${two(d.month)}';
  }
}

// ---------------------------------------------------------------------------
//  NOTIFICATIONS — ONE merged chronological list (messages + staff log)
// ---------------------------------------------------------------------------
class NotificationsPage extends StatefulWidget {
  const NotificationsPage({super.key, required this.user});

  final Map<String, dynamic> user;

  @override
  State<NotificationsPage> createState() => _NotificationsPageState();
}

class _NotificationsPageState extends State<NotificationsPage> {
  Store get s => Store.I;
  String get _uid => widget.user['id'].toString();

  List<Map<String, dynamic>> get _log {
    if (widget.user['role'] != 'staff' && widget.user['role'] != 'teacher') {
      return [];
    }
    return s.staffNotifications.where((n) => n['userId'] == _uid).toList();
  }

  List<Map<String, dynamic>> get _merged {
    final items = <Map<String, dynamic>>[];
    for (final n in s.inboxOf(_uid)) {
      items.add({...n, '_kind': 'msg'});
    }
    for (final l in _log) {
      final ts = (l['ts'] as num? ?? 0).toInt();
      final dup = items.any(
        (n) =>
            ((n['ts'] as num? ?? 0).toInt() - ts).abs() < 120000 &&
            n['type'] != 'fee' &&
            n['type'] != 'notice',
      );
      if (dup) continue;
      items.add({
        'id': l['id'],
        'title': 'JSK Institute Staff Attendance',
        'message': l['text'],
        'ts': ts,
        'type': l['kind'],
        'read': true,
        '_kind': 'log',
      });
    }
    items.sort(
      (a, b) => ((b['ts'] as num? ?? 0)).compareTo(a['ts'] as num? ?? 0),
    );
    return items;
  }

  @override
  Widget build(BuildContext context) {
    final unread = s.unreadOf(_uid);
    final filter = s.inboxFilter;
    final mine = _merged;
    final shown = s.inboxShown ?? 5;
    final filtered = filter == 'unread'
        ? mine.where((n) => n['read'] != true).toList()
        : mine;
    final pageItems = filtered.take(shown).toList();
    final more = filtered.length - pageItems.length;
    final student = s.studentOfUser(_uid);
    final isGuardian = widget.user['role'] == 'guardian';

    return ListView(
      padding: EdgeInsets.fromLTRB(14, 14, 14, 22),
      children: [
        PageHeading(
          s.t('Notifications'),
          student == null
              ? 'Your check-ins, office notices and institute updates.'
              : 'Attendance, fees, class schedules and office notices '
                    '${isGuardian ? 'for ${student['name']}.' : 'for you.'} $unread unread',
          Icons.notifications_none,
        ),
        SizedBox(height: 12),
        Row(
          children: [
            Expanded(
              child: FilledButton(
                onPressed: () => setState(() {
                  s.inboxFilter = 'all';
                  s.inboxShown = null;
                }),
                style: FilledButton.styleFrom(
                  backgroundColor: filter == 'all'
                      ? Color(0xFFE99B53)
                      : context.panel2,
                  foregroundColor: filter == 'all'
                      ? Color(0xFF201C14)
                      : context.soft,
                ),
                child: Text(
                  TT("All ({0})", [mine.length]),
                  style: TextStyle(fontSize: 11.5),
                ),
              ),
            ),
            SizedBox(width: 7),
            Expanded(
              child: OutlinedButton(
                onPressed: () => setState(() {
                  s.inboxFilter = 'unread';
                  s.inboxShown = null;
                }),
                style: OutlinedButton.styleFrom(
                  backgroundColor: filter == 'unread'
                      ? Skin.gold.withValues(alpha: .18)
                      : null,
                  side: BorderSide(
                    color: filter == 'unread' ? Skin.gold : context.line,
                  ),
                ),
                child: Text(
                  TT("Unread ({0})", [unread]),
                  style: TextStyle(fontSize: 11.5),
                ),
              ),
            ),
          ],
        ),
        if (unread > 0)
          Align(
            alignment: Alignment.centerRight,
            child: TextButton(
              onPressed: () {
                s.markAllInboxRead(_uid);
                setState(() {});
              },
              child: Text(
                T('Mark all as read'),
                style: TextStyle(fontSize: 10),
              ),
            ),
          ),
        SizedBox(height: 4),
        Panel(
          padding: EdgeInsets.all(10),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              SectionTitle(T('Notifications')),
              SizedBox(height: 9),
              if (pageItems.isEmpty)
                Padding(
                  padding: EdgeInsets.symmetric(vertical: 26),
                  child: Center(
                    child: Text(
                      filter == 'unread'
                          ? 'No notifications here yet — you are all caught up.'
                          : 'No notifications here yet.',
                      textAlign: TextAlign.center,
                      style: TextStyle(fontSize: 11, color: context.soft),
                    ),
                  ),
                )
              else
                for (var i = 0; i < pageItems.length; i++)
                  Stagger(index: i, child: _tile(context, pageItems[i])),
              if (more > 0)
                OutlinedButton(
                  onPressed: () => setState(() => s.inboxShown = shown + 5),
                  child: Text(
                    TT("View more — {0} older", [more]),
                    style: TextStyle(fontSize: 10.5),
                  ),
                ),
            ],
          ),
        ),
      ],
    );
  }

  IconData _iconFor(String? type) {
    switch (type) {
      case 'in':
        return Icons.login;
      case 'out':
        return Icons.logout;
      case 'adj':
        return Icons.savings_outlined;
      case 'fee':
        return Icons.receipt_long_outlined;
      case 'notice':
        return Icons.campaign_outlined;
      case 'leave':
        return Icons.beach_access_outlined;
      case 'attendance':
        return Icons.fact_check_outlined;
      case 'schedule':
        return Icons.calendar_month_outlined;
      case 'late':
        return Icons.schedule;
      default:
        return Icons.notifications_active_outlined;
    }
  }

  Color _colorFor(String? type) {
    switch (type) {
      case 'in':
        return Skin.green;
      case 'out':
        return Skin.red;
      case 'fee':
        return Skin.marigold;
      case 'notice':
        return Skin.violet;
      case 'leave':
        return Skin.marigold;
      case 'late':
        return Skin.marigold;
      default:
        return Skin.green;
    }
  }

  /// every notification opens in a small sheet with the whole story
  Future<void> _openDetail(Map<String, dynamic> n) async {
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      barrierColor: Colors.black.withValues(alpha: .42),
      builder: (_) => NotificationDetailSheet(item: n),
    );
    if (mounted) setState(() {});
  }

  Widget _tile(BuildContext context, Map<String, dynamic> n) {
    final read = n['read'] == true;
    final type = n['type']?.toString();
    final isLog = n['_kind'] == 'log';
    return Pressable(
      onTap: () {
        if (!isLog) s.markInboxRead(_uid, n['id'].toString());
        setState(() {});
        _openDetail(n);
      },
      child: Container(
        margin: EdgeInsets.only(bottom: 8),
        padding: EdgeInsets.all(9),
        decoration: BoxDecoration(
          color: read
              ? (context.dark ? Color(0xFF23241F) : Color(0xFFF3F1E9))
              : (context.dark ? Color(0xFF2A2B23) : Color(0xFFFDF6E6)),
          borderRadius: BorderRadius.circular(11),
          border: Border.all(
            color: read ? context.line : Skin.gold.withValues(alpha: .45),
          ),
        ),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Container(
              width: 26,
              height: 26,
              decoration: BoxDecoration(
                color: _colorFor(type).withValues(alpha: .16),
                shape: BoxShape.circle,
              ),
              child: Icon(_iconFor(type), size: 13, color: _colorFor(type)),
            ),
            SizedBox(width: 8),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Expanded(
                        child: Text(
                          n['title'].toString(),
                          style: TextStyle(
                            fontSize: 10.5,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                      ),
                      if (!read)
                        Container(
                          width: 6,
                          height: 6,
                          decoration: BoxDecoration(
                            color: Skin.gold,
                            shape: BoxShape.circle,
                          ),
                        ),
                      if (isLog &&
                          (type == 'in' || type == 'out' || type == 'adj'))
                        Chip8(
                          type == 'in'
                              ? 'IN'
                              : type == 'out'
                              ? 'OUT'
                              : 'HOURS',
                          color: _colorFor(type),
                        ),
                    ],
                  ),
                  SizedBox(height: 3),
                  Text(
                    n['message'].toString(),
                    style: TextStyle(
                      fontSize: 9.5,
                      color: context.soft,
                      height: 1.4,
                    ),
                  ),
                  SizedBox(height: 6),
                  Text(
                    fmtTime((n['ts'] as num?)?.toInt()),
                    style: TextStyle(fontSize: 8.5, color: context.faint),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

// ---------------------------------------------------------------------------
//  NOTIFICATION DETAIL — every notification opens in this small sheet so the
//  full message is readable: who sent it, everything it says, the lecture it
//  refers to, and any file it carries, which can be viewed or downloaded.
// ---------------------------------------------------------------------------
class _AttachedFile {
  _AttachedFile(this.name, this.url);
  final String name;
  final String url;
}

class NotificationDetailSheet extends StatefulWidget {
  const NotificationDetailSheet({super.key, required this.item});

  final Map<String, dynamic> item;

  @override
  State<NotificationDetailSheet> createState() =>
      _NotificationDetailSheetState();
}

class _NotificationDetailSheetState extends State<NotificationDetailSheet> {
  String? _busy;

  Store get s => Store.I;
  Map<String, dynamic> get n => widget.item;

  /// the record this notification was raised from — a notice or a lecture
  Map<String, dynamic>? _byRef(String type) {
    final refType = (n['refType'] ?? '').toString();
    final refId = (n['refId'] ?? '').toString();
    if (refType != type || refId.isEmpty) return null;
    final list = type == 'schedule' ? s.schedules : s.announcements;
    for (final r in list) {
      if ((r['id'] ?? '').toString() == refId) return r;
    }
    return null;
  }

  Map<String, dynamic>? get _notice => _byRef('notice');
  Map<String, dynamic>? get _lecture => _byRef('schedule');

  /// The screen this message is about, so opening it lands the person where
  /// they can act on it instead of leaving them to find the page. Null means
  /// the sheet itself is the whole story and no button is offered.
  String? _pageFor() {
    final type = (n['type'] ?? '').toString();
    final role = (s.me?['role'] ?? '').toString();
    if (role == 'admin') {
      switch (type) {
        case 'fee':
        case 'fee_period':
        case 'fee_paid':
          return 'fees';
        case 'leave':
        case 'late':
        case 'adj':
        case 'staff_update':
        case 'in':
        case 'out':
          return 'staff';
        case 'notice':
          return 'notices';
        case 'attendance':
        case 'class_note':
        case 'student_batch':
        case 'schedule':
        case 'holiday':
          return 'students';
      }
      return null;
    }
    if (role == 'teacher') {
      switch (type) {
        case 'attendance':
          return 'attendance';
        case 'schedule':
          return 'schedule';
        case 'in':
        case 'out':
        case 'late':
        case 'adj':
        case 'staff_update':
        case 'leave':
          return 'myatt';
        case 'holiday':
        case 'notice':
          return 'home';
      }
      return null;
    }
    if (role == 'staff') {
      switch (type) {
        case 'in':
        case 'out':
        case 'late':
        case 'adj':
        case 'staff_update':
        case 'leave':
          return 'attendance';
        case 'holiday':
        case 'notice':
          return 'home';
      }
      return null;
    }
    switch (type) {
      case 'attendance':
        return 'attendance';
      case 'fee':
      case 'fee_period':
      case 'fee_paid':
      case 'notice':
      case 'schedule':
      case 'class_note':
      case 'student_batch':
      case 'holiday':
        return 'home';
    }
    return null;
  }

  String _openLabel() {
    final name = switch (_pageFor()) {
      'fees' => T('Fees'),
      'staff' => T('Staff'),
      'notices' => T('Send Notices'),
      'students' => T('Students'),
      'schedule' => T('Schedule Lecture'),
      'myatt' => T('My attendance'),
      'attendance' => T('Attendance'),
      _ => T('Home'),
    };
    return '${T('Open')} $name';
  }

  String _typeLabel(String? type) {
    switch (type) {
      case 'notice':
        return T('Notice');
      case 'schedule':
        return T('Class schedule');
      case 'fee':
        return T('Fees');
      case 'leave':
        return T('Leave');
      case 'attendance':
        return T('Attendance');
      case 'in':
        return T('Check in');
      case 'out':
        return T('Check out');
      case 'adj':
        return T('Hours bank');
      case 'late':
        return T('Late');
      case 'welcome':
        return T('Welcome');
      default:
        return T('Update');
    }
  }

  Color _tone(String? type) {
    switch (type) {
      case 'in':
        return Skin.green;
      case 'out':
        return Skin.red;
      case 'fee':
      case 'leave':
        return Skin.marigold;
      case 'notice':
      case 'schedule':
        return Skin.violet;
      default:
        return Skin.green;
    }
  }

  IconData _glyph(String? type) {
    switch (type) {
      case 'in':
        return Icons.login;
      case 'out':
        return Icons.logout;
      case 'adj':
        return Icons.savings_outlined;
      case 'fee':
        return Icons.receipt_long_outlined;
      case 'notice':
        return Icons.campaign_outlined;
      case 'leave':
        return Icons.beach_access_outlined;
      case 'attendance':
        return Icons.fact_check_outlined;
      case 'schedule':
        return Icons.calendar_month_outlined;
      case 'late':
        return Icons.schedule;
      default:
        return Icons.notifications_active_outlined;
    }
  }

  String _when(int? ts) {
    if (ts == null) return '—';
    final d = DateTime.fromMillisecondsSinceEpoch(ts);
    return '${two(d.day)} ${kMonthShort[d.month - 1]} ${d.year} · '
        '${fmtClock(ts)}';
  }

  /// who sent it: the office member on the notice, else the lecture's teacher
  String get _sender {
    final a = _notice;
    if (a != null) {
      final by = (a['by'] ?? '').toString().trim();
      if (by.isNotEmpty) return by;
    }
    final l = _lecture;
    if (l != null) {
      final t = s.userById((l['teacherId'] ?? '').toString());
      final name = (t?['name'] ?? '').toString().trim();
      if (name.isNotEmpty) return name;
    }
    if (n['_kind'] == 'log') return T('JSK Institute staff register');
    return T('JSK Institute office');
  }

  /// who the notice went to
  String get _audience {
    final a = _notice;
    if (a == null) return '';
    final aud = (a['audience'] ?? 'all').toString();
    if (aud == 'batch') {
      final b = s.batchName(a['batchId']);
      return b.isEmpty ? T('One batch') : b;
    }
    switch (aud) {
      case 'students':
        return T('Student');
      case 'guardians':
        return T('Guardians');
      case 'staff':
        return T('Staff');
      case 'teachers':
        return T('Teacher');
      case 'sgt':
        return T('Students, guardians & teachers');
      case 'all':
        return T('All students & guardians');
      default:
        return T('Everyone — students, guardians, staff & teachers');
    }
  }

  /// files carried by the notice, plus any link written into the text
  List<_AttachedFile> get _files {
    final out = <_AttachedFile>[];
    final seen = <String>{};

    void take(Object? raw, {String? named}) {
      if (raw == null) return;
      if (raw is String) {
        final u = raw.trim();
        if ((u.startsWith('http') || u.startsWith('data:')) && seen.add(u)) {
          out.add(_AttachedFile(named ?? '', u));
        }
        return;
      }
      if (raw is Map) {
        final u =
            (raw['url'] ?? raw['href'] ?? raw['link'] ?? raw['fileUrl'] ?? '')
                .toString()
                .trim();
        final label =
            (raw['name'] ?? raw['fileName'] ?? raw['title'] ?? named ?? '')
                .toString()
                .trim();
        if ((u.startsWith('http') || u.startsWith('data:')) && seen.add(u)) {
          out.add(_AttachedFile(label, u));
        }
        return;
      }
      if (raw is List) {
        for (final e in raw) {
          take(e);
        }
      }
    }

    void takeFrom(Map<String, dynamic> src) {
      take(src['attachment'], named: src['fileName']?.toString());
      for (final key in const <String>[
        'attachments',
        'files',
        'fileUrl',
        'file',
        'url',
        'link',
      ]) {
        take(src[key]);
      }
    }

    final a = _notice;
    if (a != null) takeFrom(a);
    takeFrom(n);

    final text = (n['message'] ?? '').toString();
    for (final m in RegExp(r'https?://[^\s]+').allMatches(text)) {
      final u = m.group(0)!.replaceAll(RegExp(r'[),.;]+$'), '');
      if (seen.add(u)) out.add(_AttachedFile('', u));
    }
    return out;
  }

  String _fileLabel(_AttachedFile f) {
    final named = f.name.trim();
    if (named.isNotEmpty) return named;
    final path = Uri.tryParse(f.url)?.path ?? '';
    final parts = path.split('/').where((p) => p.trim().isNotEmpty).toList();
    if (parts.isEmpty) return T('Attached file');
    final raw = parts.last;
    // storage keys often start with a timestamp: 1746….pdf
    final cleaned = raw.replaceFirst(RegExp(r'^\d{8,}_'), '');
    return cleaned.isEmpty ? raw : cleaned;
  }

  String _fileExt(_AttachedFile f) {
    final name = _fileLabel(f);
    final dot = name.lastIndexOf('.');
    if (dot < 0 || dot == name.length - 1) return '';
    return name.substring(dot + 1).toLowerCase();
  }

  IconData _fileIcon(String ext) {
    switch (ext) {
      case 'pdf':
        return Icons.picture_as_pdf_outlined;
      case 'doc':
      case 'docx':
      case 'txt':
      case 'rtf':
        return Icons.description_outlined;
      case 'xls':
      case 'xlsx':
      case 'csv':
        return Icons.table_chart_outlined;
      case 'ppt':
      case 'pptx':
        return Icons.slideshow_outlined;
      case 'png':
      case 'jpg':
      case 'jpeg':
      case 'webp':
      case 'gif':
        return Icons.image_outlined;
      case 'zip':
      case 'rar':
      case '7z':
        return Icons.folder_zip_outlined;
      case 'mp4':
      case 'mov':
      case 'mkv':
        return Icons.video_library_outlined;
      case 'mp3':
      case 'wav':
      case 'm4a':
        return Icons.audiotrack_outlined;
      default:
        return Icons.insert_drive_file_outlined;
    }
  }

  Future<void> _open(String url) async {
    if (url.startsWith('data:')) {
      // the file rides inside the notice itself, so it needs no host
      try {
        final tmp = await getTemporaryDirectory();
        final dir = Directory('${tmp.path}/jsk_files');
        if (!dir.existsSync()) dir.createSync(recursive: true);
        final named = _files
            .firstWhere(
              (f) => f.url == url,
              orElse: () => _AttachedFile('file', url),
            )
            .name
            .trim();
        final clean = noteSafeName(named.isEmpty ? 'notice_file' : named);
        final file = File('${dir.path}/$clean');
        await file.writeAsBytes(noteDataBytes(url), flush: true);
        await OpenFilex.open(file.path);
      } catch (_) {
        if (mounted) toast(context, T('Could not open this file.'));
      }
      return;
    }
    final uri = Uri.tryParse(url);
    if (uri == null) {
      toast(context, T('That link does not look right.'));
      return;
    }
    try {
      final ok = await launchUrl(uri, mode: LaunchMode.externalApplication);
      if (!ok && mounted) toast(context, T('Could not open this file.'));
    } catch (_) {
      if (mounted) toast(context, T('Could not open this file.'));
    }
  }

  String _saveName(_AttachedFile f) {
    final clean = _fileLabel(f).replaceAll(RegExp(r'[\\/:*?"<>|]'), '_').trim();
    return clean.isEmpty ? 'jsk_file' : clean;
  }

  Future<void> _download(_AttachedFile f) async {
    if (_busy != null) return;
    setState(() => _busy = f.url);
    try {
      if (f.url.startsWith('data:')) {
        final base = await getApplicationDocumentsDirectory();
        final dir = Directory('${base.path}/jsk_files');
        if (!dir.existsSync()) dir.createSync(recursive: true);
        final file = File('${dir.path}/${_saveName(f)}');
        await file.writeAsBytes(noteDataBytes(f.url), flush: true);
        if (!mounted) return;
        setState(() => _busy = null);
        toast(context, TT("Saved {0}", [_saveName(f)]));
        await OpenFilex.open(file.path);
        return;
      }
      final res = await http.get(Uri.parse(f.url));
      if (res.statusCode < 200 || res.statusCode >= 300) {
        throw Exception('download failed');
      }
      final base = await getApplicationDocumentsDirectory();
      final dir = Directory('${base.path}/jsk_files');
      if (!dir.existsSync()) dir.createSync(recursive: true);
      final file = File('${dir.path}/${_saveName(f)}');
      await file.writeAsBytes(res.bodyBytes, flush: true);
      if (!mounted) return;
      setState(() => _busy = null);
      toast(context, TT("Saved {0}", [_saveName(f)]));
      await OpenFilex.open(file.path);
    } catch (_) {
      // a drive/sign-in link cannot be fetched directly — let the phone's
      // browser take it, where it can still be saved
      if (!mounted) return;
      setState(() => _busy = null);
      await _open(f.url);
    }
  }

  Widget _sectionLabel(String text) => Text(
    text.toUpperCase(),
    style: TextStyle(
      fontSize: 8.5,
      fontWeight: FontWeight.w800,
      letterSpacing: 1.5,
      color: context.faint,
    ),
  );

  Widget _lectureDetails(Map<String, dynamic> l) {
    final start = (l['time'] ?? '').toString().trim();
    final end = (l['endTime'] ?? '').toString().trim();
    final when = start.isEmpty ? '—' : (end.isEmpty ? start : '$start – $end');
    final date = (l['date'] ?? '').toString().trim();
    final rows = <List<String>>[
      [T('Subject'), s.subjectName(l['subjectId'])],
      [T('Batch'), s.batchName(l['batchId'])],
      if ((l['topic'] ?? '').toString().trim().isNotEmpty)
        [T('Topic'), l['topic'].toString().trim()],
      [T('Date'), date.isEmpty ? '—' : fmtDate(date)],
      [T('Time'), when],
      if ((l['room'] ?? '').toString().trim().isNotEmpty)
        [T('Room'), l['room'].toString().trim()],
      if ((l['note'] ?? '').toString().trim().isNotEmpty)
        [T('Note'), l['note'].toString().trim()],
    ];
    return Container(
      padding: EdgeInsets.fromLTRB(11, 8, 11, 8),
      decoration: BoxDecoration(
        color: context.panel2,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: context.line),
      ),
      child: Column(
        children: [
          for (final r in rows)
            Padding(
              padding: EdgeInsets.symmetric(vertical: 3),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  SizedBox(
                    width: 72,
                    child: Text(
                      r[0],
                      style: TextStyle(fontSize: 9, color: context.faint),
                    ),
                  ),
                  Expanded(
                    child: Text(
                      r[1],
                      style: TextStyle(
                        fontSize: 10.5,
                        fontWeight: FontWeight.w600,
                        color: context.ink,
                      ),
                    ),
                  ),
                ],
              ),
            ),
        ],
      ),
    );
  }

  Widget _fileRow(_AttachedFile f) {
    final ext = _fileExt(f);
    final busy = _busy == f.url;
    return Container(
      margin: EdgeInsets.only(bottom: 7),
      padding: EdgeInsets.fromLTRB(9, 7, 6, 7),
      decoration: BoxDecoration(
        color: context.panel2,
        borderRadius: BorderRadius.circular(11),
        border: Border.all(color: context.line),
      ),
      child: Row(
        children: [
          Container(
            width: 30,
            height: 30,
            decoration: BoxDecoration(
              color: Skin.gold.withValues(alpha: .15),
              borderRadius: BorderRadius.circular(8),
            ),
            child: Icon(_fileIcon(ext), size: 15, color: Skin.gold),
          ),
          SizedBox(width: 9),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  _fileLabel(f),
                  maxLines: 2,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(
                    fontSize: 10.5,
                    fontWeight: FontWeight.w700,
                    color: context.ink,
                  ),
                ),
                SizedBox(height: 2),
                Text(
                  ext.isEmpty ? T('File') : ext.toUpperCase(),
                  style: TextStyle(
                    fontSize: 8,
                    letterSpacing: .8,
                    color: context.faint,
                  ),
                ),
              ],
            ),
          ),
          TextButton(
            onPressed: busy ? null : () => _open(f.url),
            style: TextButton.styleFrom(
              minimumSize: Size(0, 30),
              padding: EdgeInsets.symmetric(horizontal: 8),
            ),
            child: Text(
              T('View'),
              style: TextStyle(fontSize: 10, fontWeight: FontWeight.w700),
            ),
          ),
          IconButton(
            onPressed: busy ? null : () => _download(f),
            tooltip: T('Download'),
            padding: EdgeInsets.zero,
            constraints: BoxConstraints(minWidth: 30, minHeight: 30),
            icon: busy
                ? SizedBox(
                    width: 14,
                    height: 14,
                    child: CircularProgressIndicator(
                      strokeWidth: 1.6,
                      color: Skin.gold,
                    ),
                  )
                : Icon(Icons.download_rounded, size: 17, color: Skin.gold),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final type = n['type']?.toString();
    final tone = _tone(type);
    final lecture = _lecture;
    final files = _files;
    final message = (n['message'] ?? '').toString().trim();
    final title = (n['title'] ?? '').toString().trim();
    final audience = _audience;

    return Container(
      decoration: BoxDecoration(
        color: context.panel,
        borderRadius: BorderRadius.vertical(top: Radius.circular(18)),
        border: Border.all(color: context.line),
      ),
