class NotificationSettingsPage extends StatefulWidget {
  const NotificationSettingsPage({super.key});

  @override
  State<NotificationSettingsPage> createState() =>
      _NotificationSettingsPageState();
}

class _NotificationSettingsPageState extends State<NotificationSettingsPage> {
  Store get s => Store.I;

  bool _get(String k, bool dflt) {
    if (k == 'push') {
      return FcmPushService.pushEnabledForUser(s.userId);
    }
    return s.prefs?.getBool('notif_$k') ?? dflt;
  }

  void _set(String k, bool v) {
    s.prefs?.setBool('notif_$k', v);
    setState(() {});
  }

  Future<void> _setPush(bool enabled) async {
    if (s.userId == null) return;
    if (!enabled) {
      await FcmPushService.unregisterCurrent();
      final user = s.me;
      if (user != null) {
        user['phoneNotifs'] = false;
        s.save();
      }
      if (mounted) setState(() {});
      return;
    }

    try {
      final registered = await FcmPushService.requestPermissionAndRegister();
      if (!registered) {
        if (mounted) {
          setState(() {});
          toast(context, s.t('Notification permission was not granted.'));
        }
        return;
      }
      final user = s.me;
      if (user != null) {
        user['phoneNotifs'] = true;
        s.save();
      }
      if (mounted) {
        setState(() {});
        toast(context, s.t('Push notifications enabled.'));
      }
    } catch (_) {
      if (mounted) {
        setState(() {});
        toast(context, s.t('Could not enable push notifications.'));
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return ListView(
      padding: EdgeInsets.fromLTRB(14, 12, 14, 22),
      children: [
        _subHeader(
          context,
          s.t('Notifications'),
          s.t("Choose what's worth a buzz."),
        ),
        SizedBox(height: 12),
        Panel(
          padding: EdgeInsets.zero,
          child: SwitchListTile(
            contentPadding: EdgeInsets.symmetric(horizontal: 12),
            title: Text(
              s.t('Push Notifications'),
              style: TextStyle(fontSize: 11.5, fontWeight: FontWeight.w700),
            ),
            subtitle: Text(
              T(
                'Attendance, fees, schedules and notices — delivered to your lock screen, even when the app is closed (where the device supports it).',
              ),
              style: TextStyle(
                fontSize: 8.8,
                color: context.faint,
                height: 1.35,
              ),
            ),
            value: _get('push', false),
            onChanged: (v) => unawaited(_setPush(v)),
          ),
        ),
        SizedBox(height: 12),
        SmallLabel(s.t('DEVICE PERMISSIONS')),
        Panel(
          padding: EdgeInsets.zero,
          child: Column(
            children: [
              _perm(
                context,
                s.t('Notifications on this device'),
                s.online
                    ? 'Allowed by the system settings'
                    : 'Offline — system decides',
                Icons.notifications_active_outlined,
              ),
              _perm(
                context,
                s.t('Location on this device'),
                'Used only to confirm the ${(s.geofence['radius'] as num? ?? 150).round()} m check-in zone',
                Icons.my_location,
              ),
            ],
          ),
        ),
        SizedBox(height: 12),
        SmallLabel(s.t('NOTIFY ME ABOUT')),
        Panel(
          padding: EdgeInsets.zero,
          child: Column(
            children: [
              _toggle(
                context,
                'attendance',
                s.t('Attendance updates'),
                s.t('When attendance is marked or corrected'),
              ),
              _toggle(
                context,
                'notices',
                s.t('Notices & announcements'),
                s.t('School notices sent to you'),
              ),
            ],
          ),
        ),
        SizedBox(height: 12),
        SmallLabel(s.t('SOUND & VIBRATION')),
        Panel(
          padding: EdgeInsets.zero,
          child: _toggle(
            context,
            'sound',
            s.t('Sound'),
            s.t('A soft chime for new alerts'),
          ),
        ),
      ],
    );
  }

  Widget _toggle(BuildContext context, String key, String title, String sub) =>
      SwitchListTile(
        contentPadding: EdgeInsets.symmetric(horizontal: 12),
        title: Text(
          title,
          style: TextStyle(fontSize: 11.5, fontWeight: FontWeight.w700),
        ),
        subtitle: Text(
          sub,
          style: TextStyle(fontSize: 8.8, color: context.faint),
        ),
        value: _get(key, true),
        onChanged: (v) => _set(key, v),
      );

  Widget _perm(BuildContext context, String title, String sub, IconData icon) =>
      Padding(
        padding: EdgeInsets.symmetric(horizontal: 12, vertical: 11),
        child: Row(
          children: [
            Icon(icon, size: 16, color: Store.I.skin.accent),
            SizedBox(width: 9),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    title,
                    style: TextStyle(fontSize: 11, fontWeight: FontWeight.w700),
                  ),
                  SizedBox(height: 2),
                  Text(
                    sub,
                    style: TextStyle(fontSize: 8.8, color: context.faint),
                  ),
                ],
              ),
            ),
          ],
        ),
      );
}

