// ---------------------------------------------------------------------------
//  STUDENT + GUARDIAN
// ---------------------------------------------------------------------------
List<Map<String, dynamic>> studentSubjects(Store s, Map<String, dynamic> st) {
  final ids = <Object?>{};
  for (final a in s.assignments) {
    if (a['batchId'] == st['batchId']) ids.add(a['subjectId']);
  }
  for (final r in s.studentRecords(st['id'].toString())) {
    ids.add(r['subjectId']);
  }
  return s.subjects.where((x) => ids.contains(x['id'])).toList();
}

/// Students keep the date in `dob`; the office writes it into `birthday` for
/// teachers and staff. Whichever key holds it, this reads the same date.
String bdayOf(Map<String, dynamic>? person) {
  if (person == null) return '';
  for (final key in <String>['dob', 'birthday']) {
    final v = (person[key] ?? '').toString().trim();
    if (bdayMonthDay(v).isNotEmpty) return v;
  }
  return '';
}

/// The primary reading of a birth date, as `MM-DD`, from any of
/// `YYYY-MM-DD`, `YYYY/MM/DD`, `DD-MM-YYYY`, `DD/MM/YYYY` or an ISO stamp.
String bdayMonthDay(String raw) {
  final List<String> all = bdayMonthDays(raw);
  return all.isEmpty ? '' : all.first;
}

/// Birthdays follow the institute's calendar day, not the phone's, so a device
/// set to another timezone still celebrates on the right date. India has no
/// daylight saving, so a fixed offset is exact.
String bdayTodayStr() {
  final DateTime ist = DateTime.now().toUtc().add(
    const Duration(hours: 5, minutes: 30),
  );
  return '${ist.year}-${two(ist.month)}-${two(ist.day)}';
}

/// Every month/day this birth date could mean. The office types birthdays by
/// hand, so `07-11-2026` is read both as 7 November (Indian order) and as
/// 11 July, and either reading can make it their birthday.
List<String> bdayMonthDays(String raw) {
  final String v = raw.trim();
  if (v.isEmpty) return const <String>[];

  RegExpMatch? m = RegExp(
    r'^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})',
  ).firstMatch(v);
  if (m != null) {
    final int mo = int.parse(m.group(2)!);
    final int da = int.parse(m.group(3)!);
    if (mo < 1 || mo > 12 || da < 1 || da > 31) return const <String>[];
    return <String>['${two(mo)}-${two(da)}'];
  }

  m = RegExp(r'^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4}|\d{2})$').firstMatch(v);
  if (m != null) {
    final int first = int.parse(m.group(1)!);
    final int second = int.parse(m.group(2)!);
    final Set<String> out = <String>{};
    if (first >= 1 && first <= 31 && second >= 1 && second <= 12) {
      out.add('${two(second)}-${two(first)}');
    }
    if (first >= 1 && first <= 12 && second >= 1 && second <= 31) {
      out.add('${two(first)}-${two(second)}');
    }
    if (out.isNotEmpty) return out.toList();
  }

  // `7 Nov 2026`, `Nov 7 2026`, `07-November-1988`
  final String low = v.toLowerCase();
  for (var i = 0; i < kMonthShort.length; i++) {
    final String name = kMonthShort[i].toLowerCase();
    if (!low.contains(name)) continue;
    final RegExpMatch? day = RegExp(r'\d{1,2}').firstMatch(v);
    if (day == null) return const <String>[];
    final int d = int.parse(day.group(0)!);
    if (d < 1 || d > 31) return const <String>[];
    return <String>['${two(i + 1)}-${two(d)}'];
  }
  return const <String>[];
}

/// Month and day only, so the year of birth never matters.
bool bdayToday(Map<String, dynamic>? person) {
  final List<String> mine = bdayMonthDays(bdayOf(person));
  if (mine.isEmpty) return false;
  return mine.contains(bdayMonthDay(bdayTodayStr()));
}

/// A birth date the way a printed card reads it: `07.11.2026`.
String bdayCardDate(String raw) {
  final List<String> md = bdayMonthDays(raw);
  if (md.isEmpty) return '';
  final List<String> parts = md.first.split('-');
  final RegExpMatch? year = RegExp(r'\d{4}').firstMatch(raw);
  final String dd = parts[1];
  final String mm = parts[0];
  return year == null ? '$dd.$mm' : '$dd.$mm.${year.group(0)}';
}

/// The same date in words for the admin lists: `07 Nov 2026`.
String fmtBirthday(String raw) {
  final String t = raw.trim();
  if (t.isEmpty) return '';
  if (DateTime.tryParse(t) != null) return fmtDate(t);
  final String card = bdayCardDate(t);
  if (card.isEmpty) return t;
  final List<String> parts = card.split('.');
  final int month = int.tryParse(parts.length > 1 ? parts[1] : '') ?? 0;
  final String name = month >= 1 && month <= 12 ? kMonthShort[month - 1] : '';
  final String year = parts.length > 2 ? ' ${parts[2]}' : '';
  return '${parts[0]} $name$year'.trim();
}

bool isBirthdayToday(Map<String, dynamic>? person) => bdayToday(person);

/// Who the viewer may celebrate with today. The classroom side of the
/// institute — students and teachers — sees student and teacher birthdays.
/// The staff register sees staff birthdays only. An admin keeps every record,
/// so an admin sees both lists. Guardians get their own child's card instead.
List<Map<String, dynamic>> birthdaysTodayFor(String role) {
  final s = Store.I;
  final out = <Map<String, dynamic>>[];
  void add(Map<String, dynamic> p, String as) {
    final name = (p['name'] ?? '').toString().trim();
    if (name.isEmpty) return;
    out.add(<String, dynamic>{
      'id': (p['id'] ?? '').toString(),
      'name': name,
      'photo': (p['photo'] ?? '').toString().trim(),
      'as': as,
    });
  }

  final classroom = role == 'student' || role == 'teacher' || role == 'admin';
  final staffSide = role == 'staff' || role == 'admin';
  if (classroom) {
    for (final st in s.students) {
      if (bdayToday(st)) add(st, 'student');
    }
    for (final t in s.users) {
      if (t['role'] == 'teacher' && bdayToday(t)) add(t, 'teacher');
    }
  }
  if (staffSide) {
    for (final p in s.users) {
      if (p['role'] == 'staff' && bdayToday(p)) add(p, 'staff');
    }
  }
  return out;
}

