  final s = Store.I;
  final fee = s.feeStatusOf(student['id'].toString(), ym);
  final history = s.feePaymentsFor(student['id'].toString(), ym);
  return Panel(
    child: Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        SectionTitle(T('Fees')),
        SizedBox(height: 9),
        Row(
          children: [
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    monthLabel(ym),
                    style: TextStyle(
                      fontSize: 11.5,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                  SizedBox(height: 3),
                  Text(
                    fee.paid
                        ? 'Marked paid on ${fmtDate(history.isEmpty ? '' : history.first['date'].toString())}'
                        : T(
                            'Not paid yet — the office will mark it when received.',
                          ),
                    style: TextStyle(
                      fontSize: 9,
                      color: context.faint,
                      height: 1.35,
                    ),
                  ),
                ],
              ),
            ),
