//  ---------------------------------------------------------------------------
//  ATTENDANCE TREND — the card the attendance screens share: the running
//  percentage from the semester start to today, the target it is measured
//  against, and how many lectures the student can still miss (or needs) to
//  land on that target.
//  ---------------------------------------------------------------------------
({String type, int count})? attendanceBuffer(
  int present,
  int total,
  int target,
) {
  if (total <= 0) return null;
  final t = target.clamp(1, 100);
  if (t >= 100) return (type: 'safe', count: 0);
  if (100 * present >= t * total) {
    final allowed = (100 * present) ~/ t - total;
    return (type: 'safe', count: allowed < 0 ? 0 : allowed);
  }
  final needed = ((t * total - 100 * present) / (100 - t) - 0.0000001).ceil();
  return (type: 'needed', count: needed < 0 ? 0 : needed);
}

/// Day by day, week by week or month by month, each point is the running
/// attendance up to that bucket, the way the chart reads.
List<({String date, int value})> attendanceTrendPoints(
  List<Map<String, dynamic>> recs,
  String grain,
) {
  final s = Store.I;
  if (recs.isEmpty) return const [];
  final rows = [...recs]
    ..sort((a, b) => '${a['date']}'.compareTo('${b['date']}'));
  final buckets = <String, List<Map<String, dynamic>>>{};
  for (final r in rows) {
    final d = parseDay(r['date'].toString());
    final String key;
    if (grain == 'monthly') {
      key = '${d.year}-${two(d.month)}';
    } else if (grain == 'weekly') {
      key = todayStr(d.subtract(Duration(days: d.weekday - 1)));
    } else {
      key = todayStr(d);
    }
    buckets.putIfAbsent(key, () => <Map<String, dynamic>>[]).add(r);
  }
  final keys = buckets.keys.toList()..sort();
  final points = <({String date, int value})>[];
  final running = <Map<String, dynamic>>[];
  for (final k in keys) {
    final inBucket = buckets[k]!;
    running.addAll(inBucket);
    final pct = s.pctOf(s.statsOf(running)) ?? 0;
    final last = inBucket
        .map((r) => parseDay(r['date'].toString()))
        .reduce((a, b) => a.isAfter(b) ? a : b);
    points.add((
      date: '${two(last.day)} ${kMonthShort[last.month - 1]}',
      value: pct,
    ));
  }
  //  daily runs can be long: keep the whole span but thin the points out,
  //  so the axis still starts at the semester and ends today
  final cap = grain == 'daily' ? 12 : 8;
  if (points.length <= cap) return points;
  final out = <({String date, int value})>[];
  for (var i = 0; i < cap; i++) {
    final idx = (i * (points.length - 1) / (cap - 1)).round();
    out.add(points[idx]);
  }
  return out;
}

class AttendanceTrendCard extends StatefulWidget {
  const AttendanceTrendCard({
    super.key,
    required this.records,
    required this.target,
  });

  final List<Map<String, dynamic>> records;
  final int target;

  @override
  State<AttendanceTrendCard> createState() => _AttendanceTrendCardState();
}

class _AttendanceTrendCardState extends State<AttendanceTrendCard> {
  String _grain = 'daily';

  @override
  Widget build(BuildContext context) {
    final stats = Store.I.statsOf(widget.records);
    final buffer = attendanceBuffer(stats.present, stats.total, widget.target);
    final safe = buffer == null || buffer.type == 'safe';
    final tone = buffer == null ? Skin.gold : (safe ? Skin.green : Skin.red);

    return Panel(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          SectionTitle(T('Attendance Trend')),
          SizedBox(height: 2),
          Text(
            T('From semester start to today'),
            style: TextStyle(fontSize: 9.5, color: context.soft),
          ),
          SizedBox(height: 9),
          Row(
            children: [
              Chip8(
                '${widget.target}%',
                color: Skin.gold,
                icon: Icons.flag_outlined,
              ),
              Spacer(),
              _grainPicker(context),
            ],
          ),
          SizedBox(height: 8),
          TrendChart(
            points: attendanceTrendPoints(widget.records, _grain),
            target: widget.target,
            height: 142,
            divisions: 4,
          ),
          SizedBox(height: 9),
          Container(
            padding: EdgeInsets.symmetric(horizontal: 10, vertical: 8),
            decoration: BoxDecoration(
              color: tone.withValues(alpha: .10),
              borderRadius: BorderRadius.circular(9),
            ),
            child: Row(
              children: [
                Icon(
                  safe ? Icons.check : Icons.priority_high,
                  size: 13,
                  color: tone,
                ),
                SizedBox(width: 7),
                Expanded(
                  child: Text(
                    buffer == null
                        ? T('No classes recorded yet.')
                        : (safe
                              ? TT(
                                  buffer.count == 1
                                      ? '{0} more lecture you can miss and stay above {1}%'
                                      : '{0} more lectures you can miss and stay above {1}%',
                                  [buffer.count, widget.target],
                                )
                              : TT(
                                  buffer.count == 1
                                      ? '{0} more lecture needed to reach {1}%'
                                      : '{0} more lectures needed to reach {1}%',
                                  [buffer.count, widget.target],
                                )),
                    style: TextStyle(
                      fontSize: 9.6,
                      height: 1.35,
                      color: context.soft,
                    ),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _grainPicker(BuildContext context) => Container(
    padding: EdgeInsets.symmetric(horizontal: 8),
    decoration: BoxDecoration(
      color: context.panel2,
      borderRadius: BorderRadius.circular(9),
      border: Border.all(color: context.line),
    ),
    child: DropdownButtonHideUnderline(
      child: DropdownButton<String>(
        value: _grain,
        isDense: true,
        padding: EdgeInsets.symmetric(vertical: 6),
        style: TextStyle(
          fontSize: 10,
          fontWeight: FontWeight.w700,
          color: context.ink,
        ),
        icon: Icon(Icons.keyboard_arrow_down, size: 15, color: context.faint),
        items: [
          DropdownMenuItem(value: 'daily', child: Text(T('Daily'))),
          DropdownMenuItem(value: 'weekly', child: Text(T('Weekly'))),
          DropdownMenuItem(value: 'monthly', child: Text(T('Monthly'))),
        ],
        onChanged: (v) => setState(() => _grain = v ?? 'daily'),
      ),
    ),
  );
}

