/// Today's birthdays as circles with the name written under each one. The
/// list is scoped by role in [birthdaysTodayFor], so the classroom side never
/// sees staff birthdays and the staff register never sees the classroom's.
class BirthdayCircles extends StatelessWidget {
  const BirthdayCircles({super.key, required this.role});

  /// the viewer's role: student, teacher, staff or admin
  final String role;

  @override
  Widget build(BuildContext context) {
    final people = birthdaysTodayFor(role);
    if (people.isEmpty) return const SizedBox.shrink();
    final k = context.k;
    return Panel(
      border: Skin.gold,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: <Widget>[
              Expanded(child: SectionTitle(T('Birthdays today'))),
              const Text('🎂', style: TextStyle(fontSize: 15)),
            ],
          ),
          Wrap(
            spacing: 12,
            runSpacing: 12,
            children: <Widget>[for (final p in people) _face(context, p)],
          ),
          const SizedBox(height: 10),
          Text(
            T('Wish them a happy birthday today.'),
            style: TextStyle(fontSize: 10.5, height: 1.4, color: k.faint),
          ),
        ],
      ),
    );
  }

  Widget _face(BuildContext context, Map<String, dynamic> p) {
    final k = context.k;
    final name = p['name'].toString();
    final photo = p['photo'].toString();
    final label = switch (p['as']) {
      'student' => T('Student'),
      'teacher' => T('Teacher'),
      _ => T('Staff'),
    };
    return SizedBox(
      width: 74,
      child: Column(
        children: <Widget>[
          Container(
            width: 54,
            height: 54,
            clipBehavior: Clip.antiAlias,
            alignment: Alignment.center,
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              color: k.surface2,
              border: Border.all(color: Skin.gold, width: 2),
            ),
            child: _faceImage(context, name, photo, 54),
          ),
          const SizedBox(height: 5),
          Text(
            name,
            textAlign: TextAlign.center,
            maxLines: 2,
            overflow: TextOverflow.ellipsis,
            style: TextStyle(
              fontSize: 10.5,
              height: 1.2,
              fontWeight: FontWeight.w700,
              color: k.ink,
            ),
          ),
          Text(
            label,
            textAlign: TextAlign.center,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: TextStyle(
              fontSize: 8.5,
              letterSpacing: .3,
              fontWeight: FontWeight.w700,
              color: k.faint,
            ),
          ),
        ],
      ),
    );
  }

  /// A stored display picture when there is one (data URL or link), otherwise
  /// the person's initials.
  Widget _faceImage(
    BuildContext context,
    String name,
    String photo,
    double size,
  ) {
    final initials = Text(
      Avatar.initials(name),
      style: TextStyle(
        fontSize: size * .34,
        fontWeight: FontWeight.w800,
        color: context.k.ink,
      ),
    );
    final comma = photo.indexOf(',');
    if (photo.startsWith('data:image') && comma > 0) {
      try {
        final bytes = base64Decode(photo.substring(comma + 1));
        return Image.memory(
          bytes,
          width: size,
          height: size,
          fit: BoxFit.cover,
          errorBuilder: (_, _, _) => initials,
        );
      } catch (_) {
        return initials;
      }
    }
    if (photo.startsWith('http')) {
      return Image.network(
        photo,
        width: size,
        height: size,
        fit: BoxFit.cover,
        errorBuilder: (_, _, _) => initials,
      );
    }
    return initials;
  }
}

//  ---------------------------------------------------------------------------
//  ID CARD — a two-sided institute pass. Everything is read live from the
//  office records on every build, so an admin changing a batch, standard or
//  ID number shows up here by itself. Tap the card to turn it over.
//  ---------------------------------------------------------------------------
class IdCardPage extends StatefulWidget {
  const IdCardPage({super.key, required this.user, this.student});

  final Map<String, dynamic> user;

  /// A guardian opens the card for their child, so the student record comes in
  /// with the login. When it is set the card prints the child's details.
  final Map<String, dynamic>? student;

  @override
  State<IdCardPage> createState() => _IdCardPageState();
}

class _IdCardPageState extends State<IdCardPage> with TickerProviderStateMixin {
  Store get s => Store.I;

  bool _back = false;

  late final AnimationController _intro;
  late final AnimationController _sheen;

  @override
  void initState() {
    super.initState();
    _intro = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: 1150),
    )..forward();
    _sheen = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: 3200),
    )..repeat();
  }

  @override
  void dispose() {
    _intro.dispose();
    _sheen.dispose();
    super.dispose();
  }

  String get _uid => widget.user['id'].toString();

  String get _role => (widget.user['role'] ?? 'staff').toString();

  bool get _isStudent => widget.student != null || _role == 'student';

  bool get _isTeacher => _role == 'teacher';

  /// staff and teachers hold their own employment details, students come from
  /// the student register — in both cases the live record, never the login copy
  Map<String, dynamic> get _person {
    final linked = widget.student;
    if (linked != null) return linked;
    if (_role == 'student') return s.studentOfUser(_uid) ?? widget.user;
    for (final u in s.users) {
      if (u['id'].toString() == _uid) return u;
    }
    return widget.user;
  }

  String _tidy(Object? raw) {
    final t = (raw ?? '').toString().trim();
    return t.isEmpty ? T('Not set') : t;
  }

  /// 2008-02-14 → 14.02.2008, the way a printed card reads
  String _date(Object? raw) {
    final t = (raw ?? '').toString().trim();
    final m = RegExp(r'^(\d{4})-(\d{2})-(\d{2})$').firstMatch(t);
    if (m == null) return t.isEmpty ? T('Not set') : t;
    return '${m[3]}.${m[2]}.${m[1]}';
  }

  /// the card runs to the end of the session unless the office sets a date
  String get _expire {
    final raw = (_person['expire'] ?? '').toString().trim();
    if (raw.isNotEmpty) return _date(raw);
    final now = DateTime.now();
    final y = now.month >= 4 ? now.year + 1 : now.year;
    return '31.03.$y';
  }

  String get _roleLine {
    final p = _person;
    if (_isStudent) {
      final std = (p['standard'] ?? '').toString().trim();
      final batch = s.batchName(p['batchId']);
      if (batch.isEmpty && std.isEmpty) return T('Student').toString();
      if (batch.isEmpty) return std;
      if (std.isEmpty || batch.toLowerCase().contains(std.toLowerCase())) {
        return batch;
      }
      return '$std · $batch';
    }
    final designation = (p['designation'] ?? '').toString().trim();
    if (designation.isNotEmpty) return designation;
    if (_isTeacher) return T('Teacher');
    if (_role == 'admin') return T('Administrator');
    return T('Staff member');
  }

  String get _shift {
    final p = _person;
    final start = (p['shift'] ?? '').toString().trim();
    final end = (p['shiftEnd'] ?? '').toString().trim();
    if (start.isEmpty) return '';
    return end.isEmpty ? start : '$start – $end';
  }

  String get _blood {
    final t = (_person['blood'] ?? '').toString().trim();
    return t.isEmpty ? '—' : t;
  }

  /// The birthday, read from whichever key holds it — students keep it in
  /// `dob`, staff and teachers in `birthday` — printed as `07.11.2026`.
  String _bdayOf(Map<String, dynamic> person) {
    final String raw = bdayOf(person);
    if (raw.isEmpty) return T('Not set');
    final String card = bdayCardDate(raw);
    return card.isEmpty ? raw : card;
  }

  /// the two columns printed on the front
  List<List<String>> get _frontCells {
    final p = _person;
    if (_isStudent) {
      return [
        [T('Blood group'), _blood],
        [T('Dob'), _bdayOf(p), 'm'],
        [T('Phone'), _tidy(p['phone']), 'm'],
        [T('Email'), _tidy(p['email'])],
        [T('Valid till'), _expire, 'm'],
      ];
    }
    return [
      [T('Blood group'), _blood],
      // staff, teachers and the admin keep the date on their login profile
      [T('Birthday'), _bdayOf(p), 'm'],
      [T('Phone'), _tidy(p['phone']), 'm'],
      [T('Email'), _tidy(p['email'])],
      [T('Shift'), _tidy(_shift), 'm'],
    ];
  }

  /// the details printed on the back
  List<List<String>> get _backCells {
    final p = _person;
    if (_isStudent) {
      return [
        [T('Standard'), _tidy(p['standard'])],
        [T('Batch'), _tidy(s.batchName(p['batchId']))],
        [T('Course'), _tidy(p['course'])],
        [T('Guardian'), _tidy(p['guardianName'])],
        [T('Guardian contact'), _tidy(p['guardianContact']), 'm'],
        [T('Joined'), _date(p['joined']), 'm'],
        [T('Valid till'), _expire, 'm'],
      ];
    }
    return [
      [T('Designation'), _roleLine],
      [T('Joined'), _date(p['joined']), 'm'],
      [T('Blood group'), _blood],
    ];
  }

  @override
  Widget build(BuildContext context) {
    final p = _person;
    final name = (p['name'] ?? widget.user['name'] ?? '').toString();

    return ListView(
      padding: EdgeInsets.fromLTRB(14, 14, 14, 24),
      children: [
        PageHeading(
          T('ID Card'),
          TT("{0} · {1}", [name, T('shows your live office details')]),
          Icons.badge_outlined,
        ),
        SizedBox(height: 12),
        AnimatedBuilder(
          animation: _intro,
          builder: (context, inner) {
            final t = Curves.easeOutCubic.transform(_intro.value);
            return Opacity(
              opacity: t.clamp(0, 1),
              child: Transform.translate(
                offset: Offset(0, (1 - t) * 26),
                child: Transform.scale(scale: .93 + .07 * t, child: inner),
              ),
            );
          },
          child: GestureDetector(
            key: const Key('cardSlot'),
            onTap: () => setState(() => _back = !_back),
            child: _isTeacher
                ? _facultyIntro(
                    TweenAnimationBuilder<double>(
                      tween: Tween<double>(begin: 0, end: _back ? 1 : 0),
                      duration: Duration(milliseconds: 360),
                      curve: Curves.easeInOutCubic,
                      builder: (ctx, t, _) {
                        final angle = t * 3.1415926;
                        final back = angle > 1.5707963;
                        final card = _isTeacher
                            ? (back
                                  ? _facultyBack(ctx, name, p)
                                  : _facultyFront(ctx, name, p))
                            : (back
                                  ? (_isStudent
                                        ? _collegeBack(ctx, name, p)
                                        : _cardBack(ctx, name, p))
                                  : (_isStudent
                                        ? _collegeFront(ctx, name, p)
                                        : _cardFront(ctx, name, p)));
                        return Transform(
                          alignment: Alignment.center,
                          transform: Matrix4.identity()
                            ..setEntry(3, 2, 0.0012)
                            ..rotateY(angle),
                          child: back
                              ? Transform(
                                  alignment: Alignment.center,
                                  transform: Matrix4.identity()
                                    ..rotateY(3.1415926),
                                  child: card,
                                )
                              : card,
                        );
                      },
                    ),
                  )
                : TweenAnimationBuilder<double>(
                    tween: Tween<double>(begin: 0, end: _back ? 1 : 0),
                    duration: Duration(milliseconds: 360),
                    curve: Curves.easeInOutCubic,
                    builder: (ctx, t, _) {
                      final angle = t * 3.1415926;
                      final back = angle > 1.5707963;
                      final card = back
                          ? (_isStudent
                                ? _collegeBack(ctx, name, p)
                                : _cardBack(ctx, name, p))
                          : (_isStudent
                                ? _collegeFront(ctx, name, p)
                                : _cardFront(ctx, name, p));
                      return Transform(
                        alignment: Alignment.center,
                        transform: Matrix4.identity()
                          ..setEntry(3, 2, 0.0012)
                          ..rotateY(angle),
                        child: back
                            ? Transform(
                                alignment: Alignment.center,
                                transform: Matrix4.identity()
                                  ..rotateY(3.1415926),
                                child: card,
                              )
                            : card,
                      );
                    },
                  ),
          ),
        ),
        SizedBox(height: 9),
        Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Icon(Icons.threesixty, size: 11, color: context.faint),
            SizedBox(width: 4),
            Text(
              _back
                  ? T('Tap to see the front')
                  : T('Tap the card to see the back'),
              style: TextStyle(fontSize: 9.1, color: context.faint),
            ),
          ],
        ),
      ],
    );
  }

  //  ------------------------------- front -----------------------------------
  Widget _cardFront(
