  //  ------------------------ student college card ---------------------------
  //  Students asked for a standing college card: deep blue into pink stock in
  //  portrait, portrait and name up top, and the facts a guard, a lecturer or
  //  a clinic actually asks for printed across it. The back is the same stock,
  //  so the flip reads as one card instead of two designs.
  static const List<Color> _cardStock = [
    Color(0xFF1D3FA8),
    Color(0xFF7B2FBE),
    Color(0xFFD6377E),
  ];

  String _clean(Object? v) => (v ?? '').toString().trim();

  /// the card runs to the end of the session unless the office sets a date
  String get _cardValid {
    final raw = _clean(_person['expire']);
    final d = raw.isEmpty ? null : DateTime.tryParse(raw);
    final now = DateTime.now();
    final end = d ?? DateTime(now.month >= 4 ? now.year + 1 : now.year, 3, 31);
    return '${two(end.day)} ${kMonthShort[end.month - 1]} ${end.year}';
  }

  Widget _collegeCard({required Widget child}) => AspectRatio(
    aspectRatio: 0.66,
    child: Container(
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(20),
