  /// a white barcode that reads as the card number, drawn from the code itself
  Widget _cardBarcode(String code) {
    var v = code.codeUnits.fold<int>(11, (a, b) => (a * 31 + b) & 0x7fffffff);
    final bars = <Widget>[];
    for (var i = 0; i < 52; i++) {
      v = (v * 1103515245 + 12345) & 0x7fffffff;
      bars.add(
        Container(
          width: (v >> 9) % 3 == 0 ? 2.4 : 1.2,
          margin: const EdgeInsets.only(right: 1.7),
          decoration: BoxDecoration(
            color: Colors.white.withValues(alpha: .86),
            borderRadius: BorderRadius.circular(1),
          ),
        ),
      );
    }
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [SizedBox(height: 36, child: Row(children: bars))],
    );
  }

