  //  ------------------------------------------------------------------------
  //  FACULTY CARD — teachers get their own card: midnight blue stock with a
  //  gold foil band, a slowly turning gold arc around the portrait, a sheen
  //  that sweeps the surface, and a staggered entrance every time it opens.
  //  ------------------------------------------------------------------------
  static const _facTop = Color(0xFF16304A);
  static const _facMid = Color(0xFF102438);
  static const _facBottom = Color(0xFF0A1622);
  static const _facGold = Color(0xFFF0B559);
  static const _facInk = Color(0xFFF4EFE2);
  static const _facSoft = Color(0xFFA8B6C4);

  List<String> get _subjectsTaught {
    final out = <String>[];
    for (final a in s.teacherAssignments(_uid)) {
      final n = s.subjectName(a['subjectId']);
      if (n.isNotEmpty && !out.contains(n)) out.add(n);
    }
    return out;
  }

  List<String> get _batchesTaught {
    final out = <String>[];
    for (final a in s.teacherAssignments(_uid)) {
      final n = s.batchName(a['batchId']);
      if (n.isNotEmpty && !out.contains(n)) out.add(n);
    }
    return out;
  }

  String get _lecturesThisWeek {
    final now = DateTime.now();
    final monday = DateTime(
      now.year,
      now.month,
      now.day,
    ).subtract(Duration(days: now.weekday - 1));
    final sunday = monday.add(Duration(days: 6));
    var n = 0;
    for (final x in s.schedules) {
      if (x['teacherId'] != _uid) continue;
      final d = parseDay('${x['date']}');
      if (d.isBefore(monday) || d.isAfter(sunday)) continue;
      n++;
    }
    return '$n';
  }

  /// swings in with a little perspective, like a card being handed over
  Widget _facultyIntro(Widget child) => AnimatedBuilder(
    animation: _intro,
    builder: (ctx, _) {
      final t = Curves.easeOutCubic.transform(_intro.value);
      return Opacity(
        opacity: (t * 1.8).clamp(0.0, 1.0),
        child: Transform(
          alignment: Alignment.center,
          transform: Matrix4.identity()
            ..setEntry(3, 2, 0.0016)
            ..rotateY((1 - t) * -0.55)
            ..rotateX((1 - t) * 0.10)
            ..scaleByDouble(
              0.90 + 0.10 * t,
              0.90 + 0.10 * t,
              0.90 + 0.10 * t,
              1,
            ),
          child: child,
        ),
      );
    },
  );

