  Widget _facultyChips(BuildContext context, List<String> items, int max) {
    if (items.isEmpty) return SizedBox.shrink();
    final shown = items.take(max).toList();
    final more = items.length - shown.length;
    return Wrap(
      spacing: 5,
      runSpacing: 5,
      children: [
        for (final x in shown)
          Container(
            padding: EdgeInsets.symmetric(horizontal: 7, vertical: 3),
            decoration: BoxDecoration(
              color: _facGold.withValues(alpha: .10),
              borderRadius: BorderRadius.circular(20),
              border: Border.all(color: _facGold.withValues(alpha: .35)),
            ),
            child: Text(
              x,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                fontSize: 7.6,
                fontWeight: FontWeight.w700,
                letterSpacing: .3,
                color: _facGold,
              ),
            ),
          ),
        if (more > 0)
          Padding(
            padding: EdgeInsets.only(top: 3),
            child: Text(
              '+$more',
              style: TextStyle(fontSize: 7.6, color: _facSoft),
            ),
          ),
