      LayoutBuilder(
        builder: (ctx, c) {
          final w = (c.maxWidth - 12) / 2;
          //  the cells stagger in with the intro, so they have to rebuild on
          //  every tick — a single build at t=0 paints them all transparent
          return AnimatedBuilder(
            animation: _intro,
            builder: (ctx, _) => Wrap(
              spacing: 12,
              runSpacing: 10,
              children: [
                for (var i = 0; i < cells.length; i++)
                  SizedBox(
                    width: w,
                    child: Opacity(
                      opacity: (_intro.value * 2.4 - i * 0.22).clamp(0.0, 1.0),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Text(
                            cells[i][0].toUpperCase(),
