/// Very fine pinstripes and a faint arc, so the surface reads as printed stock
/// instead of a flat filled box.
class _CardTexture extends CustomPainter {
  _CardTexture({required this.front});

  final bool front;

  @override
  void paint(Canvas canvas, Size size) {
    final light = Paint()
      ..color = Colors.white.withValues(alpha: .028)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1;

    for (var x = -size.height; x < size.width; x += 9) {
      canvas.drawLine(
        Offset(x.toDouble(), size.height),
        Offset(x + size.height, 0),
        light,
      );
    }

    // a soft gold arc sweeping through the lower corner
    final arc = Paint()
      ..shader = LinearGradient(
        colors: [
          Skin.gold.withValues(alpha: .10),
          Skin.gold.withValues(alpha: 0),
        ],
      ).createShader(Rect.fromLTWH(0, 0, size.width, size.height))
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.2;
    canvas.drawArc(
      Rect.fromCircle(
        center: Offset(size.width * .96, size.height * .96),
        radius: size.height * (front ? .62 : .5),
      ),
      3.4,
      2.0,
      false,
      arc,
    );
    canvas.drawArc(
      Rect.fromCircle(
        center: Offset(size.width * .96, size.height * .96),
        radius: size.height * (front ? .74 : .62),
      ),
      3.5,
      1.7,
      false,
      arc,
    );

    // top edge highlight
    canvas.drawLine(
      Offset.zero,
      Offset(size.width, 0),
      Paint()
        ..color = Colors.white.withValues(alpha: .05)
        ..strokeWidth = 1,
    );
  }

  @override
  bool shouldRepaint(_CardTexture old) => old.front != front;
}

class _BarcodePainter extends CustomPainter {
  _BarcodePainter(this.code);

  final String code;

  @override
  void paint(Canvas canvas, Size size) {
    final ink = Paint()..color = const Color(0xFF17170F);
    final pad = 6.0;
    final mid = size.height / 2;

    // a dense deterministic pattern built out of the card number
    final bits = <bool>[];
    var h = 5381;
    for (var round = 0; round < 6; round++) {
      for (final unit in code.codeUnits) {
        h = (h * 33 + unit + round * 7) & 0x7fffffff;
        for (var b = 0; b < 7; b++) {
          bits.add(((h >> b) & 0x3) != 0);
        }
      }
    }

    final usable = size.width - pad * 2 - 10;
    final module = (usable / (bits.length + 4)).clamp(1.25, 2.6);

    var x = pad;
    for (final w in [module * 1.6, module * 1.6]) {
      canvas.drawRect(
        Rect.fromLTWH(x, mid - size.height * .36, w, size.height * .72),
        ink,
      );
      x += w + module;
    }
    x += module;

    for (var i = 0; i < bits.length; i++) {
      final w = (bits[i] ? module * 1.6 : module).roundToDouble();
      final tall = i % 5 != 0;
      final height = size.height * (tall ? .84 : .64);
      if (x + w > size.width - pad - module * 4) break;
      canvas.drawRect(
        Rect.fromLTWH(x.roundToDouble(), mid - height / 2, w, height),
        ink,
      );
      x += w + module;
    }

    x = size.width - pad;
    for (final w in [module * 1.6, module * 1.6]) {
      x -= w;
      canvas.drawRect(
        Rect.fromLTWH(x, mid - size.height * .36, w, size.height * .72),
        ink,
      );
      x -= module;
    }
  }

  @override
  bool shouldRepaint(_BarcodePainter old) => old.code != code;
}

class StudentProfilePage extends StatefulWidget {
  const StudentProfilePage({
    super.key,
    required this.user,
    required this.student,
  });

  final Map<String, dynamic> user;
  final Map<String, dynamic> student;

  @override
  State<StudentProfilePage> createState() => _StudentProfilePageState();
}

class _StudentProfilePageState extends State<StudentProfilePage> {
  bool _editing = false;

  final Map<String, TextEditingController> _c = {};
  String _gender = '';
  String _course = '';
  String _standard = '';
  String _stream = '';
  String _relation = '';

  Store get s => Store.I;
  Map<String, dynamic> get st => widget.student;

  @override
  void initState() {
    super.initState();
    _loadForm();
  }

  @override
  void dispose() {
    for (final c in _c.values) {
      c.dispose();
    }
    super.dispose();
  }

  /// fill the editors from the live record whenever the form opens
  void _loadForm() {
    for (final c in _c.values) {
      c.dispose();
    }
    _c.clear();
    for (final k in const [
      'name',
      'dob',
      'blood',
      'phone',
      'email',
      'address',
      'city',
      'birthplace',
      'guardianName',
      'guardianContact',
    ]) {
      _c[k] = TextEditingController(text: _val(k));
    }
    _gender = _norm(_val('gender'), const ['male', 'female', 'other']);
    _course = _val('course');
    _standard = _val('standard');
    _stream = _val('streamSubject');
    _relation = _val('guardianRelation');
  }

  String _val(String key) => (st[key] ?? '').toString().trim();

  String _norm(String raw, List<String> allowed) {
    final v = raw.trim();
    if (v.isEmpty) return '';
    final hit = allowed.firstWhere(
      (a) => a.toLowerCase() == v.toLowerCase(),
      orElse: () => '',
    );
    return hit.isEmpty ? allowed.last : hit;
  }

  /// date of birth, gender, blood group and place of birth are entered once;
  /// after that the office owns them
  bool _locked(String key) => _val(key).isNotEmpty;

  String _genderLabel(String raw) {
    switch (raw.trim().toLowerCase()) {
      case 'male':
      case 'm':
        return T('Male');
      case 'female':
      case 'f':
        return T('Female');
      case 'other':
        return T('Other');
      default:
        return '—';
    }
  }

  String get _dobLine {
    final raw = _val('dob');
    if (raw.isEmpty) return '—';
    //  an older record may hold a hand-typed date: show it untouched rather
    //  than pretending it is today
    final d = DateTime.tryParse(raw);
    if (d == null || d.year <= 1900) return raw;
    final now = DateTime.now();
    var age = now.year - d.year;
    if (now.month < d.month || (now.month == d.month && now.day < d.day)) age--;
    final years = age <= 0 ? '' : ' (${TT("{0} yrs old", [age])})';
    return '${fmtDate(raw)}$years';
  }

  List<Map<String, dynamic>> get _extras {
    final raw = st['extraGuardians'];
    if (raw is! List) return <Map<String, dynamic>>[];
    return raw
        .whereType<Map>()
        .map((e) => Map<String, dynamic>.from(e))
        .toList();
  }

  Future<void> _addGuardianToList() async {
    final res = await showDialog<Map<String, String>>(
      context: context,
      builder: (_) => _AddGuardianDialog(),
    );
    if (res == null) return;
    st['extraGuardians'] = [..._extras, res];
    Store.I.save();
    if (mounted) setState(() {});
  }

  void _removeGuardian(int index) {
    final list = [..._extras];
    if (index < 0 || index >= list.length) return;
    list.removeAt(index);
    st['extraGuardians'] = list;
    Store.I.save();
    setState(() {});
  }

  // ---------------------------------------------------------------- read view
  @override
  Widget build(BuildContext context) =>
      _editing ? _editView(context) : _readView(context);

  Widget _readView(BuildContext context) {
    final batch = s.batchName(st['batchId']);
    final recs = s.studentRecords(st['id'].toString());
    final stats = s.statsOf(recs);
    final pct = s.pctOf(stats);
    final subjects = studentSubjects(s, st);
    final extras = _extras;
    final course = _val('course');
    final standard = _val('standard');

    return ListView(
      padding: EdgeInsets.fromLTRB(14, 14, 14, 24),
      children: [
        PageHeading(
          'My Profile',
          TT("{0} · keep your details up to date", [batch]),
          Icons.person_outline,
        ),
        SizedBox(height: 11),
        Panel(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  PersonAvatar(
                    name: st['name'].toString(),
                    photo: s.photoOf(st),
                    radius: 25,
                    onTap: () => chooseDisplayPicture(context, st),
                  ),
                  SizedBox(width: 11),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          st['name'].toString(),
                          style: TextStyle(
                            fontSize: 13,
                            fontWeight: FontWeight.w800,
                            color: context.ink,
                          ),
                        ),
                        SizedBox(height: 3),
                        Text(
                          [
                            batch,
                            standard,
                            course,
                          ].where((x) => x.trim().isNotEmpty).join(' · '),
                          style: TextStyle(
                            fontSize: 9,
                            height: 1.45,
                            color: context.faint,
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
              SizedBox(height: 11),
              Row(
                children: [
                  Container(
                    padding: EdgeInsets.symmetric(horizontal: 10, vertical: 6),
                    decoration: BoxDecoration(
                      color: Skin.green.withValues(alpha: .16),
                      borderRadius: BorderRadius.circular(999),
                    ),
                    child: Row(
                      children: [
                        Icon(
                          Icons.event_available,
                          size: 12,
                          color: Skin.green,
                        ),
                        SizedBox(width: 5),
                        Text(
                          TT("{0}% attendance", [pct ?? 0]),
                          style: TextStyle(
                            fontSize: 10.5,
                            fontWeight: FontWeight.w700,
                            color: Skin.green,
                          ),
                        ),
                      ],
                    ),
                  ),
                  Spacer(),
                  FilledButton.icon(
                    onPressed: () => setState(() {
                      _loadForm();
                      _editing = true;
                    }),
                    style: FilledButton.styleFrom(
                      backgroundColor: Skin.gold,
                      foregroundColor: Color(0xFF201C14),
                      minimumSize: Size(0, 34),
                      padding: EdgeInsets.symmetric(horizontal: 12),
                    ),
                    icon: Icon(Icons.edit_outlined, size: 14),
                    label: Text(
                      T('Edit details'),
                      style: TextStyle(fontSize: 11),
                    ),
                  ),
                ],
              ),
            ],
          ),
        ),
        SizedBox(height: 10),
        _detailCard(context, T('Personal details'), [
          ['DATE OF BIRTH', _dobLine],
          [
            'PLACE OF BIRTH',
            _val('birthplace').isEmpty ? '—' : _val('birthplace'),
          ],
          ['GENDER', _genderLabel(_val('gender'))],
          ['BLOOD GROUP', _val('blood').isEmpty ? '—' : _val('blood')],
          ['PHONE NUMBER', _val('phone').isEmpty ? '—' : _val('phone')],
          ['EMAIL', _val('email').isEmpty ? '—' : _val('email')],
          [
            'ADDRESS (WHERE YOU LIVE)',
            _val('address').isEmpty ? '—' : _val('address'),
          ],
          ['CITY', _val('city').isEmpty ? '—' : _val('city')],
        ]),
        SizedBox(height: 10),
        _detailCard(
          context,
          T('Academic details'),
          [
            ['COURSE', course.isEmpty ? '—' : course],
            ['STANDARD', standard.isEmpty ? '—' : standard],
            [
              'SCIENCE STREAM SUBJECT',
              _val('streamSubject').isEmpty ? '—' : _val('streamSubject'),
            ],
            ['BATCH', batch.isEmpty ? '—' : batch],
          ],
          after: [
            Divider(height: 18),
            Text(
              TT("STUDYING THIS YEAR · {0}", [course.toUpperCase()]),
              style: TextStyle(
                fontSize: 8.5,
                fontWeight: FontWeight.w800,
                letterSpacing: 1.2,
                color: context.faint,
              ),
            ),
            SizedBox(height: 7),
            if (subjects.isEmpty)
              Text(
                T('No subjects assigned to your batch yet.'),
                style: TextStyle(fontSize: 9.5, color: context.soft),
              )
            else
              Wrap(
                spacing: 6,
                runSpacing: 6,
                children: [
                  for (final sub in subjects)
                    Chip8(sub['name'].toString(), color: Skin.violet),
                ],
              ),
            SizedBox(height: 11),
            Row(
              children: [
                Expanded(
                  child: _miniStat(
                    context,
                    T('LECTURES ATTENDED'),
                    TT("{0} / {1}", [stats.present, stats.total]),
                  ),
                ),
                SizedBox(width: 9),
                Expanded(
                  child: _miniStat(
                    context,
                    T('OVERALL ATTENDANCE'),
                    TT("{0}%", [pct ?? 0]),
                  ),
                ),
              ],
            ),
          ],
        ),
        SizedBox(height: 10),
        _detailCard(context, T('Guardian details'), [
          [
            'GUARDIAN NAME',
            _val('guardianName').isEmpty ? '—' : _val('guardianName'),
          ],
          [
            'RELATION',
            _val('guardianRelation').isEmpty ? '—' : _val('guardianRelation'),
          ],
          [
            'GUARDIAN CONTACT',
            _val('guardianContact').isEmpty ? '—' : _val('guardianContact'),
          ],
          for (final g in extras)
            [
              (g['relation'] ?? '').toString().trim().isEmpty
                  ? T('ADDITIONAL GUARDIAN')
                  : (g['relation'] ?? '').toString().trim().toUpperCase(),
              [
                (g['name'] ?? '').toString(),
                (g['contact'] ?? '').toString(),
              ].where((x) => x.trim().isNotEmpty).join(' · '),
            ],
        ]),
      ],
    );
  }

  Widget _detailCard(
    BuildContext context,
    String title,
    List<List<String>> rows, {
    List<Widget> after = const [],
  }) => Panel(
    child: Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        SectionTitle(title),
        SizedBox(height: 9),
        for (final r in rows) _detailRow(context, r[0], r[1]),
