/// academic year of a date, June to May, written the way the office writes it
String academicYearOf(DateTime now) {
  final start = now.month >= 6 ? now.year : now.year - 1;
  return '$start-${two((start + 2) % 100)}';
}

/// The academic year a standard's batch belongs to. A 12th std batch is
/// labelled with the year it joined (its 11th), which is how the office files
/// a passing-out batch — `2025-27` for the batch admitted in 2025.
String academicYearLabelFor(String standard) {
  final now = DateTime.now();
  var start = now.month >= 6 ? now.year : now.year - 1;
  final v = standard.trim().toLowerCase();
  if (v == '12th' || v == '12' || v == 'xii') start = start - 1;
  return '$start-${two((start + 2) % 100)}';
}

/// whether a record's date falls inside one of the four period picks
bool dayInPeriod(String iso, String period) {
  final d = parseDay(iso);
  final now = DateTime.now();
  final today = DateTime(now.year, now.month, now.day);
  final day = DateTime(d.year, d.month, d.day);
  switch (period) {
    case 'week':
      final monday = today.subtract(Duration(days: today.weekday - 1));
      return !day.isBefore(monday) && !day.isAfter(today);
    case 'month':
      return d.year == now.year && d.month == now.month;
    case 'year':
      return d.year == now.year;
    default:
      return true;
  }
}

String periodWord(String period) {
  switch (period) {
    case 'week':
      return Store.I.t('this week');
    case 'month':
      return Store.I.t('this month');
    case 'year':
      return Store.I.t('this year');
    default:
      return Store.I.t('overall');
  }
}

/// the website writes 12th as "12th" — a student counts as 12th std for the
/// previous-year storage whether the column says 12th, 12 or XII
bool isTwelfth(Map<String, dynamic> st) {
  final v = (st['standard'] ?? '').toString().trim().toLowerCase();
  return v == '12th' || v == '12' || v == 'xii';
}

