/// one student being typed in — the same boxes the website shows, in the same
/// order, so an office clerk goes down the list the way they always have
class _StudentDraft {
  _StudentDraft([Map<String, dynamic>? from]) {
    final f = from;
    if (f != null) {
      name.text = (f['name'] ?? '').toString();
      birth.text = (f['dob'] ?? '').toString();
      birthplace.text = (f['birthplace'] ?? '').toString();
      blood.text = (f['bloodGroup'] ?? '').toString();
      phone.text = (f['phone'] ?? '').toString();
      email.text = (f['email'] ?? '').toString();
      address.text = (f['address'] ?? '').toString();
      city.text = (f['city'] ?? '').toString();
      guardian.text = (f['guardianName'] ?? '').toString();
      contact.text = (f['guardianContact'] ?? '').toString();
      course = (f['course'] ?? '').toString();
      scienceGroup = (f['scienceGroup'] ?? '').toString();
      relation = (f['guardianRelation'] ?? '').toString();
      gender = (f['gender'] ?? '').toString();
      standard = (f['standard'] ?? '').toString();
      batchId = (f['batchId'] ?? '').toString();
      final ex = f['additionalGuardians'];
      if (ex is List) {
        for (final e in ex) {
          if (e is Map) {
            extra.add(
              _ExtraGuardian(
                name: (e['name'] ?? '').toString(),
                relation: (e['relation'] ?? '').toString(),
                contact: (e['contact'] ?? '').toString(),
              ),
            );
          }
        }
      }
    }
  }

  final TextEditingController name = TextEditingController();
  final TextEditingController birth = TextEditingController();
  final TextEditingController birthplace = TextEditingController();
  final TextEditingController blood = TextEditingController();
  final TextEditingController phone = TextEditingController();
  final TextEditingController email = TextEditingController();
  final TextEditingController address = TextEditingController();
  final TextEditingController city = TextEditingController();
  final TextEditingController guardian = TextEditingController();
  final TextEditingController contact = TextEditingController();

  String course = '';
  String scienceGroup = '';
  String relation = '';
  String gender = '';
  String standard = '';
  String batchId = '';
  final List<_ExtraGuardian> extra = <_ExtraGuardian>[];

  void dispose() {
    for (final c in <TextEditingController>[
      name,
      birth,
      birthplace,
      blood,
      phone,
      email,
      address,
      city,
      guardian,
      contact,
    ]) {
      c.dispose();
    }
    for (final e in extra) {
      e.dispose();
    }
  }

  /// what the office typed, in the column names the website already uses
  Map<String, dynamic> read() => <String, dynamic>{
    'name': name.text.trim(),
    'dob': birth.text.trim(),
    'birthplace': birthplace.text.trim(),
    'gender': gender,
    'bloodGroup': blood.text.trim(),
    'phone': phone.text.trim(),
    'email': email.text.trim(),
    'address': address.text.trim(),
    'city': city.text.trim(),
    'standard': standard,
    'course': course,
    'scienceGroup': course == 'Science' ? scienceGroup : '',
    'guardianName': guardian.text.trim(),
    'guardianRelation': relation,
    'guardianContact': contact.text.trim(),
    'additionalGuardians': <Map<String, String>>[
      for (final e in extra)
        if (e.name.text.trim().isNotEmpty || e.contact.text.trim().isNotEmpty)
          <String, String>{
            'name': e.name.text.trim(),
            'relation': e.relation.text.trim(),
            'contact': e.contact.text.trim(),
          },
    ],
    'batchId': batchId,
  };

  /// a valid date of birth, or null when it cannot be read
  DateTime? get birthday => DateTime.tryParse(birth.text.trim());

  bool get looksComplete =>
      name.text.trim().isNotEmpty &&
      contact.text.trim().isNotEmpty &&
      course.isNotEmpty &&
      birthday != null;
}

