  @override
  void dispose() {
    _search.dispose();
    super.dispose();
  }

  List<Map<String, dynamic>> get _shown {
    final q = _query.trim().toLowerCase();
    return s.students.where((st) {
      if (q.isEmpty) return true;
      final hay = <String>[
        st['name'].toString(),
        (st['guardianName'] ?? '').toString(),
        (st['guardianContact'] ?? '').toString(),
        (st['standard'] ?? '').toString(),
        (st['course'] ?? '').toString(),
        s.batchName(st['batchId']),
      ].join(' ').toLowerCase();
      return q.split(RegExp(r'\s+')).every(hay.contains);
    }).toList();
