  List<Widget> _summaryCard() {
    final base = _sumBase();
    final rows = base.where((st) {
      return s.attendance.any(
        (r) =>
            r['studentId'] == st['id'] &&
            dayInPeriod(r['date'].toString(), _sumPeriod) &&
            (_attFilter == 'both' || r['status'].toString() == _attFilter),
      );
    }).toList();

    final scope = s.studentById(_attStudent);
    final grouped = scope == null && _sumBatch.isEmpty && _sumGroup;

    return <Widget>[
      Panel(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: <Widget>[
            Row(
              children: <Widget>[
                Expanded(
                  child: SectionTitle(
                    scope != null
                        ? TT('{0} — summary ({1})', <String>[
                            scope['name'].toString(),
                            periodWord(_sumPeriod),
                          ])
                        : TT('Student summary — {0}', <String>[
                            periodWord(_sumPeriod),
                          ]),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 6),
            SizedBox(
              width: double.infinity,
              child: FilledButton(
                onPressed: _exportSummary,
                child: Text(T('Export to Excel')),
              ),
            ),
            const SizedBox(height: 10),
            _studentField(
              label: T('Particular student'),
              value: _attStudent,
              onPick: (v) => setState(() => _attStudent = v),
            ),
            const SizedBox(height: 10),
            _pick(T('Batch'), _sumBatch, <List<String>>[
              <String>['', T('All batches (combined)')],
              for (final c in _courses())
                <String>[
                  'stream:$c',
                  TT('{0} — all batches', <String>[c]),
                ],
              for (final b in s.batches)
                <String>[b['id'].toString(), (b['name'] ?? '').toString()],
            ], (v) => setState(() => _sumBatch = (v ?? '').toString())),
            if (scope == null && _sumBatch.isEmpty) ...<Widget>[
              const SizedBox(height: 10),
              Row(
                children: <Widget>[
                  PickPill(
                    label: T('One list'),
                    active: !_sumGroup,
                    onTap: () => setState(() => _sumGroup = false),
                  ),
                  PickPill(
                    label: T('Batch wise'),
                    active: _sumGroup,
                    onTap: () => setState(() => _sumGroup = true),
                  ),
                ],
              ),
            ],
            const SizedBox(height: 10),
            Row(
              children: <Widget>[
                for (final p in <List<String>>[
                  <String>['week', T('This week')],
                  <String>['month', T('This month')],
                  <String>['year', T('This year')],
                  <String>['all', T('Overall')],
                ])
                  PickPill(
                    label: p[1],
                    active: _sumPeriod == p[0],
                    onTap: () => setState(() => _sumPeriod = p[0]),
                  ),
              ],
            ),
            const SizedBox(height: 10),
            if (rows.isEmpty)
              Text(
                T('No attendance recorded for any student in this period yet.'),
                style: TextStyle(fontSize: 10.5, color: context.k.inkSoft),
              )
            else if (!grouped)
              ..._summaryRows(
                (_sumAll || scope != null) ? rows : rows.take(10).toList(),
                more: (scope == null && rows.length > 10 && !_sumAll)
                    ? TT('View more ({0} more students)', <String>[
                        '${rows.length - 10}',
                      ])
                    : null,
                onMore: () => setState(() => _sumAll = true),
                less: (scope == null && rows.length > 10 && _sumAll)
                    ? T('Show less')
                    : null,
                onLess: () => setState(() => _sumAll = false),
              )
            else
              ..._groupedSummary(rows),
            if (_sumBatchLabel.isNotEmpty)
              Padding(
                padding: const EdgeInsets.only(top: 8),
                child: Text(
                  _sumBatchLabel,
                  style: TextStyle(fontSize: 9.5, color: context.k.faint),
                ),
              ),
          ],
        ),
      ),
    ];
  }

  List<String> _courses() {
    final out = <String>[];
    for (final st in s.students) {
      final c = (st['course'] ?? '').toString().trim();
      if (c.isNotEmpty && !out.contains(c)) out.add(c);
    }
    out.sort();
    return out;
  }

  ({int p, int a, int pc}) _counts(Map<String, dynamic> st) {
    final recs = s.attendance.where(
      (r) =>
          r['studentId'] == st['id'] &&
          dayInPeriod(r['date'].toString(), _sumPeriod) &&
          (_attFilter == 'both' || r['status'].toString() == _attFilter),
    );
    final p = recs.where((r) => r['status'] == 'present').length;
    final total = recs.length;
    return (
      p: p,
      a: total - p,
      pc: total == 0 ? 0 : ((p * 100) / total).round(),
    );
  }

