  List<Widget> _summaryRows(
    List<Map<String, dynamic>> rows, {
    String? more,
    VoidCallback? onMore,
    String? less,
    VoidCallback? onLess,
  }) => <Widget>[
    _summaryHead(),
    for (final st in rows) _summaryRow(st),
    if (more != null)
      Padding(
        padding: const EdgeInsets.only(top: 4),
        child: OutlinedButton(
          onPressed: onMore,
          child: Text(more, style: const TextStyle(fontSize: 10)),
        ),
      ),
    if (less != null)
      Padding(
        padding: const EdgeInsets.only(top: 4),
        child: OutlinedButton(
          onPressed: onLess,
          child: Text(less, style: const TextStyle(fontSize: 10)),
        ),
      ),
  ];

  List<Widget> _groupedSummary(List<Map<String, dynamic>> rows) {
    final out = <Widget>[];
    final groups = <List<Object>>[
      for (final b in s.batches)
        <Object>[
          b['id'].toString(),
          (b['name'] ?? '').toString(),
          rows
              .where(
                (st) => (st['batchId'] ?? '').toString() == b['id'].toString(),
              )
              .toList(),
        ],
      <Object>[
        '__none',
        T('Not yet decided'),
        rows.where((st) => (st['batchId'] ?? '').toString().isEmpty).toList(),
      ],
    ];
    for (final g in groups) {
      final list = g[2] as List<Map<String, dynamic>>;
      if (list.isEmpty) continue;
      final key = g[0].toString();
      var p = 0;
      var a = 0;
      for (final st in list) {
        final c = _counts(st);
        p += c.p;
        a += c.a;
      }
      final pc = (p + a) == 0 ? 0 : ((p * 100) / (p + a)).round();
      final open = _sumMore[key] ?? false;
      out.add(
        Padding(
          padding: const EdgeInsets.only(top: 12, bottom: 6),
          child: Row(
            children: <Widget>[
              Expanded(
                child: Text(
                  g[1].toString(),
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w700,
                    color: context.k.ink,
                  ),
                ),
              ),
              Chip8(
                TT('{0} student(s)', <String>['${list.length}']),
                color: Skin.navy,
              ),
              const SizedBox(width: 4),
              Chip8('P $p', color: Skin.green),
              const SizedBox(width: 4),
              Chip8('A $a', color: Skin.brick),
              const SizedBox(width: 4),
              Chip8('$pc%', color: Skin.gold),
            ],
          ),
        ),
      );
      out.add(_summaryHead());
      for (final st in (open ? list : list.take(10))) {
        out.add(_summaryRow(st));
      }
      if (list.length > 10) {
        out.add(
          Padding(
            padding: const EdgeInsets.only(top: 4),
            child: OutlinedButton(
              onPressed: () => setState(() => _sumMore[key] = !open),
              child: Text(
                open
                    ? T('Show less')
                    : TT('View more ({0} more students)', <String>[
                        '${list.length - 10}',
                      ]),
                style: const TextStyle(fontSize: 10),
              ),
            ),
          ),
        );
      }
    }
    if (out.isEmpty) {
      out.add(
        Text(
          T('No attendance recorded for any student in this period yet.'),
          style: TextStyle(fontSize: 10.5, color: context.k.inkSoft),
        ),
      );
    }
    return out;
  }

