  // ----------------------------- exports -----------------------------
  String _xml(String v) => v
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;');

  /// the sheet the file holds, written the way Excel likes it
  String _xlsBody(_ExportDoc doc) {
    final buf = StringBuffer()
      ..write(
        '<html xmlns:x="urn:schemas-microsoft-com:office:excel"><head><meta charset="UTF-8" />'
        '<style>table{border-collapse:collapse; font-family:Arial} '
        'th{background:#1B2A4A; color:#FFFFFF; padding:8px; border:1px solid #666; font-size:11pt} '
        'td{border:1px solid #999; padding:6px}</style></head><body><table>'
        '<tr><td colspan="${doc.head.length}" style="background:#1B2A4A; color:#FFFFFF; '
        'font-weight:bold; font-size:13pt; text-align:center; padding:10px;">${_xml(doc.title)}</td></tr>'
        '<tr>${doc.head.map((h) => '<th>${_xml(h)}</th>').join()}</tr>',
      );
    for (final r in doc.rows) {
      buf.write('<tr>${r.map((c) => '<td>${_xml(c)}</td>').join()}</tr>');
    }
    buf.write('</table></body></html>');
    return buf.toString();
  }

  /// saves the export where the phone can find it and hands back where it went
  Future<Map<String, dynamic>?> _saveExportFile(_ExportDoc doc) async {
    final name = '${doc.fileName}.xls';
    final bytes = Uint8List.fromList(utf8.encode(_xlsBody(doc)));
    try {
      final out = await _filesChannel.invokeMapMethod<String, dynamic>(
        'save',
        <String, dynamic>{
          'name': name,
          'mime': 'application/vnd.ms-excel',
          'bytes': bytes,
        },
      );
      if (out != null) return out;
    } on MissingPluginException {
      // tests, desktop and the web build have no Android side: fall through
    } catch (_) {
      // fall through too, the app folder beats losing the export
    }
    try {
      final base =
          await getExternalStorageDirectory() ??
          await getApplicationDocumentsDirectory();
      final dir = Directory('${base.path}/JSK Files');
      if (!dir.existsSync()) dir.createSync(recursive: true);
      final file = File('${dir.path}/$name');
      await file.writeAsBytes(bytes, flush: true);
      return <String, dynamic>{'uri': '', 'path': file.path, 'where': dir.path};
    } catch (_) {
      return null;
    }
  }

  /// opens the export in whatever spreadsheet app the phone has
  Future<String> _openExportFile(Map<String, dynamic> out) async {
    final uri = (out['uri'] ?? '').toString();
    final path = (out['path'] ?? '').toString();
    try {
      final r = await _filesChannel.invokeMethod<String>(
        'open',
        <String, dynamic>{
          'uri': uri,
          'path': path,
          'mime': 'application/vnd.ms-excel',
        },
      );
      if (r == 'opened' || r == 'no_app') return r!;
    } on MissingPluginException {
      if (path.isEmpty) return 'failed';
      final r = await OpenFilex.open(path);
      return r.type == ResultType.done ? 'opened' : 'no_app';
    } catch (_) {
      return 'failed';
    }
    return 'failed';
  }

  /// the fallback when nothing on the phone claims .xls: send it somewhere useful
  Future<void> _shareExportFile(
    Map<String, dynamic> out,
    _ExportDoc doc,
  ) async {
    try {
      await _filesChannel.invokeMethod<String>('share', <String, dynamic>{
        'uri': (out['uri'] ?? '').toString(),
        'path': (out['path'] ?? '').toString(),
        'mime': 'application/vnd.ms-excel',
        'subject': '${doc.fileName}.xls',
      });
    } on MissingPluginException {
      await OpenFilex.open((out['path'] ?? '').toString());
    } catch (_) {}
  }

