  Future<void> _writeExcel({
    required String fileName,
    required String title,
    required List<String> head,
    required List<List<String>> rows,
  }) async {
    await _openExportSheet(
      _ExportDoc(fileName: fileName, title: title, head: head, rows: rows),
    );
  }

  Future<void> _exportSummary() async {
    final base = _sumBase().where((st) {
      return s.attendance.any(
        (r) =>
            r['studentId'] == st['id'] &&
            dayInPeriod(r['date'].toString(), _sumPeriod) &&
            (_attFilter == 'both' || r['status'].toString() == _attFilter),
      );
    }).toList();
    if (base.isEmpty) {
      toast(
        context,
        T('No attendance recorded for any student in this period yet.'),
      );
      return;
    }
    final scope = s.studentById(_attStudent);
    final rows = <List<String>>[];
    var tp = 0;
    var ta = 0;
    for (var i = 0; i < base.length; i++) {
      final c = _counts(base[i]);
      tp += c.p;
      ta += c.a;
      rows.add(<String>[
        '${i + 1}',
        base[i]['name'].toString(),
        s.batchName(base[i]['batchId']),
        (base[i]['standard'] ?? '').toString(),
        (base[i]['course'] ?? '').toString(),
        '${c.p}',
        '${c.a}',
        '${c.pc}%',
      ]);
    }
    final overall = (tp + ta) == 0 ? 0 : ((tp * 100) / (tp + ta)).round();
    await _writeExcel(
      fileName:
          'JSK-Student-Attendance-Summary-${(scope == null ? 'All-Students' : scope['name'].toString().replaceAll(' ', '-'))}',
      title:
          'JSK Institute — Student Attendance Summary (${scope == null ? 'All students' : scope['name']}, ${periodWord(_sumPeriod)})',
      head: <String>[
        '#',
        'Name',
        'Batch',
        'Standard',
        'Course',
        'Present',
        'Absent',
        '%',
      ],
      rows: rows
        ..add(<String>['', 'TOTAL', '', '', '', '$tp', '$ta', '$overall%']),
    );
  }

  Future<void> _exportRecords() async {
    final recs = _recs(_attPeriod, _attFilter, _attStudent);
    if (recs.isEmpty) {
      toast(context, T('No records match these filters.'));
      return;
    }
    final rows = <List<String>>[];
    for (final r in recs) {
      final st = s.studentById(r['studentId']?.toString());
      rows.add(<String>[
        fmtDate(r['date'].toString()),
        st == null ? '' : st['name'].toString(),
        s.batchName(r['batchId']),
        st == null ? '' : (st['standard'] ?? '').toString(),
        st == null ? '' : (st['course'] ?? '').toString(),
        s.subjectName(r['subjectId']),
        r['status'] == 'present' ? 'Present' : 'Absent',
      ]);
    }
    await _writeExcel(
      fileName: 'JSK-Student-Attendance-Records',
      title:
          'JSK Institute — Student Attendance Records (${periodWord(_attPeriod)})',
      head: <String>[
        'Date',
        'Student',
        'Batch',
        'Standard',
        'Course',
        'Subject',
        'Status',
      ],
      rows: rows,
    );
  }

  // =====================================================================
  //  Section three — Previous year Student Data (12th std)
  // =====================================================================
  Map<String, dynamic> get _prevStore {
    final v = s.data['previousYears'];
    if (v is Map) return v.cast<String, dynamic>();
    final fresh = <String, dynamic>{};
    s.data['previousYears'] = fresh;
    return fresh;
  }

  List<String> get _prevYears {
    final now = DateTime.now();
    final start = now.month >= 6 ? now.year : now.year - 1;
    final out = <String>[];
    for (var y = 2025; y <= start; y++) {
      out.add('$y-${two((y + 2) % 100)}');
    }
    for (final k in _prevStore.keys) {
      final stored = _prevStore[k];
      if (stored is List && stored.isNotEmpty && !out.contains(k)) out.add(k);
    }
    out.sort();
    return out;
  }

  List<Map<String, dynamic>> get _prevStored {
    final v = _prevStore[_prevYear];
    if (v is List) {
      return v.whereType<Map>().map((e) => e.cast<String, dynamic>()).toList();
    }
    return <Map<String, dynamic>>[];
  }

  List<Widget> _previousSection() {
    final years = _prevYears;
    if (!years.contains(_prevYear)) {
      _prevYear = years.isEmpty ? _prevYear : years.last;
    }
    final current = academicYearOf(DateTime.now());
    final live = s.students.where(isTwelfth).toList();
    final stored = _prevStored;
    final isStored = stored.isNotEmpty;

    final String status;
    final Color color;
    if (_prevYear == current) {
      status = live.isEmpty
          ? T(
              'Current 12th std academic year — no 12th std students on record yet.',
            )
          : TT(
              'Current 12th std academic year — {0} live student(s); the latest data is exported and stored.',
              <String>['${live.length}'],
            );
      color = context.k.faint;
    } else if (isStored) {
      status = TT(
        'Data available — {0} 12th std student(s) stored for {1}.',
        <String>['${stored.length}', _prevYear],
      );
      color = Skin.green;
    } else {
      status = TT(
        'No data found for {0} — only the years with stored data can be exported.',
        <String>[_prevYear],
      );
      color = Skin.brick;
    }

    return <Widget>[
      Panel(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: <Widget>[
            SectionTitle(T('Previous year Student Data — 12th Std')),
            const SizedBox(height: 6),
            Text(
              T(
                'When a student completes 12th, their whole record is saved here (profile, guardian, subject-wise attendance and months paid) and then removed from the live app. The rollover runs on its own once a year after the finals on 15 June: every 12th std student is filed here and cleared, and the 11th std students move up to 12th. Stored years are only added to — they are never cleared automatically.',
              ),
              style: TextStyle(
                fontSize: 10.5,
                height: 1.35,
                color: context.k.inkSoft,
              ),
            ),
            const SizedBox(height: 12),
            _pick(T('Academic year'), _prevYear, <List<String>>[
              for (final y in years) <String>[y, y],
            ], (v) => setState(() => _prevYear = (v ?? current).toString())),
            const SizedBox(height: 10),
            SizedBox(
              width: double.infinity,
              child: FilledButton(
                onPressed: _exportPreviousYear,
                child: Text(T('Export to Excel')),
              ),
            ),
            const SizedBox(height: 10),
            Text(
              status,
              style: TextStyle(
                fontSize: 10.5,
                fontWeight: FontWeight.w600,
                color: color,
              ),
            ),
            if (isStored && _prevYear != current) ...<Widget>[
              const SizedBox(height: 6),
              GestureDetector(
                onTap: _clearPreviousYear,
                child: Text(
                  T("Clear this year's data"),
                  style: TextStyle(
                    fontSize: 10,
                    color: context.k.faint,
                    decoration: TextDecoration.underline,
                  ),
                ),
              ),
            ],
            if (isStored) ...<Widget>[
              const SizedBox(height: 12),
              for (final r in stored)
                Container(
                  margin: const EdgeInsets.only(bottom: 5),
                  padding: const EdgeInsets.symmetric(
                    horizontal: 8,
                    vertical: 7,
                  ),
                  decoration: BoxDecoration(
                    color: context.k.surface2,
                    borderRadius: BorderRadius.circular(8),
                    border: Border.all(color: context.k.line),
                  ),
                  child: Row(
                    children: <Widget>[
                      Expanded(
                        child: Text(
                          (r['name'] ?? '').toString(),
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                            fontSize: 11,
                            fontWeight: FontWeight.w600,
                            color: context.k.ink,
                          ),
                        ),
                      ),
                      Text(
                        '${(r['batchName'] ?? '').toString().isEmpty ? s.batchName(r['batchId']) : r['batchName']} · ${(r['attPct'] ?? '').toString().isEmpty ? '—' : '${r['attPct']}%'}',
                        style: TextStyle(fontSize: 9.5, color: context.k.faint),
                      ),
                    ],
                  ),
                ),
            ],
          ],
        ),
      ),
    ];
  }

  Future<void> _exportPreviousYear() async {
    final current = academicYearOf(DateTime.now());
    var stored = _prevStored;
    if (stored.isEmpty && _prevYear != current) {
      toast(context, TT('No data found for {0}.', <String>[_prevYear]));
      return;
    }
    if (_prevYear == current) {
      final live = s.students.where(isTwelfth).toList();
      if (live.isEmpty) {
        toast(context, T('No 12th std students on record to export.'));
        return;
      }
      stored = <Map<String, dynamic>>[
        for (final st in live) s.archiveEntryOf(st, _prevYear),
      ];
      setState(() => _prevStore[_prevYear] = stored);
      s.save();
    }
    await _writeExcel(
      fileName: 'JSK-Previous-Year-12th-Std-$_prevYear',
      title:
          'JSK Institute — Previous Year Student Data (12th Std): $_prevYear',
      head: <String>[
        'Name',
        'Batch',
        'Standard',
        'Course',
        'Date of birth',
        'Gender',
        'Blood group',
        'Phone',
        'Email',
        'Address',
        'City',
        'Guardian',
        'Relation',
        'Guardian contact',
        'Subjects',
        'Present',
        'Total lectures',
        'Attendance %',
        'Months paid',
        'Academic year',
        'Saved on',
      ],
      rows: <List<String>>[
        for (final r in stored)
          <String>[
            (r['name'] ?? '').toString(),
            (r['batchName'] ?? '').toString().isEmpty
                ? s.batchName(r['batchId'])
                : r['batchName'].toString(),
            (r['standard'] ?? '').toString(),
            (r['course'] ?? '').toString(),
            (r['dob'] ?? '').toString(),
            (r['gender'] ?? '').toString(),
            (r['bloodGroup'] ?? '').toString(),
            (r['phone'] ?? '').toString(),
            (r['email'] ?? '').toString(),
            (r['address'] ?? '').toString(),
            (r['city'] ?? '').toString(),
            (r['guardianName'] ?? '').toString(),
            (r['guardianRelation'] ?? '').toString(),
            (r['guardianContact'] ?? '').toString(),
            <String>[
              for (final x in (r['subjects'] as List?) ?? const <dynamic>[])
                x.toString(),
            ].join(', '),
            (r['attPresent'] ?? '').toString(),
            (r['attTotal'] ?? '').toString(),
            (r['attPct'] ?? '').toString(),
            <String>[
              for (final x in (r['feesPaid'] as List?) ?? const <dynamic>[])
                monthLabelShort(x.toString()),
            ].where((x) => x.isNotEmpty).join(', '),
            (r['academicYear'] ?? _prevYear).toString(),
            (r['savedOn'] ?? '').toString(),
          ],
      ],
    );
  }

  Future<void> _clearPreviousYear() async {
    final sure = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(
          TT('Clear the stored data for {0}?', <String>[_prevYear]),
          style: const TextStyle(fontSize: 14),
        ),
        content: Text(
          T(
            'This year will then show "No data found" until it is saved again.',
          ),
          style: const TextStyle(fontSize: 12),
        ),
        actions: <Widget>[
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: Text(T('Keep')),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(ctx, true),
            style: FilledButton.styleFrom(backgroundColor: Skin.red),
            child: Text(T('Clear')),
          ),
        ],
      ),
    );
    if (sure != true || !mounted) return;
    setState(() => _prevStore.remove(_prevYear));
    s.save();
    toast(context, TT('Cleared stored data for {0}.', <String>[_prevYear]));
  }
}

class AdminStudentDetailPage extends StatefulWidget {
