    final guardianAccount = s.userById((st['guardianUserId'] ?? '').toString());
    final recs = s.studentRecords(st['id'].toString());
    final stats = s.statsOf(recs);
    final pct = s.pctOf(stats);
    final subjects = studentSubjects(s, st);
