        feeCard(context, st, ymOf(todayStr())),
        SizedBox(height: 10),
        Row(
          children: [
            // only a 12th std student is filed as a passing-out batch
            if (isTwelfth(st)) ...<Widget>[
              Expanded(
                child: OutlinedButton.icon(
                  onPressed: () => _completeTwelfth(st),
                  icon: Icon(Icons.workspace_premium_outlined, size: 14),
                  label: Text(
                    T('Complete 12th'),
                    style: TextStyle(fontSize: 10.5),
                  ),
                ),
              ),
              const SizedBox(width: 8),
            ],
            Expanded(
              child: OutlinedButton.icon(
                onPressed: () => _removeStudent(st),
                icon: Icon(Icons.person_remove_outlined, size: 14),
                label: Text(
                  T('Remove student'),
                  style: TextStyle(fontSize: 10.5),
                ),
                style: OutlinedButton.styleFrom(foregroundColor: Skin.red),
              ),
            ),
          ],
        ),
      ],
    );
  }

  /// Takes a student off the register for good: profile, login, attendance and
  /// fee marks all leave with them, so nothing is left orphaned behind.
  Future<void> _removeStudent(Map<String, dynamic> st) async {
    final sure = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(T('Remove student'), style: TextStyle(fontSize: 15)),
        content: Text(
          TT(
            "Remove {0} from the register? Their profile, login, attendance and fee marks are removed from the app. To file a passing-out student in Previous year Student Data first, use Complete 12th.",
            [st['name']],
          ),
          style: TextStyle(fontSize: 11, color: context.soft),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: Text(T('Keep')),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(ctx, true),
            style: FilledButton.styleFrom(backgroundColor: Skin.red),
            child: Text(T('Remove')),
          ),
        ],
      ),
    );
    if (sure != true || !mounted) return;
    s.purgeStudents(<Map<String, dynamic>>[st]);
    s.viewStudentId = null;
    s.save();
    setState(() {});
    toast(context, TT("{0} removed.", [st['name']]));
  }

  /// Files the student in Previous year Student Data, then clears them from the
  /// live app — the same archive-then-clear the year-end rollover performs, so a
  /// completed 12th std student never simply disappears.
  Future<void> _completeTwelfth(Map<String, dynamic> st) async {
    final year = academicYearLabelFor('12th');
    final nAtt = s.studentRecords(st['id'].toString()).length;
    final sure = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(
          TT('Complete 12th for {0}?', <Object?>[st['name']]),
          style: TextStyle(fontSize: 15),
        ),
        content: Text(
          TT(
            'Their full record ({0} attendance entries, fees, guardian and profile) is saved in Previous year Student Data — {1} — and then removed from the live app: profile, login, attendance and inbox.',
            <Object?>[nAtt, year],
          ),
          style: TextStyle(fontSize: 11, color: context.soft),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: Text(T('Keep')),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: Text(T('Complete')),
          ),
        ],
      ),
    );
    if (sure != true || !mounted) return;
    final done = s.completeStudents(<Map<String, dynamic>>[st], year);
    s.viewStudentId = null;
    s.save();
    setState(() {});
    toast(
      context,
      done > 0
          ? TT(
              '{0} completed — data saved in Previous year Student Data ({1}).',
              <Object?>[st['name'], year],
            )
          : T('Nothing to complete.'),
    );
  }

  Widget _mini(BuildContext context, String value, String label, Color color) =>
      Container(
        padding: EdgeInsets.symmetric(vertical: 8),
        decoration: BoxDecoration(
          color: color.withValues(alpha: .12),
          borderRadius: BorderRadius.circular(9),
        ),
        child: Column(
          children: [
            Text(
              value,
              style: TextStyle(
                fontSize: 14,
                fontWeight: FontWeight.w800,
                color: color,
              ),
            ),
            Text(label, style: TextStyle(fontSize: 8, color: context.soft)),
          ],
        ),
      );

  Widget _kv(BuildContext context, String k, String v) => Padding(
    padding: EdgeInsets.symmetric(vertical: 3),
    child: Row(
      children: [
        SizedBox(
          width: 82,
          child: Text(
            k.toUpperCase(),
            style: TextStyle(
              fontSize: 8,
              letterSpacing: .6,
              color: context.faint,
              fontWeight: FontWeight.w700,
            ),
          ),
        ),
        Expanded(
          child: Text(
            v,
            style: TextStyle(fontSize: 10.5),
            textAlign: TextAlign.right,
          ),
        ),
      ],
    ),
  );

  Future<void> _guardianLogin(
    BuildContext context,
    Map<String, dynamic> st,
  ) async {
    final name = TextEditingController(
      text: (st['guardianName'] ?? '').toString(),
    );
    final email = TextEditingController();
    final pass = TextEditingController(text: T('guardian123'));
    await showDialog<void>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(T('Create guardian login'), style: TextStyle(fontSize: 15)),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Field(label: T('Guardian name'), controller: name),
            Field(
              label: T('Email'),
              controller: email,
              hint: T('guardian@example.com'),
            ),
            Field(label: T('Password'), controller: pass),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx),
            child: Text(T('Cancel')),
          ),
          FilledButton(
            onPressed: () {
              if (email.text.trim().isEmpty) {
                toast(ctx, 'Add an email for the guardian login.');
                return;
              }
              final exists = s.users.any(
                (u) => u['email'] == email.text.trim().toLowerCase(),
              );
              if (exists) {
                toast(ctx, 'That email is already used by another account.');
                return;
              }
              final id = uid('user');
              s.allowLogin(email.text.trim().toLowerCase());
              s.rawList('users').add({
                'id': id,
                'role': 'guardian',
                'name': name.text.trim(),
                'email': email.text.trim().toLowerCase(),
                'password': pass.text,
              });
              st['guardianUserId'] = id;
              st['guardianName'] = name.text.trim();
              s.ntPush(
                userId: id,
                type: 'welcome',
                title: T('Welcome to JSK Institute'),
                message:
                    'Your guardian login is ready. You are monitoring ${st['name']}.',
              );
              s.save();
              Navigator.pop(ctx);
              setState(() {});
              toast(context, T('Guardian login created.'));
            },
            child: Text(T('Create login')),
          ),
        ],
      ),
    );
  }
}

class AdminFeesPage extends StatefulWidget {
  const AdminFeesPage({super.key, required this.user});

  final Map<String, dynamic> user;

  @override
  State<AdminFeesPage> createState() => _AdminFeesPageState();
}

class _AdminFeesPageState extends State<AdminFeesPage> {
  final _search = TextEditingController();
  Store get s => Store.I;

  @override
  void dispose() {
    _search.dispose();
    super.dispose();
  }

  /// The office's own search: name, guardian, batch, standard, course.
  List<Map<String, dynamic>> get _matching {
    final words = _search.text
        .toLowerCase()
        .trim()
        .split(RegExp(r'\s+'))
        .where((w) => w.isNotEmpty)
        .toList();
    final out = <Map<String, dynamic>>[];
    for (final st in s.students) {
      final hay = <String>[
        (st['name'] ?? '').toString(),
        (st['guardianName'] ?? '').toString(),
        (st['guardianContact'] ?? '').toString(),
        s.batchName(st['batchId']),
        (st['standard'] ?? '').toString(),
        (st['course'] ?? '').toString(),
      ].join(' ').toLowerCase();
      if (words.every(hay.contains)) out.add(st);
    }
    out.sort(
      (a, b) =>
          (a['name'] ?? '').toString().compareTo((b['name'] ?? '').toString()),
    );
    return out;
  }

  /// Paid says so to the student and the guardian, and the month's reminder
  /// is taken away at once.
  void _markPaid(Map<String, dynamic> st) {
    final ym = ymOf(todayStr());
    s.feeMarkPaid(st['id'].toString(), ym);
    s.ntStudentAndGuardians(
      st,
      type: 'fee',
      title: 'Fee marked paid',
      message:
          'Your fees are marked paid for ${monthLabel(ym)}. '
          'No reminder will be sent this month.',
      refType: 'fee_paid',
      refId: '${st['id']}|$ym',
      dedupKey: 'fee_paid_${st['id']}|$ym',
    );
    s.save();
    setState(() {});
    toast(context, '${st['name']} is marked PAID.');
  }

  /// Back to not paid: the reminder goes out again straight away.
  void _markUnpaid(Map<String, dynamic> st) {
    s.feeUndo(st['id'].toString(), ymOf(todayStr()));
    setState(() {});
    toast(context, '${st['name']} is marked NOT PAID — the reminder is back.');
  }

  @override
  Widget build(BuildContext context) {
    final k = context.k;
    final ym = ymOf(todayStr());
    var paid = 0;
    for (final st in s.students) {
      if (s.feeStatusOf(st['id'].toString(), ym).paid) paid++;
    }
    final unpaid = s.students.length - paid;
    final list = _matching;

    return ListView(
      padding: EdgeInsets.fromLTRB(14, 14, 14, 24),
      children: [
        PageHeading(
          s.t('Fees'),
          T(
            'One switch per student: paid or not paid. Students and guardians '
            'get a reminder on the 1st of every month until you mark the fee '
            'paid.',
          ),
          Icons.receipt_long_outlined,
        ),
        SizedBox(height: 10),
        Row(
          children: [
            Expanded(child: _tile(context, '$paid', T('Paid'), Skin.green)),
            SizedBox(width: 8),
            Expanded(
              child: _tile(context, '$unpaid', T('Not paid'), Skin.marigold),
            ),
            SizedBox(width: 8),
            Expanded(
              child: _tile(
                context,
                '${s.students.length}',
                T('Students'),
                Skin.navy,
              ),
            ),
          ],
        ),
        SizedBox(height: 10),
        Panel(
          padding: EdgeInsets.fromLTRB(11, 11, 11, 4),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                T('Mark paid or not paid'),
                style: TextStyle(fontSize: 13, fontWeight: FontWeight.w800),
              ),
              SizedBox(height: 9),
              // one box: the field itself draws no border of its own
              Container(
                decoration: BoxDecoration(
                  color: k.surface2,
                  border: Border.all(color: k.line),
                  borderRadius: BorderRadius.circular(9),
                ),
                padding: EdgeInsets.symmetric(horizontal: 10),
                child: TextField(
                  controller: _search,
                  onChanged: (_) => setState(() {}),
                  style: TextStyle(fontSize: 12.5, color: k.ink),
                  decoration: InputDecoration(
                    hintText: T('Search by name, guardian, batch'),
                    isDense: true,
                    filled: false,
                    border: InputBorder.none,
                    enabledBorder: InputBorder.none,
                    focusedBorder: InputBorder.none,
                    contentPadding: EdgeInsets.symmetric(vertical: 12),
                    prefixIcon: Icon(Icons.search, size: 16),
                    prefixIconConstraints: BoxConstraints(
                      minWidth: 30,
                      minHeight: 30,
                    ),
                  ),
                ),
              ),
              SizedBox(height: 9),
              Text(
                T(
                  'Reminders go out on the 1st of every month to the student '
                  'and every guardian, for each student who is not marked '
                  'paid. Marking a student paid removes the reminder straight '
                  'away; marking them not paid again puts it back.',
                ),
                style: TextStyle(
                  fontSize: 9.5,
                  color: context.faint,
                  height: 1.4,
                ),
              ),
              SizedBox(height: 10),
              if (list.isEmpty)
                Padding(
                  padding: EdgeInsets.only(bottom: 10),
                  child: Text(
                    T('No students match this search.'),
                    style: TextStyle(fontSize: 10.5, color: context.soft),
                  ),
                )
              else
                for (var i = 0; i < list.length; i++)
                  _card(context, list[i], i, ym),
            ],
          ),
        ),
      ],
    );
  }

  Widget _tile(BuildContext context, String value, String label, Color color) =>
      Container(
        padding: EdgeInsets.symmetric(vertical: 10),
        decoration: BoxDecoration(
          color: color.withValues(alpha: .12),
          borderRadius: BorderRadius.circular(10),
          border: Border.all(color: color.withValues(alpha: .35)),
        ),
        child: Column(
          children: [
            Text(
              value,
              style: TextStyle(
                fontSize: 17,
                fontWeight: FontWeight.w800,
                color: color,
              ),
            ),
            Text(label, style: TextStyle(fontSize: 8.5, color: context.soft)),
          ],
        ),
      );

  Widget _pair(BuildContext context, String label, String value) => Column(
    crossAxisAlignment: CrossAxisAlignment.start,
    children: [
      SmallLabel(label),
      SizedBox(height: 4),
      Text(
        value,
        style: TextStyle(
          fontSize: 11,
          fontWeight: FontWeight.w600,
          color: context.k.ink,
        ),
      ),
    ],
  );

  Widget _card(
    BuildContext context,
    Map<String, dynamic> st,
    int i,
    String ym,
  ) {
    final k = context.k;
    final id = st['id'].toString();
    final fee = s.feeStatusOf(id, ym);
    final history = s.feePaymentsFor(id, ym);
    return Stagger(
      index: i,
      child: Container(
        margin: EdgeInsets.only(bottom: 9),
        padding: EdgeInsets.fromLTRB(11, 11, 11, 11),
        decoration: BoxDecoration(
          color: k.surface2,
          borderRadius: BorderRadius.circular(k.radius),
          border: Border.all(
            color: fee.paid
                ? Skin.green.withValues(alpha: .45)
                : k.lineStrong.withValues(alpha: .55),
          ),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      SmallLabel(T('Student')),
                      SizedBox(height: 4),
                      Text(
                        (st['name'] ?? '').toString(),
                        style: TextStyle(
                          fontSize: 13,
                          fontWeight: FontWeight.w800,
                          color: k.ink,
                        ),
                      ),
                    ],
                  ),
                ),
                Avatar(name: (st['name'] ?? '?').toString(), radius: 15),
              ],
            ),
            SizedBox(height: 11),
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Expanded(
                  flex: 5,
                  child: _pair(
                    context,
                    T('Standard'),
                    (st['standard'] ?? '').toString().trim().isEmpty
                        ? '—'
                        : st['standard'].toString(),
                  ),
                ),
                Expanded(
                  flex: 6,
                  child: _pair(context, T('Batch'), s.batchName(st['batchId'])),
                ),
                Expanded(
                  flex: 4,
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      SmallLabel(T('Fees')),
                      SizedBox(height: 4),
                      Chip8(
                        T(fee.status),
                        color: fee.paid ? Skin.green : Skin.red,
                      ),
                    ],
                  ),
                ),
              ],
            ),
            SizedBox(height: 11),
            if (fee.paid) ...<Widget>[
              Pressable(
                onTap: () => _markUnpaid(st),
                child: Container(
                  height: 42,
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    color: k.surface,
                    borderRadius: BorderRadius.circular(k.radius),
                    border: Border.all(color: k.lineStrong),
                  ),
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      Icon(Icons.undo, size: 15, color: k.inkSoft),
                      SizedBox(width: 7),
                      Text(
                        T('Mark not paid'),
                        style: TextStyle(
                          fontSize: 12.5,
                          fontWeight: FontWeight.w700,
                          color: k.inkSoft,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
              if (history.isNotEmpty)
                Padding(
                  padding: EdgeInsets.only(top: 7),
                  child: Text(
                    TT('Marked paid on {0} by {1}', [
                      fmtDate(history.first['date'].toString()),
                      history.first['by'].toString(),
                    ]),
                    style: TextStyle(fontSize: 9, color: context.faint),
                  ),
                ),
            ] else
              Pressable(
                onTap: () => _markPaid(st),
                child: Container(
                  height: 42,
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    borderRadius: BorderRadius.circular(k.radius),
                    gradient: LinearGradient(
                      begin: Alignment.centerLeft,
                      end: Alignment.centerRight,
                      colors: [
                        Color.lerp(k.accent, Colors.black, .30)!,
                        Color.lerp(k.accent, Colors.white, .12)!,
                      ],
                    ),
                    boxShadow: [
                      BoxShadow(
                        color: k.accent.withValues(alpha: .28),
                        blurRadius: 14,
                        offset: Offset(0, 4),
                      ),
                    ],
                  ),
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      Icon(
                        Icons.check_circle_outline,
                        size: 16,
                        color: Colors.white,
                      ),
                      SizedBox(width: 7),
                      Text(
                        T('Mark paid'),
                        style: TextStyle(
                          fontSize: 12.5,
                          fontWeight: FontWeight.w800,
                          color: Colors.white,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
          ],
        ),
      ),
    );
  }
}

// ---------------------------------------------------------------------------
//  ADMIN — staff hours + leave decisions, teachers & batches, admins, guardians
// ---------------------------------------------------------------------------
class AdminStaffPage extends StatefulWidget {
  const AdminStaffPage({super.key, required this.user});

  final Map<String, dynamic> user;

  @override
  State<AdminStaffPage> createState() => _AdminStaffPageState();
}

class _AdminStaffPageState extends State<AdminStaffPage> {
  Store get s => Store.I;

  /// today = zone, holidays, add staff, hours bank, leave · month = register ·
  /// live = who is inside the institute right now
  String _view = 'today';
  String _month = ymOf(todayStr());
  Timer? _tick;

  final _q = TextEditingController();

  final _name = TextEditingController();
  final _email = TextEditingController();
  final _pass = TextEditingController();
  final _phone = TextEditingController();
  final _shift = TextEditingController(text: '09:00');
  final _shiftEnd = TextEditingController(text: '17:30');
  final _hours = TextEditingController(text: '8');
  final _birthday = TextEditingController();
  String _lateDay = 'None';
  final _lateStart = TextEditingController(text: '10:00');
  final _lateEnd = TextEditingController(text: '18:00');
  final List<Map<String, dynamic>> _lateDraft = <Map<String, dynamic>>[];

  final _lat = TextEditingController();
  final _lng = TextEditingController();
  int _radius = 150;
  bool _locating = false;

  String? _adjustFor;
  int _adjDir = 1;
  final _adjHrs = TextEditingController();
  final _adjMins = TextEditingController();
  final _adjReason = TextEditingController();

  @override
  void initState() {
    super.initState();
    final g = s.geofence;
    _lat.text = ((g['lat'] as num?) ?? 0).toString();
    _lng.text = ((g['lng'] as num?) ?? 0).toString();
    _radius = ((g['radius'] as num?) ?? 150).round();
  }

  void _setView(String v) {
    _tick?.cancel();
    _tick = null;
    if (v == 'live') {
      _tick = Timer.periodic(const Duration(seconds: 1), (_) {
        if (mounted) setState(() {});
      });
    }
    setState(() => _view = v);
  }

  @override
  void dispose() {
    _tick?.cancel();
    for (final c in <TextEditingController>[
      _q,
      _name,
      _email,
      _pass,
      _phone,
      _shift,
      _shiftEnd,
      _hours,
      _birthday,
      _lateStart,
      _lateEnd,
      _lat,
      _lng,
      _adjHrs,
      _adjMins,
      _adjReason,
    ]) {
      c.dispose();
    }
    super.dispose();
  }

  // ---------------------------------------------------------------- helpers
  List<Map<String, dynamic>> get _staff =>
      s.users.where((u) => u['role'] == 'staff').toList();

  bool _matches(Map<String, dynamic> p, String q) {
    final words = q.toLowerCase().trim().split(RegExp(r'\s+'))
      ..removeWhere((w) => w.isEmpty);
    if (words.isEmpty) return true;
    final hay = <String>[
      (p['name'] ?? '').toString(),
      (p['email'] ?? '').toString(),
      (p['phone'] ?? '').toString(),
      'staff',
    ].join(' ').toLowerCase();
    return words.every(hay.contains);
  }

  List<Map<String, dynamic>> get _pending =>
      s.leaveRequests.where((r) {
        if ((r['status'] ?? 'pending') != 'pending') return false;
        final role = s.userById((r['userId'] ?? '').toString())?['role'];
        return role == 'staff' || role == 'teacher';
      }).toList()..sort(
        (a, b) => (a['date'].toString()).compareTo(b['date'].toString()),
      );

  List<Map<String, dynamic>> get _adjustments =>
      s.listOf('hourAdjustments').toList()..sort(
        (a, b) => ((b['ts'] as num?) ?? 0).compareTo((a['ts'] as num?) ?? 0),
      );

  // ---------------------------------------------------------------- actions
  void _saveZone() {
    final lat = double.tryParse(_lat.text.trim());
    final lng = double.tryParse(_lng.text.trim());
    if (lat == null || lng == null || lat.abs() > 90 || lng.abs() > 180) {
      toast(context, T('Enter a valid latitude and longitude.'));
      return;
    }
    final g = Map<String, dynamic>.from(s.geofence);
    g['lat'] = lat;
    g['lng'] = lng;
    g['radius'] = _radius;
    s.data['geofence'] = g;
    s.save();
    setState(() {});
    toast(context, T('Institute zone saved.'));
  }

  Future<void> _useMyLocation() async {
    setState(() => _locating = true);
    try {
      if (!await Geolocator.isLocationServiceEnabled()) {
        throw T('Turn location on to place the pin.');
      }
      var perm = await Geolocator.checkPermission();
      if (perm == LocationPermission.denied) {
        perm = await Geolocator.requestPermission();
      }
      if (perm == LocationPermission.denied ||
          perm == LocationPermission.deniedForever) {
        throw T('Location permission is off. Allow it in phone settings.');
      }
      final pos = await Geolocator.getCurrentPosition(
        locationSettings: const LocationSettings(
          accuracy: LocationAccuracy.high,
          timeLimit: Duration(seconds: 30),
        ),
      );
      if (!mounted) return;
      setState(() {
        _lat.text = pos.latitude.toStringAsFixed(6);
        _lng.text = pos.longitude.toStringAsFixed(6);
        _locating = false;
      });
      toast(context, T('Pin filled in — now press Save zone.'));
    } catch (e) {
      if (!mounted) return;
      setState(() => _locating = false);
      toast(context, e.toString());
    }
  }

  void _addLateTiming() {
    if (_lateDay == 'None') {
      toast(context, T('Pick a day first.'));
      return;
    }
    setState(() {
      _lateDraft.removeWhere((x) => x['day'] == _lateDay);
      _lateDraft.add(<String, dynamic>{
        'day': _lateDay,
        'start': _lateStart.text.trim(),
        'end': _lateEnd.text.trim(),
      });
      _lateDay = 'None';
    });
  }

  void _addStaff() {
    final name = _name.text.trim();
    final email = _email.text.trim().toLowerCase();
    if (name.isEmpty || email.isEmpty) {
      toast(context, T('A name and email are required.'));
      return;
    }
    if (s.users.any(
      (u) => (u['email'] ?? '').toString().toLowerCase() == email,
    )) {
      toast(context, T('That email already has a login.'));
      return;
    }
    if (_pass.text.trim().length < 8) {
      toast(context, T('Use a temporary password with at least 8 characters.'));
      return;
    }
    s.allowLogin(email);
    s.rawList('users').add(<String, dynamic>{
      'id': uid('user'),
      'role': 'staff',
      'joined': DateTime.now().toIso8601String().substring(0, 10),
      'name': name,
      'email': email,
      'password': _pass.text.trim(),
      'phone': _phone.text.trim(),
      'birthday': _birthday.text.trim(),
      'target': double.tryParse(_hours.text.trim()) ?? 8,
      'shift': _shift.text.trim(),
      'shiftEnd': _shiftEnd.text.trim(),
      'lateDays': _lateDraft.map((x) => Map<String, dynamic>.from(x)).toList(),
    });
    s.save();
    setState(() {
      _name.clear();
      _email.clear();
      _phone.clear();
      _birthday.clear();
      _pass.clear();
      _lateDraft.clear();
    });
    toast(context, TT('{0} added — login {1}', <String>[name, email]));
  }

  void _removeStaff(Map<String, dynamic> p) {
    final id = p['id'].toString();
    s.blockLogin((p['email'] ?? '').toString());
    s.tombRows(<Map<String, dynamic>>[
      p,
      ...s.inbox.where((n) => n['userId'] == id),
    ]);
    s.data['users'] = s.users.where((u) => u['id'] != id).toList();
    s.data['inbox'] = s.inbox.where((n) => n['userId'] != id).toList();
    s.save();
    setState(() {});
    toast(context, TT('{0} removed.', <String>[p['name'].toString()]));
  }

  void _applyAdjust(Map<String, dynamic> p) {
    final hrs = double.tryParse(_adjHrs.text.trim()) ?? 0;
    final extra = double.tryParse(_adjMins.text.trim()) ?? 0;
    final totalMin = (hrs * 60 + extra).round();
    if (totalMin <= 0) {
      toast(context, T('Enter the time to adjust — e.g. 1 hour 45 minutes.'));
      return;
    }
    final reason = _adjReason.text.trim().isEmpty
        ? (_adjDir > 0
              ? T('Overtime added by the office')
              : T('Banked hours used (leave / late covered)'))
        : _adjReason.text.trim();
    final minutes = _adjDir * totalMin;
    s.rawList('hourAdjustments').add(<String, dynamic>{
      'id': uid('adj'),
      'userId': p['id'],
      'date': todayStr(),
      'minutes': minutes,
      'note': reason,
      'reason': reason,
      'by': widget.user['name'],
      'ts': DateTime.now().millisecondsSinceEpoch,
    });
    s.ntPush(
      userId: p['id'].toString(),
      type: 'adj',
      title: T('Hours bank adjusted'),
      message:
          '${minutes > 0 ? TT('{0} was added to your hours bank.', <String>[fmtHours(minutes)]) : TT('{0} was taken from your hours bank.', <String>[fmtHours(-minutes)])}'
          '\n${TT('Reason: {0}', <String>[reason])}'
          '\n${TT('Date: {0}', <String>[fmtDate(todayStr())])}',
      refType: 'staff_update',
      refId: uid('adjref'),
    );
    s.save();
    setState(() {
      _adjustFor = null;
      _adjHrs.clear();
      _adjMins.clear();
      _adjReason.clear();
      _adjDir = 1;
    });
    toast(
      context,
      TT('{0} — bank {1} ({2}).', <String>[
        p['name'].toString(),
        fmtSignedHours(minutes),
        reason,
      ]),
    );
  }

  void _deleteAdjust(Map<String, dynamic> a) {
    s.data['hourAdjustments'] = s
        .listOf('hourAdjustments')
        .where((x) => x['id'] != a['id'])
        .toList();
    s.save();
    setState(() {});
    toast(context, T('Adjustment removed — the bank is recalculated.'));
  }

  void _decide(String gid, bool accept) {
    final days = s.leaveRequests.where((r) => (r['groupId'] ?? r['id']) == gid);
    Map<String, dynamic>? first;
    for (final d in days) {
      d['status'] = accept ? 'accepted' : 'declined';
      first ??= d;
    }
    if (first == null) return;
    final uidOf = first['userId'].toString();
    final label = s.leaveRangeLabel(days.toList());
    s.leaveDecision(groupId: gid, userId: uidOf, label: label, accept: accept);
    s.save();
    setState(() {});
    toast(context, accept ? 'Leave accepted.' : 'Leave declined.');
  }

  void _openStaff(Map<String, dynamic> p) {
    s.viewStaffId = p['id'].toString();
    s.save(push: false);
    setState(() {});
  }

  String _shiftMonth(String ym, int delta) {
    final p = ym.split('-');
    final d = DateTime(int.parse(p[0]), int.parse(p[1]) + delta, 1);
    return '${d.year}-${two(d.month)}';
  }

  // ------------------------------------------------------------------- look
  Widget _label(String text) => Padding(
    padding: const EdgeInsets.only(bottom: 4),
    child: Text(
      text,
      style: TextStyle(
        fontSize: 11,
        fontWeight: FontWeight.w600,
        color: context.k.inkSoft,
      ),
    ),
  );

  Widget _field(
    String label,
    TextEditingController c, {
    String? hint,
    TextInputType? keyboard,
    bool obscure = false,
  }) => Padding(
    padding: const EdgeInsets.only(bottom: 9),
    child: Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: <Widget>[
        _label(label),
        TextField(
          controller: c,
          keyboardType: keyboard,
          obscureText: obscure,
          style: const TextStyle(fontSize: 13),
          decoration: InputDecoration(hintText: hint),
        ),
      ],
    ),
  );

  Widget _pick(
    String label,
    String value,
    List<MapEntry<String, String>> items,
    ValueChanged<String?> onPick,
  ) {
    final known = items.any((i) => i.key == value);
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: <Widget>[
        _label(label),
        DropdownButtonFormField<String>(
          value: known ? value : items.first.key,
          isDense: true,
          isExpanded: true,
          decoration: const InputDecoration(),
          items: <DropdownMenuItem<String>>[
            for (final i in items)
              DropdownMenuItem<String>(
                value: i.key,
                child: Text(
                  i.value,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(fontSize: 12.5),
                ),
              ),
          ],
          onChanged: onPick,
        ),
      ],
    );
  }

  Widget _searchBox(
    TextEditingController c,
    String hint, {
    VoidCallback? onChanged,
  }) => Container(
    decoration: BoxDecoration(
      color: context.k.surface2,
      border: Border.all(color: context.k.line),
      borderRadius: BorderRadius.circular(9),
    ),
    padding: const EdgeInsets.symmetric(horizontal: 10),
    child: TextField(
      controller: c,
      onChanged: (_) {
        if (onChanged != null) onChanged();
      },
      style: TextStyle(fontSize: 12.5, color: context.k.ink),
      decoration: InputDecoration(
        hintText: hint,
        isDense: true,
        filled: false,
        border: InputBorder.none,
        enabledBorder: InputBorder.none,
        focusedBorder: InputBorder.none,
        contentPadding: const EdgeInsets.symmetric(vertical: 12),
        prefixIcon: const Icon(Icons.search, size: 16),
        prefixIconConstraints: const BoxConstraints(
          minWidth: 30,
          minHeight: 30,
        ),
      ),
    ),
  );

  Widget _kv(String label, String value, {Color? color, double size = 11.5}) =>
      Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          Text(
            label,
            style: TextStyle(
              fontSize: 8.5,
              letterSpacing: .3,
              fontWeight: FontWeight.w700,
              color: context.faint,
            ),
          ),
          const SizedBox(height: 3),
          Text(
            value,
            style: TextStyle(
              fontSize: size,
              fontWeight: FontWeight.w600,
              color: color ?? context.k.ink,
            ),
          ),
        ],
      );

  Widget _note(String text) => Text(
    text,
    style: TextStyle(fontSize: 9.5, height: 1.45, color: context.faint),
  );

  Widget _card(String title, List<Widget> children, {Widget? trailing}) =>
      Panel(
        margin: const EdgeInsets.only(bottom: 12),
        padding: const EdgeInsets.fromLTRB(14, 14, 14, 14),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: <Widget>[
            Row(
              children: <Widget>[
                Expanded(child: SectionTitle(title)),
                ?trailing,
              ],
            ),
            const SizedBox(height: 6),
            ...children,
          ],
        ),
      );

  Widget _smallBtn(String label, VoidCallback tap, {Color? color}) => Pressable(
    onTap: tap,
    child: Container(
      padding: const EdgeInsets.symmetric(horizontal: 11, vertical: 7),
      decoration: BoxDecoration(
        color: color ?? context.k.surface2,
        borderRadius: BorderRadius.circular(999),
        border: Border.all(color: context.k.lineStrong),
      ),
      child: Text(
        label,
        style: TextStyle(
          fontSize: 10.5,
          fontWeight: FontWeight.w700,
          color: color == null ? context.k.inkSoft : Colors.white,
        ),
      ),
    ),
  );

  Widget _primaryBtn(String label, VoidCallback tap) => Pressable(
    onTap: tap,
    child: Container(
      height: 42,
      alignment: Alignment.center,
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(context.k.radius),
        gradient: LinearGradient(
          begin: Alignment.centerLeft,
          end: Alignment.centerRight,
          colors: <Color>[
            Color.lerp(context.k.accent, Colors.black, .30)!,
            Color.lerp(context.k.accent, Colors.white, .12)!,
          ],
        ),
      ),
      child: Text(
        label,
        style: const TextStyle(
          fontSize: 12.5,
          fontWeight: FontWeight.w800,
          color: Colors.white,
        ),
      ),
    ),
  );

  Widget _rowCard(List<Widget> children, {Color? border, int index = 0}) =>
      Stagger(
        index: index,
        child: Container(
          margin: const EdgeInsets.only(bottom: 8),
          padding: const EdgeInsets.fromLTRB(11, 10, 11, 10),
          decoration: BoxDecoration(
            color: context.k.surface2,
            borderRadius: BorderRadius.circular(context.k.radius),
            border: Border.all(color: border ?? context.k.line),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: children,
          ),
        ),
      );

  String _dayShort(String day) => day.length > 3 ? day.substring(0, 3) : day;

  Widget _bankChipOf(int bal) => Chip8(
    bal > 0
        ? '+${fmtHours(bal)} banked'
        : (bal < 0 ? '−${fmtHours(-bal)} pending' : T('even')),
    color: bal > 0 ? Skin.green : (bal < 0 ? Skin.red : Skin.gold),
  );

  // ------------------------------------------------------------------ build
  @override
  Widget build(BuildContext context) {
    return ListView(
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 24),
      children: <Widget>[
        PageHeading(
          T('Staff'),
          T(
            'Office staff attendance runs on the entry radar — staff can check '
            'IN and OUT only when their phone is inside the institute zone.',
          ),
          Icons.access_time,
        ),
        const SizedBox(height: 10),
        PillToggle(
          options: <MapEntry<String, String>>[
            MapEntry('today', T('Today')),
            MapEntry('month', T('Month register')),
            MapEntry('live', T('Live working')),
          ],
          value: _view,
          onChanged: _setView,
        ),
        const SizedBox(height: 12),
        if (_view == 'today') ..._todayTab(context),
        if (_view == 'month') ..._monthTab(context),
        if (_view == 'live') ..._liveTab(context),
      ],
    );
  }

  // ==================================================================
  //  One — Today
  // ==================================================================
  List<Widget> _todayTab(BuildContext context) {
    final staff = _staff;
    final q = _q.text;
    final shown = staff.where((p) => _matches(p, q)).toList();
    final g = s.geofence;

    return <Widget>[
      // ---- the entry radar
      _card(T('Institute zone (entry radar)'), <Widget>[
        _note((g['address'] ?? '').toString()),
        const SizedBox(height: 9),
        Row(
          children: <Widget>[
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: <Widget>[
                  _label(T('Latitude')),
                  TextField(
                    controller: _lat,
                    keyboardType: const TextInputType.numberWithOptions(
                      decimal: true,
                    ),
                    style: const TextStyle(fontSize: 12.5),
                  ),
                ],
              ),
            ),
            const SizedBox(width: 8),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: <Widget>[
                  _label(T('Longitude')),
                  TextField(
                    controller: _lng,
                    keyboardType: const TextInputType.numberWithOptions(
                      decimal: true,
                    ),
                    style: const TextStyle(fontSize: 12.5),
                  ),
                ],
              ),
            ),
          ],
        ),
        const SizedBox(height: 9),
        _pick(T('Check-in radius'), '$_radius', <MapEntry<String, String>>[
          MapEntry('50', '50 meters'),
          MapEntry('100', '100 meters'),
          MapEntry('150', '150 meters'),
          MapEntry('200', '200 meters'),
          MapEntry('300', '300 meters'),
        ], (v) => setState(() => _radius = int.tryParse(v ?? '150') ?? 150)),
        const SizedBox(height: 9),
        Pressable(
          onTap: _locating ? () {} : _useMyLocation,
          child: Container(
            height: 40,
            alignment: Alignment.center,
            decoration: BoxDecoration(
              color: context.k.surface,
              borderRadius: BorderRadius.circular(context.k.radius),
              border: Border.all(color: context.k.lineStrong),
            ),
            child: Text(
              _locating
                  ? T('Locating… (up to 30s)')
                  : T('Set to my current location'),
              style: TextStyle(
                fontSize: 11,
                fontWeight: FontWeight.w700,
                color: context.k.inkSoft,
              ),
            ),
          ),
        ),
        const SizedBox(height: 8),
        _primaryBtn(T('Save zone'), _saveZone),
        const SizedBox(height: 7),
        _note(
          T(
            'Stand at the institute gate and press "Set to my current location" '
            'to place the radar pin precisely.',
          ),
        ),
      ]),

      // ---- add a staff member
      _card(T('Add a staff member'), <Widget>[
        _field(T('Full name'), _name, hint: T('Staff name')),
        _field(
          T('Login email'),
          _email,
          hint: 'name@jsk.edu',
          keyboard: TextInputType.emailAddress,
        ),
        _field(
          T('Temporary password (at least 8 characters)'),
          _pass,
          hint: 'At least 8 characters',
          obscure: true,
        ),
        _field(
          T('Phone number'),
          _phone,
          hint: '+91 …',
          keyboard: TextInputType.phone,
        ),
        Row(
          children: <Widget>[
            Expanded(
              child: _field(T('Shift starts at'), _shift, hint: '09:00'),
            ),
            const SizedBox(width: 8),
            Expanded(
              child: _field(T('Shift ends at'), _shiftEnd, hint: '17:30'),
            ),
          ],
        ),
        _field(
          T('Working hours a day (type any value)'),
          _hours,
          hint: '8',
          keyboard: TextInputType.number,
        ),
        _label(
          T('Late days — pick a day with its own shift (multiple allowed)'),
        ),
        Row(
          children: <Widget>[
            Expanded(
              flex: 3,
              child: DropdownButtonFormField<String>(
                value: _lateDay,
                isDense: true,
                isExpanded: true,
                decoration: const InputDecoration(),
                items: <DropdownMenuItem<String>>[
                  DropdownMenuItem<String>(
                    value: 'None',
                    child: Text(
                      T('Pick a day'),
                      style: const TextStyle(fontSize: 12),
                    ),
                  ),
                  for (final d in const <String>[
                    'Monday',
                    'Tuesday',
                    'Wednesday',
                    'Thursday',
                    'Friday',
                    'Saturday',
                    'Sunday',
                  ])
                    DropdownMenuItem<String>(
                      value: d,
                      child: Text(d, style: const TextStyle(fontSize: 12)),
                    ),
                ],
                onChanged: (v) => setState(() => _lateDay = v ?? 'None'),
              ),
            ),
            const SizedBox(width: 6),
            Expanded(
              flex: 2,
              child: TextField(
                controller: _lateStart,
                style: const TextStyle(fontSize: 12),
                decoration: const InputDecoration(hintText: '10:00'),
              ),
            ),
            const SizedBox(width: 6),
            Expanded(
              flex: 2,
              child: TextField(
                controller: _lateEnd,
                style: const TextStyle(fontSize: 12),
                decoration: const InputDecoration(hintText: '18:00'),
              ),
            ),
          ],
        ),
        const SizedBox(height: 7),
        _smallBtn(T('Add timing'), _addLateTiming),
        if (_lateDraft.isNotEmpty)
          Padding(
            padding: const EdgeInsets.only(top: 7),
            child: Wrap(
              spacing: 6,
              runSpacing: 6,
              children: <Widget>[
                for (final x in _lateDraft)
                  Pressable(
