  // ==================================================================
  //  Two — Month register
  // ==================================================================
  List<Widget> _monthTab(BuildContext context) {
    final staff = _staff;
    final ym = _month;
    final p = ym.split('-');
    final year = int.parse(p[0]);
    final month = int.parse(p[1]);
    final daysInMonth = DateTime(year, month + 1, 0).day;

    final stats =
        <
          Map<String, dynamic>,
          ({int days, int totalMs, int? inAvg, int? outAvg, int outCount})
        >{
          for (final t in staff) t: s.staffMonthStatsOf(t['id'].toString(), ym),
        };
    var checkInDays = 0;
    var totalMs = 0;
    var inSum = 0;
    var inCount = 0;
    var outSum = 0;
    var outCount = 0;
    for (final st in stats.values) {
      checkInDays += st.days;
      totalMs += st.totalMs;
      if (st.inAvg != null) {
        inSum += st.inAvg!;
        inCount++;
      }
      if (st.outAvg != null) {
        outSum += st.outAvg!;
        outCount++;
      }
    }
    final avgIn = inCount == 0 ? null : (inSum / inCount).round();
    final avgOut = outCount == 0 ? null : (outSum / outCount).round();

    return <Widget>[
      const SizedBox(height: 2),
      Text(
        T(
          'Every check-in and check-out of the whole month, one by one, with an '
          'analysis of their timings.',
        ),
        style: TextStyle(fontSize: 10.5, height: 1.4, color: context.faint),
      ),
      const SizedBox(height: 10),
      Row(
        children: <Widget>[
          Expanded(
            child: StatTile(
              value: '${staff.length}',
              label: T('Staff members'),
            ),
          ),
          const SizedBox(width: 7),
          Expanded(
            child: StatTile(value: '$checkInDays', label: T('Check-in days')),
          ),
        ],
      ),
      const SizedBox(height: 7),
      Row(
        children: <Widget>[
          Expanded(
            child: StatTile(value: minToClock(avgIn), label: T('Avg check-in')),
          ),
          const SizedBox(width: 7),
          Expanded(
            child: StatTile(
              value: minToClock(avgOut),
              label: T('Avg check-out'),
            ),
          ),
        ],
      ),
      const SizedBox(height: 7),
      StatTile(
        value: totalMs == 0 ? '—' : fmtHours(totalMs ~/ 60000),
        label: T('Total time on campus'),
        variant: 'theme',
      ),
      const SizedBox(height: 12),
      Panel(
        margin: const EdgeInsets.only(bottom: 12),
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
        child: Row(
          children: <Widget>[
            _smallBtn('‹ ${monthLabelShort(_shiftMonth(ym, -1))}', () {
              setState(() => _month = _shiftMonth(_month, -1));
            }),
            Expanded(
              child: Center(
                child: Text(
                  monthLabelLong(ym),
                  style: TextStyle(
                    fontFamily: Skin.serif,
                    fontSize: 14,
                    fontWeight: FontWeight.w700,
                    color: context.k.ink,
                  ),
                ),
              ),
            ),
            _smallBtn('${monthLabelShort(_shiftMonth(ym, 1))} ›', () {
              setState(() => _month = _shiftMonth(_month, 1));
            }),
          ],
        ),
      ),
      if (staff.isEmpty)
        _card(T('Staff · Month register'), <Widget>[
          _note(T('No staff members yet.')),
        ])
      else
        for (var i = 0; i < staff.length; i++)
          _monthCard(staff[i], stats[staff[i]]!, ym, daysInMonth, i),
    ];
  }

