                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: <Widget>[
                    Text(
                      (t['name'] ?? '').toString(),
                      style: const TextStyle(
                        fontSize: 12.5,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                    const SizedBox(height: 2),
                    Text(
                      '${st.days} ${st.days == 1 ? 'day' : 'days'} this month · '
                      '${fmtHours(st.totalMs ~/ 60000)} on campus · '
                      '${s.targetOf(t).toStringAsFixed(0)}h target a day',
                      style: TextStyle(
                        fontSize: 9,
                        height: 1.4,
                        color: context.faint,
                      ),
                    ),
                    Text(
                      st.outCount == 0
                          ? 'Avg in ${minToClock(st.inAvg)}'
                          : 'Avg in ${minToClock(st.inAvg)} · avg out ${minToClock(st.outAvg)}',
                      style: TextStyle(fontSize: 9, color: context.faint),
                    ),
                  ],
                ),
              ),
              _bankChipOf(s.hoursBalanceOf(id, ym)),
            ],
          ),
          const SizedBox(height: 10),
          LayoutBuilder(
            builder: (context, box) {
              final w = (box.maxWidth - 6 * 5) / 7;
              return Wrap(
                spacing: 5,
                runSpacing: 5,
                children: <Widget>[
                  for (var d = 1; d <= daysInMonth; d++)
                    _dayCell(t, ym, d, w, recs),
                ],
              );
            },
          ),
        ],
      ),
    );
  }

  Widget _dayCell(
    Map<String, dynamic> t,
    String ym,
    int day,
    double width,
    List<Map<String, dynamic>> recs,
  ) {
    final k = context.k;
    final date = '$ym-${two(day)}';
    Map<String, dynamic>? rec;
    for (final r in recs) {
      if (r['date'] == date) {
        rec = r;
        break;
      }
    }
    final hol = s.holidayOn(date);
    // only a leave the office APPROVED — a pending request colours nothing
    final leave = s.leaveRequests.any(
      (r) =>
          r['userId'] == t['id'] &&
          r['date'] == date &&
          r['status'] == 'accepted',
    );
    final absent = s.plDaysOf(t['id'].toString(), ym).contains(date);

    String? inTxt;
    String foot;
    Color bg = k.surface2;
    Color line = k.line;
    Color ink = k.ink;
    Color sub = k.faint;

    if (rec != null) {
      inTxt = shortTime24((rec['inTs'] as num?)?.toInt());
      final out = (rec['outTs'] as num?)?.toInt();
      foot = out == null ? 'in' : shortTime24(out);
      if (hol != null) foot = '$foot · HOL';
      bg = Skin.green.withValues(alpha: .13);
      line = Skin.green.withValues(alpha: .38);
      ink = Skin.green;
      sub = k.inkSoft;
    } else if (hol != null) {
      // only a holiday the Admin declared
      foot = 'HOL';
      bg = Skin.navy.withValues(alpha: .07);
    } else if (leave) {
      foot = 'OFF';
      bg = Skin.navy.withValues(alpha: .07);
    } else if (absent) {
      foot = 'AB';
      bg = Skin.red.withValues(alpha: .10);
      line = Skin.red.withValues(alpha: .30);
      sub = Skin.red;
    } else {
      foot = '—';
    }

    return Container(
      width: width,
      padding: const EdgeInsets.symmetric(vertical: 5, horizontal: 2),
      decoration: BoxDecoration(
        color: bg,
        borderRadius: BorderRadius.circular(7),
        border: Border.all(color: line),
      ),
      child: Column(
        children: <Widget>[
          Text(
            two(day),
            style: TextStyle(
              fontSize: 8.5,
              fontWeight: FontWeight.w700,
              color: sub,
            ),
          ),
          if (inTxt != null)
            Text(
              inTxt,
              style: TextStyle(
                fontSize: 8.5,
                fontWeight: FontWeight.w700,
                color: ink,
              ),
            ),
          Text(
            foot,
            style: TextStyle(fontSize: inTxt == null ? 8.5 : 8, color: sub),
          ),
        ],
      ),
    );
  }

  // ==================================================================
  //  Three — Live working
  // ==================================================================
  List<Widget> _liveTab(BuildContext context) {
    final staff = _staff.toList()
      ..sort(
        (a, b) => (a['name'] ?? '').toString().compareTo(
          (b['name'] ?? '').toString(),
        ),
      );
    final today = todayStr();
    final recs = <Map<String, dynamic>, Map<String, dynamic>?>{
      for (final t in staff) t: s.staffRecordOn(t['id'].toString(), today),
    };
    final live = staff.where((t) {
      final r = recs[t];
      return r != null && r['inTs'] != null && r['outTs'] == null;
    }).toList();
    final left = staff.where((t) => recs[t]?['outTs'] != null).length;
    final notIn = staff.where((t) => recs[t] == null).length;
    final remarks = s.lateRemarksFor('staff');
    final lateToday = remarks.where((r) => r['date'] == today).length;
    final now = DateTime.now();

    return <Widget>[
      const SizedBox(height: 2),
      Text(
        T(
          'Which staff are inside the JSK right now — updated live from the '
          'entry radar.',
        ),
        style: TextStyle(fontSize: 10.5, height: 1.4, color: context.faint),
      ),
      const SizedBox(height: 10),
      Row(
        children: <Widget>[
          Expanded(
            child: StatTile(
              value: '${live.length}',
              label: T('Working now'),
              variant: 'green',
            ),
          ),
          const SizedBox(width: 7),
          Expanded(
            child: StatTile(value: '$left', label: T('Left after checking in')),
          ),
        ],
      ),
      const SizedBox(height: 7),
      Row(
        children: <Widget>[
          Expanded(
            child: StatTile(value: '$notIn', label: T('Not checked in yet')),
          ),
          const SizedBox(width: 7),
          Expanded(
            child: StatTile(value: '$lateToday', label: T('Late today')),
          ),
        ],
      ),
      const SizedBox(height: 7),
      StatTile(
        value: clockText(now),
        label: T('Time now (live)'),
        variant: 'theme',
      ),
      const SizedBox(height: 12),
      _card(T('Staff on campus now'), <Widget>[
        if (live.isEmpty)
          Text(
            T(
              'No staff member is inside the institute zone right now. People '
              'appear the moment they check IN on the entry radar and drop off '
              'when they check OUT.',
            ),
            style: TextStyle(fontSize: 10.5, height: 1.4, color: context.soft),
          )
        else
          for (var i = 0; i < live.length; i++)
            _rowCard(<Widget>[
              Row(
                children: <Widget>[
                  Container(
                    width: 7,
                    height: 7,
                    decoration: const BoxDecoration(
                      color: Skin.green,
                      shape: BoxShape.circle,
                    ),
                  ),
                  const SizedBox(width: 7),
                  Avatar(name: (live[i]['name'] ?? '?').toString(), radius: 14),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: <Widget>[
                        Text(
                          (live[i]['name'] ?? '').toString(),
                          style: const TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                        Text(
                          'in ${shortTime24((recs[live[i]]?['inTs'] as num?)?.toInt())}',
                          style: TextStyle(fontSize: 9, color: context.faint),
                        ),
                      ],
                    ),
                  ),
                  Text(
                    fmtHours(s.workedMs(recs[live[i]]) ~/ 60000),
                    style: const TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w700,
                      color: Skin.green,
                    ),
                  ),
                ],
              ),
            ], index: i),
      ]),
      _card(T('Staff today'), <Widget>[
        if (staff.isEmpty)
          _note(T('No staff members yet.'))
        else
          for (var i = 0; i < staff.length; i++)
            _rowCard(<Widget>[
              Row(
                children: <Widget>[
                  Avatar(
                    name: (staff[i]['name'] ?? '?').toString(),
                    radius: 14,
                  ),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      (staff[i]['name'] ?? '').toString(),
                      style: const TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                  ),
                  Chip8(
                    recs[staff[i]] == null
                        ? '—'
                        : (recs[staff[i]]?['outTs'] == null
                              ? T('IN')
                              : T('OUT')),
                    color: recs[staff[i]] == null
                        ? Skin.navy
                        : (recs[staff[i]]?['outTs'] == null
                              ? Skin.green
                              : Skin.marigold),
                  ),
                ],
              ),
              const SizedBox(height: 8),
              Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: <Widget>[
                  Expanded(
                    child: _kv(
                      T('TODAY IN'),
                      shortTime24((recs[staff[i]]?['inTs'] as num?)?.toInt()),
                    ),
                  ),
                  Expanded(
                    child: _kv(
                      T('TODAY OUT'),
                      shortTime24((recs[staff[i]]?['outTs'] as num?)?.toInt()),
                    ),
                  ),
                  Expanded(
                    child: _kv(
                      T('HOURS TODAY'),
                      recs[staff[i]] == null
                          ? '—'
                          : fmtHours(s.workedMs(recs[staff[i]]) ~/ 60000),
                    ),
                  ),
                  Expanded(
                    child: _kv(
                      T('TARGET'),
                      '${s.targetOf(staff[i]).toStringAsFixed(0)}h',
                    ),
                  ),
                ],
              ),
            ], index: i),
      ]),
      _card(T('Late marks · of Staff'), <Widget>[
        if (remarks.isEmpty)
          _note(
            TT(
              'No late check-ins so far — everyone arrived within the {0} '
              'minute grace.',
              <String>['$SHIFT_GRACE_MIN'],
            ),
          )
        else
          for (var i = 0; i < remarks.length && i < 12; i++)
            _rowCard(<Widget>[
              Row(
                children: <Widget>[
                  Chip8(T('LATE'), color: Skin.red),
                  const SizedBox(width: 7),
                  Expanded(
                    child: Text(
                      TT(
                        '{0} checked in at {1} — {2} min past the shift ({3} min grace).',
                        <String>[
                          (remarks[i]['name'] ?? '—').toString(),
                          shortTime24((remarks[i]['inTs'] as num?)?.toInt()),
                          '${remarks[i]['lateMin'] ?? 0}',
                          '$SHIFT_GRACE_MIN',
                        ],
                      ),
                      style: TextStyle(
                        fontSize: 10,
                        height: 1.4,
                        color: context.soft,
                      ),
                    ),
                  ),
                ],
              ),
            ], index: i),
      ]),
    ];
  }
}

class AdminStaffDetailPage extends StatefulWidget {
  const AdminStaffDetailPage({super.key, required this.user});

  final Map<String, dynamic> user;

  @override
  State<AdminStaffDetailPage> createState() => _AdminStaffDetailPageState();
}

class _AdminStaffDetailPageState extends State<AdminStaffDetailPage> {
  Store get s => Store.I;
  late String _month = ymOf(todayStr());

  String _shiftMonth(String ym, int delta) {
    final p = ym.split('-');
    final d = DateTime(int.parse(p[0]), int.parse(p[1]) + delta, 1);
    return '${d.year}-${two(d.month)}';
  }

  List<Map<String, dynamic>> get _adjustments =>
      s
          .listOf('hourAdjustments')
          .where((a) => a['userId'] == s.viewStaffId)
          .toList()
        ..sort(
          (a, b) => ((b['ts'] as num?) ?? 0).compareTo((a['ts'] as num?) ?? 0),
        );

  List<Map<String, dynamic>> get _leaves =>
      s.leaveRequests.where((r) => r['userId'] == s.viewStaffId).toList()..sort(
        (a, b) => (b['date'].toString()).compareTo(a['date'].toString()),
      );

  @override
  Widget build(BuildContext context) {
    final p = s.userById(s.viewStaffId ?? '');
    if (p == null || p['role'] != 'staff') {
      return EmptyState(
        title: T('That staff member is no longer on the staff list.'),
      );
    }
    final id = p['id'].toString();
    final ym = _month;
    final recs = s.monthStaffRecords(id, ym).toList()
      ..sort((a, b) => (b['date'].toString()).compareTo(a['date'].toString()));
    final bank = s.hoursBalanceOf(id, ym);
    final todayRec = s.staffToday(id);
    final missed = s.missedCheckoutDaysOf(id, ym);
    final plDays = s.plDaysOf(id, ym);
    final target = s.targetOf(p).toStringAsFixed(0);

    return ListView(
      padding: const EdgeInsets.fromLTRB(14, 12, 14, 24),
      children: <Widget>[
        Row(
          children: <Widget>[
            IconButton(
              onPressed: () {
                s.viewStaffId = null;
                s.save(push: false);
                setState(() {});
              },
              visualDensity: VisualDensity.compact,
              icon: const Icon(Icons.arrow_back, size: 20),
            ),
            Expanded(
              child: Text(
                T('All staff'),
                style: const TextStyle(fontFamily: 'serif', fontSize: 18),
              ),
            ),
          ],
        ),
        Panel(
          margin: const EdgeInsets.only(bottom: 12),
          child: Row(
            children: <Widget>[
              PersonAvatar(
                name: (p['name'] ?? '?').toString(),
                photo: Store.I.photoOf(p),
                radius: 22,
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: <Widget>[
                    Text(
                      (p['name'] ?? '').toString(),
                      style: const TextStyle(
                        fontSize: 13,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                    const SizedBox(height: 2),
                    Text(
                      '${T('Office staff')} · '
                      '${TT('daily target {0}h', <String>[target])} · '
                      '${TT('shift {0}–{1}', <String>[fmtShift(s.shiftOf(p)), fmtShift(s.shiftEndOf(p))])}',
                      style: TextStyle(fontSize: 9.5, color: context.faint),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
        Panel(
          margin: const EdgeInsets.only(bottom: 12),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: <Widget>[
              SectionTitle(T('Staff login')),
              SizedBox(height: 7),
              Text(
                T('Login ID'),
                style: TextStyle(
                  fontSize: 8,
                  letterSpacing: .6,
                  color: context.faint,
                ),
              ),
              SelectableText(
                (p['email'] ?? '—').toString(),
                style: TextStyle(fontSize: 11, color: context.k.ink),
              ),
              OutlinedButton.icon(
                onPressed: () => resetAndShowTemporaryPassword(
                  context,
                  id,
                  (p['name'] ?? '').toString(),
                ),
                icon: Icon(Icons.lock_reset, size: 14),
                label: Text(T('Reset password')),
              ),
              Text(
                T(
                  'Current passwords cannot be viewed. Reset to issue a new temporary password once.',
                ),
                style: TextStyle(fontSize: 9.5, color: context.faint),
              ),
            ],
          ),
        ),
        Row(
          children: <Widget>[
            Expanded(
              child: StatTile(
                value: bank > 0
                    ? '+${fmtHours(bank)}'
                    : (bank < 0 ? '−${fmtHours(-bank)}' : '0h'),
                label: bank > 0
                    ? T('Banked overtime')
                    : (bank < 0 ? T('Pending hours') : T('Even')),
                variant: bank > 0 ? 'green' : 'plain',
                valueColor: bank < 0 ? Skin.red : null,
              ),
            ),
            const SizedBox(width: 7),
            Expanded(
              child: StatTile(
                value: todayRec == null
                    ? '—'
                    : fmtHours(s.workedMs(todayRec) ~/ 60000),
                label: T('Hours today'),
              ),
