class AdminTeachersPage extends StatefulWidget {
  const AdminTeachersPage({super.key, required this.user});

  final Map<String, dynamic> user;

  @override
  State<AdminTeachersPage> createState() => _AdminTeachersPageState();
}

class _AdminTeachersPageState extends State<AdminTeachersPage> {
  Store get s => Store.I;

  /// list = Teachers & batches · att = Month register · live = Live working
  String _view = 'list';
  String _month = ymOf(todayStr());
  Timer? _tick;

  final _q = TextEditingController();
  final _name = TextEditingController();
  final _email = TextEditingController();
  final _pass = TextEditingController();
  final _target = TextEditingController(text: '200');
  final _birthday = TextEditingController();
  final _batch = TextEditingController();
  final _subject = TextEditingController();

  String? _asgTeacher;
  String? _asgBatch;
  String? _asgSubject;

  /// The clock and the "on campus for" times tick once a second, and only
  /// while the Live working tab is the one on screen.
  void _setView(String v) {
    _tick?.cancel();
    _tick = null;
    if (v == 'live') {
      _tick = Timer.periodic(const Duration(seconds: 1), (_) {
        if (mounted) setState(() {});
      });
    }
    setState(() => _view = v);
  }

  @override
  void dispose() {
    _tick?.cancel();
    for (final c in <TextEditingController>[
      _q,
      _name,
      _email,
      _pass,
      _target,
      _birthday,
      _batch,
      _subject,
    ]) {
      c.dispose();
    }
    super.dispose();
  }

  // ---------------------------------------------------------------- helpers
  List<Map<String, dynamic>> get _teachers =>
      s.users.where((u) => u['role'] == 'teacher').toList();

  bool _hasBatch(Map<String, dynamic> st) =>
      s.batches.any((b) => b['id'] == st['batchId']);

  Map<String, dynamic>? get _pickedTeacher {
    final l = _teachers;
    if (l.isEmpty) return null;
    for (final t in l) {
      if (t['id'] == _asgTeacher) return t;
    }
    return l.first;
  }

  Map<String, dynamic>? get _pickedBatch {
    if (s.batches.isEmpty) return null;
    for (final b in s.batches) {
      if (b['id'] == _asgBatch) return b;
    }
    return s.batches.first;
  }

  Map<String, dynamic>? get _pickedSubject {
    if (s.subjects.isEmpty) return null;
    for (final x in s.subjects) {
      if (x['id'] == _asgSubject) return x;
    }
    return s.subjects.first;
  }

  String _assignedLine(String teacherId) {
    final parts = s
        .teacherAssignments(teacherId)
        .map(
          (a) =>
              '${s.batchName(a['batchId'])} · ${s.subjectName(a['subjectId'])}',
        )
        .toList();
    return parts.isEmpty ? '—' : parts.join(', ');
  }

  String _hoursToday(Map<String, dynamic>? rec) =>
      rec == null ? '—' : fmtHours(s.workedMs(rec) ~/ 60000);

  /// The office's search over teachers: name, email, phone, subject, batch.
  bool _matches(Map<String, dynamic> t, String q) {
    final words = q.toLowerCase().trim().split(RegExp(r'\s+'))
      ..removeWhere((w) => w.isEmpty);
    if (words.isEmpty) return true;
    final hay = <String>[
      (t['name'] ?? '').toString(),
      (t['email'] ?? '').toString(),
      (t['phone'] ?? '').toString(),
      'teacher',
      for (final a in s.teacherAssignments(t['id'].toString()))
        '${s.subjectName(a['subjectId'])} ${s.batchName(a['batchId'])}',
    ].join(' ').toLowerCase();
    return words.every(hay.contains);
  }

  ({int batches, int students, int subjects}) _load(Map<String, dynamic> t) {
    final asg = s.teacherAssignments(t['id'].toString());
    final batches = <String>{};
    final students = <String>{};
    var subjects = 0;
    for (final a in asg) {
      batches.add((a['batchId'] ?? '').toString());
      subjects++;
      for (final st in s.studentsInBatch(a['batchId'])) {
        students.add((st['id'] ?? '').toString());
      }
    }
    return (
      batches: batches.length,
      students: students.length,
      subjects: subjects,
    );
  }

  // ---------------------------------------------------------------- actions
  void _addTeacher() {
    final name = _name.text.trim();
    final email = _email.text.trim();
    if (name.isEmpty || email.isEmpty) {
      toast(context, T('A teacher needs a name and an email.'));
      return;
    }
    if (s.users.any(
      (u) => (u['email'] ?? '').toString().toLowerCase() == email.toLowerCase(),
    )) {
      toast(context, T('That email already has a login.'));
      return;
    }
    if (_pass.text.trim().length < 8) {
      toast(context, T('Use a temporary password with at least 8 characters.'));
      return;
    }
    final target = double.tryParse(_target.text.trim()) ?? 200;
    s.allowLogin(email);
    s.rawList('users').add(<String, dynamic>{
      'id': uid('u'),
      'name': name,
      'email': email,
      'password': _pass.text.trim(),
      'role': 'teacher',
      'monthlyTarget': target,
      'birthday': _birthday.text.trim(),
      'contact': '',
      'shift': '09:00',
      'shiftEnd': '17:00',
      'target': 8,
    });
    s.save();
    setState(() {
      _name.clear();
      _email.clear();
      _pass.clear();
      _target.text = '200';
      _birthday.clear();
    });
    toast(context, TT('{0} is added — login {1}', <String>[name, email]));
  }

  void _assignTeacher() {
    final t = _pickedTeacher;
    final b = _pickedBatch;
    final x = _pickedSubject;
    if (t == null || b == null || x == null) return;
    final has = s
        .teacherAssignments(t['id'].toString())
        .any((a) => a['batchId'] == b['id'] && a['subjectId'] == x['id']);
    if (has) {
      toast(context, T('That is already assigned.'));
      return;
    }
    s.rawList('assignments').add(<String, dynamic>{
      'id': uid('asg'),
      'teacherId': t['id'].toString(),
      'batchId': b['id'].toString(),
      'subjectId': x['id'].toString(),
      'chapters': <dynamic>[],
    });
    s.save();
    setState(() {});
    toast(
      context,
      TT('{0} now teaches {1} · {2}', <String>[
        t['name'].toString(),
        s.subjectName(x['id']),
        s.batchName(b['id']),
      ]),
    );
  }

  void _removeAssignment(Map<String, dynamic> t, Map<String, dynamic> a) {
    s.data['assignments'] = s.assignments
        .where((r) => r['id'] != a['id'])
        .toList();
    s.save();
    setState(() {});
    toast(
      context,
      TT('{0} no longer teaches {1} · {2}', <String>[
        t['name'].toString(),
        s.subjectName(a['subjectId']),
        s.batchName(a['batchId']),
      ]),
    );
  }

  void _removeTeacher(Map<String, dynamic> t) {
    final id = t['id'].toString();
    s.blockLogin((t['email'] ?? '').toString());
    s.data['users'] = s.users.where((u) => u['id'] != id).toList();
    s.data['assignments'] = s.assignments
        .where((a) => a['teacherId'] != id)
        .toList();
    s.save();
    setState(() {});
    toast(context, TT('{0} removed.', <String>[t['name'].toString()]));
  }

  void _addBatch(String name) {
    final nm = name.trim();
    if (nm.isEmpty) return;
    if (s.batches.any(
      (b) => (b['name'] ?? '').toString().toLowerCase() == nm.toLowerCase(),
    )) {
      toast(context, T('That batch already exists.'));
      return;
    }
    s.rawList('batches').add(<String, dynamic>{'id': uid('b'), 'name': nm});
    s.save();
    setState(() {});
    toast(context, TT('{0} added.', <String>[nm]));
  }

  void _removeBatch(Map<String, dynamic> b) {
    final id = b['id'].toString();
    // whoever was in it goes back to Not yet decided, and the teaching for it
    // goes with it
    for (final st in s.students) {
      if (st['batchId'] == id) st['batchId'] = '';
    }
    s.data['batches'] = s.batches.where((x) => x['id'] != id).toList();
    s.data['assignments'] = s.assignments
        .where((a) => a['batchId'] != id)
        .toList();
    s.save();
    setState(() {});
    toast(context, TT('{0} removed.', <String>[s.batchName(id)]));
  }

  void _setStudentBatch(Map<String, dynamic> st, String batchId) {
    st['batchId'] = batchId;
    s.save();
    final nm = batchId.isEmpty ? T('Not yet decided') : s.batchName(batchId);
    s.ntStudentAndGuardians(
      st,
      type: 'class_note',
      title: T('Your batch'),
      message: TT('Your batch is now {0}.', <String>[nm]),
      refType: 'student_batch',
      refId: st['id'].toString(),
      dedupKey: 'batch_${st['id']}_$batchId',
    );
    s.save();
    setState(() {});
    toast(context, TT('{0} → {1}', <String>[st['name'].toString(), nm]));
  }

  void _addSubject() {
    final nm = _subject.text.trim();
    if (nm.isEmpty) return;
    if (s.subjects.any(
      (x) => (x['name'] ?? '').toString().toLowerCase() == nm.toLowerCase(),
    )) {
      toast(context, T('That subject already exists.'));
      return;
    }
    s.rawList('subjects').add(<String, dynamic>{'id': uid('su'), 'name': nm});
    s.save();
    setState(() => _subject.clear());
    toast(context, TT('{0} added.', <String>[nm]));
  }

  void _removeSubject(Map<String, dynamic> x) {
    final id = x['id'].toString();
    s.data['subjects'] = s.subjects.where((y) => y['id'] != id).toList();
    s.data['assignments'] = s.assignments
        .where((a) => a['subjectId'] != id)
        .toList();
    s.save();
    setState(() {});
    toast(context, TT('{0} removed.', <String>[x['name'].toString()]));
  }

  void _openTeacher(Map<String, dynamic> t) {
    s.viewTeacherId = t['id'].toString();
    s.save(push: false);
    setState(() {});
  }

  String _shiftMonth(String ym, int delta) {
    final p = ym.split('-');
    final d = DateTime(int.parse(p[0]), int.parse(p[1]) + delta, 1);
    return '${d.year}-${two(d.month)}';
  }

  String _monthShortOf(String ym) {
    final p = ym.split('-');
    return '${kMonthShort[int.parse(p[1]) - 1]} ${p[0]}';
  }

  // ------------------------------------------------------------------- look
  Widget _field(
    String label,
    TextEditingController c, {
    String? hint,
    TextInputType? keyboard,
    bool obscure = false,
  }) => Padding(
    padding: const EdgeInsets.only(bottom: 9),
    child: Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: <Widget>[
        _label(label),
        TextField(
          controller: c,
          keyboardType: keyboard,
          obscureText: obscure,
          style: const TextStyle(fontSize: 13),
          decoration: InputDecoration(hintText: hint),
        ),
      ],
    ),
  );

  Widget _label(String text) => Padding(
    padding: const EdgeInsets.only(bottom: 4),
    child: Text(
      text,
      style: TextStyle(
        fontSize: 11,
        fontWeight: FontWeight.w600,
        color: context.k.inkSoft,
      ),
    ),
  );

  Widget _pick(
    String label,
    String? value,
    List<MapEntry<String, String>> items,
    ValueChanged<String?> onPick,
  ) {
    final known = items.any((i) => i.key == value);
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: <Widget>[
        _label(label),
        DropdownButtonFormField<String>(
          value: known ? value : items.first.key,
          isDense: true,
          isExpanded: true,
          decoration: const InputDecoration(),
          items: <DropdownMenuItem<String>>[
            for (final i in items)
              DropdownMenuItem<String>(
                value: i.key,
                child: Text(
                  i.value,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(fontSize: 12.5),
                ),
              ),
          ],
          onChanged: onPick,
        ),
      ],
    );
  }

  Widget _searchBox(
    TextEditingController c,
    String hint, {
    VoidCallback? onChanged,
  }) => Container(
    decoration: BoxDecoration(
      color: context.k.surface2,
      border: Border.all(color: context.k.line),
      borderRadius: BorderRadius.circular(9),
    ),
    padding: const EdgeInsets.symmetric(horizontal: 10),
    child: TextField(
      controller: c,
      onChanged: (_) {
        if (onChanged != null) onChanged();
      },
      style: TextStyle(fontSize: 12.5, color: context.k.ink),
      decoration: InputDecoration(
        hintText: hint,
        isDense: true,
        filled: false,
        border: InputBorder.none,
        enabledBorder: InputBorder.none,
        focusedBorder: InputBorder.none,
        contentPadding: const EdgeInsets.symmetric(vertical: 12),
        prefixIcon: const Icon(Icons.search, size: 16),
        prefixIconConstraints: const BoxConstraints(
          minWidth: 30,
          minHeight: 30,
        ),
      ),
    ),
  );

  Widget _kv(String label, String value, {Color? color, double size = 11.5}) =>
      Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          Text(
            label,
            style: TextStyle(
              fontSize: 8.5,
              letterSpacing: .3,
              fontWeight: FontWeight.w700,
              color: context.faint,
            ),
          ),
          const SizedBox(height: 3),
          Text(
            value,
            style: TextStyle(
              fontSize: size,
              fontWeight: FontWeight.w600,
              color: color ?? context.k.ink,
            ),
          ),
        ],
      );

  Widget _note(String text) => Text(
    text,
    style: TextStyle(fontSize: 9.5, height: 1.45, color: context.faint),
