    return ListView(
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 24),
      children: <Widget>[
        PageHeading(
          T('Teachers & batches'),
          T(
            'Set up batches, subjects, teacher accounts, and who can take '
            'attendance for what.',
          ),
          Icons.school_outlined,
