  Widget _teacherFinderCard(Map<String, dynamic> t, int i, String ym) {
    final load = _load(t);
    final asg = s.teacherAssignments(t['id'].toString());
    final bits = <String>[
      if (load.batches > 0)
        '${load.batches} ${load.batches == 1 ? 'batch' : 'batches'}',
      if (load.students > 0)
        '${load.students} ${load.students == 1 ? 'student' : 'students'}',
      '${fmtHours(s.monthWorkedMin(t['id'].toString(), ym))} of '
          '${s.monthlyTargetOf(t).toStringAsFixed(0)}h this month',
    ];
    return _rowCard(<Widget>[
      Row(
        children: <Widget>[
          Avatar(name: (t['name'] ?? '?').toString(), radius: 14),
          const SizedBox(width: 8),
          Expanded(
            child: Text(
              (t['name'] ?? '').toString(),
              style: const TextStyle(
                fontSize: 12.5,
                fontWeight: FontWeight.w800,
              ),
            ),
          ),
          _smallBtn(T('View everything'), () => _openTeacher(t)),
        ],
      ),
      const SizedBox(height: 7),
      if (asg.isEmpty)
        Text(
          T('No subject assigned yet'),
          style: TextStyle(fontSize: 10.5, color: context.faint),
        )
      else
        Wrap(
          spacing: 10,
          runSpacing: 4,
          children: <Widget>[
            for (final a in asg)
              Text(
                '${s.subjectName(a['subjectId'])} · ${s.batchName(a['batchId'])}',
                style: TextStyle(fontSize: 10.5, color: context.soft),
              ),
          ],
        ),
      const SizedBox(height: 5),
      Text(
        bits.join(' · '),
        style: TextStyle(fontSize: 9, color: context.faint),
      ),
    ], index: i);
  }

  List<Widget> _subjectRows(List<Map<String, dynamic>> shownTeachers) {
    final q = _q.text.trim().toLowerCase();
    final out = <Widget>[];
    for (final x in s.subjects) {
      final who = <Map<String, dynamic>>[];
      for (final a in s.assignments) {
        if (a['subjectId'] != x['id']) continue;
        for (final t in _teachers) {
          if (t['id'] == a['teacherId'] &&
              !who.any((w) => w['id'] == t['id'])) {
            who.add(t);
          }
        }
      }
      if (q.isNotEmpty && !who.any((t) => _matches(t, q))) continue;
      out.add(
        _rowCard(<Widget>[
          Row(
            children: <Widget>[
              Expanded(
                flex: 3,
                child: _kv(
                  T('SUBJECT'),
                  (x['name'] ?? '').toString(),
                  size: 12.5,
                ),
