  // ==================================================================
  //  Two — Teacher attendance (month register)
  // ==================================================================
  List<Widget> _attTab(BuildContext context) {
    final teachers = _teachers;
    final ym = _month;
    final p = ym.split('-');
    final year = int.parse(p[0]);
    final month = int.parse(p[1]);
    final daysInMonth = DateTime(year, month + 1, 0).day;

    final stats =
        <
          Map<String, dynamic>,
          ({int days, int totalMs, int? inAvg, int? outAvg, int outCount})
        >{
          for (final t in teachers)
            t: s.staffMonthStatsOf(t['id'].toString(), ym),
        };
    var checkInDays = 0;
    var totalMs = 0;
    var inSum = 0;
    var inCount = 0;
    var outSum = 0;
    var outCount = 0;
    for (final st in stats.values) {
      checkInDays += st.days;
      totalMs += st.totalMs;
      if (st.inAvg != null) {
        inSum += st.inAvg!;
        inCount++;
      }
      if (st.outAvg != null) {
        outSum += st.outAvg!;
        outCount++;
      }
    }
    final avgIn = inCount == 0 ? null : (inSum / inCount).round();
    final avgOut = outCount == 0 ? null : (outSum / outCount).round();

    return <Widget>[
      const SizedBox(height: 2),
      Text(
        T(
          'Every check-in and check-out of the whole month, one by one, with an '
          'analysis of their timings.',
        ),
        style: TextStyle(fontSize: 10.5, height: 1.4, color: context.faint),
      ),
      const SizedBox(height: 10),
      Row(
        children: <Widget>[
          Expanded(
            child: StatTile(
              value: '${teachers.length}',
              label: T('Staff members'),
            ),
          ),
          const SizedBox(width: 7),
          Expanded(
            child: StatTile(value: '$checkInDays', label: T('Check-in days')),
          ),
        ],
      ),
      const SizedBox(height: 7),
      Row(
        children: <Widget>[
          Expanded(
            child: StatTile(value: minToClock(avgIn), label: T('Avg check-in')),
          ),
          const SizedBox(width: 7),
          Expanded(
            child: StatTile(
              value: minToClock(avgOut),
              label: T('Avg check-out'),
            ),
          ),
        ],
      ),
      const SizedBox(height: 7),
      StatTile(
        value: totalMs == 0 ? '—' : fmtHours(totalMs ~/ 60000),
        label: T('Total time on campus'),
        variant: 'theme',
      ),
      const SizedBox(height: 12),
      Panel(
        margin: const EdgeInsets.only(bottom: 12),
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
        child: Row(
          children: <Widget>[
            _smallBtn('‹ ${_monthShortOf(_shiftMonth(ym, -1))}', () {
              setState(() => _month = _shiftMonth(_month, -1));
            }),
            Expanded(
              child: Center(
                child: Text(
                  monthLabelLong(ym),
                  style: TextStyle(
                    fontFamily: Skin.serif,
                    fontSize: 14,
                    fontWeight: FontWeight.w700,
                    color: context.k.ink,
                  ),
                ),
              ),
            ),
            _smallBtn('${_monthShortOf(_shiftMonth(ym, 1))} ›', () {
              setState(() => _month = _shiftMonth(_month, 1));
            }),
          ],
        ),
      ),
      if (teachers.isEmpty)
        _card(T('Teachers · Month register'), <Widget>[
          Text(
            T('No teachers yet.'),
            style: TextStyle(fontSize: 11, color: context.soft),
          ),
        ])
      else
        for (var i = 0; i < teachers.length; i++)
          _monthCard(
            teachers[i],
            stats[teachers[i]]!,
            ym,
            daysInMonth,
            year,
            month,
            i,
          ),
    ];
  }

  Widget _monthCard(
    Map<String, dynamic> t,
    ({int days, int totalMs, int? inAvg, int? outAvg, int outCount}) st,
    String ym,
    int daysInMonth,
    int year,
    int month,
    int i,
  ) {
    final id = t['id'].toString();
    final targetMin = (s.monthlyTargetOf(t) * 60).round();
    final leftMin = targetMin - (st.totalMs ~/ 60000);
    final facts = <String>[
      '${st.days} ${st.days == 1 ? 'day' : 'days'} this month',
      '${fmtHours(st.totalMs ~/ 60000)} on campus',
      leftMin <= 0
          ? 'month target ${(targetMin / 60).toStringAsFixed(0)}h met ✓'
          : 'month target ${(targetMin / 60).toStringAsFixed(0)}h — '
                '${fmtHours(leftMin)} left',
    ];

    return Panel(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.fromLTRB(12, 12, 12, 12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          Row(
            children: <Widget>[
              Avatar(name: (t['name'] ?? '?').toString(), radius: 15),
              const SizedBox(width: 9),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: <Widget>[
                    Text(
                      (t['name'] ?? '').toString(),
                      style: const TextStyle(
                        fontSize: 12.5,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                    const SizedBox(height: 2),
                    Text(
                      facts.join(' · '),
                      style: TextStyle(
                        fontSize: 9,
                        height: 1.4,
                        color: context.faint,
                      ),
                    ),
                    Text(
                      st.outCount == 0
                          ? 'Avg in ${minToClock(st.inAvg)}'
                          : 'Avg in ${minToClock(st.inAvg)} · avg out ${minToClock(st.outAvg)}',
                      style: TextStyle(fontSize: 9, color: context.faint),
                    ),
                  ],
                ),
              ),
            ],
          ),
          const SizedBox(height: 10),
          LayoutBuilder(
            builder: (context, box) {
              final w = (box.maxWidth - 6 * 5) / 7;
              final recs = s.monthStaffRecords(id, ym);
              return Wrap(
                spacing: 5,
                runSpacing: 5,
                children: <Widget>[
                  for (var d = 1; d <= daysInMonth; d++)
                    _dayCell(t, ym, d, w, recs),
                ],
              );
            },
          ),
        ],
      ),
    );
  }

  Widget _dayCell(
    Map<String, dynamic> t,
    String ym,
    int day,
    double width,
    List<Map<String, dynamic>> recs,
  ) {
    final k = context.k;
    final date = '$ym-${two(day)}';
    Map<String, dynamic>? rec;
    for (final r in recs) {
      if (r['date'] == date) {
        rec = r;
        break;
      }
    }
    final hol = s.holidayOn(date);
    // A leave day on the calendar is only ever the one the office APPROVED —
    // a request that is still pending must not colour anybody's month.
    final leave = s.leaveRequests.any(
      (r) =>
          r['userId'] == t['id'] &&
          r['date'] == date &&
          r['status'] == 'accepted',
    );
    final absent = s.plDaysOf(t['id'].toString(), ym).contains(date);

    var head = two(day);
    String? inTxt;
    String foot;
    Color bg = k.surface2;
    Color line = k.line;
    Color ink = k.ink;
    Color sub = k.faint;

    if (rec != null) {
      inTxt = shortTime24((rec['inTs'] as num?)?.toInt());
      final out = (rec['outTs'] as num?)?.toInt();
      foot = out == null ? 'in' : shortTime24(out);
      if (hol != null) foot = '$foot · HOL';
      bg = Skin.green.withValues(alpha: .13);
      line = Skin.green.withValues(alpha: .38);
      ink = Skin.green;
      sub = k.inkSoft;
    } else if (hol != null) {
      // only a holiday the Admin declared for the whole institute
      foot = 'HOL';
      bg = Skin.navy.withValues(alpha: .07);
    } else if (leave) {
      foot = 'OFF';
      bg = Skin.navy.withValues(alpha: .07);
    } else if (absent) {
      foot = 'AB';
      bg = Skin.red.withValues(alpha: .10);
      line = Skin.red.withValues(alpha: .30);
      sub = Skin.red;
    } else {
      // a plain working day — nothing is written on it until the Admin gives a
      // holiday or the office approves a leave
      foot = '—';
    }

    return Container(
      width: width,
      padding: const EdgeInsets.symmetric(vertical: 5, horizontal: 2),
      decoration: BoxDecoration(
        color: bg,
        borderRadius: BorderRadius.circular(7),
        border: Border.all(color: line),
      ),
      child: Column(
        children: <Widget>[
          Text(
            head,
            style: TextStyle(
              fontSize: 8.5,
              fontWeight: FontWeight.w700,
              color: sub,
            ),
          ),
          if (inTxt != null)
            Text(
              inTxt,
              style: TextStyle(
                fontSize: 8.5,
                fontWeight: FontWeight.w700,
                color: ink,
              ),
            ),
          Text(
            foot,
            style: TextStyle(fontSize: inTxt == null ? 8.5 : 8, color: sub),
          ),
        ],
      ),
    );
  }

  // ==================================================================
  //  Three — Live working
  // ==================================================================
  List<Widget> _liveTab(BuildContext context) {
    final teachers = _teachers.toList()
      ..sort(
        (a, b) => (a['name'] ?? '').toString().compareTo(
          (b['name'] ?? '').toString(),
        ),
      );
    final today = todayStr();
    final recs = <Map<String, dynamic>, Map<String, dynamic>?>{
      for (final t in teachers) t: s.staffRecordOn(t['id'].toString(), today),
    };
    final live =
        teachers.where((t) {
          final r = recs[t];
          return r != null && r['inTs'] != null && r['outTs'] == null;
        }).toList()..sort(
          (a, b) => ((recs[a]?['inTs'] as num?) ?? 0).compareTo(
            (recs[b]?['inTs'] as num?) ?? 0,
          ),
        );
    final left = teachers.where((t) => recs[t]?['outTs'] != null).length;
    final notIn = teachers.where((t) => recs[t] == null).length;
    final remarks = s.lateRemarksFor('teacher');
    final lateToday = remarks.where((r) => r['date'] == today).length;
    final now = DateTime.now();

    return <Widget>[
      const SizedBox(height: 2),
      Text(
        T(
          'Which teachers are inside the JSK right now — updated live from the '
          'entry radar.',
        ),
        style: TextStyle(fontSize: 10.5, height: 1.4, color: context.faint),
      ),
      const SizedBox(height: 10),
      Row(
        children: <Widget>[
          Expanded(
            child: StatTile(
              value: '${live.length}',
              label: T('Working now'),
              variant: 'green',
            ),
          ),
          const SizedBox(width: 7),
          Expanded(
            child: StatTile(value: '$left', label: T('Left after checking in')),
          ),
        ],
      ),
      const SizedBox(height: 7),
      Row(
        children: <Widget>[
          Expanded(
            child: StatTile(value: '$notIn', label: T('Not checked in yet')),
          ),
          const SizedBox(width: 7),
          Expanded(
            child: StatTile(value: '$lateToday', label: T('Late today')),
          ),
        ],
      ),
      const SizedBox(height: 7),
      StatTile(
        value: clockText(now),
        label: T('Time now (live)'),
        variant: 'theme',
      ),
      const SizedBox(height: 12),
      _card(T('Teachers on campus now'), <Widget>[
        if (live.isEmpty)
          Text(
            T(
              'No teachers member is inside the institute zone right now. '
              'People appear the moment they check IN on the entry radar and '
              'drop off when they check OUT.',
            ),
            style: TextStyle(fontSize: 10.5, height: 1.4, color: context.soft),
          )
        else
          for (var i = 0; i < live.length; i++)
            _rowCard(<Widget>[
              Row(
                children: <Widget>[
                  Container(
                    width: 7,
                    height: 7,
                    decoration: const BoxDecoration(
                      color: Skin.green,
                      shape: BoxShape.circle,
                    ),
                  ),
                  const SizedBox(width: 7),
                  Avatar(name: (live[i]['name'] ?? '?').toString(), radius: 14),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: <Widget>[
                        Text(
                          (live[i]['name'] ?? '').toString(),
                          style: const TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                        Text(
                          'in ${shortTime24((recs[live[i]]?['inTs'] as num?)?.toInt())}'
                          ' · ${fmtHours(s.workedMs(recs[live[i]]) ~/ 60000)}',
                          style: TextStyle(fontSize: 9, color: context.faint),
                        ),
                      ],
                    ),
                  ),
                  Text(
                    fmtHours(s.workedMs(recs[live[i]]) ~/ 60000),
                    style: const TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w700,
                      color: Skin.green,
                    ),
                  ),
                ],
              ),
            ], index: i),
      ]),
      _card(T('Teachers today'), <Widget>[
        if (teachers.isEmpty)
          Text(
            T('No teachers yet.'),
            style: TextStyle(fontSize: 11, color: context.soft),
          )
        else
          for (var i = 0; i < teachers.length; i++)
            _rowCard(<Widget>[
              Row(
                children: <Widget>[
                  Avatar(
                    name: (teachers[i]['name'] ?? '?').toString(),
                    radius: 14,
                  ),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      (teachers[i]['name'] ?? '').toString(),
                      style: const TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                  ),
                  Chip8(
                    recs[teachers[i]] == null
                        ? '—'
                        : (recs[teachers[i]]?['outTs'] == null
                              ? T('IN')
                              : T('OUT')),
                    color: recs[teachers[i]] == null
                        ? Skin.navy
                        : (recs[teachers[i]]?['outTs'] == null
                              ? Skin.green
                              : Skin.marigold),
                  ),
                ],
              ),
              const SizedBox(height: 8),
              Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: <Widget>[
                  Expanded(
                    child: _kv(
                      T('TODAY IN'),
                      shortTime24(
                        (recs[teachers[i]]?['inTs'] as num?)?.toInt(),
                      ),
                    ),
                  ),
                  Expanded(
                    child: _kv(
                      T('TODAY OUT'),
                      shortTime24(
                        (recs[teachers[i]]?['outTs'] as num?)?.toInt(),
                      ),
                    ),
                  ),
                  Expanded(
                    child: _kv(
                      T('HOURS TODAY'),
                      _hoursToday(recs[teachers[i]]),
                    ),
                  ),
                  Expanded(
                    child: _kv(
                      T('STATUS'),
                      recs[teachers[i]] == null
                          ? '—'
                          : (recs[teachers[i]]?['outTs'] == null
                                ? T('In')
                                : T('Out')),
                    ),
                  ),
                ],
              ),
            ], index: i),
      ]),
    ];
  }
}

