  }

  Widget _kv(BuildContext context, String k, String v) => Padding(
    padding: EdgeInsets.symmetric(vertical: 3),
    child: Row(
      children: [
        SizedBox(
          width: 92,
          child: Text(
            k.toUpperCase(),
            style: TextStyle(
              fontSize: 8,
              letterSpacing: .6,
              color: context.faint,
            ),
          ),
        ),
        Expanded(
          child: Text(
            v,
            textAlign: TextAlign.right,
            style: TextStyle(fontSize: 10.5),
          ),
        ),
      ],
    ),
  );

  Future<void> _timings(BuildContext context, Map<String, dynamic> t) async {
    final target = TextEditingController(
      text: s.targetOf(t).toStringAsFixed(0),
    );
    final monthly = TextEditingController(
      text: s.monthlyTargetOf(t).toStringAsFixed(0),
    );
    final shift = TextEditingController(text: s.shiftOf(t));
    final shiftEnd = TextEditingController(text: s.shiftEndOf(t));
    final days = s
        .lateDaysOf(t)
        .map((d) => Map<String, dynamic>.from(d))
        .toList();

    await showDialog<void>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setLocal) => AlertDialog(
          title: Text(
            TT("{0} · timings", [t['name']]),
            style: TextStyle(fontSize: 14),
          ),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Row(
                  children: [
                    Expanded(
                      child: Field(
                        label: T('Daily target (h)'),
                        controller: target,
                        keyboard: TextInputType.number,
                      ),
                    ),
                    SizedBox(width: 8),
                    Expanded(
                      child: Field(
                        label: T('Monthly target (h)'),
                        controller: monthly,
                        keyboard: TextInputType.number,
                      ),
                    ),
                  ],
                ),
                Row(
                  children: [
                    Expanded(
                      child: Field(
                        label: T('Shift start'),
                        controller: shift,
                        hint: T('09:00'),
                      ),
                    ),
                    SizedBox(width: 8),
                    Expanded(
                      child: Field(
                        label: T('Shift end'),
                        controller: shiftEnd,
                        hint: T('13:00'),
                      ),
                    ),
                  ],
                ),
                SmallLabel(T('SPECIAL DAY TIMINGS')),
                for (var i = 0; i < days.length; i++)
                  Padding(
                    padding: EdgeInsets.only(bottom: 6),
                    child: Row(
                      children: [
                        Expanded(
                          child: Text(
                            TT("{0} · {1}–{2}", [
                              days[i]['day'],
                              days[i]['start'],
                              days[i]['end'],
                            ]),
                            style: TextStyle(fontSize: 10.5),
                          ),
                        ),
                        IconButton(
                          visualDensity: VisualDensity.compact,
                          onPressed: () => setLocal(() => days.removeAt(i)),
                          icon: Icon(Icons.close, size: 15),
                        ),
                      ],
                    ),
                  ),
                if (days.length < 7)
                  TextButton.icon(
                    onPressed: () => setLocal(
                      () => days.add({
                        'day': 'Saturday',
                        'start': '10:00',
                        'end': '14:00',
                      }),
                    ),
                    icon: Icon(Icons.add, size: 14),
                    label: Text(
                      T('Add a late day'),
                      style: TextStyle(fontSize: 10),
                    ),
                  ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: Text(T('Cancel')),
            ),
            FilledButton(
              onPressed: () {
                t['target'] =
                    double.tryParse(target.text.trim()) ?? s.targetOf(t);
                t['monthlyTarget'] =
                    double.tryParse(monthly.text.trim()) ??
                    s.monthlyTargetOf(t);
                t['shift'] = shift.text.trim();
                t['shiftEnd'] = shiftEnd.text.trim();
                t['lateDays'] = days;
                s.save();
                Navigator.pop(ctx);
                setState(() {});
                toast(context, T('Timings saved.'));
              },
              child: Text(T('Save')),
            ),
          ],
        ),
      ),
    );
  }
}

/// Admin → Admins. The same screen as the website: add an admin by email,
/// read the login details to share, then edit a name, reset a password or
/// remove an admin from the current list.
class AdminAdminsPage extends StatefulWidget {
  const AdminAdminsPage({super.key, required this.user});

  final Map<String, dynamic> user;

  @override
  State<AdminAdminsPage> createState() => _AdminAdminsPageState();
}

class _AdminAdminsPageState extends State<AdminAdminsPage> {
  Store get s => Store.I;

  final _name = TextEditingController();
  final _email = TextEditingController();
  final _editName = TextEditingController();

  /// the line under the form, like the website's `errMsg`
  String? _err;

  /// the admin whose name is being edited right now
  String? _editing;

  @override
  void dispose() {
    for (final c in <TextEditingController>[_name, _email, _editName]) {
      c.dispose();
    }
    super.dispose();
  }

  // ---------------------------------------------------------------- people
  List<Map<String, dynamic>> get _admins =>
      s.users.where((u) => u['role'] == 'admin').toList();

  bool _isMe(Map<String, dynamic> a) =>
      (a['id'] ?? '').toString() == (widget.user['id'] ?? '').toString();

  String _newPassword() => secureTemporaryPassword();

  static bool _validEmail(String v) =>
      RegExp(r'^[^\s@]+@[^\s@]+\.[^\s@]+$').hasMatch(v);

  // --------------------------------------------------------------- actions
  void _addAdmin() {
    final name = _name.text.trim();
    final email = _email.text.trim().toLowerCase();
    if (name.isEmpty) {
      setState(() => _err = T("Please enter the admin's name."));
      return;
    }
    if (!_validEmail(email)) {
      setState(() => _err = T('Please enter a valid email ID.'));
      return;
    }
    if (s.users.any(
      (u) => (u['email'] ?? '').toString().toLowerCase() == email,
    )) {
      setState(() => _err = T('That email already has an account.'));
      return;
    }
    final pw = _newPassword();
    s.allowLogin(email);
    s.rawList('users').add(<String, dynamic>{
      'id': uid('usr'),
      'role': 'admin',
      'name': name,
      'email': email,
      'password': pw,
    });
    s.setLastAdminInvite(<String, dynamic>{
      'name': name,
      'email': email,
      'pw': pw,
    });
    s.save();
    FocusScope.of(context).unfocus();
    _name.clear();
    _email.clear();
    setState(() => _err = null);
    toast(context, TT('{0} now has admin powers.', <String>[name]));
  }

  void _saveName(Map<String, dynamic> a) {
    final v = _editName.text.trim();
    if (v.isEmpty) return;
    a['name'] = v;
    s.save();
    setState(() => _editing = null);
    toast(context, T('Name updated.'));
  }

  Future<void> _resetPassword(Map<String, dynamic> a) async {
    await resetAndShowTemporaryPassword(
      context,
      (a['id'] ?? '').toString(),
      (a['name'] ?? '').toString(),
    );
  }

  Future<void> _removeAdmin(Map<String, dynamic> a) async {
    final admins = _admins;
    if (_isMe(a) || admins.length <= 1) return;
    final sure = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(
          TT('Remove {0} as admin?', <String>[a['name'].toString()]),
          style: const TextStyle(fontSize: 14),
        ),
        content: Text(
          T('Their login is deleted.'),
          style: const TextStyle(fontSize: 12),
        ),
        actions: <Widget>[
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: Text(T('Keep')),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: Text(T('Remove')),
          ),
        ],
      ),
    );
    if (sure != true || !mounted) return;
    final email = (a['email'] ?? '').toString();
    s.blockLogin(email);
    s.data['users'] = s.users.where((x) => x['id'] != a['id']).toList();
    final invite = s.lastAdminInvite;
    if (invite != null && (invite['email'] ?? '').toString() == email) {
      s.setLastAdminInvite(null);
    }
    s.save();
    setState(() {});
    toast(context, TT('{0} removed as admin.', <String>[a['name'].toString()]));
  }

  // ------------------------------------------------------------------ ui
  Widget _kv(String label, String value, {bool mono = false}) => Padding(
    padding: const EdgeInsets.only(bottom: 7),
    child: Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: <Widget>[
        SizedBox(
          width: 78,
          child: Text(
            label.toUpperCase(),
            style: TextStyle(
              fontSize: 10,
              letterSpacing: .5,
              fontWeight: FontWeight.w700,
              color: context.faint,
            ),
          ),
        ),
        Expanded(
          child: Text(
            value,
            style: TextStyle(
              fontSize: mono ? 12.5 : 12.8,
              fontFamily: mono ? Skin.mono : null,
              fontWeight: mono ? FontWeight.w700 : FontWeight.w600,
              color: context.k.ink,
            ),
          ),
        ),
      ],
    ),
  );

  Widget _smallBtn(String label, VoidCallback tap, {bool disabled = false}) =>
      Opacity(
        opacity: disabled ? .45 : 1,
        child: Pressable(
          onTap: disabled ? null : tap,
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 11, vertical: 7),
            decoration: BoxDecoration(
              color: context.k.surface,
              borderRadius: BorderRadius.circular(999),
              border: Border.all(color: context.k.lineStrong),
            ),
            child: Text(
              label,
              style: TextStyle(
                fontSize: 10.5,
                fontWeight: FontWeight.w700,
                color: context.k.inkSoft,
              ),
            ),
          ),
        ),
      );

  Widget _adminCard(Map<String, dynamic> a) {
    final k = context.k;
    final me = _isMe(a);
    final name = (a['name'] ?? '').toString();
    final id = (a['id'] ?? '').toString();
    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.fromLTRB(12, 11, 12, 11),
      decoration: BoxDecoration(
        color: k.surface2,
        borderRadius: BorderRadius.circular(k.radius),
        border: Border.all(color: k.line),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          Row(
            children: <Widget>[
              Avatar(name: name, radius: 15, color: Skin.navy),
              const SizedBox(width: 9),
              Expanded(
                child: Text(
                  name,
                  style: TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w700,
                    color: k.ink,
                  ),
                ),
              ),
              if (me) Chip8(T('You'), color: Skin.green),
            ],
          ),
          const SizedBox(height: 9),
          _kv(T('Email'), (a['email'] ?? '').toString()),
          if (_editing == id)
            Padding(
              padding: const EdgeInsets.only(top: 2, bottom: 6),
              child: Column(
                children: <Widget>[
                  Field(label: T('Name'), controller: _editName),
                  Row(
                    children: <Widget>[
                      Expanded(
                        child: FilledButton(
                          onPressed: () => _saveName(a),
                          child: Text(T('Save')),
                        ),
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: OutlinedButton(
                          onPressed: () => setState(() => _editing = null),
                          child: Text(T('Cancel')),
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),
          Wrap(
            spacing: 6,
            runSpacing: 6,
            children: <Widget>[
              _smallBtn(T('Edit name'), () {
                _editName.text = name;
                setState(() => _editing = id);
              }),
              _smallBtn(T('Reset password'), () => _resetPassword(a)),
              _smallBtn(
                T('Remove'),
                () => _removeAdmin(a),
                disabled: me || _admins.length <= 1,
              ),
            ],
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final k = context.k;
    final admins = _admins;
    final invite = s.lastAdminInvite;
    final inviteName = (invite?['name'] ?? '').toString().isEmpty
        ? (invite?['email'] ?? '').toString()
        : invite!['name'].toString();
    return ListView(
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 24),
      children: <Widget>[
        PageHeading(
          T('Admins'),
          T('Add more admins, share their login details, and manage access.'),
          Icons.shield_outlined,
        ),

        // ---- add an admin ----
        Panel(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: <Widget>[
              SectionTitle(T('Add an admin')),
              Text(
                T(
                  "Enter the person's email ID. An admin login is created "
                  'instantly — you get the password to share with them, and '
                  'they get full admin powers when they sign in.',
                ),
                style: TextStyle(
                  fontSize: 12.2,
                  height: 1.45,
                  color: k.inkSoft,
                ),
              ),
              const SizedBox(height: 12),
              Field(
                label: T('Name'),
                controller: _name,
                hint: T('e.g. Priya Sharma'),
              ),
              Field(
                label: T('Email ID'),
                controller: _email,
                hint: T('e.g. priya@jskinstitute.com'),
                keyboard: TextInputType.emailAddress,
              ),
              if (_err != null)
                Padding(
                  padding: const EdgeInsets.only(bottom: 8),
                  child: Text(
                    _err!,
                    style: TextStyle(fontSize: 11.5, color: Skin.brick),
                  ),
                ),
              SizedBox(
                width: double.infinity,
                child: FilledButton(
                  onPressed: _addAdmin,
                  child: Text(T('Add admin')),
                ),
              ),
            ],
          ),
        ),

        // ---- the details to hand over ----
        if (invite != null)
          Panel(
            borderColor: Skin.green,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: <Widget>[
                SectionTitle(T('Login details to share')),
                Text(
                  T(
                    'Share these login details once. The password will not '
                    'be shown again after you leave this page.',
                  ),
                  style: TextStyle(
                    fontSize: 12.2,
                    height: 1.45,
                    color: k.inkSoft,
                  ),
                ),
                const SizedBox(height: 10),
                _kv(T('Name'), inviteName),
                _kv(T('Email'), (invite['email'] ?? '').toString()),
                _kv(T('Password'), (invite['pw'] ?? '').toString(), mono: true),
              ],
            ),
          ),

        // ---- who is an admin right now ----
        Panel(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: <Widget>[
              SectionTitle(T('Current admins')),
              for (final a in admins) _adminCard(a),
              Text(
                T(
                  'Passwords are securely stored by Supabase Auth and are not '
                  'shown in account lists. Use Reset password to issue a new one.',
                ),
                style: TextStyle(fontSize: 11.5, height: 1.4, color: k.faint),
              ),
            ],
          ),
        ),
      ],
    );
  }
}

