/// Midnight stock with a woven gold monogram, so the faculty card catches the
/// light differently from the paper-white student pass.
class _FacultyTexture extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final line = Paint()
      ..color = Colors.white.withValues(alpha: .022)
      ..strokeWidth = 1;
    for (var x = -size.height; x < size.width; x += 11) {
      canvas.drawLine(
        Offset(x.toDouble(), size.height),
        Offset(x + size.height, 0),
        line,
      );
    }

    final gold = Paint()
      ..color = _IdCardPageState._facGold.withValues(alpha: .05)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.1;
    canvas.drawCircle(
      Offset(size.width * .92, size.height * .12),
      size.height * .55,
      gold,
    );
    canvas.drawCircle(
      Offset(size.width * .92, size.height * .12),
      size.height * .70,
      gold,
    );

    final glow = Paint()
      ..shader =
          RadialGradient(
            colors: [
              _IdCardPageState._facGold.withValues(alpha: .10),
              _IdCardPageState._facGold.withValues(alpha: 0),
            ],
          ).createShader(
            Rect.fromCircle(center: Offset.zero, radius: size.height * .8),
          );
    canvas.drawRect(Offset.zero & size, glow);
  }

  @override
  bool shouldRepaint(_FacultyTexture old) => false;
}

/// The light band that keeps travelling across the card.
class _FacultySheen extends CustomPainter {
  _FacultySheen(this.t);

  final double t;

  @override
  void paint(Canvas canvas, Size size) {
    final travel = -size.width * 1.2 + t * size.width * 2.4;
    final band = Rect.fromCenter(
      center: Offset(travel, size.height / 2),
      width: size.width * .45,
      height: size.height * 2.2,
    );
    final paint = Paint()
      ..shader = LinearGradient(
        begin: Alignment.centerLeft,
        end: Alignment.centerRight,
        colors: [
          Colors.white.withValues(alpha: 0),
          _IdCardPageState._facGold.withValues(alpha: .10),
          Colors.white.withValues(alpha: .05),
          Colors.white.withValues(alpha: 0),
        ],
        stops: [0.0, .45, .55, 1.0],
      ).createShader(band);
    canvas.save();
    canvas.clipRect(Offset.zero & size);
    canvas.translate(size.width / 2, size.height / 2);
    canvas.rotate(-0.30);
    canvas.translate(-size.width / 2, -size.height / 2);
    canvas.drawRect(Offset.zero & size, paint);
    canvas.restore();
  }

  @override
  bool shouldRepaint(_FacultySheen old) => old.t != t;
}

/// A bright gold arc that revolves around the faculty portrait.
class _FacultyArc extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final rect = Rect.fromCircle(
      center: Offset(size.width / 2, size.height / 2),
      radius: size.width / 2 - 2,
    );
    final gold = Paint()
      ..shader = SweepGradient(
        colors: [
          _IdCardPageState._facGold.withValues(alpha: 0),
          _IdCardPageState._facGold,
          _IdCardPageState._facGold.withValues(alpha: .15),
          _IdCardPageState._facGold.withValues(alpha: 0),
        ],
        stops: [0.0, .18, .45, 1.0],
      ).createShader(rect)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 2.1
      ..strokeCap = StrokeCap.round;
    canvas.drawArc(rect, 0, 4.4, false, gold);

    final faint = Paint()
      ..color = _IdCardPageState._facGold.withValues(alpha: .18)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1;
    canvas.drawArc(rect, 0, 6.28318, false, faint);
  }

  @override
  bool shouldRepaint(_FacultyArc old) => false;
}

/// The card's Edit details dialog. It owns its text controllers and disposes
/// them when the route is torn down — disposing them right after showDialog
/// returns crashes the app while the dialog is still sliding away.

class _CoinBadge extends StatefulWidget {
  const _CoinBadge({required this.name, this.size = 84, this.photo = ''});

  final String name;
  final double size;
  final String photo;

  @override
  State<_CoinBadge> createState() => _CoinBadgeState();
}

class _CoinBadgeState extends State<_CoinBadge>
    with SingleTickerProviderStateMixin {
  late final AnimationController _c = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 3800),
  )..repeat();

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  String get _initials {
    final parts = widget.name
        .trim()
        .split(RegExp(r'\s+'))
        .where((p) => p.isNotEmpty)
        .toList();
    if (parts.isEmpty) return '?';
    final first = parts.first.substring(0, 1);
    final last = parts.length > 1 ? parts.last.substring(0, 1) : '';
    return (first + last).toUpperCase();
  }

  @override
  Widget build(BuildContext context) {
    final s = widget.size;
    final photo = widget.photo.trim();
    return SizedBox(
      width: s + 26,
      height: s + 26,
      child: AnimatedBuilder(
        animation: _c,
        builder: (context, _) {
          final t = _c.value;
          final pulse = .5 + .5 * math.sin(t * 2 * math.pi);
          return Stack(
            alignment: Alignment.center,
            children: [
              // breathing halo
              Container(
                width: s + 12 + 10 * pulse,
                height: s + 12 + 10 * pulse,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  color: Colors.white.withValues(
                    alpha: .05 + .06 * (1 - pulse),
                  ),
                ),
              ),
              // the faint full ring
              Container(
                width: s + 9,
                height: s + 9,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  border: Border.all(
                    color: Colors.white.withValues(alpha: .34),
                    width: 1,
                  ),
                ),
              ),
              // the bright arc that sweeps around it
              Transform.rotate(
                angle: t * 2 * math.pi,
                child: CustomPaint(
                  size: Size(s + 9, s + 9),
                  painter: _RingSweep(),
                ),
              ),
              // the coin itself
              Container(
                width: s,
                height: s,
                alignment: Alignment.center,
                clipBehavior: Clip.antiAlias,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  gradient: LinearGradient(
                    begin: Alignment.topLeft,
                    end: Alignment.bottomRight,
                    colors: [
                      Colors.white.withValues(alpha: .38),
                      Colors.white.withValues(alpha: .14),
                    ],
                  ),
                  border: Border.all(
                    color: Colors.white.withValues(alpha: .6),
                    width: 1.4,
                  ),
                ),
                child: photo.isEmpty
                    ? Text(
                        _initials,
                        style: TextStyle(
                          fontSize: s * .32,
                          fontWeight: FontWeight.w800,
                          letterSpacing: .5,
                          color: Colors.white,
                        ),
                      )
                    : Image.network(
                        photo,
                        width: s,
                        height: s,
                        fit: BoxFit.cover,
                        errorBuilder: (_, _, _) => Text(
                          _initials,
                          style: TextStyle(
                            fontSize: s * .32,
                            fontWeight: FontWeight.w800,
                            color: Colors.white,
                          ),
                        ),
                      ),
              ),
            ],
          );
        },
      ),
    );
  }
}

/// a bright arc with a soft tail, drawn once around the avatar
class _RingSweep extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final rect = Rect.fromLTWH(0, 0, size.width, size.height);
    final start = -math.pi / 2;
    const sweep = math.pi * 1.15;
    final paint = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.8
      ..strokeCap = StrokeCap.round;
    // three passes fading out behind the head of the arc
    for (var i = 0; i < 12; i++) {
      final a = i / 12;
      paint.color = Colors.white.withValues(alpha: .06 + .5 * a);
      canvas.drawArc(
        rect.deflate(1),
        start + sweep * a,
        sweep / 12 + .02,
        false,
        paint,
      );
    }
  }

  @override
  bool shouldRepaint(covariant _RingSweep old) => false;
}

// ============================================================================
//  NOTES — a teacher shares a PDF from the Notes tab, every student whose
//  batch it was shared with finds it under My Notes & PDFs, and can read it
//  or keep a copy on the phone.
// ============================================================================

const List<String> kNoteCats = <String>['lecture', 'study', 'reference'];

String noteCatLabel(String c) {
  switch (c) {
    case 'study':
      return T('Study');
    case 'reference':
      return T('Reference');
    default:
      return T('Lecture');
  }
}

Color noteCatColor(String c) {
  switch (c) {
    case 'study':
      return Skin.green;
    case 'reference':
      return Skin.navy;
    default:
      return Skin.marigold;
  }
}

String noteSize(int bytes) {
  if (bytes <= 0) return '';
  if (bytes < 1024 * 1024) {
    return '${(bytes / 1024).toStringAsFixed(0)} KB';
  }
  return '${(bytes / (1024 * 1024)).toStringAsFixed(1)} MB';
}

String noteDate(Object? raw) {
  final ts = raw is num ? raw.toInt() : int.tryParse(raw?.toString() ?? '');
  if (ts == null || ts <= 0) return '—';
  final d = DateTime.fromMillisecondsSinceEpoch(ts);
  return '${d.day.toString().padLeft(2, '0')} ${kMonthShort[d.month - 1]} ${d.year}';
}

/// a readable file name out of a share link
String noteNameFromLink(String link) {
  final path = Uri.tryParse(link)?.path ?? '';
  final parts = path.split('/').where((p) => p.trim().isNotEmpty).toList();
  if (parts.isEmpty) return 'note.pdf';
  final last = parts.last.replaceFirst(RegExp(r'^\d{8,}_'), '');
  return last.contains('.') ? last : '$last.pdf';
}

// ---------------------------------------------------------------------------
//  NOTE FILES
//  A teacher can hand over the file itself instead of a link. The bytes travel
//  inside the shared row as a data URL, the same 1.5 MB-capped way the website
//  carries notice attachments, so students need no outside host to open it.
// ---------------------------------------------------------------------------
const int kNoteFileMaxBytes = 1536 * 1024;

/// extension of a file name, lower case, without the dot
String noteExt(String name) {
  final dot = name.lastIndexOf('.');
  return dot < 0 ? '' : name.substring(dot + 1).toLowerCase();
}

String noteMime(String name) {
  switch (noteExt(name)) {
    case 'pdf':
      return 'application/pdf';
    case 'png':
      return 'image/png';
    case 'jpg':
    case 'jpeg':
      return 'image/jpeg';
    case 'webp':
      return 'image/webp';
    case 'gif':
      return 'image/gif';
    case 'txt':
      return 'text/plain';
    case 'csv':
      return 'text/csv';
    case 'doc':
      return 'application/msword';
    case 'docx':
      return 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
    case 'xls':
      return 'application/vnd.ms-excel';
    case 'xlsx':
      return 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
    case 'ppt':
      return 'application/vnd.ms-powerpoint';
    case 'pptx':
      return 'application/vnd.openxmlformats-officedocument.presentationml.presentation';
    case 'zip':
      return 'application/zip';
    default:
      return 'application/octet-stream';
  }
}

IconData noteIconFor(String name) {
  switch (noteExt(name)) {
    case 'pdf':
      return Icons.picture_as_pdf_outlined;
    case 'png':
    case 'jpg':
    case 'jpeg':
    case 'webp':
    case 'gif':
    case 'heic':
      return Icons.image_outlined;
    case 'doc':
    case 'docx':
      return Icons.description_outlined;
    case 'xls':
    case 'xlsx':
    case 'csv':
      return Icons.table_chart_outlined;
    case 'ppt':
    case 'pptx':
      return Icons.slideshow_outlined;
    case 'zip':
    case 'rar':
      return Icons.folder_zip_outlined;
    case 'mp4':
    case 'mov':
    case 'mkv':
      return Icons.movie_outlined;
    case 'mp3':
    case 'wav':
    case 'm4a':
      return Icons.audiotrack_outlined;
    default:
      return Icons.insert_drive_file_outlined;
  }
}

/// a note points at a pasted link, or carries its own file as a data URL
String noteLink(Map<String, dynamic> n) {
  final url = (n['url'] ?? '').toString().trim();
  if (url.isNotEmpty) return url;
  return (n['fileData'] ?? '').toString().trim();
}

bool noteCarriesFile(Map<String, dynamic> n) => noteLink(n).startsWith('data:');

/// the label a student sees for the note's file
String noteFileName(Map<String, dynamic> n) {
  final named = (n['fileName'] ?? '').toString().trim();
  if (named.isNotEmpty) return named;
  final link = noteLink(n);
  return link.startsWith('data:') ? 'note' : noteNameFromLink(link);
}

/// decode the file a note carries
List<int> noteDataBytes(String dataUrl) {
  final comma = dataUrl.indexOf(',');
  if (comma < 0) return const <int>[];
  final meta = dataUrl.substring(0, comma);
  final payload = dataUrl.substring(comma + 1);
  if (meta.contains('base64')) return base64Decode(payload);
  return utf8.encode(Uri.decodeComponent(payload));
}

/// a name the phone can write to disk
String noteSafeName(String name) {
  final clean = name.replaceAll(RegExp(r'[\\/:*?"<>|]'), '_').trim();
  if (clean.isEmpty) return 'note';
  return clean;
}

class StudentNotesPage extends StatefulWidget {
  const StudentNotesPage({
    super.key,
    required this.user,
    required this.student,
  });

  final Map<String, dynamic> user;
  final Map<String, dynamic> student;

  @override
  State<StudentNotesPage> createState() => _StudentNotesPageState();
}

class _StudentNotesPageState extends State<StudentNotesPage> {
  Store get s => Store.I;

  final TextEditingController _search = TextEditingController();
  final FocusNode _searchFocus = FocusNode();
  String _cat = 'all';
  String? _busy;

  @override
  void dispose() {
    _search.dispose();
    _searchFocus.dispose();
    super.dispose();
  }

  List<Map<String, dynamic>> get _all => s.notesFor(widget.student);

  List<Map<String, dynamic>> get _shown {
    final q = _search.text.trim().toLowerCase();
    return _all.where((n) {
      if (_cat != 'all' && (n['category'] ?? 'lecture').toString() != _cat) {
        return false;
      }
      if (q.isEmpty) return true;
      final hay = <String>[
        (n['title'] ?? '').toString(),
        (n['description'] ?? '').toString(),
        (n['subject'] ?? '').toString(),
        (n['fileName'] ?? '').toString(),
        (n['by'] ?? '').toString(),
      ].join(' ').toLowerCase();
      return hay.contains(q);
    }).toList();
  }

  String _teacherOf(Map<String, dynamic> n) {
    final named = (n['by'] ?? '').toString().trim();
    if (named.isNotEmpty) return named;
    final u = s.userById((n['byId'] ?? '').toString());
    final looked = (u?['name'] ?? '').toString().trim();
    return looked.isEmpty ? T('Teacher') : looked;
  }

  Future<void> _open(Map<String, dynamic> n) async {
    final link = noteLink(n);
    if (link.startsWith('data:')) {
      // the note carries its own file: write it out and hand it to a viewer
      try {
        final tmp = await getTemporaryDirectory();
        final dir = Directory('${tmp.path}/jsk_notes');
        if (!dir.existsSync()) dir.createSync(recursive: true);
        final file = File('${dir.path}/${noteSafeName(noteFileName(n))}');
        await file.writeAsBytes(noteDataBytes(link), flush: true);
        await OpenFilex.open(file.path);
      } catch (_) {
        if (mounted) toast(context, T('Could not open this note.'));
      }
      return;
    }
    final uri = Uri.tryParse(link);
    if (uri == null || !link.startsWith('http')) {
      toast(context, T('This note has no readable link.'));
      return;
    }
    try {
      final ok = await launchUrl(uri, mode: LaunchMode.externalApplication);
      if (!ok && mounted) toast(context, T('Could not open this note.'));
    } catch (_) {
      if (mounted) toast(context, T('Could not open this note.'));
    }
  }

  Future<void> _download(Map<String, dynamic> n) async {
    final url = noteLink(n);
    final carried = url.startsWith('data:');
    if (!carried && !url.startsWith('http')) {
      toast(context, T('This note has no downloadable file.'));
      return;
    }
    if (_busy != null) return;
    setState(() => _busy = (n['id'] ?? '').toString());
    final clean = noteSafeName(noteFileName(n));
    try {
      final base = await getApplicationDocumentsDirectory();
      final dir = Directory('${base.path}/jsk_notes');
      if (!dir.existsSync()) dir.createSync(recursive: true);
      final file = File('${dir.path}/$clean');
      if (carried) {
        await file.writeAsBytes(noteDataBytes(url), flush: true);
      } else {
        final res = await http.get(Uri.parse(url));
        if (res.statusCode < 200 || res.statusCode >= 300) {
          throw Exception('download failed');
        }
        await file.writeAsBytes(res.bodyBytes, flush: true);
      }
      if (!mounted) return;
      setState(() => _busy = null);
      toast(context, TT('Saved {0}', [clean]));
      await OpenFilex.open(file.path);
    } catch (_) {
      // a drive or sign-in link cannot be fetched directly, so hand it to
      // the browser where the student can still save it
      if (!mounted) return;
      setState(() => _busy = null);
      await _open(n);
    }
  }

  @override
  Widget build(BuildContext context) {
    final shown = _shown;
    return CustomScrollView(
      slivers: [
        SliverPadding(
          padding: EdgeInsets.fromLTRB(14, 14, 14, 0),
          sliver: SliverList(
            delegate: SliverChildListDelegate([
              PageHeading(
                T('My Notes & PDFs'),
                '${s.batchName(widget.student['batchId'])} · ${widget.student['name']}',
                Icons.folder_copy_outlined,
              ),
              // exactly one box: the container draws the frame and the field
              // inside it is unfilled and borderless, so no second box can
              // appear behind the text
              GestureDetector(
                behavior: HitTestBehavior.opaque,
                onTap: () => _searchFocus.requestFocus(),
                child: Container(
                  height: 44,
                  padding: EdgeInsets.symmetric(horizontal: 12),
                  decoration: BoxDecoration(
                    color: context.panel,
                    borderRadius: BorderRadius.circular(12),
                    border: Border.all(
                      color: context.line.withValues(alpha: .8),
                    ),
                  ),
                  child: Row(
                    children: [
                      Icon(Icons.search, size: 16, color: context.faint),
                      SizedBox(width: 8),
                      Expanded(
                        child: TextField(
                          controller: _search,
                          focusNode: _searchFocus,
                          onChanged: (_) => setState(() {}),
                          textAlignVertical: TextAlignVertical.center,
                          cursorColor: Skin.marigold,
                          style: TextStyle(fontSize: 11.5, color: context.ink),
                          decoration: InputDecoration(
                            isCollapsed: true,
                            filled: false,
                            border: InputBorder.none,
                            enabledBorder: InputBorder.none,
                            focusedBorder: InputBorder.none,
                            hintText: T('Search notes...'),
                            hintStyle: TextStyle(
                              fontSize: 11.5,
                              color: context.faint,
                            ),
                          ),
                        ),
                      ),
                      if (_search.text.isNotEmpty)
                        GestureDetector(
                          onTap: () => setState(_search.clear),
                          child: Icon(
                            Icons.close,
                            size: 15,
                            color: context.faint,
                          ),
                        ),
                    ],
                  ),
                ),
              ),
              SizedBox(height: 10),
              SingleChildScrollView(
                scrollDirection: Axis.horizontal,
                child: Row(
                  children: [
                    _catPill('all', T('All')),
                    for (final c in kNoteCats) _catPill(c, noteCatLabel(c)),
                  ],
                ),
              ),
              SizedBox(height: 12),
              SectionTitle(
                T('Teacher PDFs'),
                trailing: Text(
                  '${shown.length}',
                  style: TextStyle(
                    fontSize: 10,
                    fontWeight: FontWeight.w700,
                    color: context.faint,
                  ),
                ),
              ),
            ]),
          ),
        ),
        // an empty shelf keeps the page's rhythm: the note sits in the middle
        // of the room it has, instead of a card stretched across it
        if (shown.isEmpty)
          SliverFillRemaining(
            hasScrollBody: false,
            child: Padding(
              padding: EdgeInsets.fromLTRB(24, 0, 24, 26),
              child: Center(child: _emptyShelf()),
            ),
          )
        else
          SliverPadding(
            padding: EdgeInsets.fromLTRB(14, 0, 14, 24),
            sliver: SliverList(
              delegate: SliverChildListDelegate([
                for (final n in shown) _noteCard(n),
              ]),
            ),
          ),
      ],
    );
  }

  Widget _emptyShelf() {
    final none = _all.isEmpty;
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Container(
          width: 52,
          height: 52,
          alignment: Alignment.center,
          decoration: BoxDecoration(
            shape: BoxShape.circle,
            color: Skin.marigold.withValues(alpha: .10),
            border: Border.all(color: Skin.marigold.withValues(alpha: .22)),
          ),
          child: Icon(
            none ? Icons.folder_open_outlined : Icons.search_off,
            size: 23,
            color: Skin.marigold.withValues(alpha: .85),
          ),
        ),
        SizedBox(height: 11),
        Text(
          none ? T('No notes yet') : T('Nothing matches that search'),
          textAlign: TextAlign.center,
          style: TextStyle(
            fontSize: 13,
            fontWeight: FontWeight.w700,
            color: context.ink,
          ),
        ),
        SizedBox(height: 5),
        ConstrainedBox(
          constraints: BoxConstraints(maxWidth: 248),
          child: Text(
            none
                ? T('When a teacher shares a PDF with your batch, it lands here.')
                : T('Try another word or switch the filter above.'),
            textAlign: TextAlign.center,
            style: TextStyle(fontSize: 10.5, height: 1.55, color: context.soft),
          ),
        ),
      ],
    );
  }

  Widget _catPill(String key, String label) {
    final active = _cat == key;
    return Padding(
      padding: EdgeInsets.only(right: 7),
      child: GestureDetector(
        onTap: () => setState(() => _cat = key),
        child: AnimatedContainer(
          duration: Duration(milliseconds: 160),
          padding: EdgeInsets.symmetric(horizontal: 12, vertical: 6),
          decoration: BoxDecoration(
            color: active
                ? Skin.marigold.withValues(alpha: .18)
                : context.panel2.withValues(alpha: .5),
            borderRadius: BorderRadius.circular(999),
            border: Border.all(
              color: active
                  ? Skin.marigold.withValues(alpha: .55)
                  : context.line.withValues(alpha: .7),
            ),
          ),
          child: Text(
            label,
            style: TextStyle(
              fontSize: 10.5,
              fontWeight: active ? FontWeight.w700 : FontWeight.w500,
              color: active ? Skin.marigold : context.soft,
            ),
          ),
        ),
      ),
    );
  }

  Widget _noteCard(Map<String, dynamic> n) {
    final cat = (n['category'] ?? 'lecture').toString();
    final subject = (n['subject'] ?? '').toString().trim();
    final name = (n['fileName'] ?? '').toString().trim();
    final size = (n['sizeLabel'] ?? '').toString().trim();
    final desc = (n['description'] ?? '').toString().trim();
    final by = _teacherOf(n);
    final busy = _busy == (n['id'] ?? '').toString();
    final when = noteDate(n['ts']);
    final meta = <String>[
      if (size.isNotEmpty) TT('Size: {0}', [size]),
      TT('Uploaded: {0}', [when]),
    ].join(' · ');

    return Panel(
      padding: EdgeInsets.fromLTRB(12, 12, 12, 10),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Container(
                width: 42,
                height: 42,
                alignment: Alignment.center,
                decoration: BoxDecoration(
                  color: Skin.brick.withValues(alpha: .14),
                  borderRadius: BorderRadius.circular(11),
                ),
                child: Icon(
                  Icons.picture_as_pdf_outlined,
                  size: 21,
                  color: Skin.brick,
                ),
              ),
              SizedBox(width: 10),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      (n['title'] ?? '').toString(),
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                        fontSize: 12.5,
                        height: 1.25,
                        fontWeight: FontWeight.w700,
                        color: context.ink,
                      ),
                    ),
                    if (desc.isNotEmpty) ...[
                      SizedBox(height: 4),
                      Text(
                        desc,
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                          fontSize: 9.8,
                          height: 1.4,
                          color: context.soft,
                        ),
                      ),
                    ],
                    if (meta.isNotEmpty) ...[
                      SizedBox(height: 5),
                      Text(
                        meta,
                        style: TextStyle(fontSize: 8.8, color: context.faint),
                      ),
                    ],
                    SizedBox(height: 7),
                    Row(
                      children: [
                        Avatar(
                          name: by,
                          radius: 8.5,
                          color: Skin.marigold.withValues(alpha: .20),
                          fontSize: 7.4,
                        ),
                        SizedBox(width: 5),
                        Text(
                          TT('Shared by {0}', [by]),
                          style: TextStyle(
                            fontSize: 9,
                            fontWeight: FontWeight.w600,
                            color: context.soft,
                          ),
                        ),
                      ],
                    ),
                  ],
                ),
              ),
            ],
          ),
          SizedBox(height: 9),
          Row(
            children: [
              if (subject.isNotEmpty) ...[
                Chip8(subject, color: noteCatColor(cat)),
                SizedBox(width: 7),
              ],
              Expanded(
                child: Row(
                  children: [
                    Icon(Icons.attach_file, size: 11, color: context.faint),
                    SizedBox(width: 3),
                    Expanded(
                      child: Text(
                        name.isEmpty ? T('PDF') : name,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(fontSize: 8.8, color: context.faint),
                      ),
                    ),
                  ],
                ),
              ),
              SizedBox(width: 6),
              _roundAction(
                icon: busy ? null : Icons.visibility_outlined,
                busy: busy,
                onTap: () => _open(n),
              ),
              SizedBox(width: 6),
              _roundAction(
                icon: Icons.download_outlined,
                busy: busy,
                onTap: () => _download(n),
              ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _roundAction({
    required IconData? icon,
    required bool busy,
    required VoidCallback onTap,
  }) => GestureDetector(
    onTap: onTap,
    child: Container(
      width: 30,
      height: 30,
      alignment: Alignment.center,
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        color: context.panel2.withValues(alpha: .55),
        border: Border.all(color: context.line.withValues(alpha: .7)),
      ),
      child: busy
          ? SizedBox(
              width: 13,
              height: 13,
              child: CircularProgressIndicator(
                strokeWidth: 1.6,
                color: context.soft,
              ),
            )
          : Icon(
              icon ?? Icons.visibility_outlined,
              size: 15,
              color: context.soft,
            ),
    ),
  );
}

class TeacherNotesPage extends StatefulWidget {
  const TeacherNotesPage({super.key, required this.user});

  final Map<String, dynamic> user;

  @override
  State<TeacherNotesPage> createState() => _TeacherNotesPageState();
}

class _TeacherNotesPageState extends State<TeacherNotesPage> {
  Store get s => Store.I;

  final TextEditingController _title = TextEditingController();
  final TextEditingController _subject = TextEditingController();
  final TextEditingController _desc = TextEditingController();
  final TextEditingController _link = TextEditingController();
  final TextEditingController _file = TextEditingController();

  String _cat = 'lecture';
  String _batchId = '';
  bool _sharing = false;

  // a file chosen from the phone travels with the note
  String _pickedName = '';
  List<int>? _pickedBytes;
  bool _picking = false;

  @override
  void dispose() {
    _title.dispose();
    _subject.dispose();
    _desc.dispose();
    _link.dispose();
    _file.dispose();
    super.dispose();
  }

  String get _uid => widget.user['id'].toString();

  List<Map<String, dynamic>> get _mine => s.notesBy(_uid);

  /// let the teacher pick a PDF, an image or any other document from the phone
  Future<void> _chooseFile() async {
    if (_picking) return;
    setState(() => _picking = true);
    try {
      // the phone's own file browser, with no type filter: any PDF, image,
      // spreadsheet or document the teacher already has
      final picked = await openFile(
        acceptedTypeGroups: <XTypeGroup>[
          const XTypeGroup(label: 'file', mimeTypes: <String>['*/*']),
        ],
      );
      if (picked == null) return; // the picker was closed
      final size = await picked.length();
      if (size > kNoteFileMaxBytes) {
        if (mounted) {
          toast(context, T('File is too large. Please keep it under 1.5 MB.'));
        }
        return;
      }
      final bytes = await picked.readAsBytes();
      if (bytes.isEmpty) {
        if (mounted) toast(context, T('Could not read that file.'));
        return;
      }
      if (bytes.length > kNoteFileMaxBytes) {
        if (mounted) {
          toast(context, T('File is too large. Please keep it under 1.5 MB.'));
        }
        return;
      }
      if (!mounted) return;
      final name = picked.name.trim();
      setState(() {
        _pickedName = name.isEmpty ? 'file' : name;
        _pickedBytes = bytes;
      });
    } catch (_) {
      if (mounted) toast(context, T('Could not read that file.'));
    } finally {
      if (mounted) setState(() => _picking = false);
    }
  }

  void _clearFile() => setState(() {
    _pickedName = '';
    _pickedBytes = null;
  });

  Future<void> _share() async {
    final title = _title.text.trim();
    if (title.isEmpty) {
      toast(context, T('Give the note a title.'));
      return;
    }
    setState(() => _sharing = true);

    final pickedName = _pickedName;
    var link = '';
    var carried = '';
    var fileName = '';
    var sizeLabel = '';

    if (pickedName.isNotEmpty) {
      final bytes = _pickedBytes;
      if (bytes == null || bytes.isEmpty) {
        setState(() => _sharing = false);
        toast(context, T('Could not read that file.'));
        return;
      }
      if (bytes.length > kNoteFileMaxBytes) {
        setState(() => _sharing = false);
        toast(context, T('File is too large. Please keep it under 1.5 MB.'));
        return;
      }
      // the file rides inside the shared row, the same way a notice attachment
      // does, so a student can open it without any outside host
      carried = 'data:${noteMime(pickedName)};base64,${base64Encode(bytes)}';
      fileName = pickedName;
      sizeLabel = noteSize(bytes.length);
    } else {
      final raw = _link.text.trim();
      final uri = Uri.tryParse(raw);
      if (uri == null || !(uri.isScheme('http') || uri.isScheme('https'))) {
        setState(() => _sharing = false);
        toast(
          context,
          T('Choose a file or paste a link that starts with http.'),
        );
        return;
      }
      link = raw;
      fileName = noteNameFromLink(raw);
      // the size is only a label on the card, so a slow host never blocks a share
      try {
        final head = await http.head(uri).timeout(const Duration(seconds: 5));
        final len = int.tryParse(head.headers['content-length'] ?? '');
        if (len != null) sizeLabel = noteSize(len);
      } catch (_) {
        sizeLabel = '';
      }
    }

    if (!mounted) return;
    final named = _file.text.trim();
    s.addNote({
      'id': uid('note'),
      'title': title,
      'description': _desc.text.trim(),
      'subject': _subject.text.trim(),
      'category': _cat,
      'url': link,
      if (carried.isNotEmpty) 'fileData': carried,
      'fileName': named.isEmpty ? fileName : named,
      'sizeLabel': sizeLabel,
      'batchId': _batchId,
      'byId': _uid,
      'by': (widget.user['name'] ?? '').toString(),
      'ts': DateTime.now().millisecondsSinceEpoch,
    });
    setState(() {
      _sharing = false;
      _pickedName = '';
      _pickedBytes = null;
      _title.clear();
      _subject.clear();
      _desc.clear();
      _link.clear();
      _file.clear();
    });
    toast(context, T('Note shared with your students.'));
  }

  Future<void> _remove(Map<String, dynamic> n) async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(
          T('Remove this note?'),
          style: TextStyle(fontSize: 15, color: context.ink),
        ),
        content: Text(
          T('Students will no longer see it in their notes.'),
          style: TextStyle(fontSize: 12, color: context.soft, height: 1.5),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: Text(T('Keep it'), style: TextStyle(fontSize: 12)),
          ),
          TextButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: Text(
              T('Remove'),
              style: TextStyle(fontSize: 12, color: Skin.brick),
            ),
          ),
        ],
      ),
    );
    if (ok != true) return;
    s.removeNote((n['id'] ?? '').toString());
    if (mounted) setState(() {});
  }

